import type { TavernMessageRole, TavernNarrativeProjectionSnapshot } from "./contracts.js";

export const DEFAULT_NARRATIVE_CONTENT_TAG = "content" as const;

const SAFE_TAG_PATTERN = /^[^\s<>/"'=]{1,64}$/u;

export function normalizeNarrativeContentTag(value: unknown): string {
  if (typeof value !== "string") return DEFAULT_NARRATIVE_CONTENT_TAG;
  const trimmed = value.trim();
  return SAFE_TAG_PATTERN.test(trimmed) ? trimmed : DEFAULT_NARRATIVE_CONTENT_TAG;
}

export function stripHtmlComments(text: string): string {
  return text.replace(/<!--[\s\S]*?-->/gu, "");
}

function escapeRegularExpression(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
}

function codePointOffset(text: string, utf16Offset: number): number {
  return [...text.slice(0, utf16Offset)].length;
}

/**
 * User/system messages remain verbatim. Assistant messages are fail-closed when
 * a configured content tag is missing or incomplete: only the last complete
 * tag block is narrative evidence, with HTML comments removed.
 */
export function projectNarrativeText(
  text: string,
  role: TavernMessageRole,
  requestedTag: unknown = DEFAULT_NARRATIVE_CONTENT_TAG,
): TavernNarrativeProjectionSnapshot {
  if (role !== "assistant") {
    return {
      text,
      strategy: "raw_selected_content",
      raw_start_code_point: 0,
      raw_end_code_point: [...text].length,
    };
  }

  const tag = normalizeNarrativeContentTag(requestedTag);
  const escapedTag = escapeRegularExpression(tag);
  const openPattern = new RegExp(`<${escapedTag}>`, "giu");
  const closePattern = new RegExp(`</${escapedTag}>`, "giu");
  let lastComplete: { readonly start: number; readonly end: number } | null = null;
  let cursor = 0;
  while (cursor < text.length) {
    openPattern.lastIndex = cursor;
    const openMatch = openPattern.exec(text);
    if (openMatch === null) break;
    const contentStart = openMatch.index + openMatch[0].length;
    closePattern.lastIndex = contentStart;
    const closeMatch = closePattern.exec(text);
    if (closeMatch === null) break;
    lastComplete = { start: contentStart, end: closeMatch.index };
    cursor = closeMatch.index + closeMatch[0].length;
  }

  if (lastComplete === null) {
    return {
      text: "",
      strategy: "assistant_configured_content_block_without_html_comments",
      raw_start_code_point: 0,
      raw_end_code_point: 0,
    };
  }
  return {
    text: stripHtmlComments(text.slice(lastComplete.start, lastComplete.end)),
    strategy: "assistant_configured_content_block_without_html_comments",
    raw_start_code_point: codePointOffset(text, lastComplete.start),
    raw_end_code_point: codePointOffset(text, lastComplete.end),
  };
}
