const jsonValue = (value: unknown): JsonValue => value as JsonValue;
const jsonObject = (value: unknown): JsonObject =>
  (value !== null && typeof value === "object" && !Array.isArray(value) ? value : {}) as JsonObject;

function emptyModuleViews(): Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>> {
  return Object.fromEntries(
    TAVERN_MEMORY_MODULE_IDS.map((moduleId) => [
      moduleId,
      {
        module_id: moduleId,
        record_count: 0,
        abnormal_count: 0,
        newest_cursor: null,
        latest_page_id: null,
        oldest_page_id: null,
        page_count: 0,
      },
    ]),
  ) as unknown as Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
}

function validAiWindows(snapshot: TavernSourceSnapshot): readonly TavernValidAiWindow[] {
  const result: TavernValidAiWindow[] = [];
  let windowStart = 0;
  for (const [index, message] of snapshot.messages.entries()) {
    if (message.role !== "assistant" || message.narrative_text === null) continue;
    const sourceUnitIds = snapshot.messages
      .slice(windowStart, index + 1)
      .filter((item) => item.narrative_text !== null)
      .map((item) => item.source_unit_id);
    result.push({
      ai_ordinal: result.length + 1,
      assistant_source_unit_id: message.source_unit_id,
      source_unit_ids: sourceUnitIds,
    });
    windowStart = index + 1;
  }
  return result;
}

function activeModule(batch: TavernMemoryBatchWorkState | null): TavernMemoryModuleId | null {
  if (batch === null) return null;
  return (
    TAVERN_MEMORY_MODULE_IDS.find((moduleId) =>
      ["RUNNING", "NEEDS_USER", "INTERRUPTED"].includes(batch.modules[moduleId].status),
    ) ??
    TAVERN_MEMORY_MODULE_IDS.find((moduleId) => batch.modules[moduleId].status === "PENDING") ??
    null
  );
}

function statusFromHead(
  head: TavernMemoryColdHead | null,
  pendingEligible: number,
): NarraMemModularRuntimeStatus {
  const batch = head?.work_state ?? null;
  if (batch === null) return pendingEligible >= 10 ? "running" : "collecting";
  if (
    TAVERN_MEMORY_MODULE_IDS.some((moduleId) =>
      ["NEEDS_USER", "INTERRUPTED"].includes(batch.modules[moduleId].status),
    )
  )
    return "waiting_for_user";
  if (batch.status === "NEEDS_USER" || batch.status === "INVALIDATED") return "waiting_for_user";
  if (batch.status === "FINALIZING" || batch.status === "CHECKPOINT_VERIFIED") return "finalizing";
  if (batch.status === "RECALL_READY" || batch.status === "VISIBILITY_APPLIED")
    return "recall_ready";
  if (batch.status === "COMPLETE") return "complete";
  return "running";
}

function errorDescriptor(error: unknown): { readonly code: string; readonly message: string } {
  if (error instanceof Error) {
    const candidate = error as Error & { readonly code?: unknown };
    return {
      code: typeof candidate.code === "string" ? candidate.code : error.name,
      message: error.message,
    };
  }
  return { code: "UNKNOWN_ERROR", message: String(error) };
}

export class NarraMemModularMemoryRuntime {
  private scope: ActiveScope | null = null;
  private tail: Promise<void> = Promise.resolve();
  private sequence = 0;
  private lastSnapshot: NarraMemModularRuntimeSnapshot;

  constructor(private readonly options: NarraMemModularMemoryRuntimeOptions) {
    this.lastSnapshot = this.makeSnapshot("disabled", null, null, null, 0, 0, [], null, null);
  }

  snapshot(): NarraMemModularRuntimeSnapshot {
    return structuredClone(this.lastSnapshot);
  }

  schedule(trigger: string, hints: readonly TavernMutationHint[] = ["unknown"]): Promise<void> {
    const operation = async (): Promise<void> => this.advance(trigger, hints);
    this.tail = this.tail.then(operation, operation);
    return this.tail;
  }

  async refresh(): Promise<void> {
    await this.schedule("refresh", ["chat_loaded"]);
  }

  async manualRepair(moduleId?: TavernMemoryModuleId): Promise<void> {
    const operation = async (): Promise<void> => {
      const config = this.options.get_config();
      const scope = await this.resolveScope();
      if (!config.enabled || scope === null) throw new TypeError("NarraMem 运行时尚未启用");
      const head = (await scope.store.readColdHead()).head;
      const batch = head?.work_state ?? null;
      const target = moduleId ?? activeModule(batch);
      if (head === null || batch === null || target === null) {
        throw new TypeError("当前没有等待手动修复的模块");
      }
      const input = await this.readBatchInput(scope.store, head, batch.batch_id);
      await runManualTavernMemoryModuleRepair({
        ...this.coordinatorCommon(config, scope.store, input, batch),
        module_id: target,
        operation_id_prefix: `manual:${batch.batch_id}:${target}:${batch.modules[target].manual_repair_calls + 1}`,
      });
      await this.updateFromCurrent(scope, "manual_repair_complete");
    };
    this.tail = this.tail.then(operation, operation);
    return this.tail;
  }

  async reprocessFromFloor(messageId: number): Promise<void> {
    if (!Number.isInteger(messageId) || messageId < 0) {
      throw new TypeError("重新处理楼层必须是非负整数");
    }
    const operation = async (): Promise<void> => {
      const config = this.options.get_config();
      const scope = await this.resolveScope();
      if (!config.enabled || scope === null) throw new TypeError("NarraMem 运行时尚未启用");
      const current = await this.captureCurrent(scope.memory_set_id, null, ["message_updated"]);
      const targetIndex = current.messages.findIndex(
        (message) => message.message_id_at_capture === messageId,
      );
      if (targetIndex < 0) throw new TypeError(`当前聊天中不存在楼层 ${messageId}`);
      const target = current.messages[targetIndex];
      if (target === undefined) throw new TypeError("无法读取重新处理楼层");
      const windows = validAiWindows(current);
      const assistantsBefore = current.messages
        .slice(0, targetIndex)
        .filter(
          (message) => message.role === "assistant" && message.narrative_text !== null,
        ).length;
      const projection = await projectTavernCoreSource({
        snapshot: current,
        known_entities: [],
        event_type_vocabulary: [],
        state_key_vocabulary: [],
        claim_predicate_vocabulary: [],
        default_story_time: DEFAULT_STORY_TIME,
        created_at: this.now(),
      });
      const rollbackRequest = {
        book_store: scope.store,
        current_source_snapshot: current,
        new_source_revision_id: projection.source_revision.revision_id,
        valid_ai_count: windows.length,
        protected_ai_ordinals: windows.slice(-4).map((item) => item.ai_ordinal),
        mutation_source_unit_id: target.source_unit_id,
        mutation_message_id: messageId,
        mutation_ai_ordinal: Math.max(1, assistantsBefore + 1),
      } as const;
      const plan = await planTavernMemoryMutationRollback(rollbackRequest);
      const unhidden = await this.options.unhide_from(plan.unhide_from_message_id);
      await commitTavernMemoryMutationRollback({
        ...rollbackRequest,
        plan,
        unhidden_from_message_id: unhidden,
        operation_id: `runtime:user_reprocess:${target.source_unit_id}:${++this.sequence}`,
        committed_at: this.now(),
      });
      this.options.on_diagnostic?.("module_record_reprocess_requested", {
        message_id: messageId,
        rollback_to_checkpoint_id: plan.to_checkpoint_id,
        committed_eligible_count_after: plan.committed_eligible_count_after,
        content_recorded: false,
      });
      await this.updateFromCurrent(scope, "user_record_reprocess");
    };
    this.tail = this.tail.then(operation, operation);
    return this.tail;
  }

  async assembleRecall(): Promise<TavernMemoryCheckpointRecallResult> {
    const scope = await this.resolveScope();
    if (scope === null) throw new TypeError("当前没有可召回的聊天");
    const current = await this.captureCurrent(scope.memory_set_id, null, ["unknown"]);
    return assembleTavernMemoryCheckpointRecall({
      book_store: scope.store,
      current_source_snapshot: current,
      token_budget: this.options.get_config().recall_token_budget,
      source_policy: "ALLOW_APPEND_ONLY_LIVE_TAIL",
    });
  }

  async readModulePage(
    moduleId: TavernMemoryModuleId,
    pageId?: string | null,
  ): Promise<NarraMemModuleRecordPage> {
    const scope = await this.resolveScope();
    if (scope === null)
      return { module_id: moduleId, page_id: null, older_page_id: null, records: [] };
    const head = (await scope.store.readColdHead()).head;
    const selectedPageId = pageId ?? head?.module_views[moduleId].latest_page_id ?? null;
    if (head === null || selectedPageId === null) {
      return { module_id: moduleId, page_id: null, older_page_id: null, records: [] };
    }
    const page = await scope.store.readModuleViewPage(selectedPageId);
    if (page.module_id !== moduleId) throw new TypeError("模块分页游标与模块不匹配");
    const records = await Promise.all(
      page.items.map(async (item): Promise<NarraMemModuleRecord> => {
        const corePage = await scope.store.readCorePage(item.core_page_id);
        const record = corePage.records.find((candidate) => candidate.record_id === item.record_id);
        if (record === undefined) throw new TypeError(`模块记录 ${item.record_id} 的正文缺失`);
        return { item, payload: record.payload as JsonValue };
      }),
    );
    return {
      module_id: moduleId,
      page_id: page.page_id,
      older_page_id: page.older_page_id,
      records,
    };
  }

  async exportCurrentData(): Promise<NarraMemModularRuntimeExport> {
    const scope = await this.resolveScope();
    if (scope === null) {
      return {
        format: "narramem.tavern-modular-export",
        export_version: NARRAMEM_MODULAR_RUNTIME_VERSION,
        exported_at: this.now(),
        scope: null,
        head: null,
        core_pages: [],
        module_view_pages: [],
      };
    }
    const head = (await scope.store.readColdHead()).head;
    return {
      format: "narramem.tavern-modular-export",
      export_version: NARRAMEM_MODULAR_RUNTIME_VERSION,
      exported_at: this.now(),
      scope: { memory_set_id: scope.memory_set_id, memory_book_name: scope.memory_book_name },
      head,
      core_pages:
        head === null
          ? []
          : await Promise.all(head.core_page_ids.map((pageId) => scope.store.readCorePage(pageId))),
      module_view_pages:
        head === null
          ? []
          : await Promise.all(
              head.module_view_page_ids.map((pageId) => scope.store.readModuleViewPage(pageId)),
            ),
    };
  }

  private async advance(trigger: string, hints: readonly TavernMutationHint[]): Promise<void> {
    const config = this.options.get_config();
    if (!config.enabled) {
      this.publish(this.makeSnapshot("disabled", null, null, null, 0, 0, [], null, null));
      return;
    }
    const scope = await this.resolveScope();
    if (scope === null) {
      this.publish(this.makeSnapshot("no_chat", null, null, null, 0, 0, [], null, null));
      return;
    }
    try {
      const current = await this.captureCurrent(scope.memory_set_id, null, hints);
      const windows = validAiWindows(current);
      let cold = await scope.store.readColdHead();
      let head = cold.head;
      if (head?.work_state !== null && head?.work_state !== undefined) {
        const frozen = await this.readBatchInput(scope.store, head, head.work_state.batch_id);
        const reconciled = await reconcileTavernSourceSnapshot(this.options.host_port, {
          memory_set_id: scope.memory_set_id,
          previous_snapshot: frozen.snapshot,
          observed_hints: hints,
        });
        if (
          reconciled.dirty_boundary !== null &&
          reconciled.dirty_boundary.from_index < frozen.snapshot.messages.length
        ) {
          await this.rollbackMutation(scope, head, frozen.snapshot, reconciled.snapshot, windows);
          await this.updateFromCurrent(scope, "active_batch_mutation_rollback");
          return;
        }
      } else if (head !== null && head.checkpoint_index.checkpoint_id !== null) {
        const previous = await this.readLatestCompletedInput(scope.store, head);
        if (previous !== null) {
          const reconciled = await reconcileTavernSourceSnapshot(this.options.host_port, {
            memory_set_id: scope.memory_set_id,
            previous_snapshot: previous.snapshot,
            observed_hints: hints,
          });
          if (
            reconciled.dirty_boundary !== null &&
            reconciled.dirty_boundary.from_index < previous.snapshot.messages.length
          ) {
            await this.rollbackMutation(
              scope,
              head,
              previous.snapshot,
              reconciled.snapshot,
              windows,
            );
            await this.updateFromCurrent(scope, "completed_checkpoint_mutation_rollback");
            return;
          }
        }
      }

      cold = await scope.store.readColdHead();
      head = cold.head;
      const batch = head?.work_state ?? null;
      if (batch === null || batch.status === "COMPLETE" || batch.status === "INVALIDATED") {
        const started = await this.startBatchIfReady(scope, head, current, windows, trigger);
        if (!started) {
          const committed = head?.source_index.committed_eligible_count ?? 0;
          const eligible = Math.max(0, windows.length - 4);
          this.publish(
            this.makeSnapshot(
              "collecting",
              scope,
              head,
              null,
              windows.length,
              Math.max(0, eligible - committed),
              windows.slice(-4).map((item) => item.ai_ordinal),
              null,
              null,
            ),
          );
        }
        return;
      }

      if (batch.status === "READY" || batch.status === "MODULE_RUNNING") {
        const input = await this.readBatchInput(
          scope.store,
          head as TavernMemoryColdHead,
          batch.batch_id,
        );
        const result = await runNextTavernMemoryModuleStep({
          ...this.coordinatorCommon(config, scope.store, input, batch),
          automatic_targeted_repair: config.automatic_targeted_repair,
          operation_id_prefix: `idle:${batch.batch_id}:${++this.sequence}`,
        });
        this.options.on_diagnostic?.("modular_step", {
          trigger,
          status: result.status,
          module_id: result.module_id,
          provider_dispatched: result.provider_dispatched,
        });
        await this.updateFromCurrent(scope, "module_step_complete");
        return;
      }
      if (batch.status === "NEEDS_USER") {
        await this.updateFromCurrent(scope, "module_waiting_for_user");
        return;
      }
      if (batch.status === "FINALIZING") {
        const input = await this.readBatchInput(
          scope.store,
          head as TavernMemoryColdHead,
          batch.batch_id,
        );
        await this.finalize(scope, head as TavernMemoryColdHead, batch, input, config);
        await this.updateFromCurrent(scope, "finalization_complete");
        return;
      }
      if (batch.status === "CHECKPOINT_VERIFIED") {
        await markTavernMemoryCheckpointRecallReady({
          book_store: scope.store,
          current_source_snapshot: current,
          token_budget: config.recall_token_budget,
          source_policy: "ALLOW_APPEND_ONLY_LIVE_TAIL",
          operation_id: `runtime:${batch.batch_id}`,
          committed_at: this.now(),
        });
        await this.updateFromCurrent(scope, "recall_ready");
        return;
      }
      if (batch.status === "RECALL_READY" || batch.status === "VISIBILITY_APPLIED") {
        const plan = await planTavernMemoryCheckpointVisibility({
          book_store: scope.store,
          current_source_snapshot: current,
        });
        const receipt = await this.options.apply_visibility(plan);
        await commitTavernMemoryCheckpointVisibility({
          book_store: scope.store,
          current_source_snapshot: current,
          receipt,
          operation_id: `runtime:${batch.batch_id}`,
          committed_at: this.now(),
        });
        await this.updateFromCurrent(scope, "visibility_complete");
      }
    } catch (error) {
      const descriptor = errorDescriptor(error);
      this.options.on_diagnostic?.("modular_runtime_failed", {
        trigger,
        error_code: descriptor.code,
        error_name: error instanceof Error ? error.name : "UnknownError",
        content_recorded: false,
      });
      const head = (await scope.store.readColdHead()).head;
      this.publish(
        this.makeSnapshot(
          "failed",
          scope,
          head,
          head?.work_state ?? null,
          0,
          0,
          [],
          descriptor.code,
          descriptor.message,
        ),
      );
    }
  }

  private coordinatorCommon(
    config: NarraMemModularRuntimeConfig,
    store: TavernMemoryBookStore,
    input: StoredBatchInput,
    batch: TavernMemoryBatchWorkState,
  ) {
    const batchUnits = new Set(batch.source_unit_ids);
    const batchEvidenceIds = new Set(
      input.projection.evidence_items
        .filter(
          (item) =>
            item.locator.external_id !== undefined && batchUnits.has(item.locator.external_id),
        )
        .map((item) => item.evidence_id),
    );
    const materials = {
      source_revision_id: input.projection.source_revision.revision_id,
      batch_id: batch.batch_id,
      current_evidence: input.projection.model_input.evidence_items.filter((item) =>
        batchEvidenceIds.has(item.evidence_id),
      ),
      checkpoint_capsule: input.checkpoint_capsule,
      known_entities: input.projection.model_input.known_entities,
      identity_context: input.identity_context,
      world_context: input.world_context,
      active_state: input.active_state,
      current_epistemic_state: input.current_epistemic_state,
      active_threads_and_impacts: input.active_threads_and_impacts,
    };
    return {
      book_store: store,
      generation_port: this.options.generation_port,
      compiler: new TavernModularStagingCompiler(store, {
        max_records_per_page: 24,
        max_page_utf8_bytes: 96_000,
        now: () => this.now(),
      }),
      input_context: materials,
      prompt_packs: config.prompt_packs,
      envelope: config.envelope,
      requested_model_id: config.requested_model_id,
      attempt_limits: {
        max_transport_retries: config.transport_retry_count,
        max_continuations: config.continuation_max_calls,
        max_targeted_repairs: config.automatic_targeted_repair ? (1 as const) : (0 as const),
      },
      ...(config.continuation_prompt === null
        ? {}
        : { continuation_prompt: config.continuation_prompt }),
      now: () => this.now(),
    };
  }

  private async startBatchIfReady(
    scope: ActiveScope,
    head: TavernMemoryColdHead | null,
    snapshot: TavernSourceSnapshot,
    windows: readonly TavernValidAiWindow[],
    trigger: string,
  ): Promise<boolean> {
    const createdAt = this.now();
    const projection = await projectTavernCoreSource({
      snapshot,
      known_entities: [],
      event_type_vocabulary: [],
      state_key_vocabulary: [],
      claim_predicate_vocabulary: [],
      default_story_time: DEFAULT_STORY_TIME,
      created_at: createdAt,
    });
    const committed = head?.source_index.committed_eligible_count ?? 0;
    const plan = await planTavernMemoryBatch({
      memory_set_id: scope.memory_set_id,
      source_revision_id: projection.source_revision.revision_id,
      committed_eligible_count: committed,
      valid_ai_windows: windows,
    });
    if (plan.batch === null) return false;
    // Character card / Persona / World Info scans can be relatively expensive.
    // Read them only after the deterministic 14-AI gate has actually opened.
    const hostMaterials = await this.options.get_host_materials();
    const batchInput: StoredBatchInput = {
      format: BATCH_INPUT_KIND,
      snapshot,
      projection,
      identity_context: jsonObject({
        character_card: hostMaterials.character_card ?? {},
        user_persona: hostMaterials.user_persona ?? {},
      }),
      world_context: jsonObject({ world_info: hostMaterials.world_info ?? {} }),
      checkpoint_capsule: {
        checkpoint_id: head?.checkpoint_index.checkpoint_id ?? null,
        boundary_summary: [],
        active_record_refs: [],
      },
      active_state: jsonValue(head?.active_state ?? {}),
      current_epistemic_state: jsonValue(head?.epistemic_state ?? {}),
      active_threads_and_impacts: jsonValue(head?.thread_impact ?? {}),
      created_at: createdAt,
    };
    const inputPageSet = await createNarraMemBatchInputPages({
      batch_id: plan.batch.batch_id,
      payload: jsonValue(batchInput),
      created_at: createdAt,
    });
    await scope.store.commit({
      commit_id: `batch_ready:${plan.batch.batch_id}`,
      expected_generation: head?.generation ?? 0,
      expected_generation_checksum: head?.generation_checksum ?? null,
      committed_at: createdAt,
      source_index: {
        source_revision_id: projection.source_revision.revision_id,
        source_checksum: snapshot.checksum,
        valid_ai_count: plan.valid_ai_count,
        committed_eligible_count: committed,
        protected_ai_ordinals: plan.protected_ai_ordinals,
        completed_batches: head?.source_index.completed_batches ?? [],
        mutation_from_source_unit_id: null,
      },
      work_state: plan.batch,
      checkpoint_index: head?.checkpoint_index ?? {
        checkpoint_id: null,
        source_revision_id: null,
        covered_ai_ordinal: 0,
        recall_version: null,
        hidden_through_message_id: null,
        core_page_ids: [],
      },
      active_state: head?.active_state ?? {},
      epistemic_state: head?.epistemic_state ?? {},
      thread_impact: head?.thread_impact ?? {},
      module_views: head?.module_views ?? emptyModuleViews(),
      audit_ring: [
        ...(head?.audit_ring ?? []),
        {
          at: createdAt,
          batch_id: plan.batch.batch_id,
          module_id: null,
          event: `batch_ready:${trigger}`,
          error_code: null,
        },
      ],
      retained_core_page_ids: head?.core_page_ids ?? [],
      retained_module_view_page_ids: head?.module_view_page_ids ?? [],
      core_pages: inputPageSet.pages,
      module_view_pages: [],
    });
    this.options.on_diagnostic?.("modular_batch_input_persisted", {
      batch_id: plan.batch.batch_id,
      payload_utf8_bytes: inputPageSet.payload_utf8_bytes,
      chunk_count: inputPageSet.chunk_count,
      content_recorded: false,
    });
    await this.updateFromCurrent(scope, "batch_started");
    return true;
  }

  private async finalize(
    scope: ActiveScope,
    _head: TavernMemoryColdHead,
    batch: TavernMemoryBatchWorkState,
    input: StoredBatchInput,
    config: NarraMemModularRuntimeConfig,
  ): Promise<void> {
    const revalidation = await revalidateCommittedTavernMemoryModules({
      book_store: scope.store,
      input_context: this.coordinatorCommon(config, scope.store, input, batch).input_context,
      operation_id: `runtime:${batch.batch_id}:trusted-partition-revalidation`,
      committed_at: this.now(),
    });
    if (revalidation.status === "RECLASSIFIED") {
      this.options.on_diagnostic?.("modular_partitions_reclassified", {
        batch_id: batch.batch_id,
        affected_modules: revalidation.affected_modules,
        provider_dispatched: revalidation.provider_dispatched,
        content_recorded: false,
      });
      return;
    }
    const windows = validAiWindows(input.snapshot);
    const covered = windows[batch.last_ai_ordinal - 1];
    if (covered === undefined) throw new TypeError("批次覆盖的 AI 楼层不存在");
    const coveredMessageIndex = input.snapshot.messages.findIndex(
      (message) => message.source_unit_id === covered.assistant_source_unit_id,
    );
    if (coveredMessageIndex < 0) throw new TypeError("批次覆盖边界无法定位");
    const prefix = await createTavernSourceSnapshotPrefix(input.snapshot, coveredMessageIndex + 1);
    const batchUnits = new Set(batch.source_unit_ids);
    const novelEvidenceIds = input.projection.evidence_items
      .filter(
        (item) =>
          item.locator.external_id !== undefined && batchUnits.has(item.locator.external_id),
      )
      .map((item) => item.evidence_id);
    const moduleCalls = Object.fromEntries(
      TAVERN_MEMORY_MODULE_IDS.map((moduleId) => {
        const state = batch.modules[moduleId];
        return [
          moduleId,
          {
            base: state.base_calls,
            transport_retry: state.transport_retry_calls,
            continuation: state.continuation_calls,
            targeted_repair: state.targeted_repair_calls,
            manual_repair: state.manual_repair_calls,
          },
        ];
      }),
    );
    const result = await finalizeTavernMemoryBatch({
      book_store: scope.store,
      memory_set_id: scope.memory_set_id,
      memory_space_id: input.projection.memory_space.memory_space_id,
      branch_id: input.projection.memory_space.branch_id,
      source_revision_id: input.projection.source_revision.revision_id,
      memory_space: input.projection.memory_space,
      source_revision: input.projection.source_revision,
      source_entities: input.projection.source_entities,
      principal_entity_id: input.projection.principal_entity_id,
      source_snapshot: input.snapshot,
      checkpoint_source_prefix: prefix,
      evidence_items: input.projection.evidence_items,
      novel_evidence_ids: novelEvidenceIds,
      extractor: {
        model_id: config.requested_model_id,
        model_identity_assurance: "requested_not_attested",
        prompt_contract_version: "tavern-modular-0.1.0",
        prompt_body_sha256: await sha256DigestUtf8(config.prompt_contract_material),
        parameters_hash: await sha256DigestUtf8(config.parameters_material),
      },
      module_provenance: jsonValue({
        runtime_version: NARRAMEM_MODULAR_RUNTIME_VERSION,
        requested_model_id: config.requested_model_id,
        modules: moduleCalls,
      }),
      compiled_at: this.now(),
      operation_id: `runtime:${batch.batch_id}`,
      max_records_per_page: 48,
      max_page_utf8_bytes: 160_000,
      on_failure_diagnostic: (error) => {
        const descriptor = errorDescriptor(error);
        this.options.on_diagnostic?.("batch_finalization_failed", {
          batch_id: batch.batch_id,
          error_code: descriptor.code,
          content_recorded: false,
        });
      },
    });
    if (result.status === "FINALIZATION_FAILED") {
      throw Object.assign(new Error("七个模块已完成，但可信编译／Checkpoint 校验失败"), {
        code: result.error_code ?? "FINALIZATION_FAILED",
      });
    }
  }

  private async rollbackMutation(
    scope: ActiveScope,
    head: TavernMemoryColdHead,
    previous: TavernSourceSnapshot,
    current: TavernSourceSnapshot,
    currentWindows: readonly TavernValidAiWindow[],
  ): Promise<void> {
    const divergence = previous.messages.findIndex((message, index) => {
      const next = current.messages[index];
      return next === undefined || next.content_fingerprint !== message.content_fingerprint;
    });
    const dirtyIndex =
      divergence < 0 ? Math.min(previous.messages.length, current.messages.length) : divergence;
    const previousMessage = previous.messages[dirtyIndex] ?? previous.messages.at(-1);
    const currentMessage = current.messages[dirtyIndex] ?? current.messages.at(-1);
    const mutationMessage = currentMessage ?? previousMessage;
    if (mutationMessage === undefined) throw new TypeError("无法定位聊天变更边界");
    const assistantsBefore = previous.messages
      .slice(0, dirtyIndex)
      .filter((message) => message.role === "assistant" && message.narrative_text !== null).length;
    const mutationAiOrdinal = Math.max(1, assistantsBefore + 1);
    const currentProjection = await projectTavernCoreSource({
      snapshot: current,
      known_entities: [],
      event_type_vocabulary: [],
      state_key_vocabulary: [],
      claim_predicate_vocabulary: [],
      default_story_time: DEFAULT_STORY_TIME,
      created_at: this.now(),
    });
    const rollbackRequest = {
      book_store: scope.store,
      current_source_snapshot: current,
      new_source_revision_id: currentProjection.source_revision.revision_id,
      valid_ai_count: currentWindows.length,
      protected_ai_ordinals: currentWindows.slice(-4).map((item) => item.ai_ordinal),
      mutation_source_unit_id: mutationMessage.source_unit_id,
      mutation_message_id: mutationMessage.message_id_at_capture,
      mutation_ai_ordinal: mutationAiOrdinal,
    } as const;
    if (head.work_state !== null && !["COMPLETE", "INVALIDATED"].includes(head.work_state.status)) {
      await scope.store.commit({
        commit_id: `invalidate:${head.work_state.batch_id}:${mutationMessage.source_unit_id}`,
        expected_generation: head.generation,
        expected_generation_checksum: head.generation_checksum,
        committed_at: this.now(),
        source_index: head.source_index,
        work_state: invalidateTavernMemoryBatch(head.work_state),
        checkpoint_index: head.checkpoint_index,
        active_state: head.active_state,
        epistemic_state: head.epistemic_state,
        thread_impact: head.thread_impact,
        module_views: head.module_views,
        audit_ring: [
          ...head.audit_ring,
          {
            at: this.now(),
            batch_id: head.work_state.batch_id,
            module_id: null,
            event: "active_batch_invalidated_by_source_mutation",
            error_code: null,
          },
        ],
        retained_core_page_ids: head.core_page_ids,
        retained_module_view_page_ids: head.module_view_page_ids,
        core_pages: [],
        module_view_pages: [],
      });
    }
    const plan = await planTavernMemoryMutationRollback(rollbackRequest);
    const unhidden = await this.options.unhide_from(plan.unhide_from_message_id);
    await commitTavernMemoryMutationRollback({
      ...rollbackRequest,
      plan,
      unhidden_from_message_id: unhidden,
      operation_id: `runtime:mutation:${mutationMessage.source_unit_id}`,
      committed_at: this.now(),
    });
  }

  private async resolveScope(): Promise<ActiveScope | null> {
    const identity = this.options.host_port.getCurrentIdentity();
    if (identity.character_id === null || identity.chat_id === null) {
      this.scope = null;
      return null;
    }
    const scopeKey = `${identity.character_id}\u0000${identity.chat_id}`;
    if (this.scope?.scope_key === scopeKey) return this.scope;
    const hash = await sha256HexUtf8(
      `${this.options.host_user_id}\u0000${identity.character_id}\u0000${identity.chat_id}`,
    );
    const memorySetId = `memory_${hash.slice(0, 48)}`;
    const memoryBookName = `${BOOK_PREFIX}${memorySetId}`;
    const anchorHash = await checksumJson({
      host_user_id: this.options.host_user_id,
      character_id: identity.character_id,
      chat_id: identity.chat_id,
    });
    await new TavernMemoryRegistryStore(this.options.host_port).upsert(
      {
        status: "ACTIVE",
        host_user_id: this.options.host_user_id,
        chat_id: identity.chat_id,
        character_or_group_id: identity.character_id,
        memory_set_id: memorySetId,
        memory_book_name: memoryBookName,
        chat_anchor_hash: anchorHash,
      },
      `runtime_scope:${hash.slice(0, 40)}`,
    );
    const store = new TavernMemoryBookStore(this.options.host_port, {
      memory_set_id: memorySetId,
      book_name: memoryBookName,
      max_cold_head_utf8_bytes: 192_000,
      max_core_page_utf8_bytes: 192_000,
      max_audit_items: 160,
    });
    await store.initialize();
    this.scope = {
      scope_key: scopeKey,
      memory_set_id: memorySetId,
      memory_book_name: memoryBookName,
      store,
    };
    return this.scope;
  }

  private async captureCurrent(
    memorySetId: string,
    previous: TavernSourceSnapshot | null,
    hints: readonly TavernMutationHint[],
  ): Promise<TavernSourceSnapshot> {
    return (
      await reconcileTavernSourceSnapshot(this.options.host_port, {
        memory_set_id: memorySetId,
        previous_snapshot: previous,
        observed_hints: hints,
      })
    ).snapshot;
  }

  private async readBatchInput(
    store: TavernMemoryBookStore,
    head: TavernMemoryColdHead,
    batchId: string,
  ): Promise<StoredBatchInput> {
    for (const pageId of [...head.core_page_ids].reverse()) {
      const page = await store.readCorePage(pageId);
      const manifestRecord = page.records.find(
        (item) =>
          item.record_kind === NARRAMEM_BATCH_INPUT_MANIFEST_KIND &&
          item.record_id === `memory_batch_input_manifest:${batchId}`,
      );
      if (manifestRecord !== undefined) {
        const value = (await readNarraMemBatchInputManifest({
          manifest_payload: manifestRecord.payload,
          read_page: (chunkPageId) => store.readCorePage(chunkPageId),
        })) as unknown as StoredBatchInput;
        if (value.format !== BATCH_INPUT_KIND) throw new TypeError("批次 Source 分片格式无效");
        return value;
      }
      const record = page.records.find(
        (item) =>
          item.record_kind === BATCH_INPUT_KIND &&
          item.record_id === `memory_batch_input:${batchId}`,
      );
      if (record !== undefined) {
        const value = record.payload as unknown as StoredBatchInput;
        if (value.format !== BATCH_INPUT_KIND) throw new TypeError("批次 Source 页面格式无效");
        return value;
      }
    }
    throw new TypeError(`批次 ${batchId} 的 Source 页面缺失`);
  }

  private async readLatestCompletedInput(
    store: TavernMemoryBookStore,
    head: TavernMemoryColdHead,
  ): Promise<StoredBatchInput | null> {
    const latest = [...head.source_index.completed_batches].sort(
      (left, right) => right.last_ai_ordinal - left.last_ai_ordinal,
    )[0];
    return latest === undefined ? null : this.readBatchInput(store, head, latest.batch_id);
  }

  private async updateFromCurrent(scope: ActiveScope, reason: string): Promise<void> {
    const current = await this.captureCurrent(scope.memory_set_id, null, ["unknown"]);
    const windows = validAiWindows(current);
    const head = (await scope.store.readColdHead()).head;
    const committed = head?.source_index.committed_eligible_count ?? 0;
    const pending = Math.max(0, Math.max(0, windows.length - 4) - committed);
    this.publish(
      this.makeSnapshot(
        statusFromHead(head, pending),
        scope,
        head,
        head?.work_state ?? null,
        windows.length,
        pending,
        windows.slice(-4).map((item) => item.ai_ordinal),
        head?.work_state?.finalization_error_code ?? null,
        null,
      ),
    );
    this.options.on_diagnostic?.("modular_runtime_state", {
      reason,
      status: this.lastSnapshot.status,
      batch_status: this.lastSnapshot.batch_status,
      valid_ai_count: windows.length,
      committed_ai_count: committed,
      pending_eligible_ai_count: pending,
      content_recorded: false,
    });
  }

  private makeSnapshot(
    status: NarraMemModularRuntimeStatus,
    scope: ActiveScope | null,
    head: TavernMemoryColdHead | null,
    batch: TavernMemoryBatchWorkState | null,
    validAiCount: number,
    pendingEligible: number,
    protectedOrdinals: readonly number[],
    errorCode: string | null,
    errorMessage: string | null,
  ): NarraMemModularRuntimeSnapshot {
    return {
      runtime_version: NARRAMEM_MODULAR_RUNTIME_VERSION,
      status,
      memory_set_id: scope?.memory_set_id ?? null,
      memory_book_name: scope?.memory_book_name ?? null,
      valid_ai_count: validAiCount,
      committed_ai_count: head?.source_index.committed_eligible_count ?? 0,
      pending_eligible_ai_count: pendingEligible,
      protected_ai_ordinals: protectedOrdinals,
      batch_id: batch?.batch_id ?? null,
      batch_first_ai_ordinal: batch?.first_ai_ordinal ?? null,
      batch_last_ai_ordinal: batch?.last_ai_ordinal ?? null,
      batch_status: batch?.status ?? null,
      module_states: batch?.modules ?? null,
      active_module_id: activeModule(batch),
      checkpoint_id: head?.checkpoint_index.checkpoint_id ?? null,
      hidden_through_message_id: head?.checkpoint_index.hidden_through_message_id ?? null,
      last_error_code: errorCode,
      last_error_message: errorMessage,
      updated_at: this.now(),
    };
  }

  private publish(snapshot: NarraMemModularRuntimeSnapshot): void {
    this.lastSnapshot = snapshot;
    this.options.on_snapshot?.(structuredClone(snapshot));
  }

  private now(): string {
    return this.options.now?.() ?? new Date().toISOString();
  }
}
