export const HASH_ALGORITHMS = ["sha256"] as const;

export type HashAlgorithm = (typeof HASH_ALGORITHMS)[number];

export interface HashDigest {
  readonly algorithm: HashAlgorithm;
  readonly value: string;
}

const SHA256_PATTERN = /^[0-9a-f]{64}$/i;

export function createSha256Digest(value: string): HashDigest {
  if (!SHA256_PATTERN.test(value)) {
    throw new TypeError("A sha256 digest must contain exactly 64 hexadecimal characters");
  }

  return {
    algorithm: "sha256",
    value: value.toLowerCase(),
  };
}

export function isHashDigest(value: unknown): value is HashDigest {
  if (typeof value !== "object" || value === null) {
    return false;
  }

  const candidate = value as Partial<HashDigest>;
  return (
    candidate.algorithm === "sha256" &&
    typeof candidate.value === "string" &&
    SHA256_PATTERN.test(candidate.value)
  );
}
