import type { ModularExtractionInput } from "@narramem/core-domain";

import type { TavernJsonValue } from "./contracts.js";
import {
  TAVERN_MEMORY_MODULE_IDS,
  type TavernMemoryBatchWorkState,
  type TavernMemoryColdHead,
  type TavernMemoryCorePage,
  type TavernMemoryModuleId,
  type TavernMemoryModuleViewIndex,
  type TavernMemoryModuleViewItem,
  type TavernMemoryModuleViewPage,
} from "./memory-book-contracts.js";
import type { TavernMemoryBookStore } from "./memory-book-store.js";
import {
  acceptTavernMemoryModuleOutput,
  buildTavernMemoryModuleInput,
  type TavernMemoryAcceptedModuleOutputs,
  type TavernMemoryModuleInputContext,
} from "./memory-module-input.js";
import { readTavernMemoryModulePartition } from "./memory-module-runner.js";
import {
  partitionTavernModularExtractionOutput,
  type TavernModularCandidatePartition,
} from "./modular-candidate-partition.js";
import { canonicalJson, sha256HexUtf8 } from "./worldbook-codec.js";

export const TAVERN_MEMORY_MODULE_REVALIDATION_VERSION = "0.1.0" as const;

export interface TavernMemoryModuleRevalidationRequest {
  readonly book_store: TavernMemoryBookStore;
  readonly input_context: TavernMemoryModuleInputContext;
  readonly operation_id: string;
  readonly committed_at: string;
  readonly max_view_items_per_page?: number;
}

export interface TavernMemoryModuleRevalidationResult {
  readonly revalidation_version: typeof TAVERN_MEMORY_MODULE_REVALIDATION_VERSION;
  readonly status: "UNCHANGED" | "RECLASSIFIED";
  readonly affected_modules: readonly TavernMemoryModuleId[];
  readonly provider_dispatched: false;
  readonly head: TavernMemoryColdHead;
}

interface RevalidatedModule {
  readonly module_id: TavernMemoryModuleId;
  readonly input: ModularExtractionInput;
  readonly partition: TavernModularCandidatePartition;
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const asJsonValue = (value: unknown): TavernJsonValue => value as TavernJsonValue;

const unique = (values: readonly string[]): string[] => [...new Set(values)];

async function loadOriginalPartitions(
  store: TavernMemoryBookStore,
  batch: TavernMemoryBatchWorkState,
): Promise<ReadonlyMap<TavernMemoryModuleId, TavernModularCandidatePartition>> {
  const partitions = new Map<TavernMemoryModuleId, TavernModularCandidatePartition>();
  for (const moduleId of TAVERN_MEMORY_MODULE_IDS) {
    if (batch.modules[moduleId].status !== "COMMITTED") {
      throw new TypeError(`Cannot revalidate ${moduleId} before every module commits`);
    }
    const partition = await readTavernMemoryModulePartition(store, batch, moduleId);
    if (partition === null || !partition.complete) {
      throw new TypeError(`${moduleId} has no complete durable partition to revalidate`);
    }
    partitions.set(moduleId, partition);
  }
  return partitions;
}

function revalidatePartitions(
  originals: ReadonlyMap<TavernMemoryModuleId, TavernModularCandidatePartition>,
  context: TavernMemoryModuleInputContext,
): RevalidatedModule[] {
  let accepted: TavernMemoryAcceptedModuleOutputs = {};
  const results: RevalidatedModule[] = [];
  for (const moduleId of TAVERN_MEMORY_MODULE_IDS) {
    const original = originals.get(moduleId);
    if (original === undefined) throw new TypeError(`Missing durable ${moduleId} partition`);
    const input = buildTavernMemoryModuleInput(moduleId, context, accepted);
    const partition = partitionTavernModularExtractionOutput(original.accepted_output, input);
    results.push({ module_id: moduleId, input, partition });
    // Revalidate each module against the exact dependency snapshot it originally
    // consumed. A bad quote in M1 must not mechanically erase otherwise correct
    // M2–M7 records before the same candidate key can be repaired.
    accepted = acceptTavernMemoryModuleOutput(accepted, original.accepted_output);
  }
  return results;
}

async function candidateRecordIds(
  store: TavernMemoryBookStore,
  head: TavernMemoryColdHead,
): Promise<ReadonlyMap<TavernMemoryModuleId, ReadonlyMap<string, string>>> {
  const byModule = new Map<TavernMemoryModuleId, Map<string, string>>(
    TAVERN_MEMORY_MODULE_IDS.map((moduleId) => [moduleId, new Map()]),
  );
  for (const pageId of head.core_page_ids) {
    const page = await store.readCorePage(pageId);
    for (const record of page.records) {
      if (record.record_kind !== "module_candidate" || !isObject(record.payload)) continue;
      const moduleId = record.payload.module_id;
      const key = record.payload.candidate_key;
      if (
        typeof moduleId === "string" &&
        TAVERN_MEMORY_MODULE_IDS.includes(moduleId as TavernMemoryModuleId) &&
        typeof key === "string"
      ) {
        byModule.get(moduleId as TavernMemoryModuleId)?.set(key, record.record_id);
      }
    }
  }
  return byModule;
}

async function currentViewItems(
  store: TavernMemoryBookStore,
  head: TavernMemoryColdHead,
  moduleId: TavernMemoryModuleId,
): Promise<TavernMemoryModuleViewItem[]> {
  const items: TavernMemoryModuleViewItem[] = [];
  const seenPages = new Set<string>();
  let pageId = head.module_views[moduleId].latest_page_id;
  while (pageId !== null) {
    if (seenPages.has(pageId)) throw new TypeError(`${moduleId} view chain contains a cycle`);
    seenPages.add(pageId);
    const page = await store.readModuleViewPage(pageId);
    if (page.module_id !== moduleId) throw new TypeError(`${moduleId} view chain crossed modules`);
    items.push(...page.items);
    pageId = page.older_page_id;
  }
  const seenRecords = new Set<string>();
  return items.filter((item) => {
    if (seenRecords.has(item.record_id)) return false;
    seenRecords.add(item.record_id);
    return true;
  });
}

async function replacementViews(
  store: TavernMemoryBookStore,
  head: TavernMemoryColdHead,
  batch: TavernMemoryBatchWorkState,
  affected: readonly RevalidatedModule[],
  recordIds: ReadonlyMap<TavernMemoryModuleId, ReadonlyMap<string, string>>,
  operationId: string,
  maximum: number,
): Promise<{
  readonly indexes: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
  readonly pages: readonly TavernMemoryModuleViewPage[];
  readonly accepted_ids: ReadonlyMap<TavernMemoryModuleId, readonly string[]>;
  readonly retained_page_ids: readonly string[];
}> {
  const affectedIds = new Set(affected.map((item) => item.module_id));
  const allViewPages = await Promise.all(
    head.module_view_page_ids.map((pageId) => store.readModuleViewPage(pageId)),
  );
  const retainedPageIds = allViewPages
    .filter((page) => !affectedIds.has(page.module_id))
    .map((page) => page.page_id);
  const indexes = { ...head.module_views };
  const pages: TavernMemoryModuleViewPage[] = [];
  const acceptedIds = new Map<TavernMemoryModuleId, readonly string[]>();

  for (const item of affected) {
    const ids = unique(
      item.partition.accepted_record_keys.flatMap((key) => {
        const id = recordIds.get(item.module_id)?.get(key);
        return id === undefined ? [] : [id];
      }),
    );
    acceptedIds.set(item.module_id, ids);
    const acceptedSet = new Set(ids);
    const visible = (await currentViewItems(store, head, item.module_id)).filter((view) =>
      acceptedSet.has(view.record_id),
    );
    const chunks: TavernMemoryModuleViewItem[][] = [];
    for (let index = 0; index < visible.length; index += maximum) {
      chunks.push(visible.slice(index, index + maximum));
    }
    const pageIds = await Promise.all(
      chunks.map((chunk, index) =>
        sha256HexUtf8(
          canonicalJson({
            version: TAVERN_MEMORY_MODULE_REVALIDATION_VERSION,
            operation_id: operationId,
            generation: head.generation,
            batch_id: batch.batch_id,
            module_id: item.module_id,
            index,
            record_ids: chunk.map((view) => view.record_id),
          }),
        ).then((hash) => `module_revalidation_view_${hash.slice(0, 40)}`),
      ),
    );
    chunks.forEach((chunk, index) => {
      pages.push({
        page_id: pageIds[index] as string,
        module_id: item.module_id,
        newer_page_id: null,
        older_page_id: pageIds[index + 1] ?? null,
        items: chunk,
      });
    });
    const newest = visible[0];
    indexes[item.module_id] = {
      module_id: item.module_id,
      record_count: visible.length,
      abnormal_count: 0,
      newest_cursor:
        newest === undefined
          ? null
          : {
              sort_time: newest.sort_time,
              record_revision: newest.record_revision,
              record_id: newest.record_id,
            },
      latest_page_id: pageIds[0] ?? null,
      oldest_page_id: pageIds.at(-1) ?? null,
      page_count: pageIds.length,
    };
  }
  return {
    indexes,
    pages,
    accepted_ids: acceptedIds,
    retained_page_ids: retainedPageIds,
  };
}

/**
 * Replays the current trusted partition rules against legacy COMMITTED module
 * pages without contacting the Provider. Only newly-invalid candidates return
 * to NEEDS_USER; model call counters and accepted siblings are preserved.
 */
export async function revalidateCommittedTavernMemoryModules(
  request: TavernMemoryModuleRevalidationRequest,
): Promise<TavernMemoryModuleRevalidationResult> {
  if (request.operation_id.trim().length === 0 || request.committed_at.trim().length === 0) {
    throw new TypeError("Revalidation operation and timestamp must be non-empty");
  }
  const maximum = request.max_view_items_per_page ?? 24;
  if (!Number.isInteger(maximum) || maximum < 1) {
    throw new TypeError("Revalidation view page limit must be a positive integer");
  }
  const cold = await request.book_store.readColdHead();
  const head = cold.head;
  if (cold.status !== "READY" || head === null || head.work_state === null) {
    throw new TypeError("Memory Book has no cold batch to revalidate");
  }
  const batch = head.work_state;
  if (
    batch.status !== "FINALIZING" ||
    batch.batch_id !== request.input_context.batch_id ||
    batch.source_revision_id !== request.input_context.source_revision_id
  ) {
    return {
      revalidation_version: TAVERN_MEMORY_MODULE_REVALIDATION_VERSION,
      status: "UNCHANGED",
      affected_modules: [],
      provider_dispatched: false,
      head,
    };
  }

  const originals = await loadOriginalPartitions(request.book_store, batch);
  const revalidated = revalidatePartitions(originals, request.input_context);
  const affected = revalidated.filter((item) => !item.partition.complete);
  if (affected.length === 0) {
    return {
      revalidation_version: TAVERN_MEMORY_MODULE_REVALIDATION_VERSION,
      status: "UNCHANGED",
      affected_modules: [],
      provider_dispatched: false,
      head,
    };
  }

  const recordIds = await candidateRecordIds(request.book_store, head);
  const views = await replacementViews(
    request.book_store,
    head,
    batch,
    affected,
    recordIds,
    request.operation_id,
    maximum,
  );
  const partitionPages: TavernMemoryCorePage[] = await Promise.all(
    affected.map(async (item) => {
      const hash = await sha256HexUtf8(
        canonicalJson({
          version: TAVERN_MEMORY_MODULE_REVALIDATION_VERSION,
          operation_id: request.operation_id,
          generation: head.generation,
          batch_id: batch.batch_id,
          module_id: item.module_id,
          partition: item.partition,
        }),
      );
      const pageId = `module_revalidation_${hash.slice(0, 40)}`;
      return {
        page_id: pageId,
        records: [
          {
            record_id: `module_revalidation_partition_${hash.slice(0, 40)}`,
            record_kind: "module_candidate_partition",
            payload: asJsonValue(item.partition),
          },
        ],
      };
    }),
  );
  const pageByModule = new Map(
    affected.map((item, index) => [item.module_id, partitionPages[index]?.page_id as string]),
  );
  const affectedById = new Map(affected.map((item) => [item.module_id, item]));
  const modules = Object.fromEntries(
    TAVERN_MEMORY_MODULE_IDS.map((moduleId) => {
      const current = batch.modules[moduleId];
      const item = affectedById.get(moduleId);
      if (item === undefined) return [moduleId, current];
      const firstCode = item.partition.quarantined[0]?.diagnostic_codes[0];
      return [
        moduleId,
        {
          ...current,
          status: "NEEDS_USER" as const,
          accepted_record_ids: views.accepted_ids.get(moduleId) ?? [],
          pending_target_ids: item.partition.pending_target_ids,
          partition_page_id: pageByModule.get(moduleId) ?? current.partition_page_id,
          last_error_code: firstCode ?? "MODULE_TARGETS_PENDING",
        },
      ];
    }),
  ) as unknown as TavernMemoryBatchWorkState["modules"];
  const pendingTargets = unique(affected.flatMap((item) => item.partition.pending_target_ids));
  const workState: TavernMemoryBatchWorkState = {
    ...batch,
    status: "NEEDS_USER",
    modules,
    finalization_error_code: null,
    finalization_error_target_ids: pendingTargets,
  };
  const committed = await request.book_store.commit({
    commit_id: `${request.operation_id}:reclassified:${head.generation}`,
    expected_generation: head.generation,
    expected_generation_checksum: head.generation_checksum,
    committed_at: request.committed_at,
    source_index: head.source_index,
    work_state: workState,
    checkpoint_index: head.checkpoint_index,
    active_state: head.active_state,
    epistemic_state: head.epistemic_state,
    thread_impact: head.thread_impact,
    module_views: views.indexes,
    audit_ring: [
      ...head.audit_ring,
      ...affected.map((item) => ({
        at: request.committed_at,
        batch_id: batch.batch_id,
        module_id: item.module_id,
        event: "module_local_revalidated",
        error_code: item.partition.quarantined[0]?.diagnostic_codes[0] ?? "MODULE_TARGETS_PENDING",
      })),
    ],
    retained_core_page_ids: head.core_page_ids,
    retained_module_view_page_ids: views.retained_page_ids,
    core_pages: partitionPages,
    module_view_pages: views.pages,
  });
  return {
    revalidation_version: TAVERN_MEMORY_MODULE_REVALIDATION_VERSION,
    status: "RECLASSIFIED",
    affected_modules: affected.map((item) => item.module_id),
    provider_dispatched: false,
    head: committed,
  };
}
