import type {
  CausalLink,
  DerivationMeta,
  DerivedRecord,
  Episode,
  EventAtom,
  EvidenceSpan,
  ModularEpisodeAnchorCandidate,
  NarraMemId,
  Scene,
  StateDelta,
} from "@narramem/core-domain";

import { createDeterministicNarraMemId } from "./core-source-projection.js";
import { canonicalJson } from "./worldbook-codec.js";

export const TAVERN_SCENE_EPISODE_PROJECTOR_VERSION = "0.1.0" as const;

export interface TavernSceneEpisodeProjectionRequest {
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly derived_records: readonly DerivedRecord[];
  readonly created_at: string;
  /** Optional M2 grouping; omitted callers retain the historical one-Scene projection. */
  readonly episode_anchors?: readonly ModularEpisodeAnchorCandidate[];
  readonly scene_id_by_candidate_key?: ReadonlyMap<string, NarraMemId<"scene">>;
}

function compareOrder(
  left: { readonly ordinal: number; readonly component: number },
  right: { readonly ordinal: number; readonly component: number },
): number {
  return left.ordinal === right.ordinal
    ? left.component - right.component
    : left.ordinal - right.ordinal;
}

function uniqueStrings<T extends string>(values: readonly T[]): T[] {
  return [...new Set(values)].sort();
}

function uniqueEvidence(values: readonly EvidenceSpan[]): EvidenceSpan[] {
  const byValue = new Map(values.map((value) => [canonicalJson(value), value]));
  return [...byValue.values()].sort((left, right) =>
    canonicalJson(left).localeCompare(canonicalJson(right)),
  );
}

function episodeTitle(scene: Scene, events: readonly EventAtom[]): string {
  const firstAction = events[0]?.action_or_occurrence.trim();
  if (firstAction !== undefined && firstAction.length > 0) {
    return [...firstAction].slice(0, 80).join("");
  }
  const start = scene.source_range.start.ordinal;
  const end = scene.source_range.end.ordinal;
  return start === end ? `Scene ${start}` : `Scene ${start}–${end}`;
}

function episodeGist(events: readonly EventAtom[]): string {
  return events.map((event) => event.action_or_occurrence).join("\n");
}

function sceneRecords(records: readonly DerivedRecord[]): Scene[] {
  return records
    .filter((record): record is Scene => "scene_id" in record)
    .sort(
      (left, right) =>
        compareOrder(left.source_range.start, right.source_range.start) ||
        left.scene_id.localeCompare(right.scene_id),
    );
}

function eventRecords(records: readonly DerivedRecord[]): EventAtom[] {
  return records
    .filter((record): record is EventAtom => "event_id" in record)
    .sort(
      (left, right) =>
        compareOrder(left.source_range.start, right.source_range.start) ||
        left.event_id.localeCompare(right.event_id),
    );
}

function stateDeltaRecords(records: readonly DerivedRecord[]): StateDelta[] {
  return records.filter((record): record is StateDelta => "delta_id" in record);
}

function causalLinkRecords(records: readonly DerivedRecord[]): CausalLink[] {
  return records.filter((record): record is CausalLink => "causal_id" in record);
}

function causalEndpointRecordIds(link: CausalLink): NarraMemId[] {
  const ids: NarraMemId[] = [];
  for (const reference of link.cause_refs) {
    if (reference.kind === "event") ids.push(reference.event_id);
    if (reference.kind === "state_assertion") ids.push(reference.assertion_id);
    if (reference.kind === "state_delta") ids.push(reference.delta_id);
    if (reference.kind === "epistemic_state") ids.push(reference.epistemic_id);
    if (reference.kind === "proposition") ids.push(reference.proposition_id);
    if (reference.kind === "narrative_thread") ids.push(reference.thread_id);
  }
  for (const reference of link.effect_refs) {
    if (reference.kind === "event") ids.push(reference.event_id);
    if (reference.kind === "state_delta") ids.push(reference.delta_id);
    if (reference.kind === "epistemic_state") ids.push(reference.epistemic_id);
    if (reference.kind === "narrative_thread") ids.push(reference.thread_id);
  }
  return ids;
}

export async function projectTavernSceneEpisodes(
  request: TavernSceneEpisodeProjectionRequest,
): Promise<readonly Episode[]> {
  const scenes = sceneRecords(request.derived_records);
  const events = eventRecords(request.derived_records);
  const stateDeltas = stateDeltaRecords(request.derived_records);
  const causalLinks = causalLinkRecords(request.derived_records);
  const episodes: Episode[] = [];
  const claimedEvents = new Set<NarraMemId<"event">>();

  for (const scene of scenes) {
    if (scene.source_revision_id !== request.source_revision_id) {
      throw new TypeError("Tavern Scene belongs to another SourceRevision");
    }
    const sceneEvents = events.filter((event) =>
      event.derivation.dependency_refs.includes(scene.scene_id),
    );
    if (sceneEvents.length === 0) continue;
    if (
      sceneEvents.some(
        (event) =>
          event.memory_space_id !== scene.memory_space_id ||
          event.branch_id !== scene.branch_id ||
          event.derivation.input_revision_id !== request.source_revision_id ||
          claimedEvents.has(event.event_id),
      )
    ) {
      throw new TypeError("Tavern Event cannot be projected into this Scene Episode");
    }
    for (const event of sceneEvents) claimedEvents.add(event.event_id);

    const sceneEventIds = new Set(sceneEvents.map((event) => event.event_id));
    const outcomes = stateDeltas.filter((delta) =>
      [...(delta.caused_by ?? []), ...(delta.cooccurs_with ?? [])].some((eventId) =>
        sceneEventIds.has(eventId),
      ),
    );
    const episodeRecordIds = new Set<NarraMemId>([
      ...sceneEventIds,
      ...outcomes.map((delta) => delta.delta_id),
    ]);
    const episodeCausalLinks = causalLinks.filter((link) =>
      causalEndpointRecordIds(link).some((recordId) => episodeRecordIds.has(recordId)),
    );

    const episodeId = await createDeterministicNarraMemId(
      "episode",
      `tavern-scene-episode:${request.source_revision_id}:${scene.scene_id}`,
    );
    const evidence = uniqueEvidence([
      ...scene.evidence,
      ...sceneEvents.flatMap((event) => event.evidence),
      ...outcomes.flatMap((delta) => delta.evidence),
      ...episodeCausalLinks.flatMap((link) => [...link.support, ...link.counterevidence]),
    ]);
    const derivation: DerivationMeta = {
      derivation_id: await createDeterministicNarraMemId(
        "derivation",
        `tavern-scene-episode-derivation:${request.source_revision_id}:${scene.scene_id}`,
      ),
      input_revision_id: request.source_revision_id,
      evidence_refs: uniqueStrings(evidence.map((span) => span.evidence_id)),
      dependency_refs: [
        scene.scene_id,
        ...sceneEvents.map((event) => event.event_id),
        ...outcomes.map((delta) => delta.delta_id),
        ...episodeCausalLinks.map((link) => link.causal_id),
      ],
      extractor: { kind: "rule" },
      validator_version: `tavern-scene-episode-projector@${TAVERN_SCENE_EPISODE_PROJECTOR_VERSION}`,
      created_at: request.created_at,
    };
    episodes.push({
      episode_id: episodeId,
      memory_space_id: scene.memory_space_id,
      branch_id: scene.branch_id,
      scene_ids: [scene.scene_id],
      experiencer_ids: uniqueStrings([
        ...scene.participant_ids,
        ...sceneEvents.flatMap((event) => [...event.actor_ids, ...(event.patient_ids ?? [])]),
      ]),
      title: episodeTitle(scene, sceneEvents),
      reconstruction_gist: episodeGist(sceneEvents),
      event_ids: sceneEvents.map((event) => event.event_id),
      context: {
        before_state_refs: [],
        ...(scene.atmosphere === undefined ? {} : { emotional_climate: scene.atmosphere }),
      },
      outcome_refs: outcomes.map((delta) => delta.delta_id),
      causal_refs: episodeCausalLinks.map((link) => link.causal_id),
      narrative_thread_refs: [],
      salience_assessment_refs: [],
      evidence,
      derivation,
    });
  }

  if (request.episode_anchors === undefined || request.episode_anchors.length === 0) {
    return episodes;
  }
  if (request.scene_id_by_candidate_key === undefined) {
    throw new TypeError("M2 Episode anchors require the compiled Scene candidate map");
  }

  const episodeByScene = new Map(
    episodes.flatMap((episode) =>
      episode.scene_ids.length === 1
        ? [[episode.scene_ids[0] as NarraMemId<"scene">, episode] as const]
        : [],
    ),
  );
  const anchoredSceneIds = new Set<NarraMemId<"scene">>();
  const grouped: Episode[] = [];
  for (const anchor of request.episode_anchors) {
    const sceneIds = anchor.scene_candidate_keys.map((key) => {
      const sceneId = request.scene_id_by_candidate_key?.get(key);
      if (sceneId === undefined)
        throw new TypeError(`Episode anchor references unknown Scene ${key}`);
      if (anchoredSceneIds.has(sceneId)) {
        throw new TypeError(`Scene ${key} belongs to more than one Episode anchor`);
      }
      anchoredSceneIds.add(sceneId);
      return sceneId;
    });
    const members = sceneIds.map((sceneId) => {
      const episode = episodeByScene.get(sceneId);
      if (episode === undefined) {
        throw new TypeError(`Episode anchor Scene ${sceneId} has no compiled Event`);
      }
      return episode;
    });
    const first = members[0];
    if (first === undefined) throw new TypeError("Episode anchor has no Scene");
    if (
      members.some(
        (episode) =>
          episode.memory_space_id !== first.memory_space_id ||
          episode.branch_id !== first.branch_id,
      )
    ) {
      throw new TypeError("Episode anchor crosses a trusted memory scope");
    }
    const evidence = uniqueEvidence(members.flatMap((episode) => episode.evidence));
    const dependencyRefs = uniqueStrings(
      members.flatMap((episode) => [
        ...episode.scene_ids,
        ...episode.event_ids,
        ...episode.outcome_refs,
        ...episode.causal_refs,
      ]),
    );
    const episodeId = await createDeterministicNarraMemId(
      "episode",
      `tavern-module-episode:${request.source_revision_id}:${anchor.candidate_key}`,
    );
    grouped.push({
      episode_id: episodeId,
      memory_space_id: first.memory_space_id,
      branch_id: first.branch_id,
      scene_ids: uniqueStrings(sceneIds),
      experiencer_ids: uniqueStrings(members.flatMap((episode) => episode.experiencer_ids)),
      title: anchor.title,
      reconstruction_gist: anchor.summary,
      event_ids: uniqueStrings(members.flatMap((episode) => episode.event_ids)),
      context: {
        before_state_refs: uniqueStrings(
          members.flatMap((episode) => episode.context.before_state_refs),
        ),
        ...(members.some((episode) => episode.context.emotional_climate !== undefined)
          ? {
              emotional_climate: {
                labels: uniqueStrings(
                  members.flatMap((episode) => episode.context.emotional_climate?.labels ?? []),
                ),
                evidence: uniqueEvidence(
                  members.flatMap((episode) => episode.context.emotional_climate?.evidence ?? []),
                ),
                ...(members.some(
                  (episode) => episode.context.emotional_climate?.intensity !== undefined,
                )
                  ? {
                      intensity: Math.max(
                        ...members.flatMap((episode) =>
                          episode.context.emotional_climate?.intensity === undefined
                            ? []
                            : [episode.context.emotional_climate.intensity],
                        ),
                      ),
                    }
                  : {}),
              },
            }
          : {}),
      },
      outcome_refs: uniqueStrings(members.flatMap((episode) => episode.outcome_refs)),
      causal_refs: uniqueStrings(members.flatMap((episode) => episode.causal_refs)),
      narrative_thread_refs: [],
      salience_assessment_refs: [],
      evidence,
      derivation: {
        derivation_id: await createDeterministicNarraMemId(
          "derivation",
          `tavern-module-episode-derivation:${request.source_revision_id}:${anchor.candidate_key}`,
        ),
        input_revision_id: request.source_revision_id,
        evidence_refs: uniqueStrings([
          ...anchor.evidence_ids,
          ...evidence.map((span) => span.evidence_id),
        ]),
        dependency_refs: dependencyRefs,
        extractor: { kind: "rule" },
        validator_version: `tavern-scene-episode-projector@${TAVERN_SCENE_EPISODE_PROJECTOR_VERSION}`,
        created_at: request.created_at,
      },
    });
  }

  return [
    ...episodes.filter((episode) => !episode.scene_ids.some((id) => anchoredSceneIds.has(id))),
    ...grouped,
  ];
}
