function toJsonValue(value: unknown): TavernJsonValue {
  canonicalJson(value);
  return value as TavernJsonValue;
}

const coreRecord = (
  recordId: string,
  recordKind: string,
  payload: unknown,
): TavernArchiveRecord => ({
  record_id: recordId,
  record_kind: recordKind,
  payload: toJsonValue(payload),
});

function assertWire(name: Parameters<typeof validateWireValue>[0], value: unknown): void {
  const report = validateWireValue(name, value);
  if (!report.valid) {
    const first = report.errors[0];
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      `${name} failed Core wire validation at ${first?.instancePath || "/"}: ${first?.message ?? "invalid"}`,
    );
  }
}

function recordValues<T>(
  records: readonly TavernArchiveRecord[],
  recordKind: string,
  schemaName: Parameters<typeof validateWireValue>[0],
  idOf: (value: T) => NarraMemId,
): T[] {
  const values: T[] = [];
  const seen = new Set<NarraMemId>();
  for (const record of records) {
    if (record.record_kind !== recordKind) continue;
    assertWire(schemaName, record.payload);
    const value = record.payload as unknown as T;
    const id = idOf(value);
    if (record.record_id !== id || seen.has(id)) {
      throw new TavernNarrativeLifecycleError(
        "INVALID_INPUT",
        `Duplicate or mismatched ${recordKind} record`,
      );
    }
    seen.add(id);
    values.push(value);
  }
  return values;
}

function singleRecord<T>(
  records: readonly TavernArchiveRecord[],
  recordKind: string,
  schemaName: Parameters<typeof validateWireValue>[0],
  idOf: (value: T) => NarraMemId,
): T {
  const values = recordValues(records, recordKind, schemaName, idOf);
  if (values.length !== 1) {
    throw new TavernNarrativeLifecycleError(
      "NO_SEMANTIC_SOURCE",
      `Lifecycle requires exactly one ${recordKind}`,
    );
  }
  return values[0] as T;
}

function unique<T>(values: readonly T[]): T[] {
  return [...new Set(values)];
}

function uniqueEvidence(spans: readonly EvidenceSpan[]): EvidenceSpan[] {
  const seen = new Set<string>();
  return spans.filter((span) => {
    const key = canonicalJson(span);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function eventContinuityKey(event: EventAtom): string {
  return canonicalJson({
    event_type: event.event_type,
    actor_ids: [...event.actor_ids].sort(),
    patient_ids: [...(event.patient_ids ?? [])].sort(),
    action_or_occurrence: event.action_or_occurrence,
    location_ids: [...(event.location_ids ?? [])].sort(),
    story_time: event.story_time,
    source_range: event.source_range,
    discourse_reveal_order: event.discourse_reveal_order ?? null,
    intentionality: event.intentionality,
    evidence_ids: event.evidence.map((span) => span.evidence_id).sort(),
  });
}

function stateDeltaContinuityKey(delta: StateDelta): string {
  return canonicalJson({
    subject: delta.subject,
    state_key: delta.state_key,
    operation: delta.operation,
    before: delta.before ?? null,
    after: delta.after ?? null,
    magnitude: delta.magnitude ?? null,
    valid_from: delta.valid_from,
    valid_until: delta.valid_until ?? null,
    evidence_ids: delta.evidence.map((span) => span.evidence_id).sort(),
  });
}

function continuityIdMap<T extends { readonly evidence: readonly EvidenceSpan[] }>(
  prior: readonly T[],
  current: readonly T[],
  idOf: (value: T) => NarraMemId,
  keyOf: (value: T) => string,
): ReadonlyMap<NarraMemId, NarraMemId> {
  const currentByKey = new Map<string, NarraMemId[]>();
  for (const value of current) {
    const key = keyOf(value);
    currentByKey.set(key, [...(currentByKey.get(key) ?? []), idOf(value)]);
  }
  const result = new Map<NarraMemId, NarraMemId>();
  for (const value of prior) {
    const matches = currentByKey.get(keyOf(value)) ?? [];
    if (matches.length === 1) result.set(idOf(value), matches[0] as NarraMemId);
  }
  return result;
}

export function readTavernNarrativeLifecycleManifestFromArchive(
  records: readonly TavernArchiveRecord[],
): TavernNarrativeLifecycleManifestPayload | null {
  const manifests = records.filter(
    (record) => record.record_id === TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_ID,
  );
  if (manifests.length === 0) return null;
  if (
    manifests.length !== 1 ||
    manifests[0]?.record_kind !== TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_KIND
  ) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      "Invalid lifecycle manifest multiplicity",
    );
  }
  const value = manifests[0].payload;
  const keys = [
    "version",
    "source_revision_id",
    "source_checksum",
    "semantic_changeset_id",
    "spec_checksum",
    "lifecycle_changeset_id",
    "model_id",
    "model_identity_assurance",
    "prompt_contract_version",
    "prompt_body_sha256",
    "parameters_hash",
    "validator_version",
  ];
  if (
    value === null ||
    typeof value !== "object" ||
    Array.isArray(value) ||
    Object.keys(value).length !== keys.length ||
    !keys.every((key) => Object.hasOwn(value, key))
  ) {
    throw new TavernNarrativeLifecycleError("INVALID_INPUT", "Lifecycle manifest shape is invalid");
  }
  const manifest = value as Readonly<Record<string, unknown>>;
  if (
    (manifest.version !== TAVERN_NARRATIVE_LIFECYCLE_LEGACY_VERSION &&
      manifest.version !== TAVERN_NARRATIVE_LIFECYCLE_VERSION) ||
    getNarraMemIdKind(manifest.source_revision_id) !== "source_revision" ||
    typeof manifest.source_checksum !== "string" ||
    !SHA256_PATTERN.test(manifest.source_checksum) ||
    getNarraMemIdKind(manifest.semantic_changeset_id) !== "change_set" ||
    typeof manifest.spec_checksum !== "string" ||
    !SHA256_PATTERN.test(manifest.spec_checksum) ||
    getNarraMemIdKind(manifest.lifecycle_changeset_id) !== "change_set" ||
    typeof manifest.model_id !== "string" ||
    manifest.model_id.length === 0 ||
    manifest.model_identity_assurance !== "requested_not_attested" ||
    typeof manifest.prompt_contract_version !== "string" ||
    manifest.prompt_contract_version.length === 0 ||
    !isHashDigest(manifest.prompt_body_sha256) ||
    !isHashDigest(manifest.parameters_hash) ||
    typeof manifest.validator_version !== "string" ||
    manifest.validator_version.length === 0
  ) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      "Lifecycle manifest values are invalid",
    );
  }
  return manifest as unknown as TavernNarrativeLifecycleManifestPayload;
}

function oldLifecycleChangesetId(
  records: readonly TavernArchiveRecord[],
): NarraMemId<"change_set"> | null {
  return readTavernNarrativeLifecycleManifestFromArchive(records)?.lifecycle_changeset_id ?? null;
}

function withoutOldLifecycle(records: readonly TavernArchiveRecord[]): TavernArchiveRecord[] {
  const oldChangesetId = oldLifecycleChangesetId(records);
  return records.filter(
    (record) =>
      !LIFECYCLE_RECORD_KINDS.has(record.record_kind) &&
      record.record_id !== TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_ID &&
      record.record_id !== TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_ID &&
      record.record_id !== oldChangesetId,
  );
}

function lifecycleContinuityBaseline(
  records: readonly TavernArchiveRecord[],
): TavernNarrativeLifecycleTask["continuity_baseline"] {
  try {
    return readTavernNarrativeLifecycleContinuityBaselineFromArchive(records);
  } catch (error) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      error instanceof Error
        ? `Invalid lifecycle continuity baseline: ${error.message}`
        : "Invalid lifecycle continuity baseline",
    );
  }
}

const TERMINAL_THREAD_STATES = new Set<NarrativeThreadState>([
  "resolved",
  "failed",
  "abandoned",
  "superseded",
]);
const TERMINAL_IMPACT_STATES = new Set<FutureImpactState>([
  "realized",
  "expired",
  "cancelled",
  "superseded",
]);

function modelInput(
  records: readonly TavernArchiveRecord[],
  baseline: TavernNarrativeLifecycleTask["continuity_baseline"],
): TavernNarrativeLifecycleModelInput {
  const revision = singleRecord<SourceRevision>(
    records,
    "core_source_revision_v1",
    "source_revision",
    (value) => value.revision_id,
  );
  const priorThreads =
    baseline?.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION
      ? baseline.narrative_threads.filter((thread) => !TERMINAL_THREAD_STATES.has(thread.state))
      : [];
  const priorImpacts =
    baseline?.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION
      ? baseline.future_impacts.filter((impact) => !TERMINAL_IMPACT_STATES.has(impact.state))
      : [];
  return {
    contract_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
    source_revision_id: revision.revision_id,
    append_evidence_boundary_ordinal:
      baseline?.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION
        ? baseline.previous_source_max_ordinal
        : null,
    prior_threads: priorThreads,
    prior_future_impacts: priorImpacts,
    entities: recordValues<Entity>(records, "core_entity_v1", "entity", (value) => value.entity_id),
    events: recordValues<EventAtom>(
      records,
      "core_event_v1",
      "event_atom",
      (value) => value.event_id,
    ),
    episodes: recordValues<Episode>(
      records,
      "core_episode_v1",
      "episode",
      (value) => value.episode_id,
    ),
    state_assertions: recordValues<StateAssertion>(
      records,
      "core_state_assertion_v1",
      "state_assertion",
      (value) => value.assertion_id,
    ),
    state_deltas: recordValues<StateDelta>(
      records,
      "core_state_delta_v1",
      "state_delta",
      (value) => value.delta_id,
    ),
    causal_links: recordValues<CausalLink>(
      records,
      "core_causal_link_v1",
      "causal_link",
      (value) => value.causal_id,
    ),
  };
}

export function validateTavernNarrativeLifecycleSpec(
  spec: TavernNarrativeLifecycleSpec,
  input: TavernNarrativeLifecycleModelInput,
): void {
  if (
    spec.contract_version !== TAVERN_NARRATIVE_LIFECYCLE_VERSION ||
    spec.source_revision_id !== input.source_revision_id ||
    spec.spec_id.trim().length === 0
  ) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      "Lifecycle spec does not target the prepared source revision",
    );
  }
  const allKeys = [...spec.threads, ...spec.future_impacts].map((item) => item.spec_key);
  if (allKeys.some((key) => key.trim().length === 0) || new Set(allKeys).size !== allKeys.length) {
    throw new TavernNarrativeLifecycleError(
      "INVALID_INPUT",
      "Lifecycle spec keys must be non-empty and unique",
    );
  }
  const entityIds = new Set(input.entities.map((entity) => entity.entity_id));
  const eventIds = new Set(input.events.map((event) => event.event_id));
  const deltaIds = new Set(input.state_deltas.map((delta) => delta.delta_id));
  const priorThreads = new Map(input.prior_threads.map((thread) => [thread.thread_id, thread]));
  const priorImpacts = new Map(
    input.prior_future_impacts.map((impact) => [impact.impact_id, impact]),
  );
  const threadDispositionIds = spec.prior_thread_dispositions.map((item) => item.prior_thread_id);
  const impactDispositionIds = spec.prior_future_impact_dispositions.map(
    (item) => item.prior_impact_id,
  );
  if (
    new Set(threadDispositionIds).size !== threadDispositionIds.length ||
    threadDispositionIds.length !== priorThreads.size ||
    threadDispositionIds.some((id) => !priorThreads.has(id)) ||
    new Set(impactDispositionIds).size !== impactDispositionIds.length ||
    impactDispositionIds.length !== priorImpacts.size ||
    impactDispositionIds.some((id) => !priorImpacts.has(id))
  ) {
    throw new TavernNarrativeLifecycleError(
      "LIFECYCLE_CONTINUITY_UNEXPLAINED",
      "Lifecycle spec must cover every authenticated prior record exactly once",
    );
  }
  const threadTransitions: Readonly<Record<NarrativeThreadState, readonly NarrativeThreadState[]>> =
    {
      latent: ["latent", "open", "armed", "abandoned", "superseded"],
      open: ["open", "armed", "triggered", "resolved", "failed", "abandoned", "superseded"],
      armed: ["armed", "triggered", "resolved", "failed", "abandoned", "superseded"],
      triggered: ["triggered", "resolved", "failed", "abandoned", "superseded"],
      resolved: ["resolved"],
      failed: ["failed"],
      abandoned: ["abandoned"],
      superseded: ["superseded"],
    };
  const impactTransitions: Readonly<Record<FutureImpactState, readonly FutureImpactState[]>> = {
    candidate: [
      "candidate",
      "armed",
      "matched",
      "surfaced",
      "realized",
      "expired",
      "cancelled",
      "superseded",
    ],
    armed: ["armed", "matched", "surfaced", "realized", "expired", "cancelled", "superseded"],
    matched: ["matched", "surfaced", "realized", "expired", "cancelled", "superseded"],
    surfaced: ["surfaced", "realized", "expired", "cancelled", "superseded"],
    realized: ["realized"],
    expired: ["expired"],
    cancelled: ["cancelled"],
    superseded: ["superseded"],
  };
  const eventMap = new Map(input.events.map((event) => [event.event_id, event]));
  const deltaMap = new Map(input.state_deltas.map((delta) => [delta.delta_id, delta]));
  const eventIsAppended = (event: EventAtom) =>
    input.append_evidence_boundary_ordinal !== null &&
    event.source_range.end.ordinal > input.append_evidence_boundary_ordinal;
  for (const disposition of spec.prior_thread_dispositions) {
    const prior = priorThreads.get(disposition.prior_thread_id) as NarrativeThread;
    const events = disposition.transition_event_ids.map((id) => eventMap.get(id));
    const changed = disposition.next_state !== prior.state;
    if (
      !threadTransitions[prior.state].includes(disposition.next_state) ||
      events.some((event) => event === undefined) ||
      (changed && (events.length === 0 || !(events as EventAtom[]).some(eventIsAppended))) ||
      (!changed && events.length !== 0)
    ) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `Thread ${disposition.prior_thread_id} transition is not evidence-backed`,
      );
    }
  }
  for (const disposition of spec.prior_future_impact_dispositions) {
    const prior = priorImpacts.get(disposition.prior_impact_id) as FutureImpact;
    const references = disposition.transition_refs.map((reference) => ({
      reference,
      value:
        reference.kind === "event"
          ? eventMap.get(reference.event_id)
          : deltaMap.get(reference.delta_id),
    }));
    const hasAppendedEvidence = references.some(({ reference, value }) => {
      if (value === undefined) return false;
      if (reference.kind === "event") return eventIsAppended(value as EventAtom);
      const delta = value as StateDelta;
      return [...(delta.caused_by ?? []), ...(delta.cooccurs_with ?? [])].some((eventId) => {
        const event = eventMap.get(eventId);
        return event !== undefined && eventIsAppended(event);
      });
    });
    const changed = disposition.next_state !== prior.state;
    if (
      !impactTransitions[prior.state].includes(disposition.next_state) ||
      references.some(({ value: reference }) => reference === undefined) ||
      (changed && (references.length === 0 || !hasAppendedEvidence)) ||
      (!changed && references.length !== 0)
    ) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `FutureImpact ${disposition.prior_impact_id} transition is not evidence-backed`,
      );
    }
  }
  for (const thread of spec.threads) {
    if (
      thread.title.trim().length === 0 ||
      thread.participant_ids.length === 0 ||
      thread.participant_ids.some((id) => !entityIds.has(id)) ||
      thread.opened_by.length === 0 ||
      thread.opened_by.some((id) => !eventIds.has(id))
    ) {
      throw new TavernNarrativeLifecycleError(
        "INVALID_INPUT",
        `Thread ${thread.spec_key} has an unresolved Entity or opening Event`,
      );
    }
  }
  for (const impact of spec.future_impacts) {
    if (
      impact.origin_refs.length === 0 ||
      impact.target_refs.length === 0 ||
      impact.target_refs.some((id) => !entityIds.has(id)) ||
      impact.origin_refs.some((id) => {
        const kind = getNarraMemIdKind(id);
        return (
          (kind === "event" && !eventIds.has(id as NarraMemId<"event">)) ||
          (kind === "state_delta" && !deltaIds.has(id as NarraMemId<"state_delta">)) ||
          (kind !== "event" && kind !== "state_delta" && kind !== "narrative_thread")
        );
      })
    ) {
      throw new TavernNarrativeLifecycleError(
        "INVALID_INPUT",
        `FutureImpact ${impact.spec_key} has an unresolved origin or target`,
      );
    }
  }
}

export interface TavernNarrativeLifecycleProjectionRequest {
  readonly memory_set_id: string;
  readonly extractor: TavernNarrativeLifecycleCommitRequest["extractor"];
  readonly compiled_at: string;
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly continuity_baseline: TavernNarrativeLifecycleTask["continuity_baseline"];
}

export async function projectTavernNarrativeLifecycleRecords(
  spec: TavernNarrativeLifecycleSpec,
  input: TavernNarrativeLifecycleModelInput,
  request: TavernNarrativeLifecycleProjectionRequest,
): Promise<{ readonly threads: NarrativeThread[]; readonly impacts: FutureImpact[] }> {
  const eventMap = new Map(input.events.map((event) => [event.event_id, event]));
  const deltaMap = new Map(input.state_deltas.map((delta) => [delta.delta_id, delta]));
  const priorEvents =
    request.continuity_baseline?.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION
      ? request.continuity_baseline.semantic_events
      : [];
  const priorDeltas =
    request.continuity_baseline?.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION
      ? request.continuity_baseline.semantic_state_deltas
      : [];
  const eventRebindings = continuityIdMap(
    priorEvents,
    input.events,
    (event) => event.event_id,
    eventContinuityKey,
  );
  const deltaRebindings = continuityIdMap(
    priorDeltas,
    input.state_deltas,
    (delta) => delta.delta_id,
    stateDeltaContinuityKey,
  );
  const rebindDependency = (id: NarraMemId): NarraMemId => {
    const kind = getNarraMemIdKind(id);
    const rebound =
      kind === "event"
        ? eventRebindings.get(id)
        : kind === "state_delta"
          ? deltaRebindings.get(id)
          : id;
    if (rebound === undefined) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `Prior ${kind ?? "record"} ${id} cannot be rebound into the current semantic graph`,
      );
    }
    return rebound;
  };
  const rebindRule = (rule: TriggerRule): TriggerRule => {
    if (rule.op === "all" || rule.op === "any") {
      return { ...rule, rules: rule.rules.map(rebindRule) };
    }
    if (rule.op === "not") return { ...rule, rule: rebindRule(rule.rule) };
    if (rule.op === "elapsed_story_time") {
      return {
        ...rule,
        predicate: { ...rule.predicate, since_ref: rebindDependency(rule.predicate.since_ref) },
      };
    }
    return rule;
  };
  const threads: NarrativeThread[] = [];
  const currentExtractor = {
    kind: "hybrid" as const,
    model_id: request.extractor.model_id,
    prompt_contract_version: request.extractor.prompt_contract_version,
    parameters_hash: request.extractor.parameters_hash,
  };
  const rebaseThread = async (
    prior: NarrativeThread,
    nextState: NarrativeThreadState,
    transitionEventIds: readonly NarraMemId<"event">[],
    modelJudged: boolean,
  ) => {
    const addedEvidence = transitionEventIds.flatMap(
      (eventId) => eventMap.get(eventId)?.evidence ?? [],
    );
    const evidence = uniqueEvidence([...prior.evidence, ...addedEvidence]);
    const openedBy = prior.opened_by.map((id) => rebindDependency(id) as NarraMemId<"event">);
    const developmentRefs = unique([
      ...prior.development_refs.map(rebindDependency),
      ...transitionEventIds,
    ]) as NarrativeThread["development_refs"];
    const resolutionRefs =
      nextState === "resolved"
        ? unique([
            ...(prior.resolution_refs ?? []).map(
              (id) => rebindDependency(id) as NarraMemId<"event">,
            ),
            ...transitionEventIds,
          ])
        : prior.resolution_refs?.map((id) => rebindDependency(id) as NarraMemId<"event">);
    const dependencies = unique([
      ...prior.participant_ids,
      ...openedBy,
      ...developmentRefs,
      ...(resolutionRefs ?? []),
    ]);
    const thread: NarrativeThread = {
      ...prior,
      memory_space_id: request.memory_space_id,
      branch_id: request.branch_id,
      opened_by: openedBy,
      state: nextState,
      trigger_rules: prior.trigger_rules.map(rebindRule),
      development_refs: developmentRefs,
      ...(resolutionRefs === undefined ? {} : { resolution_refs: resolutionRefs }),
      evidence,
      derivation: {
        derivation_id: await createDeterministicNarraMemId(
          "derivation",
          `tavern-lifecycle:${spec.source_revision_id}:thread:${prior.thread_id}:${nextState}:${transitionEventIds.join(",")}`,
        ),
        input_revision_id: spec.source_revision_id,
        evidence_refs: unique(evidence.map((span) => span.evidence_id)),
        dependency_refs: dependencies,
        extractor: modelJudged ? currentExtractor : { kind: "rule" },
        validator_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
        created_at: request.compiled_at,
      },
    };
    assertWire("narrative_thread", thread);
    return thread;
  };
  if (
    request.continuity_baseline?.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION
  ) {
    for (const prior of request.continuity_baseline.narrative_threads.filter((thread) =>
      TERMINAL_THREAD_STATES.has(thread.state),
    )) {
      threads.push(await rebaseThread(prior, prior.state, [], false));
    }
  }
  const priorThreadMap = new Map(input.prior_threads.map((thread) => [thread.thread_id, thread]));
  for (const disposition of spec.prior_thread_dispositions) {
    const prior = priorThreadMap.get(disposition.prior_thread_id);
    if (prior === undefined) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `Prior Thread disappeared before projection: ${disposition.prior_thread_id}`,
      );
    }
    threads.push(
      await rebaseThread(prior, disposition.next_state, disposition.transition_event_ids, true),
    );
  }
  for (const item of spec.threads) {
    const evidence = uniqueEvidence(
      item.opened_by.flatMap((eventId) => eventMap.get(eventId)?.evidence ?? []),
    );
    const threadId = await createTavernLifecycleThreadId(request.memory_set_id, item.spec_key);
    if (threads.some((thread) => thread.thread_id === threadId)) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `New Thread key collides with an authenticated prior Thread: ${item.spec_key}`,
      );
    }
    const thread: NarrativeThread = {
      memory_space_id: request.memory_space_id,
      branch_id: request.branch_id,
      thread_id: threadId,
      kind: item.kind,
      title: item.title,
      participant_ids: unique(item.participant_ids),
      opened_by: unique(item.opened_by),
      state: item.initial_state,
      ...(item.expected_payoff === undefined ? {} : { expected_payoff: item.expected_payoff }),
      trigger_rules: item.trigger_rules,
      development_refs: unique(item.opened_by),
      evidence,
      confidence: { level: "high", basis: "model_inferred", score: 0.8 },
      derivation: {
        derivation_id: await createDeterministicNarraMemId(
          "derivation",
          `tavern-lifecycle:${spec.source_revision_id}:thread:${item.spec_key}:derivation`,
        ),
        input_revision_id: spec.source_revision_id,
        evidence_refs: unique(evidence.map((span) => span.evidence_id)),
        dependency_refs: unique([...item.participant_ids, ...item.opened_by]),
        extractor: currentExtractor,
        validator_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
        created_at: request.compiled_at,
      },
    };
    assertWire("narrative_thread", thread);
    threads.push(thread);
  }
  const projectedThreadIds = new Set(threads.map((thread) => thread.thread_id));
  const impacts: FutureImpact[] = [];
  const rebaseImpact = async (
    prior: FutureImpact,
    nextState: FutureImpactState,
    transitionRefs: TavernNarrativeLifecycleSpec["prior_future_impact_dispositions"][number]["transition_refs"],
    modelJudged: boolean,
  ) => {
    const transitionIds = transitionRefs.map((reference) =>
      reference.kind === "event" ? reference.event_id : reference.delta_id,
    );
    const addedEvidence = transitionRefs.flatMap((reference) =>
      reference.kind === "event"
        ? (eventMap.get(reference.event_id)?.evidence ?? [])
        : (deltaMap.get(reference.delta_id)?.evidence ?? []),
    );
    const evidence = uniqueEvidence([...prior.evidence, ...addedEvidence]);
    const originRefs = prior.origin_refs.map(
      (id) => rebindDependency(id) as FutureImpact["origin_refs"][number],
    );
    const impact: FutureImpact = {
      ...prior,
      memory_space_id: request.memory_space_id,
      branch_id: request.branch_id,
      origin_refs: originRefs,
      trigger: rebindRule(prior.trigger),
      state: nextState,
      ...(prior.expires_when === undefined ? {} : { expires_when: rebindRule(prior.expires_when) }),
      evidence,
      derivation: {
        derivation_id: await createDeterministicNarraMemId(
          "derivation",
          `tavern-lifecycle:${spec.source_revision_id}:impact:${prior.impact_id}:${nextState}:${transitionIds.join(",")}`,
        ),
        input_revision_id: spec.source_revision_id,
        evidence_refs: unique(evidence.map((span) => span.evidence_id)),
        dependency_refs: unique([...originRefs, ...prior.target_refs, ...transitionIds]),
        extractor: modelJudged ? currentExtractor : { kind: "rule" },
        validator_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
        created_at: request.compiled_at,
      },
    };
    assertWire("future_impact", impact);
    return impact;
  };
  if (
    request.continuity_baseline?.version === TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION
  ) {
    for (const prior of request.continuity_baseline.future_impacts.filter((impact) =>
      TERMINAL_IMPACT_STATES.has(impact.state),
    )) {
      impacts.push(await rebaseImpact(prior, prior.state, [], false));
    }
  }
  const priorImpactMap = new Map(
    input.prior_future_impacts.map((impact) => [impact.impact_id, impact]),
  );
  for (const disposition of spec.prior_future_impact_dispositions) {
    const prior = priorImpactMap.get(disposition.prior_impact_id);
    if (prior === undefined) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `Prior FutureImpact disappeared before projection: ${disposition.prior_impact_id}`,
      );
    }
    impacts.push(
      await rebaseImpact(prior, disposition.next_state, disposition.transition_refs, true),
    );
  }
  for (const item of spec.future_impacts) {
    const missingThreadOrigin = item.origin_refs.find(
      (origin) =>
        getNarraMemIdKind(origin) === "narrative_thread" &&
        !projectedThreadIds.has(origin as NarraMemId<"narrative_thread">),
    );
    if (missingThreadOrigin !== undefined) {
      throw new TavernNarrativeLifecycleError(
        "INVALID_INPUT",
        `FutureImpact ${item.spec_key} references a NarrativeThread outside this lifecycle projection`,
      );
    }
    const evidence = uniqueEvidence(
      item.origin_refs.flatMap((origin) => {
        const kind = getNarraMemIdKind(origin);
        if (kind === "event") return eventMap.get(origin as NarraMemId<"event">)?.evidence ?? [];
        if (kind === "state_delta") {
          return deltaMap.get(origin as NarraMemId<"state_delta">)?.evidence ?? [];
        }
        return threads.find((thread) => thread.thread_id === origin)?.evidence ?? [];
      }),
    );
    const impact: FutureImpact = {
      memory_space_id: request.memory_space_id,
      branch_id: request.branch_id,
      impact_id: await createTavernLifecycleImpactId(request.memory_set_id, item.spec_key),
      origin_refs: item.origin_refs,
      target_refs: unique(item.target_refs),
      trigger: item.trigger,
      possible_effects: item.possible_effects,
      direction: item.direction,
      priority: item.priority,
      state: item.initial_state,
      ...(item.expires_when === undefined ? {} : { expires_when: item.expires_when }),
      evidence,
      confidence: { level: "high", basis: "model_inferred", score: 0.8 },
      derivation: {
        derivation_id: await createDeterministicNarraMemId(
          "derivation",
          `tavern-lifecycle:${spec.source_revision_id}:impact:${item.spec_key}:derivation`,
        ),
        input_revision_id: spec.source_revision_id,
        evidence_refs: unique(evidence.map((span) => span.evidence_id)),
        dependency_refs: unique([...item.origin_refs, ...item.target_refs]),
        extractor: currentExtractor,
        validator_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
        created_at: request.compiled_at,
      },
    };
    if (impacts.some((candidate) => candidate.impact_id === impact.impact_id)) {
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `New FutureImpact key collides with an authenticated prior Impact: ${item.spec_key}`,
      );
    }
    assertWire("future_impact", impact);
    impacts.push(impact);
  }
  return { threads, impacts };
}

function archiveRecordForDerived(record: DerivedRecord): TavernArchiveRecord {
  const object = record as unknown as Readonly<Record<string, unknown>>;
  const id =
    (object.thread_id as NarraMemId | undefined) ?? (object.impact_id as NarraMemId | undefined);
  if (id === undefined || getNarraMemIdKind(id) === undefined) {
    throw new TavernNarrativeLifecycleError("INVALID_INPUT", "Lifecycle record has no typed ID");
  }
  return coreRecord(id, `core_${getNarraMemIdKind(id)}_v1`, record);
}

export class TavernNarrativeLifecycleService {
  private readonly registry: TavernMemoryRegistry;

  constructor(
    private readonly port: TavernHostPort,
    private readonly segmentLimits: {
      readonly max_records_per_segment: number;
      readonly max_segment_utf8_bytes: number;
    },
  ) {
    this.registry = new TavernMemoryRegistry(port);
  }

  async prepare(
    normalizeSemanticMetadata?: TavernSemanticMetadataNormalizer,
  ): Promise<TavernNarrativeLifecycleTask> {
    const resolution = await this.registry.resolveCurrentMemorySet();
    if (resolution.status !== "EXACT" || resolution.selected === null) {
      throw new TavernNarrativeLifecycleError(
        "MEMORY_SET_NOT_EXACT",
        `Lifecycle requires EXACT Memory Set resolution, received ${resolution.status}`,
      );
    }
    const candidate = resolution.selected;
    const store = this.store(
      candidate.control.memory_set_id,
      candidate.control_book_name,
      candidate.control.identity_anchor,
    );
    const control = await store.readControl();
    if (control.active_view === null || control.pending_transaction !== null) {
      throw new TavernNarrativeLifecycleError(
        "NO_SEMANTIC_SOURCE",
        "Lifecycle requires one committed semantic active view",
      );
    }
    const records = await store.readActiveSnapshot();
    const semantic = readTavernSemanticManifestFromArchive(records);
    if (semantic === null) {
      throw new TavernNarrativeLifecycleError(
        "NO_SEMANTIC_SOURCE",
        "Lifecycle requires factual semantic coverage first",
      );
    }
    const sourceSnapshot = await reconstructTavernSourceSnapshot(
      records,
      candidate.control.memory_set_id,
    );
    if (
      sourceSnapshot.checksum !== control.active_view.source_checksum ||
      semantic.source_checksum !== sourceSnapshot.checksum
    ) {
      throw new TavernNarrativeLifecycleError(
        "NO_SEMANTIC_SOURCE",
        "Lifecycle source, semantic manifest, and Control disagree",
      );
    }
    const incrementalCoverage = readTavernIncrementalSemanticCoverageFromArchive(records);
    if (incrementalCoverage !== null) {
      const recovered = await recoverTavernIncrementalSemanticCoverage(
        incrementalCoverage,
        sourceSnapshot,
      );
      if (
        incrementalCoverage.stage !== "semantic_committed" ||
        recovered.source_compatibility !== "CURRENT"
      ) {
        throw new TavernNarrativeLifecycleError(
          "NO_SEMANTIC_SOURCE",
          "Incremental lifecycle requires exactly one current pending semantic chunk",
        );
      }
    }
    const continuityBaseline = lifecycleContinuityBaseline(records);
    const input = modelInput(records, continuityBaseline);
    assertWire("flat_narrative_lifecycle_model_input_v020", input);
    const taskFingerprint = await checksumJson({
      lifecycle_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
      control_checksum: control.checksum,
      active_view_id: control.active_view.view_id,
      source_checksum: sourceSnapshot.checksum,
      semantic_changeset_id: semantic.changeset_id,
      model_input: input,
      continuity_baseline: continuityBaseline,
      incremental_coverage: incrementalCoverage,
    });
    return {
      task_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
      task_fingerprint: taskFingerprint,
      memory_set_id: candidate.control.memory_set_id,
      control_book_name: candidate.control_book_name,
      identity_anchor: candidate.control.identity_anchor,
      control_checksum: control.checksum,
      commit_sequence: control.commit_sequence,
      active_view_id: control.active_view.view_id,
      source_snapshot: sourceSnapshot,
      semantic_changeset_id: semantic.changeset_id as NarraMemId<"change_set">,
      active_records: records,
      model_input: input,
      existing_manifest: readTavernNarrativeLifecycleManifestFromArchive(records),
      continuity_baseline: continuityBaseline,
      incremental_coverage: incrementalCoverage,
      ...(normalizeSemanticMetadata === undefined
        ? {}
        : { normalize_semantic_metadata: normalizeSemanticMetadata }),
    };
  }

  async commit(
    request: TavernNarrativeLifecycleCommitRequest,
  ): Promise<TavernNarrativeLifecycleCommitResult> {
    if (request.task.task_version !== TAVERN_NARRATIVE_LIFECYCLE_VERSION) {
      throw new TavernNarrativeLifecycleError(
        "INVALID_INPUT",
        "Unsupported lifecycle task version",
      );
    }
    validateTavernNarrativeLifecycleSpec(request.spec, request.task.model_input);
    const resolution = await this.registry.resolveCurrentMemorySet();
    if (
      resolution.status !== "EXACT" ||
      resolution.selected === null ||
      resolution.selected.control_book_name !== request.task.control_book_name
    ) {
      throw new TavernNarrativeLifecycleError(
        "STALE_TASK",
        "Memory Set identity changed after prepare",
      );
    }
    const store = this.store(
      request.task.memory_set_id,
      request.task.control_book_name,
      request.task.identity_anchor,
    );
    const control = await store.readControl();
    if (
      control.checksum !== request.task.control_checksum ||
      control.commit_sequence !== request.task.commit_sequence ||
      control.pending_transaction !== null ||
      control.active_view?.view_id !== request.task.active_view_id ||
      control.active_view.source_checksum !== request.task.source_snapshot.checksum
    ) {
      throw new TavernNarrativeLifecycleError(
        "STALE_TASK",
        "Control changed after lifecycle prepare",
      );
    }
    const activeRecords = await store.readActiveSnapshot();
    if ((await checksumJson(activeRecords)) !== (await checksumJson(request.task.active_records))) {
      throw new TavernNarrativeLifecycleError(
        "STALE_TASK",
        "Active archive changed after lifecycle prepare",
      );
    }
    const semantic = readTavernSemanticManifestFromArchive(activeRecords);
    if (semantic === null) {
      throw new TavernNarrativeLifecycleError(
        "NO_SEMANTIC_SOURCE",
        "Semantic manifest disappeared",
      );
    }
    const memorySpace = singleRecord<{
      readonly memory_space_id: NarraMemId<"memory_space">;
      readonly branch_id: NarraMemId<"branch">;
    }>(activeRecords, "core_memory_space_v1", "memory_space", (value) => value.memory_space_id);
    const projected = await projectTavernNarrativeLifecycleRecords(
      request.spec,
      request.task.model_input,
      {
        memory_set_id: request.task.memory_set_id,
        extractor: request.extractor,
        compiled_at: request.compiled_at,
        memory_space_id: memorySpace.memory_space_id,
        branch_id: memorySpace.branch_id,
        continuity_baseline: request.task.continuity_baseline,
      },
    );
    const continuityBaseline = lifecycleContinuityBaseline(activeRecords);
    const droppedThreads =
      continuityBaseline !== null &&
      continuityBaseline.narrative_thread_count > 0 &&
      projected.threads.length === 0;
    const droppedImpacts =
      continuityBaseline !== null &&
      continuityBaseline.future_impact_count > 0 &&
      projected.impacts.length === 0;
    if (droppedThreads || droppedImpacts) {
      const dropped = [
        ...(droppedThreads
          ? [`${continuityBaseline.narrative_thread_count} authenticated NarrativeThread records`]
          : []),
        ...(droppedImpacts
          ? [`${continuityBaseline.future_impact_count} authenticated FutureImpact records`]
          : []),
      ];
      throw new TavernNarrativeLifecycleError(
        "LIFECYCLE_CONTINUITY_UNEXPLAINED",
        `Append-only lifecycle projection silently dropped ${dropped.join(" and ")}`,
      );
    }
    const operations = [...projected.threads, ...projected.impacts].map((record) => ({
      op: "add_derived" as const,
      record,
    }));
    const changesetId = await createDeterministicNarraMemId(
      "change_set",
      `tavern-lifecycle:${request.spec.source_revision_id}:${request.spec.spec_id}:changeset`,
    );
    const proposal: ModelChangeSetProposal = {
      stage: "proposal",
      changeset_id: changesetId,
      memory_space_id: memorySpace.memory_space_id,
      branch_id: memorySpace.branch_id,
      based_on_revision_id: request.spec.source_revision_id,
      producer: "hybrid",
      operations,
      unresolved_items: [],
      created_at: request.compiled_at,
    };
    const evidenceIds = recordValues<{ readonly evidence_id: NarraMemId<"evidence"> }>(
      activeRecords,
      "core_evidence_v1",
      "evidence_item",
      (value) => value.evidence_id,
    ).map((evidence) => evidence.evidence_id);
    const knownRecords = activeRecords.flatMap((record) => {
      const kind = getNarraMemIdKind(record.record_id);
      if (kind === undefined || kind === "evidence" || kind === "source_revision") return [];
      const payload = record.payload as Readonly<Record<string, unknown>>;
      return payload.memory_space_id === memorySpace.memory_space_id &&
        payload.branch_id === memorySpace.branch_id
        ? [
            {
              record_id: record.record_id as NarraMemId,
              memory_space_id: memorySpace.memory_space_id,
              branch_id: memorySpace.branch_id,
            },
          ]
        : [];
    });
    const report = validateChangeSetProposal(proposal, {
      memory_space_id: memorySpace.memory_space_id,
      branch_id: memorySpace.branch_id,
      active_revision_id: request.spec.source_revision_id,
      known_evidence_ids: evidenceIds,
      known_records: knownRecords,
    });
    if (!report.accepted) {
      throw new TavernNarrativeLifecycleError(
        "PROPOSAL_REJECTED",
        `Core Validator rejected lifecycle proposal: ${report.issues.map((issue) => issue.code).join(",")}`,
      );
    }
    const acceptedReport = { ...report, accepted: true as const };
    const policyHash: HashDigest = createSha256Digest(
      await checksumJson({
        committer_version: "tavern-narrative-lifecycle-committer@0.1.0",
        allowed_operations: ["add_derived"],
        source_task_fingerprint: request.task.task_fingerprint,
      }),
    );
    const authorized: AuthorizedChangeSet = {
      stage: "authorized",
      changeset_id: changesetId,
      memory_space_id: memorySpace.memory_space_id,
      branch_id: memorySpace.branch_id,
      based_on_revision_id: request.spec.source_revision_id,
      producer: "hybrid",
      operations,
      validation_report: acceptedReport,
      authorization: {
        committer_version: "tavern-narrative-lifecycle-committer@0.1.0",
        policy_hash: policyHash,
        authorized_at: request.compiled_at,
      },
    };
    assertWire("authorized_change_set", authorized);
    const manifest: TavernNarrativeLifecycleManifestPayload = {
      version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
      source_revision_id: request.spec.source_revision_id,
      source_checksum: request.task.source_snapshot.checksum,
      semantic_changeset_id: semantic.changeset_id as NarraMemId<"change_set">,
      spec_checksum: await checksumJson(request.spec),
      lifecycle_changeset_id: changesetId,
      model_id: request.extractor.model_id,
      model_identity_assurance: request.extractor.model_identity_assurance,
      prompt_contract_version: request.extractor.prompt_contract_version,
      prompt_body_sha256: request.extractor.prompt_body_sha256,
      parameters_hash: request.extractor.parameters_hash,
      validator_version: report.validator_version,
    };
    const incrementalCoverage =
      request.task.incremental_coverage === null
        ? null
        : await createTavernLifecycleCoverageCommit({
            source_snapshot: request.task.source_snapshot,
            cursor: request.task.incremental_coverage,
            lifecycle_changeset_id: changesetId,
            provenance: {
              ...request.extractor,
              validator_version: report.validator_version,
            },
          });
    const lifecycleRecords = [
      ...withoutOldLifecycle(activeRecords),
      ...operations.map((operation) => archiveRecordForDerived(operation.record)),
      coreRecord(changesetId, "core_authorized_changeset_v1", authorized),
      coreRecord(
        TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_ID,
        TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_KIND,
        manifest,
      ),
    ];
    const records =
      incrementalCoverage === null
        ? lifecycleRecords
        : replaceTavernIncrementalSemanticCoverageRecord(lifecycleRecords, incrementalCoverage);
    const committed = await store.commitFullSnapshot({
      transaction_id: request.transaction_id,
      writer_id: request.writer_id,
      build_id: request.build_id,
      view_id: request.view_id,
      source_revision: request.task.source_snapshot.source_revision,
      source_checksum: request.task.source_snapshot.checksum,
      expected_commit_sequence: control.commit_sequence,
      expected_view_id: control.active_view.view_id,
      records,
      after_durable_phase: async (phase) => {
        if (phase === "pending_recorded" || phase === "pointer_committed") {
          const stability = await reconcileTavernSourceSnapshot(this.port, {
            memory_set_id: request.task.memory_set_id,
            previous_snapshot: request.task.source_snapshot,
            observed_hints: [],
            ...(request.task.normalize_semantic_metadata === undefined
              ? {}
              : { normalize_semantic_metadata: request.task.normalize_semantic_metadata }),
          });
          if (stability.status !== "UNCHANGED") {
            throw new TavernNarrativeLifecycleError(
              "SOURCE_CHANGED_DURING_COMMIT",
              `Current chat changed during lifecycle ${phase}`,
            );
          }
        }
        await request.after_durable_phase?.(phase);
      },
    });
    return {
      control: committed.control,
      proposal,
      validation_report: acceptedReport,
      authorized_changeset: authorized,
      narrative_thread_count: projected.threads.length,
      future_impact_count: projected.impacts.length,
      incremental_coverage: incrementalCoverage,
    };
  }

  private store(
    memorySetId: string,
    controlBookName: string,
    identityAnchor: TavernControlPayload["identity_anchor"],
  ): TavernWorldbookSnapshotStore {
    return new TavernWorldbookSnapshotStore(this.port, {
      memory_set_id: memorySetId,
      control_book_name: controlBookName,
      segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${memorySetId}__`,
      initial_identity_anchor: identityAnchor,
      max_records_per_segment: this.segmentLimits.max_records_per_segment,
      max_segment_utf8_bytes: this.segmentLimits.max_segment_utf8_bytes,
    });
  }
}
