import type {
  Entity,
  NarraMemId,
  RecallBundle,
  RecallQuery,
  RecallTrace,
} from "@narramem/core-domain";

import type { TavernExtractionJobAudit } from "./extraction-job-contracts.js";
import type { TavernSemanticMetadataNormalizer } from "./source-snapshot-contracts.js";

export const TAVERN_RECALL_ENGINE_VERSION = "0.3.2" as const;
export const TAVERN_RECALL_READ_ONLY_QUERY_VERSION = "0.1.0" as const;

export type TavernRecallSourcePolicy = "EXACT_ONLY" | "ALLOW_APPEND_ONLY_LIVE_TAIL";

export interface TavernRecallSourceAlignment {
  readonly mode: "EXACT" | "APPEND_ONLY_LIVE_TAIL";
  readonly committed_message_count: number;
  readonly live_tail_message_count: number;
  readonly current_source_checksum: string;
}

export interface TavernRecallAssemblyRequest {
  readonly token_budget: number;
  readonly expected_semantic_coverage: TavernExtractionJobAudit;
  readonly source_policy?: TavernRecallSourcePolicy;
  readonly principal_entity_id?: NarraMemId<"entity">;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
}

export interface TavernRecallAssemblyResult {
  readonly recall_version: typeof TAVERN_RECALL_ENGINE_VERSION;
  readonly memory_set_id: string;
  readonly control_checksum: string;
  readonly active_view_id: string;
  readonly source_checksum: string;
  readonly source_alignment: TavernRecallSourceAlignment;
  readonly principal: Entity;
  readonly query: RecallQuery;
  readonly bundle: RecallBundle;
  readonly trace: RecallTrace;
}

export type TavernRecallReadOnlyQueryRequest = Omit<
  TavernRecallAssemblyRequest,
  "source_policy"
> & {
  /** Ephemeral evaluator input. It is never appended to the authoritative Tavern Source. */
  readonly query_text: string;
  /** Exact current Source checksum captured before the read-only evaluator call. */
  readonly expected_authoritative_source_checksum: string;
};

export interface TavernRecallReadOnlyQueryResult {
  readonly read_only_query_version: typeof TAVERN_RECALL_READ_ONLY_QUERY_VERSION;
  readonly authoritative_source_checksum: string;
  readonly authoritative_source_unchanged: true;
  /** Produced by the same TavernRecallService and deterministic assembly engine as product Recall. */
  readonly recall: TavernRecallAssemblyResult;
}

export class TavernRecallError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "MEMORY_SET_NOT_EXACT"
      | "NO_ACTIVE_VIEW"
      | "ARCHIVE_CORRUPT"
      | "SEMANTIC_COVERAGE_MISSING"
      | "SEMANTIC_COVERAGE_MISMATCH"
      | "PRINCIPAL_UNRESOLVED"
      | "SOURCE_CHANGED"
      | "OUTPUT_SCHEMA_INVALID",
    message: string,
  ) {
    super(message);
    this.name = "TavernRecallError";
  }
}
