import { normalizeNarrativeContentTag, type TavernRolePrompt } from "@narramem/tavern-adapter";
import memoryHeadSystem from "../../../prompts/runtime/NM-P0027_v0.1.0.md";
import memoryTailPrefill from "../../../prompts/runtime/NM-P0028_v0.2.0.md";
import memoryMaterialAcknowledgement from "../../../prompts/runtime/NM-P0029_v0.1.0.md";
import memoryJsonOutputRule from "../../../prompts/runtime/NM-P0030_v0.1.0.md";
import hostMaterialContract from "../../../prompts/runtime/NM-P0032_v0.1.0.md";

export const NARRAMEM_BETA_SETTINGS_VERSION = "0.4.0" as const;
export const NARRAMEM_EXTENSION_SETTINGS_KEY = "narramem" as const;
export const DEEPSEEK_OFFICIAL_ENDPOINT = "https://api.deepseek.com/beta" as const;

export const MEMORY_PROMPT_PROFILES = [
  {
    id: "universal-modular",
    label: "通用模块化 Prompt",
  },
] as const;

export type MemoryPromptProfileId = (typeof MEMORY_PROMPT_PROFILES)[number]["id"];
export type MemoryApiSource = "custom" | "deepseek";

export interface NarraMemMemoryApiProfile {
  readonly id: string;
  readonly name: string;
  readonly source: MemoryApiSource;
  readonly api_url: string;
  readonly model: string;
  /** Opaque SillyTavern secret ID. The credential value never enters extension settings. */
  readonly credential_secret_id: string;
  /** Advanced compatibility override. Null means route only from the actual model name. */
  readonly prompt_profile_override: MemoryPromptProfileId | null;
}

export interface NarraMemBetaSettings {
  readonly schema_version: typeof NARRAMEM_BETA_SETTINGS_VERSION;
  readonly enabled: boolean;
  readonly active_profile_id: string;
  readonly profiles: readonly NarraMemMemoryApiProfile[];
  /** Assistant narrative is read only from the last complete tag block. */
  readonly narrative_content_tag: string;
  readonly head_system: string;
  /** Legacy storage key: editable identity-confirmation message before task data. */
  readonly tail_message: string;
  readonly material_acknowledgement: string;
  /** Selects whether the material acknowledgement is assistant prefill or system. */
  readonly assistant_prefill_enabled: boolean;
  readonly timeout_ms: number;
  readonly min_interval_ms: number;
  readonly max_requests_per_minute: number;
  readonly concurrency: number;
  /** Automatic retries after the first call. Durable runners support 0 to 2. */
  readonly retry_count: number;
  /** Optional extra calls for a JSON response that ended mid-value. */
  readonly continuation_enabled: boolean;
  readonly continuation_max_calls: number;
  /** Optional extra calls for a complete JSON value that fails strict Schema validation. */
  readonly schema_repair_enabled: boolean;
  readonly schema_repair_max_calls: number;
}

const DEFAULT_PROFILE: NarraMemMemoryApiProfile = Object.freeze({
  id: "default",
  name: "默认配置",
  source: "custom",
  api_url: "",
  model: "",
  credential_secret_id: "",
  prompt_profile_override: null,
});

export const DEFAULT_NARRAMEM_BETA_SETTINGS: NarraMemBetaSettings = Object.freeze({
  schema_version: NARRAMEM_BETA_SETTINGS_VERSION,
  enabled: false,
  active_profile_id: DEFAULT_PROFILE.id,
  profiles: Object.freeze([DEFAULT_PROFILE]),
  narrative_content_tag: "content",
  head_system: memoryHeadSystem,
  tail_message: memoryTailPrefill,
  material_acknowledgement: memoryMaterialAcknowledgement,
  assistant_prefill_enabled: true,
  timeout_ms: 180_000,
  min_interval_ms: 0,
  max_requests_per_minute: 0,
  concurrency: 1,
  retry_count: 1,
  continuation_enabled: false,
  continuation_max_calls: 1,
  schema_repair_enabled: false,
  schema_repair_max_calls: 1,
});

export interface NarraMemSettingsHost {
  readonly extensionSettings: Record<string, unknown>;
  saveSettingsDebounced(): void;
  /** Hot-updated extension instances must not overwrite settings after losing ownership. */
  canPersist?(): boolean;
}

function plainObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function integer(value: unknown, fallback: number, minimum: number, maximum: number): number {
  return Number.isInteger(value) && (value as number) >= minimum && (value as number) <= maximum
    ? (value as number)
    : fallback;
}

function promptProfile(value: unknown): MemoryPromptProfileId | null {
  return MEMORY_PROMPT_PROFILES.some((item) => item.id === value)
    ? (value as MemoryPromptProfileId)
    : null;
}

function profileId(value: unknown, fallback: string): string {
  return typeof value === "string" && /^[A-Za-z0-9_-]{1,80}$/u.test(value) ? value : fallback;
}

function profileName(value: unknown, fallback: string): string {
  if (typeof value !== "string") return fallback;
  const trimmed = value.trim();
  return trimmed.length > 0 && trimmed.length <= 80 ? trimmed : fallback;
}

function source(value: unknown): MemoryApiSource {
  return value === "deepseek" ? "deepseek" : "custom";
}

function parseProfile(value: unknown, index: number): NarraMemMemoryApiProfile | null {
  if (!plainObject(value)) return null;
  const parsedSource = source(value.source);
  return {
    id: profileId(value.id, `profile_${index + 1}`),
    name: profileName(value.name, `配置 ${index + 1}`),
    source: parsedSource,
    api_url:
      parsedSource === "custom" && typeof value.api_url === "string" ? value.api_url.trim() : "",
    model: typeof value.model === "string" ? value.model.trim() : "",
    credential_secret_id:
      typeof value.credential_secret_id === "string" ? value.credential_secret_id.trim() : "",
    prompt_profile_override: promptProfile(value.prompt_profile_override),
  };
}

function legacyProfile(value: Record<string, unknown>): NarraMemMemoryApiProfile {
  const parsedSource = source(value.api_source);
  const model = typeof value.model === "string" ? value.model.trim() : "";
  const legacyPrompt = promptProfile(value.prompt_profile);
  return {
    ...DEFAULT_PROFILE,
    source: parsedSource,
    api_url:
      parsedSource === "custom" && typeof value.api_url === "string" ? value.api_url.trim() : "",
    model,
    credential_secret_id:
      typeof value.credential_secret_id === "string" ? value.credential_secret_id.trim() : "",
    prompt_profile_override: inferMemoryPromptProfile(model) === null ? legacyPrompt : null,
  };
}

function uniqueProfiles(values: readonly NarraMemMemoryApiProfile[]): NarraMemMemoryApiProfile[] {
  const seen = new Set<string>();
  const result: NarraMemMemoryApiProfile[] = [];
  for (const value of values) {
    let id = value.id;
    let suffix = 2;
    while (seen.has(id)) {
      id = `${value.id}_${suffix}`;
      suffix += 1;
    }
    seen.add(id);
    result.push(id === value.id ? value : { ...value, id });
  }
  return result;
}

export function parseNarraMemBetaSettings(value: unknown): NarraMemBetaSettings {
  if (!plainObject(value)) return structuredClone(DEFAULT_NARRAMEM_BETA_SETTINGS);
  const parsedProfiles = Array.isArray(value.profiles)
    ? uniqueProfiles(
        value.profiles
          .map((item, index) => parseProfile(item, index))
          .filter((item): item is NarraMemMemoryApiProfile => item !== null),
      )
    : [];
  const profiles = parsedProfiles.length > 0 ? parsedProfiles : [legacyProfile(value)];
  const requestedActiveId = profileId(
    value.active_profile_id,
    profiles[0]?.id ?? DEFAULT_PROFILE.id,
  );
  const activeProfileId = profiles.some((item) => item.id === requestedActiveId)
    ? requestedActiveId
    : (profiles[0]?.id ?? DEFAULT_PROFILE.id);
  return {
    schema_version: NARRAMEM_BETA_SETTINGS_VERSION,
    enabled: value.enabled === true,
    active_profile_id: activeProfileId,
    profiles,
    narrative_content_tag: normalizeNarrativeContentTag(value.narrative_content_tag),
    head_system:
      typeof value.head_system === "string"
        ? value.head_system
        : DEFAULT_NARRAMEM_BETA_SETTINGS.head_system,
    tail_message:
      typeof value.tail_message === "string"
        ? value.tail_message
        : DEFAULT_NARRAMEM_BETA_SETTINGS.tail_message,
    material_acknowledgement:
      typeof value.material_acknowledgement === "string"
        ? value.material_acknowledgement
        : DEFAULT_NARRAMEM_BETA_SETTINGS.material_acknowledgement,
    assistant_prefill_enabled: value.assistant_prefill_enabled !== false,
    timeout_ms: integer(value.timeout_ms, 180_000, 1_000, 900_000),
    min_interval_ms: 0,
    max_requests_per_minute: 0,
    concurrency: integer(value.concurrency, 1, 1, 16),
    retry_count: integer(value.retry_count, 1, 0, 2),
    continuation_enabled: value.continuation_enabled === true,
    continuation_max_calls: integer(value.continuation_max_calls, 1, 1, 3),
    schema_repair_enabled: value.schema_repair_enabled === true,
    schema_repair_max_calls: integer(value.schema_repair_max_calls, 1, 1, 3),
  };
}

export function activeMemoryApiProfile(settings: NarraMemBetaSettings): NarraMemMemoryApiProfile {
  const match = settings.profiles.find((item) => item.id === settings.active_profile_id);
  if (match === undefined) throw new TypeError("NarraMem active API profile is invalid");
  return { ...match };
}

export function inferMemoryPromptProfile(model: string): MemoryPromptProfileId | null {
  return model.trim().length > 0 ? "universal-modular" : null;
}

export function resolvedMemoryPromptProfile(
  profile: NarraMemMemoryApiProfile,
): MemoryPromptProfileId | null {
  return profile.prompt_profile_override ?? inferMemoryPromptProfile(profile.model);
}

export function promptProfileLabel(id: MemoryPromptProfileId): string {
  const match = MEMORY_PROMPT_PROFILES.find((item) => item.id === id);
  if (match === undefined) throw new TypeError("NarraMem Prompt profile is invalid");
  return match.label;
}

export function memoryPromptCompatibilityRoute(
  settings: NarraMemBetaSettings,
): MemoryPromptProfileId {
  const resolved = resolvedMemoryPromptProfile(activeMemoryApiProfile(settings));
  if (resolved === null) {
    throw new TypeError("当前模型无法自动匹配 NarraMem Prompt，请在高级设置选择兼容 Prompt");
  }
  return resolved;
}

export class NarraMemBetaSettingsStore {
  private current: NarraMemBetaSettings;

  constructor(private readonly host: NarraMemSettingsHost) {
    const stored = host.extensionSettings[NARRAMEM_EXTENSION_SETTINGS_KEY];
    this.current = parseNarraMemBetaSettings(stored);
    this.persist();
    if (stored !== undefined && JSON.stringify(stored) !== JSON.stringify(this.current)) {
      this.host.saveSettingsDebounced();
    }
  }

  get(): NarraMemBetaSettings {
    return structuredClone(this.current);
  }

  replace(value: NarraMemBetaSettings): NarraMemBetaSettings {
    this.assertCurrentOwner();
    this.current = parseNarraMemBetaSettings(value);
    this.persist();
    this.host.saveSettingsDebounced();
    return this.get();
  }

  patch(value: Partial<NarraMemBetaSettings>): NarraMemBetaSettings {
    return this.replace({ ...this.current, ...value });
  }

  selectProfile(id: string): NarraMemBetaSettings {
    if (!this.current.profiles.some((item) => item.id === id)) {
      throw new TypeError("NarraMem API profile does not exist");
    }
    return this.patch({ active_profile_id: id });
  }

  updateActiveProfile(value: Partial<NarraMemMemoryApiProfile>): NarraMemBetaSettings {
    const active = activeMemoryApiProfile(this.current);
    return this.updateProfile(active.id, value);
  }

  updateProfile(id: string, value: Partial<NarraMemMemoryApiProfile>): NarraMemBetaSettings {
    if (!this.current.profiles.some((item) => item.id === id)) {
      throw new TypeError("NarraMem API profile does not exist");
    }
    const profiles = this.current.profiles.map((item) =>
      item.id === id ? { ...item, ...value, id } : item,
    );
    return this.patch({ profiles });
  }

  createProfile(name: string, requestedSource: MemoryApiSource = "custom"): NarraMemBetaSettings {
    const normalizedName = profileName(name, `配置 ${this.current.profiles.length + 1}`);
    const token = globalThis.crypto?.randomUUID?.().replaceAll("-", "") ?? Date.now().toString(36);
    const id = `profile_${token}`;
    const next: NarraMemMemoryApiProfile = {
      ...DEFAULT_PROFILE,
      id,
      name: normalizedName,
      source: requestedSource,
      model: "",
    };
    return this.patch({ profiles: [...this.current.profiles, next], active_profile_id: id });
  }

  renameActiveProfile(name: string): NarraMemBetaSettings {
    return this.updateActiveProfile({
      name: profileName(name, activeMemoryApiProfile(this.current).name),
    });
  }

  deleteActiveProfile(): NarraMemBetaSettings {
    if (this.current.profiles.length <= 1) {
      throw new TypeError("至少保留一个 NarraMem API 配置");
    }
    const profiles = this.current.profiles.filter(
      (item) => item.id !== this.current.active_profile_id,
    );
    return this.patch({ profiles, active_profile_id: profiles[0]?.id ?? DEFAULT_PROFILE.id });
  }

  private persist(): void {
    this.assertCurrentOwner();
    this.host.extensionSettings[NARRAMEM_EXTENSION_SETTINGS_KEY] = structuredClone(this.current);
  }

  private assertCurrentOwner(): void {
    if (this.host.canPersist?.() === false) {
      throw new TypeError("Stale NarraMem extension instance cannot persist settings");
    }
  }
}

export function memoryApiConfigured(
  settings: NarraMemBetaSettings,
  credentialConfigured: boolean,
): boolean {
  const profile = activeMemoryApiProfile(settings);
  return (
    settings.enabled &&
    profile.model.length > 0 &&
    profile.credential_secret_id.length > 0 &&
    (profile.source === "deepseek" || profile.api_url.length > 0) &&
    resolvedMemoryPromptProfile(profile) !== null &&
    credentialConfigured
  );
}

export function createMemoryMessageEnvelope(
  settings: NarraMemBetaSettings,
  taskMessages: readonly TavernRolePrompt[],
  hostMaterials: Readonly<Record<string, unknown>> | null = null,
): readonly TavernRolePrompt[] {
  if (
    taskMessages.length < 2 ||
    taskMessages[0]?.role !== "system" ||
    taskMessages[1]?.role !== "user" ||
    (taskMessages.length !== 2 &&
      (taskMessages.length === 3
        ? taskMessages[2]?.role !== "user"
        : taskMessages.length !== 4 ||
          new Set(taskMessages.slice(2).map((message) => message.role)).size !== 2 ||
          !taskMessages.slice(2).some((message) => message.role === "user") ||
          !taskMessages.slice(2).some((message) => message.role === "assistant")))
  ) {
    throw new TypeError(
      "NarraMem task messages require one trusted system, one data user, and at most one controlled recovery pair",
    );
  }
  const materialBundle = JSON.stringify({
    bundle_version: "0.1.0",
    trust_boundary: "untrusted_host_material",
    character_card: hostMaterials?.character_card ?? null,
    user_persona: hostMaterials?.user_persona ?? null,
    world_info: hostMaterials?.world_info ?? null,
    task_input: JSON.parse(taskMessages[1].content) as unknown,
  });
  return [
    ...(settings.head_system.trim().length === 0
      ? []
      : [{ role: "system" as const, content: settings.head_system }]),
    ...(settings.tail_message.trim().length === 0
      ? []
      : [{ role: "assistant" as const, content: settings.tail_message }]),
    taskMessages[0],
    { role: "system", content: `${hostMaterialContract}\n\n${materialBundle}` },
    ...(settings.material_acknowledgement.trim().length === 0
      ? []
      : [
          {
            role: settings.assistant_prefill_enabled ? ("assistant" as const) : ("system" as const),
            content: settings.material_acknowledgement,
          },
        ]),
    ...(taskMessages.length === 3
      ? [taskMessages[2] as TavernRolePrompt]
      : [{ role: "user" as const, content: memoryJsonOutputRule }, ...taskMessages.slice(2)]),
  ];
}

export function memoryProxyRequest(
  settings: NarraMemBetaSettings,
  request: {
    readonly prompt: readonly TavernRolePrompt[];
    readonly schemaName: string;
    readonly jsonSchema: Readonly<Record<string, unknown>>;
    readonly responseFormat?: "structured_json" | "text_fragment";
  },
  hostMaterials: Readonly<Record<string, unknown>> | null = null,
): Readonly<Record<string, unknown>> {
  return {
    messages: createMemoryMessageEnvelope(settings, request.prompt, hostMaterials),
    schema_name: request.schemaName,
    json_schema: request.jsonSchema,
    response_format: request.responseFormat ?? "structured_json",
    timeout_ms: settings.timeout_ms,
    limits: {
      min_interval_ms: settings.min_interval_ms,
      max_requests_per_minute: settings.max_requests_per_minute,
      concurrency: settings.concurrency,
    },
  };
}
