import type { TavernMemoryBatchWorkState, TavernMemoryModuleId } from "./memory-book-contracts.js";
import { TAVERN_MEMORY_MODULE_IDS, TavernMemoryBookError } from "./memory-book-contracts.js";
import { checksumJson } from "./worldbook-codec.js";

export const TAVERN_MEMORY_BATCH_SIZE = 10 as const;
export const TAVERN_MEMORY_PROTECTED_AI_COUNT = 4 as const;

export interface TavernValidAiWindow {
  /** One-based position among stable, valid AI replies; a valid greeting is ordinal 1. */
  readonly ai_ordinal: number;
  readonly assistant_source_unit_id: string;
  /** Complete continuity window ending at this AI reply, including its preceding user message(s). */
  readonly source_unit_ids: readonly string[];
}

export interface TavernMemoryBatchPlanRequest {
  readonly memory_set_id: string;
  readonly source_revision_id: string;
  readonly committed_eligible_count: number;
  readonly valid_ai_windows: readonly TavernValidAiWindow[];
}

export interface TavernMemoryBatchPlan {
  readonly status: "COLLECTING" | "READY";
  readonly valid_ai_count: number;
  readonly eligible_ai_count: number;
  readonly pending_eligible_count: number;
  readonly protected_ai_ordinals: readonly number[];
  readonly batch: TavernMemoryBatchWorkState | null;
}

const emptyModule = (moduleId: TavernMemoryModuleId) => ({
  module_id: moduleId,
  status: "PENDING" as const,
  module_revision: 0,
  accepted_record_ids: [],
  pending_target_ids: [],
  partition_page_id: null,
  last_attempt_page_id: null,
  base_calls: 0,
  transport_retry_calls: 0,
  continuation_calls: 0,
  targeted_repair_calls: 0,
  manual_repair_calls: 0,
  last_error_code: null,
});

export async function planTavernMemoryBatch(
  request: TavernMemoryBatchPlanRequest,
): Promise<TavernMemoryBatchPlan> {
  if (
    request.memory_set_id.trim().length === 0 ||
    request.source_revision_id.trim().length === 0 ||
    !Number.isInteger(request.committed_eligible_count) ||
    request.committed_eligible_count < 0
  ) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Invalid batch planner request");
  }
  const assistantIds = new Set<string>();
  for (const [index, window] of request.valid_ai_windows.entries()) {
    if (
      window.ai_ordinal !== index + 1 ||
      window.assistant_source_unit_id.trim().length === 0 ||
      assistantIds.has(window.assistant_source_unit_id) ||
      window.source_unit_ids.length === 0 ||
      !window.source_unit_ids.includes(window.assistant_source_unit_id)
    ) {
      throw new TavernMemoryBookError(
        "INVALID_INPUT",
        "Valid AI windows must be unique, contiguous, and include their assistant source unit",
      );
    }
    assistantIds.add(window.assistant_source_unit_id);
  }

  const validAiCount = request.valid_ai_windows.length;
  const eligibleAiCount = Math.max(0, validAiCount - TAVERN_MEMORY_PROTECTED_AI_COUNT);
  if (request.committed_eligible_count > eligibleAiCount) {
    throw new TavernMemoryBookError(
      "INVALID_INPUT",
      "Committed eligible count cannot exceed the currently eligible prefix",
    );
  }
  const pendingEligibleCount = eligibleAiCount - request.committed_eligible_count;
  const protectedAiOrdinals = request.valid_ai_windows
    .slice(Math.max(0, validAiCount - TAVERN_MEMORY_PROTECTED_AI_COUNT))
    .map((window) => window.ai_ordinal);
  if (pendingEligibleCount < TAVERN_MEMORY_BATCH_SIZE) {
    return {
      status: "COLLECTING",
      valid_ai_count: validAiCount,
      eligible_ai_count: eligibleAiCount,
      pending_eligible_count: pendingEligibleCount,
      protected_ai_ordinals: protectedAiOrdinals,
      batch: null,
    };
  }

  const batchWindows = request.valid_ai_windows.slice(
    request.committed_eligible_count,
    request.committed_eligible_count + TAVERN_MEMORY_BATCH_SIZE,
  );
  const first = batchWindows[0];
  const last = batchWindows.at(-1);
  if (first === undefined || last === undefined) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Ready batch window is incomplete");
  }
  const sourceUnitIds = [...new Set(batchWindows.flatMap((window) => window.source_unit_ids))];
  const batchHash = await checksumJson({
    memory_set_id: request.memory_set_id,
    first_ai_ordinal: first.ai_ordinal,
    last_ai_ordinal: last.ai_ordinal,
    source_revision_id: request.source_revision_id,
  });
  const modules = Object.fromEntries(
    TAVERN_MEMORY_MODULE_IDS.map((moduleId) => [moduleId, emptyModule(moduleId)]),
  ) as unknown as TavernMemoryBatchWorkState["modules"];
  return {
    status: "READY",
    valid_ai_count: validAiCount,
    eligible_ai_count: eligibleAiCount,
    pending_eligible_count: pendingEligibleCount,
    protected_ai_ordinals: protectedAiOrdinals,
    batch: {
      batch_id: `batch_${batchHash.slice(0, 32)}`,
      source_revision_id: request.source_revision_id,
      first_ai_ordinal: first.ai_ordinal,
      last_ai_ordinal: last.ai_ordinal,
      source_unit_ids: sourceUnitIds,
      status: "READY",
      modules,
    },
  };
}
