import {
  type CausalLink,
  type CurrentStateView,
  DERIVED_RECORD_KINDS,
  type DerivedRecordId,
  type Entity,
  type Episode,
  type EpistemicState,
  type EventAtom,
  type EvidenceItem,
  getNarraMemIdKind,
  type HashDigest,
  isHashDigest,
  isIsoInstant,
  type ModelChangeSetProposal,
  type NarraMemId,
  type Proposition,
  type Scene,
  type SourceOrder,
  type StateAssertion,
  type StateDelta,
  type StateSubjectRef,
} from "@narramem/core-domain";
import { validateWireValue, type WireSchemaName } from "@narramem/core-validator";

import { CandidateCompilationError, type CandidateCompilerPorts } from "./compiler-contracts.js";

export const NARRATIVE_INCREMENTAL_SEMANTIC_MERGE_VERSION = "0.1.0" as const;

export type NarrativeIncrementalSemanticRecord =
  | Entity
  | Scene
  | Episode
  | EventAtom
  | StateAssertion
  | StateDelta
  | Proposition
  | EpistemicState
  | CausalLink
  | CurrentStateView;

export interface NarrativeIncrementalSemanticMergeInput {
  readonly memory_space_id: NarraMemId<"memory_space">;
  readonly branch_id: NarraMemId<"branch">;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly checkpoint: SourceOrder;
  readonly replace_from_ordinal: number;
  readonly stable_records: readonly NarrativeIncrementalSemanticRecord[];
  readonly chunk_proposal: ModelChangeSetProposal;
  readonly current_evidence_items: readonly EvidenceItem[];
  readonly merge_key: string;
}

export interface NarrativeIncrementalSemanticMergeResult {
  readonly merge_version: typeof NARRATIVE_INCREMENTAL_SEMANTIC_MERGE_VERSION;
  readonly records: readonly NarrativeIncrementalSemanticRecord[];
  readonly current_state_view: CurrentStateView;
  readonly removed_record_ids: readonly DerivedRecordId[];
  readonly semantic_corpus_hash: HashDigest;
}

const SEMANTIC_KINDS = new Set([
  "entity",
  "scene",
  "episode",
  "event",
  "state_assertion",
  "state_delta",
  "proposition",
  "epistemic_state",
  "causal_link",
  "current_state_view",
] as const);

const ID_FIELDS = [
  "entity_id",
  "scene_id",
  "episode_id",
  "event_id",
  "assertion_id",
  "delta_id",
  "epistemic_id",
  "proposition_id",
  "causal_id",
  "view_id",
] as const;

function recordId(record: NarrativeIncrementalSemanticRecord): DerivedRecordId {
  const object = record as unknown as Readonly<Record<string, unknown>>;
  for (const field of ID_FIELDS) {
    const value = object[field];
    const kind = getNarraMemIdKind(value);
    if (kind !== undefined && SEMANTIC_KINDS.has(kind as never)) {
      return value as DerivedRecordId;
    }
  }
  throw new CandidateCompilationError("Incremental semantic record has no supported typed ID", [
    "INCREMENTAL_MERGE_RECORD_KIND_UNSUPPORTED",
  ]);
}

function collectNarraMemIds(value: unknown, result = new Set<NarraMemId>()): Set<NarraMemId> {
  if (typeof value === "string") {
    if (getNarraMemIdKind(value) !== undefined) result.add(value as NarraMemId);
    return result;
  }
  if (Array.isArray(value)) {
    value.forEach((item) => {
      collectNarraMemIds(item, result);
    });
    return result;
  }
  if (value === null || typeof value !== "object") return result;
  Object.values(value as Readonly<Record<string, unknown>>).forEach((item) => {
    collectNarraMemIds(item, result);
  });
  return result;
}

function evidenceIds(
  record: NarrativeIncrementalSemanticRecord,
): readonly NarraMemId<"evidence">[] {
  return [...collectNarraMemIds(record)].filter(
    (value): value is NarraMemId<"evidence"> => getNarraMemIdKind(value) === "evidence",
  );
}

function derivedReferences(record: NarrativeIncrementalSemanticRecord): readonly DerivedRecordId[] {
  const ownId = recordId(record);
  const derivedKinds = new Set<string>(DERIVED_RECORD_KINDS);
  return [...collectNarraMemIds(record)].filter((value): value is DerivedRecordId => {
    const kind = getNarraMemIdKind(value);
    return value !== ownId && kind !== undefined && derivedKinds.has(kind);
  });
}

function compareSourceOrder(left: SourceOrder, right: SourceOrder): number {
  return left.ordinal - right.ordinal || left.component - right.component;
}

function subjectKey(subject: StateSubjectRef): string {
  if (subject.kind === "entity") return `entity:${subject.entity_id}`;
  if (subject.kind === "world") return `world:${subject.scope_key}`;
  return `relation:${subject.relation_type}:${[...subject.participant_ids].sort().join(",")}`;
}

function canonicalJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  const object = value as Readonly<Record<string, unknown>>;
  return `{${Object.keys(object)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalJson(object[key])}`)
    .join(",")}}`;
}

function validateRecord(record: NarrativeIncrementalSemanticRecord): void {
  const id = recordId(record);
  const kind = getNarraMemIdKind(id);
  if (kind === undefined || !SEMANTIC_KINDS.has(kind as never)) {
    throw new CandidateCompilationError("Unsupported record kind entered semantic merge", [
      "INCREMENTAL_MERGE_RECORD_KIND_UNSUPPORTED",
    ]);
  }
  const schemaName = kind === "event" ? "event_atom" : (kind as WireSchemaName);
  const report = validateWireValue(schemaName, record);
  if (!report.valid) {
    const errors = report.errors.slice(0, 12);
    throw new CandidateCompilationError(
      "Semantic record failed its Core wire Schema",
      [
        "INCREMENTAL_MERGE_RECORD_SCHEMA_INVALID",
        ...errors.map((error) => {
          const path = error.instancePath
            .split("/")
            .filter((part) => part.length > 0)
            .join(".");
          return `CORE_WIRE.${kind}.${error.keyword}:${path.length === 0 ? "record" : path}`;
        }),
      ],
      {
        diagnostic_paths: errors.map((error) => `/merged/${kind}${error.instancePath}`),
        record_ids: [id],
        dependency_record_ids: record.derivation.dependency_refs,
      },
    );
  }
}

function assertScope(
  record: NarrativeIncrementalSemanticRecord,
  input: NarrativeIncrementalSemanticMergeInput,
): void {
  if (record.memory_space_id !== input.memory_space_id || record.branch_id !== input.branch_id) {
    throw new CandidateCompilationError("Semantic merge record crossed its trusted scope", [
      "INCREMENTAL_MERGE_SCOPE_MISMATCH",
    ]);
  }
}

function rebaseStableRecord(
  record: Exclude<NarrativeIncrementalSemanticRecord, CurrentStateView>,
  input: NarrativeIncrementalSemanticMergeInput,
  ports: CandidateCompilerPorts,
  createdAt: string,
): Exclude<NarrativeIncrementalSemanticRecord, CurrentStateView> {
  const id = recordId(record);
  const derivationId = ports.allocate_id(
    "derivation",
    `${input.source_revision_id}:${input.merge_key}:rebase:${id}`,
  );
  if (getNarraMemIdKind(derivationId) !== "derivation") {
    throw new CandidateCompilationError("Semantic merge allocator returned a wrong ID kind", [
      "COMPILER_ID_KIND_INVALID",
    ]);
  }
  return {
    ...record,
    ...(getNarraMemIdKind(id) === "scene" ? { source_revision_id: input.source_revision_id } : {}),
    derivation: {
      ...record.derivation,
      derivation_id: derivationId,
      input_revision_id: input.source_revision_id,
      validator_version: `narrative-incremental-semantic-merge@${NARRATIVE_INCREMENTAL_SEMANTIC_MERGE_VERSION}`,
      created_at: createdAt,
    },
  } as Exclude<NarrativeIncrementalSemanticRecord, CurrentStateView>;
}

/**
 * Merges one validated chunk into the authenticated semantic prefix and builds
 * the only consumer-visible CurrentStateView from the complete merged corpus.
 */
export async function mergeNarrativeIncrementalSemanticCorpus(
  input: NarrativeIncrementalSemanticMergeInput,
  ports: CandidateCompilerPorts,
): Promise<NarrativeIncrementalSemanticMergeResult> {
  if (!Number.isInteger(input.replace_from_ordinal) || input.replace_from_ordinal < 0) {
    throw new CandidateCompilationError("Semantic merge overlap boundary is invalid", [
      "INCREMENTAL_MERGE_BOUNDARY_INVALID",
    ]);
  }
  if (input.replace_from_ordinal > input.checkpoint.ordinal) {
    throw new CandidateCompilationError("Semantic merge overlap starts after its checkpoint", [
      "INCREMENTAL_MERGE_BOUNDARY_INVALID",
    ]);
  }
  if (input.merge_key.length === 0) {
    throw new CandidateCompilationError("Semantic merge key cannot be empty", [
      "COMPILER_NAMESPACE_INVALID",
    ]);
  }
  if (
    input.chunk_proposal.memory_space_id !== input.memory_space_id ||
    input.chunk_proposal.branch_id !== input.branch_id ||
    input.chunk_proposal.based_on_revision_id !== input.source_revision_id
  ) {
    throw new CandidateCompilationError("Chunk proposal does not match semantic merge scope", [
      "INCREMENTAL_MERGE_PROPOSAL_SCOPE_MISMATCH",
    ]);
  }
  const createdAt = ports.now();
  if (!isIsoInstant(createdAt)) {
    throw new CandidateCompilationError("Semantic merge clock returned a non-ISO instant", [
      "COMPILER_CLOCK_INVALID",
    ]);
  }

  const evidenceById = new Map(
    input.current_evidence_items.map((item) => [item.evidence_id, item]),
  );
  if (evidenceById.size !== input.current_evidence_items.length) {
    throw new CandidateCompilationError("Current Evidence contains duplicate IDs", [
      "INCREMENTAL_MERGE_EVIDENCE_DUPLICATE",
    ]);
  }
  if (
    input.current_evidence_items.some(
      (evidence) => evidence.revision_id !== input.source_revision_id,
    )
  ) {
    throw new CandidateCompilationError("Current Evidence contains a stale revision", [
      "INCREMENTAL_MERGE_EVIDENCE_STALE",
    ]);
  }

  const stableById = new Map<DerivedRecordId, NarrativeIncrementalSemanticRecord>();
  for (const record of input.stable_records) {
    validateRecord(record);
    assertScope(record, input);
    const id = recordId(record);
    if (stableById.has(id)) {
      throw new CandidateCompilationError("Stable semantic corpus contains duplicate record IDs", [
        "INCREMENTAL_MERGE_RECORD_ID_DUPLICATE",
      ]);
    }
    stableById.set(id, record);
    for (const evidenceId of evidenceIds(record)) {
      if (!evidenceById.has(evidenceId)) {
        throw new CandidateCompilationError("Stable record cites unavailable current Evidence", [
          "INCREMENTAL_MERGE_EVIDENCE_UNKNOWN",
        ]);
      }
    }
  }

  const chunkRecordIds = new Set(
    input.chunk_proposal.operations.flatMap((operation) =>
      operation.op === "add_derived"
        ? [recordId(operation.record as NarrativeIncrementalSemanticRecord)]
        : [],
    ),
  );
  const removedIds = new Set<DerivedRecordId>();
  for (const [id, record] of stableById) {
    const kind = getNarraMemIdKind(id);
    if (kind === "current_state_view") {
      removedIds.add(id);
      continue;
    }
    // Staged extraction recompiles the dependency-closed candidate prefix with
    // the same compilation key. Replace an entity only when this chunk carries
    // the exact same deterministic ID; unrelated stable entities remain
    // append-only.
    if (kind === "entity") {
      if (chunkRecordIds.has(id)) removedIds.add(id);
      continue;
    }
    if (
      evidenceIds(record).some(
        (evidenceId) =>
          (evidenceById.get(evidenceId)?.source_order.ordinal ?? Number.POSITIVE_INFINITY) >=
          input.replace_from_ordinal,
      )
    ) {
      removedIds.add(id);
    }
  }
  let changed = true;
  while (changed) {
    changed = false;
    for (const [id, record] of stableById) {
      if (removedIds.has(id)) continue;
      if (derivedReferences(record).some((reference) => removedIds.has(reference))) {
        removedIds.add(id);
        changed = true;
      }
    }
  }

  const mergedById = new Map<DerivedRecordId, NarrativeIncrementalSemanticRecord>();
  for (const [id, record] of stableById) {
    if (removedIds.has(id) || getNarraMemIdKind(id) === "current_state_view") continue;
    const rebased = rebaseStableRecord(
      record as Exclude<NarrativeIncrementalSemanticRecord, CurrentStateView>,
      input,
      ports,
      createdAt,
    );
    validateRecord(rebased);
    mergedById.set(id, rebased);
  }

  for (const operation of input.chunk_proposal.operations) {
    if (operation.op !== "add_derived") {
      throw new CandidateCompilationError(
        "Incremental merge only accepts add_derived chunk output",
        ["INCREMENTAL_MERGE_OPERATION_UNSUPPORTED"],
      );
    }
    const record = operation.record as NarrativeIncrementalSemanticRecord;
    const kind = getNarraMemIdKind(recordId(record));
    if (kind === undefined || !SEMANTIC_KINDS.has(kind as never)) {
      throw new CandidateCompilationError("Chunk output contains a non-semantic record kind", [
        "INCREMENTAL_MERGE_RECORD_KIND_UNSUPPORTED",
      ]);
    }
    validateRecord(record);
    assertScope(record, input);
    if (record.derivation.input_revision_id !== input.source_revision_id) {
      throw new CandidateCompilationError("Chunk record derivation is stale", [
        "INCREMENTAL_MERGE_DERIVATION_STALE",
      ]);
    }
    for (const evidenceId of evidenceIds(record)) {
      const evidence = evidenceById.get(evidenceId);
      if (evidence === undefined) {
        throw new CandidateCompilationError("Chunk record cites unavailable current Evidence", [
          "INCREMENTAL_MERGE_EVIDENCE_UNKNOWN",
        ]);
      }
      if (compareSourceOrder(evidence.source_order, input.checkpoint) > 0) {
        throw new CandidateCompilationError("Chunk record cites Evidence after its checkpoint", [
          "INCREMENTAL_MERGE_EVIDENCE_AFTER_CHECKPOINT",
        ]);
      }
    }
    if (kind === "current_state_view") continue;
    const id = recordId(record);
    if (mergedById.has(id)) {
      throw new CandidateCompilationError("Chunk record collides with the retained stable prefix", [
        "INCREMENTAL_MERGE_RECORD_ID_COLLISION",
      ]);
    }
    mergedById.set(id, record);
  }

  for (const record of mergedById.values()) {
    const dangling = derivedReferences(record).find((reference) => !mergedById.has(reference));
    if (dangling !== undefined) {
      throw new CandidateCompilationError(`Semantic corpus has dangling reference ${dangling}`, [
        "INCREMENTAL_MERGE_DANGLING_REFERENCE",
      ]);
    }
  }

  const assertions = [...mergedById.values()].filter(
    (record): record is StateAssertion => getNarraMemIdKind(recordId(record)) === "state_assertion",
  );
  const latestBySubject = new Map<string, StateAssertion>();
  const assertionOrder = (assertion: StateAssertion): SourceOrder => {
    const orders = evidenceIds(assertion).flatMap((evidenceId) => {
      const evidence = evidenceById.get(evidenceId);
      return evidence === undefined ? [] : [evidence.source_order];
    });
    if (orders.length === 0) {
      throw new CandidateCompilationError("StateAssertion has no current Evidence order", [
        "INCREMENTAL_MERGE_STATE_ORDER_MISSING",
      ]);
    }
    return [...orders].sort(compareSourceOrder).at(-1) as SourceOrder;
  };
  for (const assertion of assertions) {
    const key = `${subjectKey(assertion.subject)}|${assertion.state_key}`;
    const previous = latestBySubject.get(key);
    if (previous === undefined) {
      latestBySubject.set(key, assertion);
      continue;
    }
    const comparison = compareSourceOrder(assertionOrder(previous), assertionOrder(assertion));
    if (comparison === 0 && previous.assertion_id !== assertion.assertion_id) {
      throw new CandidateCompilationError("Two StateAssertions compete at the same source order", [
        "INCREMENTAL_MERGE_STATE_ORDER_AMBIGUOUS",
      ]);
    }
    if (comparison < 0) latestBySubject.set(key, assertion);
  }
  const assertionRefs = [...latestBySubject.values()]
    .map((assertion) => assertion.assertion_id)
    .sort();
  const projectionHash = await ports.hash_text(canonicalJson(assertionRefs));
  if (!isHashDigest(projectionHash)) {
    throw new CandidateCompilationError("Semantic merge hash port returned an invalid digest", [
      "COMPILER_HASH_INVALID",
    ]);
  }
  const viewId = ports.allocate_id(
    "current_state_view",
    `${input.source_revision_id}:${input.merge_key}:current_state_view`,
  );
  const viewDerivationId = ports.allocate_id(
    "derivation",
    `${input.source_revision_id}:${input.merge_key}:derivation:current_state_view`,
  );
  if (
    getNarraMemIdKind(viewId) !== "current_state_view" ||
    getNarraMemIdKind(viewDerivationId) !== "derivation"
  ) {
    throw new CandidateCompilationError("Semantic merge allocator returned a wrong ID kind", [
      "COMPILER_ID_KIND_INVALID",
    ]);
  }
  const stateRecords = [...mergedById.values()].filter((record) => {
    const kind = getNarraMemIdKind(recordId(record));
    return kind === "state_assertion" || kind === "state_delta";
  });
  // An empty StateView still represents a trusted projection over the semantic
  // corpus. Bind it to that corpus instead of emitting an unsupported rule-only
  // record when a chunk contains Experience but no explicit state observation.
  const viewDependencies = stateRecords.length > 0 ? stateRecords : [...mergedById.values()];
  const currentStateView: CurrentStateView = {
    view_id: viewId,
    memory_space_id: input.memory_space_id,
    branch_id: input.branch_id,
    checkpoint: input.checkpoint,
    source_revision_id: input.source_revision_id,
    assertion_refs: assertionRefs,
    projection_hash: projectionHash,
    derivation: {
      derivation_id: viewDerivationId,
      input_revision_id: input.source_revision_id,
      evidence_refs: [...new Set(viewDependencies.flatMap((record) => evidenceIds(record)))].sort(),
      dependency_refs: viewDependencies.map(recordId).sort(),
      extractor: { kind: "rule" },
      validator_version: `narrative-incremental-semantic-merge@${NARRATIVE_INCREMENTAL_SEMANTIC_MERGE_VERSION}`,
      created_at: createdAt,
    },
  };
  validateRecord(currentStateView);
  mergedById.set(currentStateView.view_id, currentStateView);

  const records = [...mergedById.values()].sort((left, right) =>
    recordId(left).localeCompare(recordId(right)),
  );
  const semanticCorpusHash = await ports.hash_text(canonicalJson(records));
  if (!isHashDigest(semanticCorpusHash)) {
    throw new CandidateCompilationError("Semantic merge hash port returned an invalid digest", [
      "COMPILER_HASH_INVALID",
    ]);
  }
  return {
    merge_version: NARRATIVE_INCREMENTAL_SEMANTIC_MERGE_VERSION,
    records,
    current_state_view: currentStateView,
    removed_record_ids: [...removedIds].sort(),
    semantic_corpus_hash: semanticCorpusHash,
  };
}
