import type {
  CurrentStateView,
  EventAtom,
  FutureImpact,
  NarraMemId,
  NarrativeThread,
  RecallQuery,
  StateAssertion,
  StatePredicate,
} from "@narramem/core-domain";
import {
  evaluateNarrativeFutureImpact,
  evaluateNarrativeTriggerRule,
  type NarrativeRuleEvaluation,
  type NarrativeTriggerEvaluationContext,
} from "@narramem/narrative-runtime";

import { canonicalJson } from "./worldbook-codec.js";

export interface TavernNarrativeTriggerCorpus {
  readonly revision_id: NarraMemId<"source_revision">;
  readonly events: readonly EventAtom[];
  readonly state_assertions: readonly StateAssertion[];
  readonly current_state_view: CurrentStateView | null;
  readonly narrative_threads: readonly NarrativeThread[];
  readonly current_state_is_current?: boolean;
  readonly checkpoint_includes_current_scene?: boolean;
}

function sameSubject(left: StatePredicate["subject"], right: StateAssertion["subject"]): boolean {
  return canonicalJson(left) === canonicalJson(right);
}

export function createTavernNarrativeTriggerContext(
  query: RecallQuery,
  corpus: TavernNarrativeTriggerCorpus,
): NarrativeTriggerEvaluationContext {
  if (query.checkpoint.kind !== "source_order") {
    throw new TypeError("Tavern trigger evaluation requires a source_order checkpoint");
  }
  const checkpointOrdinal = query.checkpoint.value.ordinal;
  const perceived = new Set(query.current_scene.perceived_event_refs ?? []);
  const currentAssertions = new Set(corpus.current_state_view?.assertion_refs ?? []);
  return {
    current_scene: query.current_scene,
    current_event_types: corpus.events
      .filter((event) => perceived.has(event.event_id))
      .map((event) => event.event_type),
    resolve_state: (predicate) => {
      if (corpus.current_state_is_current === false) return { status: "unknown" };
      const assertion = corpus.state_assertions.find(
        (candidate) =>
          currentAssertions.has(candidate.assertion_id) &&
          candidate.state_key === predicate.state_key &&
          sameSubject(predicate.subject, candidate.subject),
      );
      return assertion === undefined
        ? { status: "absent" }
        : { status: "known", value: assertion.value };
    },
    resolve_thread_state: (threadId) =>
      corpus.narrative_threads.find((thread) => thread.thread_id === threadId)?.state,
    resolve_elapsed_story_time: (predicate) => {
      if (corpus.checkpoint_includes_current_scene === false) return undefined;
      if (predicate.unit !== "turn" || !predicate.since_ref.startsWith("nm_event_")) {
        return undefined;
      }
      const event = corpus.events.find((candidate) => candidate.event_id === predicate.since_ref);
      return event === undefined ? undefined : checkpointOrdinal - event.source_range.start.ordinal;
    },
  };
}

export function evaluateTavernNarrativeTriggerRule(
  rule: Parameters<typeof evaluateNarrativeTriggerRule>[0],
  query: RecallQuery,
  corpus: TavernNarrativeTriggerCorpus,
): NarrativeRuleEvaluation {
  return evaluateNarrativeTriggerRule(rule, createTavernNarrativeTriggerContext(query, corpus));
}

export function evaluateTavernFutureImpact(
  impact: FutureImpact,
  query: RecallQuery,
  corpus: TavernNarrativeTriggerCorpus,
) {
  return evaluateNarrativeFutureImpact(
    impact,
    corpus.revision_id,
    createTavernNarrativeTriggerContext(query, corpus),
  );
}
