import {
  TAVERN_MEMORY_MODULE_IDS,
  type TavernMemoryBatchWorkState,
  type TavernMemoryColdHead,
  type TavernMemoryModuleId,
} from "./memory-book-contracts.js";
import type { TavernMemoryBookStore } from "./memory-book-store.js";
import {
  acceptTavernMemoryModuleOutput,
  buildTavernMemoryModuleInput,
  type TavernMemoryAcceptedModuleOutputs,
  type TavernMemoryModuleInputContext,
} from "./memory-module-input.js";
import {
  assembleTavernMemoryModulePrompt,
  assembleTavernMemoryModuleRepairPrompt,
  type TavernMemoryModulePromptPack,
  type TavernMemorySixMessageEnvelope,
} from "./memory-module-prompt.js";
import {
  readTavernMemoryModulePartition,
  runTavernMemoryModuleAttempt,
  runTavernMemoryModuleWithRecovery,
  type TavernMemoryModuleCompilerPort,
  type TavernMemoryModuleGenerationPort,
  type TavernMemoryModuleRecoveryRunResult,
  type TavernMemoryModuleRunResult,
} from "./memory-module-runner.js";
import type { TavernMemoryAttemptLimits } from "./memory-module-state.js";
import { recoverInterruptedTavernMemoryBatch } from "./memory-module-state.js";

export const TAVERN_MEMORY_MODULE_COORDINATOR_VERSION = "0.1.0" as const;

interface CoordinatorCommonRequest {
  readonly book_store: TavernMemoryBookStore;
  readonly generation_port: TavernMemoryModuleGenerationPort;
  readonly compiler: TavernMemoryModuleCompilerPort;
  readonly input_context: TavernMemoryModuleInputContext;
  readonly prompt_packs: Readonly<Record<TavernMemoryModuleId, TavernMemoryModulePromptPack>>;
  readonly envelope: TavernMemorySixMessageEnvelope;
  readonly requested_model_id: string;
  readonly attempt_limits: TavernMemoryAttemptLimits;
  readonly continuation_prompt?: {
    readonly prompt_asset_ref: string;
    readonly body: string;
  };
  readonly operation_id_prefix: string;
  readonly now: () => string;
}

export interface TavernMemoryModuleCoordinatorResult {
  readonly coordinator_version: typeof TAVERN_MEMORY_MODULE_COORDINATOR_VERSION;
  readonly status:
    | "MODULE_ATTEMPTED"
    | "WAITING_FOR_USER"
    | "INTERRUPTED_RECOVERED"
    | "FINALIZING"
    | "BATCH_ALREADY_ADVANCED"
    | "BATCH_INVALIDATED";
  readonly module_id: TavernMemoryModuleId | null;
  readonly provider_dispatched: boolean;
  readonly head: TavernMemoryColdHead;
  readonly recovery: TavernMemoryModuleRecoveryRunResult | null;
  readonly attempt: TavernMemoryModuleRunResult | null;
}

async function loadAcceptedOutputs(
  store: TavernMemoryBookStore,
  batch: TavernMemoryBatchWorkState,
  before: TavernMemoryModuleId,
): Promise<TavernMemoryAcceptedModuleOutputs> {
  let accepted: TavernMemoryAcceptedModuleOutputs = {};
  const position = TAVERN_MEMORY_MODULE_IDS.indexOf(before);
  for (const moduleId of TAVERN_MEMORY_MODULE_IDS.slice(0, position)) {
    if (batch.modules[moduleId].status !== "COMMITTED") {
      throw new TypeError(`${before} cannot load before ${moduleId} commits`);
    }
    const partition = await readTavernMemoryModulePartition(store, batch, moduleId);
    if (partition === null || !partition.complete) {
      throw new TypeError(`${moduleId} has no complete durable partition`);
    }
    accepted = acceptTavernMemoryModuleOutput(accepted, partition.accepted_output);
  }
  return accepted;
}

function nextPendingModule(batch: TavernMemoryBatchWorkState): TavernMemoryModuleId | null {
  return (
    TAVERN_MEMORY_MODULE_IDS.find((moduleId) => batch.modules[moduleId].status === "PENDING") ??
    null
  );
}

async function commitInterruptedRecovery(
  store: TavernMemoryBookStore,
  head: TavernMemoryColdHead,
  now: () => string,
  operationId: string,
): Promise<TavernMemoryColdHead> {
  const workState = head.work_state;
  if (workState === null) throw new TypeError("Memory Book has no active batch");
  const recovered = recoverInterruptedTavernMemoryBatch(workState);
  const at = now();
  return store.commit({
    commit_id: `${operationId}:recover_interrupted`,
    expected_generation: head.generation,
    expected_generation_checksum: head.generation_checksum,
    committed_at: at,
    source_index: head.source_index,
    work_state: recovered,
    checkpoint_index: head.checkpoint_index,
    active_state: head.active_state,
    epistemic_state: head.epistemic_state,
    thread_impact: head.thread_impact,
    module_views: head.module_views,
    audit_ring: [
      ...head.audit_ring,
      {
        at,
        batch_id: recovered.batch_id,
        module_id:
          TAVERN_MEMORY_MODULE_IDS.find(
            (moduleId) => recovered.modules[moduleId].status === "INTERRUPTED",
          ) ?? null,
        event: "module_interrupted_recovered",
        error_code: "INTERRUPTED",
      },
    ],
    retained_core_page_ids: head.core_page_ids,
    retained_module_view_page_ids: head.module_view_page_ids,
    core_pages: [],
    module_view_pages: [],
  });
}

/**
 * Advances at most one module. The host idle scheduler must call this again for
 * the next module, so one idle opportunity can never fan out into seven calls.
 */
export async function runNextTavernMemoryModuleStep(
  request: CoordinatorCommonRequest & { readonly automatic_targeted_repair: boolean },
): Promise<TavernMemoryModuleCoordinatorResult> {
  const cold = await request.book_store.readColdHead();
  const initialHead = cold.head;
  if (initialHead === null || initialHead.work_state === null) {
    throw new TypeError("Memory Book has no active batch");
  }
  const initialBatch = initialHead.work_state;
  if (initialBatch.batch_id !== request.input_context.batch_id) {
    throw new TypeError("Coordinator input does not match the durable batch");
  }
  if (initialBatch.status === "MODULE_RUNNING") {
    const head = await commitInterruptedRecovery(
      request.book_store,
      initialHead,
      request.now,
      request.operation_id_prefix,
    );
    return {
      coordinator_version: TAVERN_MEMORY_MODULE_COORDINATOR_VERSION,
      status: "INTERRUPTED_RECOVERED",
      module_id:
        TAVERN_MEMORY_MODULE_IDS.find(
          (moduleId) => head.work_state?.modules[moduleId].status === "INTERRUPTED",
        ) ?? null,
      provider_dispatched: false,
      head,
      recovery: null,
      attempt: null,
    };
  }
  const waitingModule =
    TAVERN_MEMORY_MODULE_IDS.find((moduleId) =>
      ["NEEDS_USER", "INTERRUPTED"].includes(initialBatch.modules[moduleId].status),
    ) ?? null;
  // beta.36 could persist READY after one of several revalidated modules was
  // repaired. Treat the durable module states as authoritative so cold recovery
  // waits without dispatching or forcing users to delete their Memory Book.
  if (initialBatch.status === "NEEDS_USER" || waitingModule !== null) {
    return {
      coordinator_version: TAVERN_MEMORY_MODULE_COORDINATOR_VERSION,
      status: "WAITING_FOR_USER",
      module_id: waitingModule,
      provider_dispatched: false,
      head: initialHead,
      recovery: null,
      attempt: null,
    };
  }
  if (initialBatch.status === "FINALIZING") {
    return {
      coordinator_version: TAVERN_MEMORY_MODULE_COORDINATOR_VERSION,
      status: "FINALIZING",
      module_id: null,
      provider_dispatched: false,
      head: initialHead,
      recovery: null,
      attempt: null,
    };
  }
  if (initialBatch.status === "INVALIDATED") {
    return {
      coordinator_version: TAVERN_MEMORY_MODULE_COORDINATOR_VERSION,
      status: "BATCH_INVALIDATED",
      module_id: null,
      provider_dispatched: false,
      head: initialHead,
      recovery: null,
      attempt: null,
    };
  }
  if (initialBatch.status !== "READY") {
    return {
      coordinator_version: TAVERN_MEMORY_MODULE_COORDINATOR_VERSION,
      status: "BATCH_ALREADY_ADVANCED",
      module_id: null,
      provider_dispatched: false,
      head: initialHead,
      recovery: null,
      attempt: null,
    };
  }
  const moduleId = nextPendingModule(initialBatch);
  if (moduleId === null) throw new TypeError("READY batch has no pending module");
  const accepted = await loadAcceptedOutputs(request.book_store, initialBatch, moduleId);
  const input = buildTavernMemoryModuleInput(moduleId, request.input_context, accepted);
  const pack = request.prompt_packs[moduleId];
  const prompt = assembleTavernMemoryModulePrompt({
    input,
    prompt_pack: pack,
    envelope: request.envelope,
  });
  const recovery = await runTavernMemoryModuleWithRecovery({
    book_store: request.book_store,
    generation_port: request.generation_port,
    compiler: request.compiler,
    input,
    prompt,
    requested_model_id: request.requested_model_id,
    attempt_limits: request.attempt_limits,
    operation_id_prefix: `${request.operation_id_prefix}:${moduleId}`,
    now: request.now,
    automatic_targeted_repair: request.automatic_targeted_repair,
    repair_prompt: (partition) =>
      assembleTavernMemoryModuleRepairPrompt({
        input,
        partition,
        prompt_pack: pack,
        envelope: request.envelope,
      }),
    ...(request.continuation_prompt === undefined
      ? {}
      : { continuation_prompt: request.continuation_prompt }),
  });
  return {
    coordinator_version: TAVERN_MEMORY_MODULE_COORDINATOR_VERSION,
    status: "MODULE_ATTEMPTED",
    module_id: moduleId,
    provider_dispatched: true,
    head: recovery.final.head,
    recovery,
    attempt: null,
  };
}

/** One explicit click equals one model call; there is no manual click count cap. */
export async function runManualTavernMemoryModuleRepair(
  request: CoordinatorCommonRequest & { readonly module_id: TavernMemoryModuleId },
): Promise<TavernMemoryModuleCoordinatorResult> {
  const cold = await request.book_store.readColdHead();
  const head = cold.head;
  if (head === null || head.work_state === null)
    throw new TypeError("Memory Book has no active batch");
  const batch = head.work_state;
  const module = batch.modules[request.module_id];
  const repairableBatchStatus = batch.status === "NEEDS_USER" || batch.status === "READY";
  if (!repairableBatchStatus || !["NEEDS_USER", "INTERRUPTED"].includes(module.status)) {
    throw new TypeError(`${request.module_id} is not waiting for manual repair`);
  }
  const accepted = await loadAcceptedOutputs(request.book_store, batch, request.module_id);
  const input = buildTavernMemoryModuleInput(request.module_id, request.input_context, accepted);
  const pack = request.prompt_packs[request.module_id];
  const prior = await readTavernMemoryModulePartition(request.book_store, batch, request.module_id);
  const basePrompt = assembleTavernMemoryModulePrompt({
    input,
    prompt_pack: pack,
    envelope: request.envelope,
  });
  const prompt =
    prior === null
      ? basePrompt
      : assembleTavernMemoryModuleRepairPrompt({
          input,
          partition: prior,
          prompt_pack: pack,
          envelope: request.envelope,
        });
  const attempt = await runTavernMemoryModuleAttempt({
    book_store: request.book_store,
    generation_port: request.generation_port,
    compiler: request.compiler,
    input,
    prompt,
    requested_model_id: request.requested_model_id,
    attempt_kind: "manual_repair",
    attempt_limits: request.attempt_limits,
    operation_id: `${request.operation_id_prefix}:${request.module_id}:manual:${module.manual_repair_calls + 1}`,
    now: request.now,
    ...(prior === null ? {} : { prior_partition: prior }),
  });
  return {
    coordinator_version: TAVERN_MEMORY_MODULE_COORDINATOR_VERSION,
    status: "MODULE_ATTEMPTED",
    module_id: request.module_id,
    provider_dispatched: true,
    head: attempt.head,
    recovery: null,
    attempt,
  };
}
