import type { JsonValue } from "@narramem/core-domain";
import { canonicalJson, sha256HexUtf8, type TavernMemoryCorePage } from "@narramem/tavern-adapter";

export const NARRAMEM_BATCH_INPUT_MANIFEST_KIND = "memory_batch_input_manifest_v2" as const;
export const NARRAMEM_BATCH_INPUT_CHUNK_KIND = "memory_batch_input_chunk_v2" as const;

const BATCH_INPUT_CHUNK_UTF8_BYTES = 96_000;

interface BatchInputManifestV2 {
  readonly format: typeof NARRAMEM_BATCH_INPUT_MANIFEST_KIND;
  readonly batch_id: string;
  readonly encoding: "base64_utf8_canonical_json";
  readonly payload_sha256: string;
  readonly payload_utf8_bytes: number;
  readonly chunk_count: number;
  readonly chunk_page_ids: readonly string[];
  readonly created_at: string;
}

interface BatchInputChunkV2 {
  readonly format: typeof NARRAMEM_BATCH_INPUT_CHUNK_KIND;
  readonly batch_id: string;
  readonly chunk_index: number;
  readonly chunk_count: number;
  readonly encoded_payload: string;
}

export interface NarraMemBatchInputPageSet {
  readonly manifest_page_id: string;
  readonly pages: readonly TavernMemoryCorePage[];
  readonly payload_utf8_bytes: number;
  readonly chunk_count: number;
}

const jsonValue = (value: unknown): JsonValue => value as JsonValue;

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000));
  }
  return btoa(binary);
}

function base64ToBytes(value: string): Uint8Array {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

function asObject(value: unknown, label: string): Readonly<Record<string, unknown>> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} 格式无效`);
  }
  return value as Readonly<Record<string, unknown>>;
}

function asManifest(value: unknown): BatchInputManifestV2 {
  const manifest = asObject(value, "批次输入 manifest");
  if (
    manifest.format !== NARRAMEM_BATCH_INPUT_MANIFEST_KIND ||
    typeof manifest.batch_id !== "string" ||
    manifest.encoding !== "base64_utf8_canonical_json" ||
    typeof manifest.payload_sha256 !== "string" ||
    typeof manifest.payload_utf8_bytes !== "number" ||
    !Number.isInteger(manifest.payload_utf8_bytes) ||
    manifest.payload_utf8_bytes < 0 ||
    typeof manifest.chunk_count !== "number" ||
    !Number.isInteger(manifest.chunk_count) ||
    manifest.chunk_count < 1 ||
    !Array.isArray(manifest.chunk_page_ids) ||
    manifest.chunk_page_ids.length !== manifest.chunk_count ||
    !manifest.chunk_page_ids.every((item) => typeof item === "string" && item.length > 0) ||
    typeof manifest.created_at !== "string"
  ) {
    throw new TypeError("批次输入 manifest 字段无效");
  }
  if (new Set(manifest.chunk_page_ids).size !== manifest.chunk_page_ids.length) {
    throw new TypeError("批次输入 manifest 含重复分片页");
  }
  return manifest as unknown as BatchInputManifestV2;
}

function asChunk(value: unknown): BatchInputChunkV2 {
  const chunk = asObject(value, "批次输入分片");
  if (
    chunk.format !== NARRAMEM_BATCH_INPUT_CHUNK_KIND ||
    typeof chunk.batch_id !== "string" ||
    typeof chunk.chunk_index !== "number" ||
    !Number.isInteger(chunk.chunk_index) ||
    chunk.chunk_index < 0 ||
    typeof chunk.chunk_count !== "number" ||
    !Number.isInteger(chunk.chunk_count) ||
    chunk.chunk_count < 1 ||
    typeof chunk.encoded_payload !== "string"
  ) {
    throw new TypeError("批次输入分片字段无效");
  }
  return chunk as unknown as BatchInputChunkV2;
}

export async function createNarraMemBatchInputPages(input: {
  readonly batch_id: string;
  readonly payload: JsonValue;
  readonly created_at: string;
}): Promise<NarraMemBatchInputPageSet> {
  const serialized = canonicalJson(input.payload);
  const bytes = new TextEncoder().encode(serialized);
  const chunks: Uint8Array[] = [];
  for (let offset = 0; offset < bytes.length; offset += BATCH_INPUT_CHUNK_UTF8_BYTES) {
    chunks.push(bytes.slice(offset, offset + BATCH_INPUT_CHUNK_UTF8_BYTES));
  }
  if (chunks.length === 0) chunks.push(new Uint8Array());

  const chunkPageIds = chunks.map(
    (_, index) => `batch_input_${input.batch_id}_chunk_${String(index).padStart(4, "0")}`,
  );
  const chunkPages = chunks.map<TavernMemoryCorePage>((chunk, index) => {
    const pageId = chunkPageIds[index];
    if (pageId === undefined) throw new TypeError(`批次输入分片 ${index} 缺少页 ID`);
    return {
      page_id: pageId,
      records: [
        {
          record_id: `memory_batch_input_chunk:${input.batch_id}:${index}`,
          record_kind: NARRAMEM_BATCH_INPUT_CHUNK_KIND,
          payload: jsonValue({
            format: NARRAMEM_BATCH_INPUT_CHUNK_KIND,
            batch_id: input.batch_id,
            chunk_index: index,
            chunk_count: chunks.length,
            encoded_payload: bytesToBase64(chunk),
          } satisfies BatchInputChunkV2),
        },
      ],
    };
  });
  const manifestPageId = `batch_input_${input.batch_id}_manifest`;
  const manifest: BatchInputManifestV2 = {
    format: NARRAMEM_BATCH_INPUT_MANIFEST_KIND,
    batch_id: input.batch_id,
    encoding: "base64_utf8_canonical_json",
    payload_sha256: await sha256HexUtf8(serialized),
    payload_utf8_bytes: bytes.length,
    chunk_count: chunks.length,
    chunk_page_ids: chunkPageIds,
    created_at: input.created_at,
  };
  return {
    manifest_page_id: manifestPageId,
    pages: [
      ...chunkPages,
      {
        page_id: manifestPageId,
        records: [
          {
            record_id: `memory_batch_input_manifest:${input.batch_id}`,
            record_kind: NARRAMEM_BATCH_INPUT_MANIFEST_KIND,
            payload: jsonValue(manifest),
          },
        ],
      },
    ],
    payload_utf8_bytes: bytes.length,
    chunk_count: chunks.length,
  };
}

export async function readNarraMemBatchInputManifest(input: {
  readonly manifest_payload: JsonValue;
  read_page(page_id: string): Promise<TavernMemoryCorePage>;
}): Promise<JsonValue> {
  const manifest = asManifest(input.manifest_payload);
  const chunks: Uint8Array[] = [];
  let totalBytes = 0;
  for (let index = 0; index < manifest.chunk_page_ids.length; index += 1) {
    const pageId = manifest.chunk_page_ids[index];
    if (pageId === undefined) throw new TypeError(`批次输入分片 ${index} 缺少页 ID`);
    const page = await input.read_page(pageId);
    if (page.page_id !== pageId) throw new TypeError(`批次输入分片页 ${pageId} 身份不匹配`);
    const record = page.records.find(
      (item) =>
        item.record_kind === NARRAMEM_BATCH_INPUT_CHUNK_KIND &&
        item.record_id === `memory_batch_input_chunk:${manifest.batch_id}:${index}`,
    );
    if (record === undefined) throw new TypeError(`批次输入分片 ${index} 缺失`);
    const chunk = asChunk(record.payload);
    if (
      chunk.batch_id !== manifest.batch_id ||
      chunk.chunk_index !== index ||
      chunk.chunk_count !== manifest.chunk_count
    ) {
      throw new TypeError(`批次输入分片 ${index} 顺序或归属无效`);
    }
    const decoded = base64ToBytes(chunk.encoded_payload);
    chunks.push(decoded);
    totalBytes += decoded.length;
  }
  if (totalBytes !== manifest.payload_utf8_bytes) throw new TypeError("批次输入分片总长度校验失败");
  const bytes = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.length;
  }
  const serialized = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  if ((await sha256HexUtf8(serialized)) !== manifest.payload_sha256) {
    throw new TypeError("批次输入分片校验和不匹配");
  }
  return JSON.parse(serialized) as JsonValue;
}
