import {
  readVerifiedTavernMemoryCheckpoint,
  type TavernMemoryCheckpointStorePort,
} from "./memory-batch-finalizer.js";
import type { TavernMemoryColdHead } from "./memory-book-contracts.js";
import {
  alignTavernMemoryCheckpointSource,
  TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION,
} from "./memory-checkpoint-recall.js";
import {
  advanceTavernMemoryBatchDurability,
  canApplyTavernMemoryVisibility,
} from "./memory-module-state.js";
import { findTavernProtectedWindowStartIndex } from "./protected-chat-window.js";
import type { TavernSourceSnapshot } from "./source-snapshot-contracts.js";
import { canonicalJson } from "./worldbook-codec.js";

export const TAVERN_MEMORY_VISIBILITY_VERSION = "0.1.0" as const;
export const TAVERN_MEMORY_PROTECTED_LATEST_AI = 4 as const;

export interface TavernMemoryCheckpointVisibilityPlan {
  readonly visibility_version: typeof TAVERN_MEMORY_VISIBILITY_VERSION;
  readonly checkpoint_id: string;
  readonly covered_ai_ordinal: number;
  readonly hide_through_index: number | null;
  readonly hide_through_message_id: number | null;
  readonly protected_window_start_index: number;
  readonly protected_window_start_message_id: number | null;
  readonly protected_ai_message_ids: readonly number[];
}

export interface TavernMemoryCheckpointVisibilityRequest {
  readonly book_store: TavernMemoryCheckpointStorePort;
  readonly current_source_snapshot: TavernSourceSnapshot;
}

export interface TavernMemoryVisibilityReceipt {
  readonly checkpoint_id: string;
  readonly hide_through_message_id: number | null;
  readonly protected_ai_message_ids: readonly number[];
}

export interface TavernMemoryVisibilityCommitRequest
  extends TavernMemoryCheckpointVisibilityRequest {
  readonly receipt: TavernMemoryVisibilityReceipt;
  readonly operation_id: string;
  readonly committed_at: string;
}

export interface TavernMemoryVisibilityCommitResult {
  readonly status: "COMPLETE" | "ALREADY_COMPLETE";
  readonly head: TavernMemoryColdHead;
  readonly plan: TavernMemoryCheckpointVisibilityPlan;
}

export async function planTavernMemoryCheckpointVisibility(
  request: TavernMemoryCheckpointVisibilityRequest,
): Promise<TavernMemoryCheckpointVisibilityPlan> {
  const verified = await readVerifiedTavernMemoryCheckpoint(request.book_store);
  const { head, manifest } = verified;
  const batch = head.work_state;
  if (
    batch === null ||
    !["RECALL_READY", "VISIBILITY_APPLIED", "COMPLETE"].includes(batch.status) ||
    head.checkpoint_index.recall_version !== TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION ||
    head.source_index.mutation_from_source_unit_id !== null
  ) {
    throw new TypeError("Visibility requires a mutation-free Recall-ready checkpoint");
  }
  await alignTavernMemoryCheckpointSource(
    manifest,
    request.current_source_snapshot,
    "ALLOW_APPEND_ONLY_LIVE_TAIL",
  );
  const messages = request.current_source_snapshot.messages;
  const ai = messages
    .map((message, index) =>
      message.role === "assistant" && message.narrative_text !== null ? { message, index } : null,
    )
    .filter((item): item is NonNullable<typeof item> => item !== null);
  const covered = ai[head.checkpoint_index.covered_ai_ordinal - 1];
  if (covered === undefined) {
    throw new TypeError("Checkpoint covered AI ordinal is outside the current Source");
  }
  const protectedWindowStart = findTavernProtectedWindowStartIndex(
    messages,
    TAVERN_MEMORY_PROTECTED_LATEST_AI,
  );
  const protectedAi = ai.slice(-TAVERN_MEMORY_PROTECTED_LATEST_AI);
  const hideThroughIndex = Math.min(covered.index, protectedWindowStart - 1);
  const hideThrough = hideThroughIndex < 0 ? null : messages[hideThroughIndex];
  return {
    visibility_version: TAVERN_MEMORY_VISIBILITY_VERSION,
    checkpoint_id: manifest.checkpoint_id,
    covered_ai_ordinal: head.checkpoint_index.covered_ai_ordinal,
    hide_through_index: hideThrough === undefined || hideThrough === null ? null : hideThroughIndex,
    hide_through_message_id: hideThrough?.message_id_at_capture ?? null,
    protected_window_start_index: protectedWindowStart,
    protected_window_start_message_id:
      messages[protectedWindowStart]?.message_id_at_capture ?? null,
    protected_ai_message_ids: protectedAi.map((item) => item.message.message_id_at_capture),
  };
}

async function commitVisibilityStage(
  request: TavernMemoryVisibilityCommitRequest,
  head: TavernMemoryColdHead,
  step: "visibility_applied" | "complete",
  plan: TavernMemoryCheckpointVisibilityPlan,
): Promise<TavernMemoryColdHead> {
  const batch = head.work_state;
  if (batch === null) throw new TypeError("Visibility checkpoint has no batch state");
  const completedBatches = head.source_index.completed_batches.map((item) =>
    item.checkpoint_id === plan.checkpoint_id
      ? {
          ...item,
          recall_version: TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION,
          hidden_through_message_id: plan.hide_through_message_id,
        }
      : item,
  );
  return request.book_store.commit({
    commit_id: `${request.operation_id}:${step}:${plan.checkpoint_id}`,
    expected_generation: head.generation,
    expected_generation_checksum: head.generation_checksum,
    committed_at: request.committed_at,
    source_index: { ...head.source_index, completed_batches: completedBatches },
    work_state: advanceTavernMemoryBatchDurability(batch, step),
    checkpoint_index: {
      ...head.checkpoint_index,
      hidden_through_message_id: plan.hide_through_message_id,
    },
    active_state: head.active_state,
    epistemic_state: head.epistemic_state,
    thread_impact: head.thread_impact,
    module_views: head.module_views,
    audit_ring: [
      ...head.audit_ring,
      {
        at: request.committed_at,
        batch_id: batch.batch_id,
        module_id: null,
        event: step === "complete" ? "batch_complete" : "batch_visibility_applied",
        error_code: null,
      },
    ],
    retained_core_page_ids: head.core_page_ids,
    retained_module_view_page_ids: head.module_view_page_ids,
    core_pages: [],
    module_view_pages: [],
  });
}

export async function commitTavernMemoryCheckpointVisibility(
  request: TavernMemoryVisibilityCommitRequest,
): Promise<TavernMemoryVisibilityCommitResult> {
  if (request.operation_id.trim().length === 0 || request.committed_at.trim().length === 0) {
    throw new TypeError("Visibility commit identity is required");
  }
  const plan = await planTavernMemoryCheckpointVisibility(request);
  const expectedReceipt: TavernMemoryVisibilityReceipt = {
    checkpoint_id: plan.checkpoint_id,
    hide_through_message_id: plan.hide_through_message_id,
    protected_ai_message_ids: plan.protected_ai_message_ids,
  };
  if (canonicalJson(request.receipt) !== canonicalJson(expectedReceipt)) {
    throw new TypeError("Host visibility receipt does not match the current checkpoint plan");
  }
  let verified = await readVerifiedTavernMemoryCheckpoint(request.book_store, plan.checkpoint_id);
  if (verified.head.work_state?.status === "COMPLETE") {
    if (verified.head.checkpoint_index.hidden_through_message_id !== plan.hide_through_message_id) {
      throw new TypeError("Completed visibility cursor disagrees with the current plan");
    }
    return { status: "ALREADY_COMPLETE", head: verified.head, plan };
  }
  if (
    verified.head.work_state !== null &&
    canApplyTavernMemoryVisibility(verified.head.work_state)
  ) {
    await commitVisibilityStage(request, verified.head, "visibility_applied", plan);
    verified = await readVerifiedTavernMemoryCheckpoint(request.book_store, plan.checkpoint_id);
  }
  if (verified.head.work_state?.status !== "VISIBILITY_APPLIED") {
    throw new TypeError("Visibility can only complete after a verified host application");
  }
  await commitVisibilityStage(request, verified.head, "complete", plan);
  const completed = await readVerifiedTavernMemoryCheckpoint(
    request.book_store,
    plan.checkpoint_id,
  );
  if (
    completed.head.work_state?.status !== "COMPLETE" ||
    completed.head.checkpoint_index.hidden_through_message_id !== plan.hide_through_message_id
  ) {
    throw new TypeError("Visibility completion failed cold verification");
  }
  return { status: "COMPLETE", head: completed.head, plan };
}
