import type { HashDigest, NarraMemId, NarraMemIdKind } from "@narramem/core-domain";

export interface CandidateCompilerPorts {
  readonly allocate_id: <Kind extends NarraMemIdKind>(
    kind: Kind,
    stable_key: string,
  ) => NarraMemId<Kind>;
  readonly hash_text: (text: string) => Promise<HashDigest>;
  readonly now: () => string;
}

export class CandidateCompilationError extends Error {
  public readonly codes: readonly string[];
  public readonly candidate_keys: readonly string[];
  public readonly diagnostic_paths: readonly string[];
  public readonly record_ids: readonly NarraMemId[];
  public readonly dependency_record_ids: readonly NarraMemId[];

  public constructor(
    message: string,
    codes: readonly string[],
    diagnostics: {
      readonly candidate_keys?: readonly string[];
      readonly diagnostic_paths?: readonly string[];
      readonly record_ids?: readonly NarraMemId[];
      readonly dependency_record_ids?: readonly NarraMemId[];
    } = {},
  ) {
    super(message);
    this.name = "CandidateCompilationError";
    this.codes = codes;
    this.candidate_keys = diagnostics.candidate_keys ?? [];
    this.diagnostic_paths = diagnostics.diagnostic_paths ?? [];
    this.record_ids = diagnostics.record_ids ?? [];
    this.dependency_record_ids = diagnostics.dependency_record_ids ?? [];
  }
}
