import type { NarraMemModularRuntimeSnapshot } from "./modular-memory-runtime.js";

const VISIBLE_STATUSES = new Set<NarraMemModularRuntimeSnapshot["status"]>([
  "running",
  "finalizing",
  "waiting_for_user",
  "failed",
  "complete",
]);

/** A toast belongs to one durable batch, not to each module status update. */
export function memoryCenterToastTaskKey(
  snapshot: Pick<NarraMemModularRuntimeSnapshot, "batch_id">,
): string | null {
  return snapshot.batch_id;
}

export function shouldShowMemoryCenterToast(
  snapshot: Pick<NarraMemModularRuntimeSnapshot, "batch_id" | "status">,
  dismissedTaskKey: string | null,
): boolean {
  const taskKey = memoryCenterToastTaskKey(snapshot);
  return taskKey !== null && taskKey !== dismissedTaskKey && VISIBLE_STATUSES.has(snapshot.status);
}
