import type { Entity, RecallBundle, RecallQuery, RecallTrace } from "@narramem/core-domain";

import {
  readVerifiedTavernMemoryCheckpoint,
  type TavernMemoryCheckpointManifest,
  type TavernMemoryCheckpointStorePort,
} from "./memory-batch-finalizer.js";
import type { TavernMemoryColdHead } from "./memory-book-contracts.js";
import { advanceTavernMemoryBatchDurability } from "./memory-module-state.js";
import { assembleTavernRecallCorpus, parseTavernRecallCorpus } from "./recall.js";
import {
  TAVERN_RECALL_ENGINE_VERSION,
  TavernRecallError,
  type TavernRecallSourceAlignment,
  type TavernRecallSourcePolicy,
} from "./recall-contracts.js";
import { verifyTavernSourceSnapshot } from "./source-snapshot.js";
import {
  TAVERN_SOURCE_SNAPSHOT_VERSION,
  type TavernSourceSnapshot,
} from "./source-snapshot-contracts.js";
import { canonicalJson } from "./worldbook-codec.js";

export const TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION = TAVERN_RECALL_ENGINE_VERSION;

export interface TavernMemoryCheckpointRecallRequest {
  readonly book_store: TavernMemoryCheckpointStorePort;
  readonly current_source_snapshot: TavernSourceSnapshot;
  readonly token_budget: number;
  readonly source_policy?: TavernRecallSourcePolicy;
  readonly latest_raw_input?: string;
}

export interface TavernMemoryCheckpointRecallResult {
  readonly checkpoint_recall_version: typeof TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION;
  readonly head: TavernMemoryColdHead;
  readonly manifest: TavernMemoryCheckpointManifest;
  readonly source_alignment: TavernRecallSourceAlignment;
  readonly principal: Entity;
  readonly query: RecallQuery;
  readonly bundle: RecallBundle;
  readonly trace: RecallTrace;
}

export interface TavernMemoryCheckpointRecallReadyRequest
  extends TavernMemoryCheckpointRecallRequest {
  readonly operation_id: string;
  readonly committed_at: string;
}

export interface TavernMemoryCheckpointRecallReadyResult
  extends TavernMemoryCheckpointRecallResult {
  readonly status: "RECALL_READY" | "ALREADY_READY";
}

function sameScope(
  left: TavernSourceSnapshot["scope"],
  right: TavernSourceSnapshot["scope"],
): boolean {
  return left.character_id === right.character_id && left.chat_id === right.chat_id;
}

export async function alignTavernMemoryCheckpointSource(
  manifest: TavernMemoryCheckpointManifest,
  current: TavernSourceSnapshot,
  policy: TavernRecallSourcePolicy,
): Promise<TavernRecallSourceAlignment> {
  await verifyTavernSourceSnapshot(current);
  if (
    current.memory_set_id !== manifest.memory_set_id ||
    !sameScope(current.scope, manifest.source_scope)
  ) {
    throw new TavernRecallError(
      "SOURCE_CHANGED",
      "Current chat scope does not match the checkpoint",
    );
  }
  if (current.checksum === manifest.source_checksum) {
    if (
      current.messages.length !== manifest.source_message_count ||
      current.root_chain_hash !== manifest.source_root_chain_hash
    ) {
      throw new TavernRecallError("ARCHIVE_CORRUPT", "Checkpoint Source authentication disagrees");
    }
    return {
      mode: "EXACT",
      committed_message_count: manifest.source_message_count,
      live_tail_message_count: 0,
      current_source_checksum: current.checksum,
    };
  }
  if (
    policy !== "ALLOW_APPEND_ONLY_LIVE_TAIL" ||
    current.messages.length <= manifest.source_message_count
  ) {
    throw new TavernRecallError(
      "SOURCE_CHANGED",
      "Current Source is not the exact checkpoint Source",
    );
  }
  const authenticatedPrefix: TavernSourceSnapshot = {
    schema_version: TAVERN_SOURCE_SNAPSHOT_VERSION,
    memory_set_id: manifest.memory_set_id,
    scope: manifest.source_scope,
    source_revision: manifest.source_snapshot_revision,
    messages: current.messages.slice(0, manifest.source_message_count),
    root_chain_hash: manifest.source_root_chain_hash,
    checksum: manifest.source_checksum,
  };
  try {
    await verifyTavernSourceSnapshot(authenticatedPrefix);
  } catch {
    throw new TavernRecallError(
      "SOURCE_CHANGED",
      "Current Source is not an authenticated append-only checkpoint successor",
    );
  }
  return {
    mode: "APPEND_ONLY_LIVE_TAIL",
    committed_message_count: manifest.source_message_count,
    live_tail_message_count: current.messages.length - manifest.source_message_count,
    current_source_checksum: current.checksum,
  };
}

export async function assembleTavernMemoryCheckpointRecall(
  request: TavernMemoryCheckpointRecallRequest,
): Promise<TavernMemoryCheckpointRecallResult> {
  if (
    !Number.isInteger(request.token_budget) ||
    request.token_budget < 64 ||
    request.token_budget > 32_768
  ) {
    throw new TavernRecallError("INVALID_INPUT", "Recall token budget must be 64-32768");
  }
  const verified = await readVerifiedTavernMemoryCheckpoint(request.book_store);
  const alignment = await alignTavernMemoryCheckpointSource(
    verified.manifest,
    request.current_source_snapshot,
    request.source_policy ?? "EXACT_ONLY",
  );
  const corpus = parseTavernRecallCorpus(verified.records);
  const principal = corpus.entities.find(
    (entity) =>
      entity.entity_id === verified.manifest.principal_entity_id &&
      entity.entity_type === "character",
  );
  if (principal === undefined) {
    throw new TavernRecallError(
      "PRINCIPAL_UNRESOLVED",
      "Checkpoint D0 principal is absent from the consumer-safe Entity corpus",
    );
  }
  const latestRawInput =
    request.latest_raw_input ??
    [...request.current_source_snapshot.messages]
      .reverse()
      .find((message) => message.narrative_text !== null)?.narrative_text ??
    undefined;
  const assembled = await assembleTavernRecallCorpus(
    corpus,
    principal,
    latestRawInput,
    request.token_budget,
    alignment,
  );
  if (
    assembled.bundle.based_on_revision_id !== verified.manifest.source_revision_id ||
    assembled.query.memory_space_id !== corpus.memory_space_id
  ) {
    throw new TavernRecallError("OUTPUT_SCHEMA_INVALID", "Checkpoint Recall identity mismatch");
  }
  return {
    checkpoint_recall_version: TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION,
    head: verified.head,
    manifest: verified.manifest,
    source_alignment: alignment,
    principal,
    ...assembled,
  };
}

export async function markTavernMemoryCheckpointRecallReady(
  request: TavernMemoryCheckpointRecallReadyRequest,
): Promise<TavernMemoryCheckpointRecallReadyResult> {
  if (request.operation_id.trim().length === 0 || request.committed_at.trim().length === 0) {
    throw new TavernRecallError("INVALID_INPUT", "Recall-ready commit identity is required");
  }
  const assembled = await assembleTavernMemoryCheckpointRecall(request);
  const head = assembled.head;
  const batch = head.work_state;
  if (batch === null) {
    throw new TavernRecallError("ARCHIVE_CORRUPT", "Checkpoint has no active batch state");
  }
  if (["RECALL_READY", "VISIBILITY_APPLIED", "COMPLETE"].includes(batch.status)) {
    if (head.checkpoint_index.recall_version !== TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION) {
      throw new TavernRecallError("ARCHIVE_CORRUPT", "Ready checkpoint has another Recall version");
    }
    return { ...assembled, status: "ALREADY_READY" };
  }
  if (batch.status !== "CHECKPOINT_VERIFIED") {
    throw new TavernRecallError(
      "SEMANTIC_COVERAGE_MISSING",
      `Recall-ready requires CHECKPOINT_VERIFIED, found ${batch.status}`,
    );
  }
  const nextBatch = advanceTavernMemoryBatchDurability(batch, "recall_ready");
  const completedBatches = head.source_index.completed_batches.map((item) =>
    item.checkpoint_id === assembled.manifest.checkpoint_id
      ? { ...item, recall_version: TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION }
      : item,
  );
  await request.book_store.commit({
    commit_id: `${request.operation_id}:recall_ready:${assembled.manifest.checkpoint_id}`,
    expected_generation: head.generation,
    expected_generation_checksum: head.generation_checksum,
    committed_at: request.committed_at,
    source_index: { ...head.source_index, completed_batches: completedBatches },
    work_state: nextBatch,
    checkpoint_index: {
      ...head.checkpoint_index,
      recall_version: TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION,
    },
    active_state: head.active_state,
    epistemic_state: head.epistemic_state,
    thread_impact: head.thread_impact,
    module_views: head.module_views,
    audit_ring: [
      ...head.audit_ring,
      {
        at: request.committed_at,
        batch_id: batch.batch_id,
        module_id: null,
        event: "batch_recall_ready",
        error_code: null,
      },
    ],
    retained_core_page_ids: head.core_page_ids,
    retained_module_view_page_ids: head.module_view_page_ids,
    core_pages: [],
    module_view_pages: [],
  });
  const cold = await readVerifiedTavernMemoryCheckpoint(
    request.book_store,
    assembled.manifest.checkpoint_id,
  );
  if (
    cold.head.work_state?.status !== "RECALL_READY" ||
    cold.head.checkpoint_index.recall_version !== TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION ||
    canonicalJson(cold.manifest) !== canonicalJson(assembled.manifest)
  ) {
    throw new TavernRecallError("ARCHIVE_CORRUPT", "Recall-ready cold verification failed");
  }
  return { ...assembled, head: cold.head, status: "RECALL_READY" };
}
