import type {
  CurrentSceneContext,
  ElapsedStoryTimePredicate,
  FutureImpact,
  JsonValue,
  NarraMemId,
  NarrativeThreadState,
  StatePredicate,
  TriggerEvaluation,
  TriggerRule,
} from "@narramem/core-domain";
import { validateWireValue } from "@narramem/core-validator";

export const NARRATIVE_TRIGGER_EVALUATOR_VERSION = "0.1.0" as const;

export interface NarrativeRuleEvaluation {
  readonly result: "eligible" | "ineligible" | "unknown";
  readonly matched_rule_paths: readonly string[];
  readonly unresolved_rule_paths: readonly string[];
}

export type NarrativeStateResolution =
  | { readonly status: "known"; readonly value: JsonValue }
  | { readonly status: "absent" }
  | { readonly status: "unknown" };

/**
 * Host-neutral, read-only trigger context. Game and Tavern adapters must resolve
 * their own time and state histories; this runtime never reads untrusted raw
 * text and never mutates a Thread or FutureImpact.
 */
export interface NarrativeTriggerEvaluationContext {
  readonly current_scene: CurrentSceneContext;
  readonly current_event_types: readonly string[];
  readonly resolve_state: (predicate: StatePredicate) => NarrativeStateResolution;
  readonly resolve_thread_state: (
    threadId: NarraMemId<"narrative_thread">,
  ) => NarrativeThreadState | undefined;
  readonly resolve_elapsed_story_time: (predicate: ElapsedStoryTimePredicate) => number | undefined;
}

function unique(values: readonly string[]): readonly string[] {
  return [...new Set(values)];
}

function canonicalJson(value: JsonValue): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  return `{${Object.entries(value)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([key, nested]) => `${JSON.stringify(key)}:${canonicalJson(nested)}`)
    .join(",")}}`;
}

function merge(
  op: "all" | "any",
  evaluations: readonly NarrativeRuleEvaluation[],
): NarrativeRuleEvaluation {
  const matched = unique(evaluations.flatMap((item) => item.matched_rule_paths));
  const unresolved = unique(evaluations.flatMap((item) => item.unresolved_rule_paths));
  if (op === "all") {
    return {
      result: evaluations.some((item) => item.result === "ineligible")
        ? "ineligible"
        : evaluations.some((item) => item.result === "unknown")
          ? "unknown"
          : "eligible",
      matched_rule_paths: matched,
      unresolved_rule_paths: unresolved,
    };
  }
  return {
    result: evaluations.some((item) => item.result === "eligible")
      ? "eligible"
      : evaluations.some((item) => item.result === "unknown")
        ? "unknown"
        : "ineligible",
    matched_rule_paths: matched,
    unresolved_rule_paths: unresolved,
  };
}

function compareState(predicate: StatePredicate, actual: NarrativeStateResolution): boolean {
  if (predicate.comparison === "exists") return actual.status === "known";
  if (actual.status !== "known" || predicate.expected === undefined) return false;
  const left = actual.value;
  const right = predicate.expected;
  switch (predicate.comparison) {
    case "eq":
      return canonicalJson(left) === canonicalJson(right);
    case "ne":
      return canonicalJson(left) !== canonicalJson(right);
    case "gt":
    case "gte":
    case "lt":
    case "lte":
      if (typeof left !== "number" || typeof right !== "number") return false;
      if (predicate.comparison === "gt") return left > right;
      if (predicate.comparison === "gte") return left >= right;
      if (predicate.comparison === "lt") return left < right;
      return left <= right;
    case "contains":
      return typeof left === "string"
        ? typeof right === "string" && left.includes(right)
        : Array.isArray(left) && left.some((item) => canonicalJson(item) === canonicalJson(right));
  }
}

function compareElapsed(predicate: ElapsedStoryTimePredicate, elapsed: number): boolean {
  if (predicate.comparison === "gt") return elapsed > predicate.amount;
  if (predicate.comparison === "gte") return elapsed >= predicate.amount;
  if (predicate.comparison === "lt") return elapsed < predicate.amount;
  if (predicate.comparison === "lte") return elapsed <= predicate.amount;
  return (
    predicate.upper_amount !== undefined &&
    elapsed >= predicate.amount &&
    elapsed <= predicate.upper_amount
  );
}

export function evaluateNarrativeTriggerRule(
  rule: TriggerRule,
  context: NarrativeTriggerEvaluationContext,
  path = "$",
): NarrativeRuleEvaluation {
  const eligible = (matchedPath = path): NarrativeRuleEvaluation => ({
    result: "eligible",
    matched_rule_paths: [matchedPath],
    unresolved_rule_paths: [],
  });
  const ineligible = (): NarrativeRuleEvaluation => ({
    result: "ineligible",
    matched_rule_paths: [],
    unresolved_rule_paths: [],
  });
  const unknown = (): NarrativeRuleEvaluation => ({
    result: "unknown",
    matched_rule_paths: [],
    unresolved_rule_paths: [path],
  });
  const entities = new Set([
    ...context.current_scene.participant_ids,
    ...(context.current_scene.object_ids ?? []),
    ...(context.current_scene.focalizer_id === undefined
      ? []
      : [context.current_scene.focalizer_id]),
  ]);

  switch (rule.op) {
    case "all":
    case "any":
      return merge(
        rule.op,
        rule.rules.map((nested, index) =>
          evaluateNarrativeTriggerRule(nested, context, `${path}.rules[${index}]`),
        ),
      );
    case "not": {
      const nested = evaluateNarrativeTriggerRule(rule.rule, context, `${path}.rule`);
      return nested.result === "unknown"
        ? nested
        : nested.result === "eligible"
          ? ineligible()
          : eligible();
    }
    case "event_type":
      return context.current_event_types.includes(rule.event_type) ? eligible() : ineligible();
    case "entity_involved":
      return entities.has(rule.entity_id) ? eligible() : ineligible();
    case "object_present":
      return new Set(context.current_scene.object_ids ?? []).has(rule.object_id)
        ? eligible()
        : ineligible();
    case "location_is":
      return context.current_scene.location_id === rule.location_id ? eligible() : ineligible();
    case "state_predicate":
    case "relationship_predicate": {
      const actual = context.resolve_state(rule.predicate);
      return actual.status === "unknown"
        ? unknown()
        : compareState(rule.predicate, actual)
          ? eligible()
          : ineligible();
    }
    case "thread_state": {
      const state = context.resolve_thread_state(rule.predicate.thread_id);
      return state === undefined
        ? unknown()
        : rule.predicate.state_in.includes(state)
          ? eligible()
          : ineligible();
    }
    case "elapsed_story_time": {
      const elapsed = context.resolve_elapsed_story_time(rule.predicate);
      return elapsed === undefined
        ? unknown()
        : compareElapsed(rule.predicate, elapsed)
          ? eligible()
          : ineligible();
    }
    case "semantic_cue":
      return unknown();
  }
}

export function evaluateNarrativeFutureImpact(
  impact: FutureImpact,
  evaluatedAtRevisionId: NarraMemId<"source_revision">,
  context: NarrativeTriggerEvaluationContext,
): TriggerEvaluation {
  const evaluation = evaluateNarrativeTriggerRule(impact.trigger, context);
  const result: TriggerEvaluation = {
    impact_id: impact.impact_id,
    evaluated_at_revision_id: evaluatedAtRevisionId,
    result: evaluation.result,
    matched_rule_paths: evaluation.matched_rule_paths,
    unresolved_rule_paths: evaluation.unresolved_rule_paths,
    persistent_state_unchanged: true,
  };
  const wire = validateWireValue("trigger_evaluation", result);
  if (!wire.valid) throw new TypeError("Trigger evaluator emitted an invalid TriggerEvaluation");
  return result;
}
