import type { ModularExtractionInput, ModularExtractionOutput } from "@narramem/core-domain";

import type { TavernJsonValue } from "./contracts.js";
import type {
  TavernMemoryCorePage,
  TavernMemoryModuleId,
  TavernMemoryModuleViewIndex,
  TavernMemoryModuleViewItem,
  TavernMemoryModuleViewPage,
} from "./memory-book-contracts.js";
import type { TavernMemoryBookStore } from "./memory-book-store.js";
import type {
  TavernMemoryModuleCompilerPort,
  TavernMemoryPreparedModuleCommit,
} from "./memory-module-runner.js";
import type { TavernModularCandidatePartition } from "./modular-candidate-partition.js";
import { canonicalJson, sha256HexUtf8, utf8ByteLength } from "./worldbook-codec.js";

export const TAVERN_MODULAR_STAGING_COMPILER_VERSION = "0.1.0" as const;

export interface TavernModularStagingCompilerOptions {
  readonly max_records_per_page: number;
  readonly max_page_utf8_bytes: number;
  readonly now: () => string;
}

interface CandidateRecord {
  readonly field: string;
  readonly candidate_key: string;
  readonly value: Record<string, unknown>;
}

interface StagedRecord {
  readonly record_id: string;
  readonly record_kind: "module_candidate";
  readonly payload: TavernJsonValue;
  readonly view: Omit<TavernMemoryModuleViewItem, "core_page_id">;
}

const RECORD_FIELDS: Readonly<Record<TavernMemoryModuleId, readonly string[]>> = {
  M1: ["entities"],
  M2: ["scenes", "episodes"],
  M3: ["events"],
  M4: ["state_transitions"],
  M5: ["epistemic_states"],
  M6: ["causal_links"],
  M7: [
    "prior_thread_dispositions",
    "prior_future_impact_dispositions",
    "threads",
    "future_impacts",
  ],
};

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const nonEmpty = (value: unknown): string | null =>
  typeof value === "string" && value.trim().length > 0 ? value.trim() : null;

const clip = (value: string, maximum = 120): string =>
  value.length <= maximum ? value : `${value.slice(0, maximum - 1)}…`;

function records(output: ModularExtractionOutput): CandidateRecord[] {
  const raw = output as unknown as Record<string, unknown>;
  return RECORD_FIELDS[output.module_id].flatMap((field) =>
    Array.isArray(raw[field])
      ? (raw[field] as readonly unknown[]).flatMap((value) =>
          isObject(value) && nonEmpty(value.candidate_key) !== null
            ? [{ field, candidate_key: nonEmpty(value.candidate_key) as string, value }]
            : [],
        )
      : [],
  );
}

function evidenceIds(
  moduleId: TavernMemoryModuleId,
  field: string,
  value: Record<string, unknown>,
): string[] {
  if (moduleId === "M2") {
    const ids = field === "scenes" ? value.source_evidence_ids : value.evidence_ids;
    return Array.isArray(ids) ? ids.filter((item): item is string => typeof item === "string") : [];
  }
  if (moduleId === "M7") {
    return Array.isArray(value.evidence_ids)
      ? value.evidence_ids.filter((item): item is string => typeof item === "string")
      : [];
  }
  return Array.isArray(value.evidence_quotes)
    ? value.evidence_quotes.flatMap((quote) =>
        isObject(quote) && typeof quote.evidence_id === "string" ? [quote.evidence_id] : [],
      )
    : [];
}

function displayText(
  moduleId: TavernMemoryModuleId,
  field: string,
  value: Record<string, unknown>,
): {
  readonly title: string;
  readonly summary: string;
} {
  const key = nonEmpty(value.candidate_key) ?? "未命名记录";
  if (moduleId === "M1") {
    return {
      title: nonEmpty(value.canonical_label) ?? key,
      summary: clip(
        [nonEmpty(value.entity_type), ...(Array.isArray(value.aliases) ? value.aliases : [])]
          .filter(Boolean)
          .join(" · ") || "人物／实体",
      ),
    };
  }
  if (moduleId === "M2" && field === "episodes") {
    return {
      title: nonEmpty(value.title) ?? key,
      summary: clip(nonEmpty(value.summary) ?? "章节锚点"),
    };
  }
  if (moduleId === "M2") {
    return {
      title: `场景 · ${key}`,
      summary: clip(nonEmpty(value.boundary_reason) ?? "场景边界"),
    };
  }
  if (moduleId === "M3") {
    return {
      title: clip(nonEmpty(value.action_or_occurrence) ?? key, 64),
      summary: clip(`事件 · ${nonEmpty(value.event_type) ?? "未分类"}`),
    };
  }
  if (moduleId === "M4") {
    return {
      title: nonEmpty(value.state_key) ?? key,
      summary: clip(`状态变化 · ${nonEmpty(value.operation) ?? "更新"}`),
    };
  }
  if (moduleId === "M5") {
    const target = isObject(value.target) ? nonEmpty(value.target.kind) : null;
    return {
      title: `角色认知 · ${key}`,
      summary: clip(`${nonEmpty(value.mode) ?? "认知"} · ${target ?? "命题"}`),
    };
  }
  if (moduleId === "M6") {
    return {
      title: `因果 · ${nonEmpty(value.relation) ?? key}`,
      summary: clip(nonEmpty(value.mechanism) ?? "因果机制"),
    };
  }
  if (field === "prior_thread_dispositions") {
    return {
      title: `线索状态 · ${nonEmpty(value.prior_thread_ref) ?? key}`,
      summary: clip(`更新为 ${nonEmpty(value.next_state) ?? "待确认"}`),
    };
  }
  if (field === "prior_future_impact_dispositions") {
    return {
      title: `未来影响状态 · ${nonEmpty(value.prior_impact_ref) ?? key}`,
      summary: clip(`更新为 ${nonEmpty(value.next_state) ?? "待确认"}`),
    };
  }
  if (field === "threads") {
    return {
      title: nonEmpty(value.title) ?? key,
      summary: clip(nonEmpty(value.trigger_summary) ?? "叙事线索"),
    };
  }
  return {
    title: `未来影响 · ${key}`,
    summary: clip(nonEmpty(value.trigger_summary) ?? "未来影响候选"),
  };
}

function floorRange(
  input: ModularExtractionInput,
  ids: readonly string[],
): readonly [number | null, number | null] {
  const idSet = new Set(ids);
  const ordinals = input.current_evidence
    .filter((evidence) => idSet.has(evidence.evidence_id))
    .map((evidence) => evidence.source_order.ordinal);
  return ordinals.length === 0 ? [null, null] : [Math.min(...ordinals), Math.max(...ordinals)];
}

function dependencyRefs(value: unknown, ownKey: string): string[] {
  const refs = new Set<string>();
  const visit = (current: unknown, property: string | null): void => {
    if (typeof current === "string") {
      if (
        current !== ownKey &&
        property !== null &&
        (property === "candidate_key" ||
          property.endsWith("_candidate_key") ||
          property.endsWith("_refs") ||
          property.endsWith("_keys"))
      ) {
        refs.add(current);
      }
      return;
    }
    if (Array.isArray(current)) {
      for (const item of current) visit(item, property);
      return;
    }
    if (isObject(current)) for (const [key, item] of Object.entries(current)) visit(item, key);
  };
  visit(value, null);
  return [...refs].sort();
}

function pageChunks(
  records: readonly StagedRecord[],
  options: TavernModularStagingCompilerOptions,
): StagedRecord[][] {
  const chunks: StagedRecord[][] = [];
  let current: StagedRecord[] = [];
  for (const record of records) {
    const proposed = [...current, record];
    if (
      current.length > 0 &&
      (proposed.length > options.max_records_per_page ||
        utf8ByteLength(canonicalJson({ records: proposed })) > options.max_page_utf8_bytes)
    ) {
      chunks.push(current);
      current = [record];
    } else {
      current = proposed;
    }
  }
  if (current.length > 0) chunks.push(current);
  return chunks;
}

export class TavernModularStagingCompiler implements TavernMemoryModuleCompilerPort {
  constructor(
    private readonly store: TavernMemoryBookStore,
    private readonly options: TavernModularStagingCompilerOptions,
  ) {
    if (
      !Number.isInteger(options.max_records_per_page) ||
      options.max_records_per_page < 1 ||
      !Number.isInteger(options.max_page_utf8_bytes) ||
      options.max_page_utf8_bytes < 1024
    ) {
      throw new TypeError("Invalid modular staging page limits");
    }
  }

  async prepare(
    partition: TavernModularCandidatePartition,
    input: ModularExtractionInput,
    previous: TavernModularCandidatePartition | null,
  ): Promise<TavernMemoryPreparedModuleCommit> {
    const cold = await this.store.readColdHead();
    const head = cold.head;
    if (head === null) throw new TypeError("Memory Book has no cold head");
    if (
      partition.module_id !== input.module_id ||
      partition.source_revision_id !== input.source_revision_id
    ) {
      throw new TypeError("Staging partition does not match module input");
    }
    const previousKeys = new Set(previous?.accepted_record_keys ?? []);
    const allRecords = records(partition.accepted_output);
    const acceptedRecordIds = await Promise.all(
      allRecords.map(
        async (record) =>
          `module_record_${(
            await sha256HexUtf8(
              canonicalJson({
                source_revision_id: input.source_revision_id,
                batch_id: input.batch_id,
                module_id: input.module_id,
                candidate_key: record.candidate_key,
              }),
            )
          ).slice(0, 40)}`,
      ),
    );
    const idByKey = new Map(
      allRecords.map((record, index) => [record.candidate_key, acceptedRecordIds[index] as string]),
    );
    const createdAt = this.options.now();
    const staged = await Promise.all(
      allRecords
        .filter((record) => !previousKeys.has(record.candidate_key))
        .map(async (record): Promise<StagedRecord> => {
          const recordId = idByKey.get(record.candidate_key);
          if (recordId === undefined) throw new TypeError("Missing stable staged record ID");
          const ids = evidenceIds(input.module_id, record.field, record.value);
          const [floorStart, floorEnd] = floorRange(input, ids);
          const display = displayText(input.module_id, record.field, record.value);
          return {
            record_id: recordId,
            record_kind: "module_candidate",
            payload: {
              version: TAVERN_MODULAR_STAGING_COMPILER_VERSION,
              record_id: recordId,
              record_revision: 1,
              status: "ACTIVE",
              module_id: input.module_id,
              source_revision_id: input.source_revision_id,
              batch_id: input.batch_id,
              candidate_key: record.candidate_key,
              candidate_field: record.field,
              evidence_ids: ids,
              dependencies: dependencyRefs(record.value, record.candidate_key),
              candidate: record.value as TavernJsonValue,
            },
            view: {
              record_id: recordId,
              record_revision: 1,
              sort_time: createdAt,
              title: display.title,
              summary: display.summary,
              status: "ACTIVE",
              source_floor_start: floorStart,
              source_floor_end: floorEnd,
            },
          };
        }),
    );
    staged.sort((left, right) => right.record_id.localeCompare(left.record_id));
    const oversized = staged.filter(
      (record) =>
        utf8ByteLength(canonicalJson({ page_id: "candidate", records: [record] })) >
        this.options.max_page_utf8_bytes,
    );
    if (oversized.length > 0) {
      const keyById = new Map(
        allRecords.map((record) => [idByKey.get(record.candidate_key), record.candidate_key]),
      );
      return {
        accepted_record_ids: acceptedRecordIds,
        compiler_findings: oversized.flatMap((record) => {
          const key = keyById.get(record.record_id);
          return key === undefined
            ? []
            : [
                {
                  candidate_key: key,
                  diagnostic_codes: ["STAGED_RECORD_PAGE_TOO_LARGE"],
                  diagnostic_paths: ["/candidate"],
                },
              ];
        }),
        core_pages: [],
        module_view_pages: [],
      };
    }
    if (staged.length === 0) {
      return {
        accepted_record_ids: acceptedRecordIds,
        compiler_findings: [],
        core_pages: [],
        module_view_pages: [],
        module_views: head.module_views,
      };
    }
    const chunks = pageChunks(staged, this.options);
    const pageIds = await Promise.all(
      chunks.map(
        async (chunk, index) =>
          `module_page_${(
            await sha256HexUtf8(
              canonicalJson({
                source_revision_id: input.source_revision_id,
                module_id: input.module_id,
                record_ids: chunk.map((record) => record.record_id),
                index,
              }),
            )
          ).slice(0, 40)}`,
      ),
    );
    const corePages: TavernMemoryCorePage[] = chunks.map((chunk, index) => ({
      page_id: pageIds[index] as string,
      records: chunk.map((record) => ({
        record_id: record.record_id,
        record_kind: record.record_kind,
        payload: record.payload,
      })),
    }));
    const currentIndex = head.module_views[input.module_id];
    const viewPages: TavernMemoryModuleViewPage[] = chunks.map((chunk, index) => ({
      page_id: `module_view_${pageIds[index] as string}`,
      module_id: input.module_id,
      newer_page_id: null,
      older_page_id:
        index + 1 < chunks.length
          ? `module_view_${pageIds[index + 1] as string}`
          : currentIndex.latest_page_id,
      items: chunk.map((record) => ({ ...record.view, core_page_id: pageIds[index] as string })),
    }));
    const newest = viewPages[0]?.items[0];
    if (newest === undefined) throw new TypeError("Staged view page has no newest record");
    const nextIndex: TavernMemoryModuleViewIndex = {
      module_id: input.module_id,
      record_count: currentIndex.record_count + staged.length,
      abnormal_count: currentIndex.abnormal_count,
      newest_cursor: {
        sort_time: newest.sort_time,
        record_revision: newest.record_revision,
        record_id: newest.record_id,
      },
      latest_page_id: viewPages[0]?.page_id ?? currentIndex.latest_page_id,
      oldest_page_id: currentIndex.oldest_page_id ?? viewPages.at(-1)?.page_id ?? null,
      page_count: currentIndex.page_count + viewPages.length,
    };
    const moduleViews = {
      ...head.module_views,
      [input.module_id]: nextIndex,
    } as Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
    return {
      accepted_record_ids: acceptedRecordIds,
      compiler_findings: [],
      core_pages: corePages,
      module_view_pages: viewPages,
      module_views: moduleViews,
    };
  }
}
