declare const narramemIdBrand: unique symbol;

export const NARRAMEM_ID_KINDS = [
  "memory_space",
  "branch",
  "source_revision",
  "evidence",
  "scene",
  "episode",
  "event",
  "entity",
  "identity_claim",
  "salience_assessment",
  "state_assertion",
  "state_delta",
  "current_state_view",
  "proposition",
  "epistemic_state",
  "information_transfer",
  "causal_link",
  "narrative_thread",
  "future_impact",
  "interpretation",
  "recall_cue",
  "derivation",
  "change_set",
  "recall_bundle",
  "recall_trace",
  "investigation",
  "transaction",
  "shard",
] as const;

export type NarraMemIdKind = (typeof NARRAMEM_ID_KINDS)[number];

export type NarraMemId<Kind extends NarraMemIdKind = NarraMemIdKind> = string & {
  readonly [narramemIdBrand]: Kind;
};

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const idKindSet: ReadonlySet<string> = new Set(NARRAMEM_ID_KINDS);

export function isUuid(value: string): boolean {
  return UUID_PATTERN.test(value);
}

export function createNarraMemId<Kind extends NarraMemIdKind>(
  kind: Kind,
  uuid: string,
): NarraMemId<Kind> {
  if (!isUuid(uuid)) {
    throw new TypeError(`Invalid UUID for NarraMem ${kind} id`);
  }

  return `nm_${kind}_${uuid.toLowerCase()}` as NarraMemId<Kind>;
}

export function parseNarraMemId<Kind extends NarraMemIdKind>(
  kind: Kind,
  value: unknown,
): NarraMemId<Kind> | undefined {
  if (typeof value !== "string") {
    return undefined;
  }

  const prefix = `nm_${kind}_`;
  if (!value.startsWith(prefix) || !isUuid(value.slice(prefix.length))) {
    return undefined;
  }

  return value as NarraMemId<Kind>;
}

export function getNarraMemIdKind(value: unknown): NarraMemIdKind | undefined {
  if (typeof value !== "string" || !value.startsWith("nm_")) {
    return undefined;
  }

  for (const kind of NARRAMEM_ID_KINDS) {
    const prefix = `nm_${kind}_`;
    if (value.startsWith(prefix) && isUuid(value.slice(prefix.length))) {
      return kind;
    }
  }

  return undefined;
}

export function isNarraMemIdKind(value: unknown): value is NarraMemIdKind {
  return typeof value === "string" && idKindSet.has(value);
}
