import type { NarraMemMemoryApiProfile } from "./memory-api-settings.js";

interface MemoryApiFormClient {
  listModels(profile: NarraMemMemoryApiProfile): Promise<readonly string[]>;
  saveCredential(apiKey: string, profile: NarraMemMemoryApiProfile): Promise<void>;
}

export function sameMemoryApiConnectionProfile(
  saved: NarraMemMemoryApiProfile,
  draft: NarraMemMemoryApiProfile,
): boolean {
  return (
    saved.source === draft.source && saved.api_url === draft.api_url && saved.model === draft.model
  );
}

export function assertMemoryApiProfileCanPersist(
  saved: NarraMemMemoryApiProfile,
  draft: NarraMemMemoryApiProfile,
): void {
  if (saved.source !== draft.source && saved.credential_secret_id.length > 0) {
    throw new TypeError(
      "当前配置已有独立 Key，不能直接切换接口来源；请新建配置，或先删除当前配置的 Key。",
    );
  }
}

export function listMemoryApiModelsFromDraft(
  client: MemoryApiFormClient,
  draft: NarraMemMemoryApiProfile,
): Promise<readonly string[]> {
  return client.listModels(draft);
}

export async function saveMemoryApiCredentialForSavedProfile(
  client: MemoryApiFormClient,
  saved: NarraMemMemoryApiProfile,
  draft: NarraMemMemoryApiProfile,
  apiKey: string,
): Promise<void> {
  if (!sameMemoryApiConnectionProfile(saved, draft)) {
    throw new TypeError("普通配置有未保存修改；请先保存配置，再保存／替换 Key。");
  }
  await client.saveCredential(apiKey, saved);
}
