import type {
  JsonObject,
  JsonValue,
  ModularExtractionInput,
  ModularExtractionM1Input,
  ModularExtractionM1Output,
  ModularExtractionM2Output,
  ModularExtractionM3Output,
  ModularExtractionM4Output,
  ModularExtractionM5Output,
  ModularExtractionM6Output,
  ModularExtractionM7Output,
  ModularExtractionModuleId,
  ModularExtractionOutput,
} from "@narramem/core-domain";
import { validateModularExtractionInput } from "@narramem/core-validator";

export interface TavernMemoryModuleInputContext {
  readonly source_revision_id: ModularExtractionInput["source_revision_id"];
  readonly batch_id: string;
  readonly current_evidence: ModularExtractionM1Input["current_evidence"];
  readonly checkpoint_capsule: ModularExtractionM1Input["checkpoint_capsule"];
  readonly known_entities: ModularExtractionM1Input["known_entities"];
  readonly identity_context: JsonObject;
  readonly world_context: JsonObject;
  readonly active_state: JsonValue;
  readonly current_epistemic_state: JsonValue;
  readonly active_threads_and_impacts: JsonValue;
}

export interface TavernMemoryAcceptedModuleOutputs {
  readonly M1?: ModularExtractionM1Output;
  readonly M2?: ModularExtractionM2Output;
  readonly M3?: ModularExtractionM3Output;
  readonly M4?: ModularExtractionM4Output;
  readonly M5?: ModularExtractionM5Output;
  readonly M6?: ModularExtractionM6Output;
  readonly M7?: ModularExtractionM7Output;
}

function requireOutput<ModuleId extends keyof TavernMemoryAcceptedModuleOutputs>(
  accepted: TavernMemoryAcceptedModuleOutputs,
  moduleId: ModuleId,
): NonNullable<TavernMemoryAcceptedModuleOutputs[ModuleId]> {
  const output = accepted[moduleId];
  if (output === undefined)
    throw new TypeError(`${moduleId} must commit before its dependent module`);
  return output as NonNullable<TavernMemoryAcceptedModuleOutputs[ModuleId]>;
}

function validate(input: ModularExtractionInput): ModularExtractionInput {
  const report = validateModularExtractionInput(input, input.module_id);
  if (!report.accepted) {
    throw new TypeError(
      `Invalid ${input.module_id} input: ${report.issues
        .map((issue) => `${issue.code}@${issue.path}`)
        .join(", ")}`,
    );
  }
  return input;
}

/**
 * Builds exactly one module input. A dependent module receives only the accepted
 * outputs it needs; uncommitted/quarantined siblings never cross this boundary.
 */
export function buildTavernMemoryModuleInput(
  moduleId: ModularExtractionModuleId,
  context: TavernMemoryModuleInputContext,
  accepted: TavernMemoryAcceptedModuleOutputs,
): ModularExtractionInput {
  const base = {
    contract_version: "0.1.0" as const,
    source_revision_id: context.source_revision_id,
    batch_id: context.batch_id,
    current_evidence: context.current_evidence,
    checkpoint_capsule: context.checkpoint_capsule,
  };
  switch (moduleId) {
    case "M1":
      return validate({
        ...base,
        module_id: "M1",
        known_entities: context.known_entities,
        identity_context: context.identity_context,
      });
    case "M2":
      return validate({
        ...base,
        module_id: "M2",
        accepted_m1: requireOutput(accepted, "M1"),
        world_context: context.world_context,
      });
    case "M3":
      return validate({
        ...base,
        module_id: "M3",
        accepted_m1: requireOutput(accepted, "M1"),
        accepted_m2: requireOutput(accepted, "M2"),
      });
    case "M4":
      return validate({
        ...base,
        module_id: "M4",
        accepted_m1: requireOutput(accepted, "M1"),
        accepted_m3: requireOutput(accepted, "M3"),
        active_state: context.active_state,
      });
    case "M5":
      return validate({
        ...base,
        module_id: "M5",
        accepted_m1: requireOutput(accepted, "M1"),
        accepted_m3: requireOutput(accepted, "M3"),
        current_epistemic_state: context.current_epistemic_state,
      });
    case "M6":
      return validate({
        ...base,
        module_id: "M6",
        accepted_m3: requireOutput(accepted, "M3"),
        accepted_m4: requireOutput(accepted, "M4"),
      });
    case "M7":
      return validate({
        ...base,
        module_id: "M7",
        accepted_m3: requireOutput(accepted, "M3"),
        accepted_m4: requireOutput(accepted, "M4"),
        accepted_m6: requireOutput(accepted, "M6"),
        active_threads_and_impacts: context.active_threads_and_impacts,
      });
  }
}

export function acceptTavernMemoryModuleOutput(
  accepted: TavernMemoryAcceptedModuleOutputs,
  output: ModularExtractionOutput,
): TavernMemoryAcceptedModuleOutputs {
  return { ...accepted, [output.module_id]: output };
}
