import { getNarraMemIdKind } from "@narramem/core-domain";

import type {
  TavernHostPort,
  TavernWorldbookEntry,
  TavernWorldbookEntryDraft,
} from "./contracts.js";
import { canonicalJson, checksumJson, utf8ByteLength } from "./worldbook-codec.js";
import {
  TAVERN_CONTROL_FORMAT,
  TAVERN_SEGMENT_FORMAT,
  TAVERN_WORLDBOOK_STORE_VERSION,
  type TavernActiveView,
  type TavernArchiveRecord,
  type TavernControlPayload,
  type TavernFullSnapshotCommitRequest,
  type TavernFullSnapshotCommitResult,
  type TavernIdentityAnchorUpdateRequest,
  type TavernMemoryIdentityAnchor,
  type TavernPendingTransaction,
  type TavernRecoveryRequest,
  type TavernRecoveryResult,
  type TavernSegmentPayload,
  type TavernSegmentRef,
  TavernWorldbookStoreError,
  type TavernWorldbookStoreOptions,
} from "./worldbook-store-contracts.js";

const SHA256_PATTERN = /^[a-f0-9]{64}$/u;
const SAFE_TOKEN_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;

type ControlState = {
  readonly entry: TavernWorldbookEntry;
  readonly payload: TavernControlPayload;
};

type PreparedSegment = {
  readonly payload: TavernSegmentPayload;
  readonly content: string;
  readonly utf8Bytes: number;
  readonly bookName: string;
};

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const hasOnlyKeys = (value: Record<string, unknown>, allowed: readonly string[]): boolean => {
  const allowedSet = new Set(allowed);
  return Object.keys(value).every((key) => allowedSet.has(key));
};

function assertSafeToken(label: string, value: string): void {
  if (!SAFE_TOKEN_PATTERN.test(value)) {
    throw new TavernWorldbookStoreError(
      "INVALID_INPUT",
      `${label} must match ${SAFE_TOKEN_PATTERN.source}`,
    );
  }
}

function assertNonNegativeInteger(label: string, value: number): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new TavernWorldbookStoreError("INVALID_INPUT", `${label} must be a non-negative integer`);
  }
}

function assertIdentityAnchor(
  value: unknown,
  errorCode: "INVALID_INPUT" | "CONTROL_CORRUPT",
): asserts value is TavernMemoryIdentityAnchor {
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "identity_version",
      "character_locator",
      "chat_locator",
      "chat_anchor_hash",
      "character_revision_hash",
      "principal_binding",
    ]) ||
    value.identity_version !== "0.1.0" ||
    !isObject(value.character_locator) ||
    !hasOnlyKeys(value.character_locator, ["host_character_id"]) ||
    typeof value.character_locator.host_character_id !== "string" ||
    value.character_locator.host_character_id.trim().length === 0 ||
    !isObject(value.chat_locator) ||
    !hasOnlyKeys(value.chat_locator, ["host_chat_id"]) ||
    typeof value.chat_locator.host_chat_id !== "string" ||
    value.chat_locator.host_chat_id.trim().length === 0 ||
    typeof value.chat_anchor_hash !== "string" ||
    !SHA256_PATTERN.test(value.chat_anchor_hash) ||
    (value.character_revision_hash !== null &&
      (typeof value.character_revision_hash !== "string" ||
        !SHA256_PATTERN.test(value.character_revision_hash))) ||
    (value.principal_binding !== undefined &&
      (!isObject(value.principal_binding) ||
        !hasOnlyKeys(value.principal_binding, [
          "binding_version",
          "host_character_id",
          "principal_entity_id",
          "principal_entity_label",
          "binding_mode",
          "bound_at_source_revision_id",
        ]) ||
        value.principal_binding.binding_version !== "0.1.0" ||
        value.principal_binding.host_character_id !== value.character_locator.host_character_id ||
        getNarraMemIdKind(value.principal_binding.principal_entity_id) !== "entity" ||
        typeof value.principal_binding.principal_entity_label !== "string" ||
        value.principal_binding.principal_entity_label.trim().length === 0 ||
        !["automatic_exact_label", "user_confirmed"].includes(
          value.principal_binding.binding_mode as string,
        ) ||
        getNarraMemIdKind(value.principal_binding.bound_at_source_revision_id) !==
          "source_revision"))
  ) {
    throw new TavernWorldbookStoreError(errorCode, "Invalid Memory Set identity anchor");
  }
}

function machineEntryDraft(
  name: string,
  content: string,
  extra: Readonly<Record<string, unknown>>,
): TavernWorldbookEntryDraft {
  return {
    name,
    enabled: false,
    content,
    strategy: {
      type: "constant",
      keys: [],
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: {
      type: "after_character_definition",
      role: "system",
      depth: 0,
      order: 0,
    },
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra,
  };
}

function assertMachineEntry(entry: TavernWorldbookEntry, label: string): void {
  if (
    !Number.isInteger(entry.uid) ||
    entry.uid < 0 ||
    entry.enabled ||
    entry.strategy.type !== "constant" ||
    entry.strategy.keys.length !== 0 ||
    !entry.recursion.prevent_incoming ||
    !entry.recursion.prevent_outgoing
  ) {
    throw new TavernWorldbookStoreError("SEGMENT_CORRUPT", `${label} safety settings changed`);
  }
}

function withoutChecksum<T extends { readonly checksum: string }>(value: T): Omit<T, "checksum"> {
  const { checksum: _checksum, ...unsigned } = value;
  return unsigned;
}

async function addChecksum<T extends object>(value: T): Promise<T & { readonly checksum: string }> {
  return { ...value, checksum: await checksumJson(value) };
}

function parseJson(content: string, label: string): unknown {
  try {
    return JSON.parse(content);
  } catch {
    throw new TavernWorldbookStoreError("CONTROL_CORRUPT", `${label} is not valid JSON`);
  }
}

function assertSegmentRefShape(value: unknown): asserts value is TavernSegmentRef {
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "book_name",
      "entry_uid",
      "segment_id",
      "checksum",
      "record_count",
      "utf8_bytes",
    ]) ||
    typeof value.book_name !== "string" ||
    typeof value.entry_uid !== "number" ||
    !Number.isInteger(value.entry_uid) ||
    value.entry_uid < 0 ||
    typeof value.segment_id !== "string" ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum) ||
    typeof value.record_count !== "number" ||
    !Number.isInteger(value.record_count) ||
    value.record_count < 0 ||
    typeof value.utf8_bytes !== "number" ||
    !Number.isInteger(value.utf8_bytes) ||
    value.utf8_bytes < 0
  ) {
    throw new TavernWorldbookStoreError("CONTROL_CORRUPT", "Invalid segment reference");
  }
}

async function assertViewShapeAndChecksum(value: unknown): Promise<TavernActiveView> {
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "view_id",
      "build_id",
      "source_revision",
      "source_checksum",
      "segments",
      "checksum",
    ]) ||
    typeof value.view_id !== "string" ||
    typeof value.build_id !== "string" ||
    typeof value.source_revision !== "number" ||
    !Number.isInteger(value.source_revision) ||
    value.source_revision < 0 ||
    typeof value.source_checksum !== "string" ||
    !SHA256_PATTERN.test(value.source_checksum) ||
    !Array.isArray(value.segments) ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum)
  ) {
    throw new TavernWorldbookStoreError("CONTROL_CORRUPT", "Invalid active view");
  }
  for (const segment of value.segments) assertSegmentRefShape(segment);
  const segmentIds = value.segments.map((segment) => segment.segment_id);
  const segmentLocators = value.segments.map(
    (segment) => `${segment.book_name}\u0000${segment.entry_uid}`,
  );
  if (
    new Set(segmentIds).size !== segmentIds.length ||
    new Set(segmentLocators).size !== segmentLocators.length
  ) {
    throw new TavernWorldbookStoreError("CONTROL_CORRUPT", "Active view has duplicate segments");
  }
  const view = value as unknown as TavernActiveView;
  if ((await checksumJson(withoutChecksum(view))) !== view.checksum) {
    throw new TavernWorldbookStoreError(
      "CONTROL_CORRUPT",
      `View ${view.view_id} checksum mismatch`,
    );
  }
  return view;
}

async function parseControlPayload(
  content: string,
  memorySetId: string,
): Promise<TavernControlPayload> {
  const value = parseJson(content, "Control entry");
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "format",
      "schema_version",
      "memory_set_id",
      "identity_anchor",
      "commit_sequence",
      "active_view",
      "pending_transaction",
      "checksum",
    ]) ||
    value.format !== TAVERN_CONTROL_FORMAT ||
    value.schema_version !== TAVERN_WORLDBOOK_STORE_VERSION ||
    value.memory_set_id !== memorySetId ||
    !("identity_anchor" in value) ||
    typeof value.commit_sequence !== "number" ||
    !Number.isInteger(value.commit_sequence) ||
    value.commit_sequence < 0 ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum) ||
    !("active_view" in value) ||
    !("pending_transaction" in value)
  ) {
    throw new TavernWorldbookStoreError("CONTROL_CORRUPT", "Invalid Control payload shape");
  }
  assertIdentityAnchor(value.identity_anchor, "CONTROL_CORRUPT");
  const activeView =
    value.active_view === null ? null : await assertViewShapeAndChecksum(value.active_view);
  let pending: TavernPendingTransaction | null = null;
  if (value.pending_transaction !== null) {
    const raw = value.pending_transaction;
    if (
      !isObject(raw) ||
      !hasOnlyKeys(raw, [
        "transaction_id",
        "writer_id",
        "phase",
        "base_view",
        "target_view",
        "obsolete_books",
      ]) ||
      typeof raw.transaction_id !== "string" ||
      typeof raw.writer_id !== "string" ||
      (raw.phase !== "staging_verified" && raw.phase !== "pointer_committed") ||
      !Array.isArray(raw.obsolete_books) ||
      raw.obsolete_books.some((name) => typeof name !== "string") ||
      !("base_view" in raw) ||
      !("target_view" in raw)
    ) {
      throw new TavernWorldbookStoreError("CONTROL_CORRUPT", "Invalid pending transaction");
    }
    pending = {
      transaction_id: raw.transaction_id,
      writer_id: raw.writer_id,
      phase: raw.phase,
      base_view: raw.base_view === null ? null : await assertViewShapeAndChecksum(raw.base_view),
      target_view: await assertViewShapeAndChecksum(raw.target_view),
      obsolete_books: raw.obsolete_books as string[],
    };
  }
  const payload: TavernControlPayload = {
    format: TAVERN_CONTROL_FORMAT,
    schema_version: TAVERN_WORLDBOOK_STORE_VERSION,
    memory_set_id: memorySetId,
    identity_anchor: value.identity_anchor,
    commit_sequence: value.commit_sequence,
    active_view: activeView,
    pending_transaction: pending,
    checksum: value.checksum,
  };
  if ((await checksumJson(withoutChecksum(payload))) !== payload.checksum) {
    throw new TavernWorldbookStoreError("CONTROL_CORRUPT", "Control checksum mismatch");
  }
  return payload;
}

async function parseSegmentPayload(
  content: string,
  memorySetId: string,
): Promise<TavernSegmentPayload> {
  const value = parseJson(content, "Segment entry");
  if (
    !isObject(value) ||
    !hasOnlyKeys(value, [
      "format",
      "schema_version",
      "memory_set_id",
      "transaction_id",
      "build_id",
      "segment_id",
      "source_revision",
      "ordinal",
      "records",
      "checksum",
    ]) ||
    value.format !== TAVERN_SEGMENT_FORMAT ||
    value.schema_version !== TAVERN_WORLDBOOK_STORE_VERSION ||
    value.memory_set_id !== memorySetId ||
    typeof value.transaction_id !== "string" ||
    typeof value.build_id !== "string" ||
    typeof value.segment_id !== "string" ||
    typeof value.source_revision !== "number" ||
    !Number.isInteger(value.source_revision) ||
    value.source_revision < 0 ||
    typeof value.ordinal !== "number" ||
    !Number.isInteger(value.ordinal) ||
    value.ordinal < 0 ||
    !Array.isArray(value.records) ||
    typeof value.checksum !== "string" ||
    !SHA256_PATTERN.test(value.checksum)
  ) {
    throw new TavernWorldbookStoreError("SEGMENT_CORRUPT", "Invalid segment payload shape");
  }
  for (const record of value.records) {
    if (
      !isObject(record) ||
      !hasOnlyKeys(record, ["record_id", "record_kind", "payload"]) ||
      typeof record.record_id !== "string" ||
      typeof record.record_kind !== "string" ||
      !("payload" in record)
    ) {
      throw new TavernWorldbookStoreError("SEGMENT_CORRUPT", "Invalid archive record");
    }
    canonicalJson(record.payload);
  }
  const payload = value as unknown as TavernSegmentPayload;
  if ((await checksumJson(withoutChecksum(payload))) !== payload.checksum) {
    throw new TavernWorldbookStoreError(
      "SEGMENT_CORRUPT",
      `Segment ${payload.segment_id} checksum mismatch`,
    );
  }
  return payload;
}

const sameViewId = (left: TavernActiveView | null, right: TavernActiveView | null): boolean =>
  left?.view_id === right?.view_id && (left !== null || right === null);

export async function readTavernControlPayload(
  port: TavernHostPort,
  controlBookName: string,
): Promise<TavernControlPayload> {
  if (!controlBookName.startsWith("NarraMem__CONTROL__")) {
    throw new TavernWorldbookStoreError(
      "INVALID_INPUT",
      "Refusing to inspect a non-NarraMem Control book",
    );
  }
  const entries = await port.readWorldbook(controlBookName);
  const entry = entries[0];
  if (entries.length !== 1 || entry === undefined) {
    throw new TavernWorldbookStoreError(
      "CONTROL_CORRUPT",
      `${controlBookName} must contain exactly one entry`,
    );
  }
  assertMachineEntry(entry, controlBookName);
  const header = parseJson(entry.content, controlBookName);
  if (!isObject(header) || typeof header.memory_set_id !== "string") {
    throw new TavernWorldbookStoreError(
      "CONTROL_CORRUPT",
      `${controlBookName} has no Memory Set identity`,
    );
  }
  assertSafeToken("memory_set_id", header.memory_set_id);
  return parseControlPayload(entry.content, header.memory_set_id);
}

export class TavernWorldbookSnapshotStore {
  private writerTail: Promise<void> = Promise.resolve();

  constructor(
    private readonly port: TavernHostPort,
    private readonly options: TavernWorldbookStoreOptions,
  ) {
    assertSafeToken("memory_set_id", options.memory_set_id);
    assertIdentityAnchor(options.initial_identity_anchor, "INVALID_INPUT");
    if (!options.control_book_name.startsWith("NarraMem__CONTROL__")) {
      throw new TavernWorldbookStoreError(
        "INVALID_INPUT",
        "control_book_name must start with NarraMem__CONTROL__",
      );
    }
    if (!options.segment_book_prefix.startsWith("NarraMem__ARCHIVE__")) {
      throw new TavernWorldbookStoreError(
        "INVALID_INPUT",
        "segment_book_prefix must start with NarraMem__ARCHIVE__",
      );
    }
    if (!Number.isInteger(options.max_records_per_segment) || options.max_records_per_segment < 1) {
      throw new TavernWorldbookStoreError(
        "INVALID_INPUT",
        "max_records_per_segment must be a positive integer",
      );
    }
    if (!Number.isInteger(options.max_segment_utf8_bytes) || options.max_segment_utf8_bytes < 256) {
      throw new TavernWorldbookStoreError(
        "INVALID_INPUT",
        "max_segment_utf8_bytes must be an integer of at least 256",
      );
    }
  }

  private enqueue<T>(operation: () => Promise<T>): Promise<T> {
    const execute = () =>
      this.port.withWorldbookExclusiveLock?.(this.options.control_book_name, operation) ??
      operation();
    const result = this.writerTail.then(execute, execute);
    this.writerTail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  async initialize(): Promise<TavernControlPayload> {
    return this.enqueue(async () => {
      if (this.port.listWorldbooks().includes(this.options.control_book_name)) {
        return (await this.readControlState()).payload;
      }
      const created = await this.port.createWorldbook(this.options.control_book_name);
      if (!created) return (await this.readControlState()).payload;
      const initial = await this.encodeControl({
        identityAnchor: this.options.initial_identity_anchor,
        commitSequence: 0,
        activeView: null,
        pendingTransaction: null,
      });
      try {
        const appended = await this.port.appendWorldbookEntries(this.options.control_book_name, [
          machineEntryDraft("NarraMem Control", canonicalJson(initial), {
            narramem: {
              record_kind: "control",
              memory_set_id: this.options.memory_set_id,
            },
          }),
        ]);
        if (appended.new_entries.length !== 1) {
          throw new TavernWorldbookStoreError(
            "CONTROL_CORRUPT",
            "Control initialization did not create exactly one entry",
          );
        }
        const state = await this.readControlState();
        if (state.payload.checksum !== initial.checksum) {
          throw new TavernWorldbookStoreError("WRITE_CONFLICT", "Control initialization changed");
        }
        return state.payload;
      } catch (error) {
        let safeToDelete = false;
        try {
          const entries = await this.port.readWorldbook(this.options.control_book_name);
          if (entries.length === 0) {
            safeToDelete = true;
          } else if (entries.length === 1 && entries[0] !== undefined) {
            const payload = await parseControlPayload(
              entries[0].content,
              this.options.memory_set_id,
            );
            safeToDelete = payload.checksum === initial.checksum;
          }
        } catch {
          // An uncertain or externally changed Control book is never deleted automatically.
        }
        if (safeToDelete) await this.port.deleteWorldbook(this.options.control_book_name);
        throw error;
      }
    });
  }

  async readControl(): Promise<TavernControlPayload> {
    return (await this.readControlState()).payload;
  }

  async readActiveSnapshot(): Promise<readonly TavernArchiveRecord[]> {
    const control = await this.readControl();
    if (control.active_view === null) return [];
    const segments = await this.verifyView(control.active_view);
    return segments.flatMap((segment) => segment.records);
  }

  updateIdentityAnchor(request: TavernIdentityAnchorUpdateRequest): Promise<TavernControlPayload> {
    return this.enqueue(async () => {
      assertIdentityAnchor(request.next_identity_anchor, "INVALID_INPUT");
      if (!SHA256_PATTERN.test(request.expected_control_checksum)) {
        throw new TavernWorldbookStoreError(
          "INVALID_INPUT",
          "expected_control_checksum must be SHA-256",
        );
      }
      const state = await this.readControlState();
      if (state.payload.pending_transaction !== null) {
        throw new TavernWorldbookStoreError(
          "FOREIGN_PENDING_TRANSACTION",
          "Identity cannot change while a snapshot transaction is pending",
        );
      }
      if (state.payload.checksum !== request.expected_control_checksum) {
        throw new TavernWorldbookStoreError("STALE_BASE", "Identity update base is stale");
      }
      const updated = await this.encodeControl({
        identityAnchor: request.next_identity_anchor,
        commitSequence: state.payload.commit_sequence + 1,
        activeView: state.payload.active_view,
        pendingTransaction: null,
      });
      return (await this.replaceControl(state.entry, updated)).payload;
    });
  }

  commitFullSnapshot(
    request: TavernFullSnapshotCommitRequest,
  ): Promise<TavernFullSnapshotCommitResult> {
    return this.enqueue(() => this.commitFullSnapshotExclusive(request));
  }

  recover(request: TavernRecoveryRequest): Promise<TavernRecoveryResult> {
    return this.enqueue(() => this.recoverExclusive(request));
  }

  private async commitFullSnapshotExclusive(
    request: TavernFullSnapshotCommitRequest,
  ): Promise<TavernFullSnapshotCommitResult> {
    this.validateCommitRequest(request);
    const base = await this.readControlState();
    this.assertExpectedBase(base.payload, request);
    if (base.payload.pending_transaction !== null) {
      throw new TavernWorldbookStoreError(
        "FOREIGN_PENDING_TRANSACTION",
        `Pending transaction ${base.payload.pending_transaction.transaction_id} requires recovery`,
      );
    }
    const prepared = await this.prepareSegments(request);
    let createdBooks: readonly string[] = [];
    try {
      const staged = await this.stageSegments(prepared);
      const refs = staged.refs;
      createdBooks = staged.createdBooks;
      await request.after_durable_phase?.("segments_staged");

      const targetView = await this.encodeView({
        viewId: request.view_id,
        buildId: request.build_id,
        sourceRevision: request.source_revision,
        sourceChecksum: request.source_checksum,
        segments: refs,
      });
      const obsoleteBooks = [
        ...new Set(base.payload.active_view?.segments.map((item) => item.book_name) ?? []),
      ];
      const pending: TavernPendingTransaction = {
        transaction_id: request.transaction_id,
        writer_id: request.writer_id,
        phase: "staging_verified",
        base_view: base.payload.active_view,
        target_view: targetView,
        obsolete_books: obsoleteBooks,
      };
      const pendingControl = await this.encodeControl({
        identityAnchor: base.payload.identity_anchor,
        commitSequence: base.payload.commit_sequence,
        activeView: base.payload.active_view,
        pendingTransaction: pending,
      });
      const beforePending = await this.readControlState();
      this.assertSameControl(beforePending.payload, base.payload, "Control changed while staging");
      const pendingState = await this.replaceControl(beforePending.entry, pendingControl);
      this.assertPending(pendingState.payload, request.transaction_id, "staging_verified");
      await request.after_durable_phase?.("pending_recorded");

      const committedPending: TavernPendingTransaction = { ...pending, phase: "pointer_committed" };
      const committedControl = await this.encodeControl({
        identityAnchor: base.payload.identity_anchor,
        commitSequence: base.payload.commit_sequence + 1,
        activeView: targetView,
        pendingTransaction: committedPending,
      });
      const beforeCommit = await this.readControlState();
      this.assertPending(beforeCommit.payload, request.transaction_id, "staging_verified");
      const committedState = await this.replaceControl(beforeCommit.entry, committedControl);
      this.assertPending(committedState.payload, request.transaction_id, "pointer_committed");
      if (committedState.payload.active_view?.view_id !== request.view_id) {
        throw new TavernWorldbookStoreError(
          "WRITE_CONFLICT",
          "Active view pointer was not committed",
        );
      }
      await request.after_durable_phase?.("pointer_committed");

      await this.deleteBooks(obsoleteBooks);
      await request.after_durable_phase?.("obsolete_collected");

      const finalControl = await this.encodeControl({
        identityAnchor: committedState.payload.identity_anchor,
        commitSequence: committedState.payload.commit_sequence,
        activeView: targetView,
        pendingTransaction: null,
      });
      const beforeClear = await this.readControlState();
      this.assertPending(beforeClear.payload, request.transaction_id, "pointer_committed");
      const finalState = await this.replaceControl(beforeClear.entry, finalControl);
      if (
        finalState.payload.pending_transaction !== null ||
        finalState.payload.active_view?.view_id !== targetView.view_id
      ) {
        throw new TavernWorldbookStoreError("WRITE_CONFLICT", "Final Control verification failed");
      }
      await request.after_durable_phase?.("pending_cleared");
      return { control: finalState.payload, replaced_segment_books: obsoleteBooks };
    } catch (error) {
      const current = await this.tryReadControl();
      const transactionRecorded =
        current?.pending_transaction?.transaction_id === request.transaction_id ||
        current?.active_view?.view_id === request.view_id;
      if (!transactionRecorded) await this.deleteBooksBestEffort(createdBooks);
      throw error;
    }
  }

  private async recoverExclusive(request: TavernRecoveryRequest): Promise<TavernRecoveryResult> {
    assertNonNegativeInteger("current_source_revision", request.current_source_revision);
    if (
      request.current_source_checksum !== null &&
      !SHA256_PATTERN.test(request.current_source_checksum)
    ) {
      throw new TavernWorldbookStoreError(
        "INVALID_INPUT",
        "current_source_checksum must be null or SHA-256",
      );
    }
    let state = await this.readControlState();
    let pending = state.payload.pending_transaction;
    if (pending === null) {
      const deletedBooks = request.exclusive_writer_confirmed
        ? await this.collectUnreferencedSegments(state.payload.active_view)
        : [];
      return {
        action: deletedBooks.length === 0 ? "NO_ACTION" : "ORPHANS_COLLECTED",
        control: (await this.readControlState()).payload,
        deleted_books: deletedBooks,
      };
    }

    if (!request.exclusive_writer_confirmed) {
      throw new TavernWorldbookStoreError(
        "FOREIGN_PENDING_TRANSACTION",
        "Recovery requires an explicitly confirmed exclusive writer",
      );
    }

    const beganFromStaging = pending.phase === "staging_verified";
    if (pending.phase === "staging_verified") {
      const targetValid = await this.isViewValid(pending.target_view);
      if (
        request.current_source_revision !== pending.target_view.source_revision ||
        request.current_source_checksum !== pending.target_view.source_checksum ||
        !targetValid
      ) {
        const deleted = await this.deleteViewBooksBestEffort(pending.target_view);
        const restored = await this.encodeControl({
          identityAnchor: state.payload.identity_anchor,
          commitSequence: state.payload.commit_sequence,
          activeView: pending.base_view,
          pendingTransaction: null,
        });
        state = await this.replaceControl(state.entry, restored);
        return {
          action: "STAGING_ABORTED_STALE",
          control: state.payload,
          deleted_books: deleted,
        };
      }
      if (!sameViewId(state.payload.active_view, pending.base_view)) {
        throw new TavernWorldbookStoreError(
          "WRITE_CONFLICT",
          "Staging recovery base no longer matches active view",
        );
      }
      pending = { ...pending, phase: "pointer_committed" };
      const committed = await this.encodeControl({
        identityAnchor: state.payload.identity_anchor,
        commitSequence: state.payload.commit_sequence + 1,
        activeView: pending.target_view,
        pendingTransaction: pending,
      });
      state = await this.replaceControl(state.entry, committed);
    }

    pending = state.payload.pending_transaction;
    if (pending === null || pending.phase !== "pointer_committed") {
      throw new TavernWorldbookStoreError("CONTROL_CORRUPT", "Recovery lost pending transaction");
    }
    if (!(await this.isViewValid(pending.target_view))) {
      const baseValid = pending.base_view === null || (await this.isViewValid(pending.base_view));
      if (baseValid) {
        const rollback = await this.encodeControl({
          identityAnchor: state.payload.identity_anchor,
          commitSequence: state.payload.commit_sequence + 1,
          activeView: pending.base_view,
          pendingTransaction: null,
        });
        const rolledBack = await this.replaceControl(state.entry, rollback);
        const deleted = await this.deleteViewBooksBestEffort(pending.target_view);
        return { action: "ROLLED_BACK", control: rolledBack.payload, deleted_books: deleted };
      }
      const quarantine = await this.encodeControl({
        identityAnchor: state.payload.identity_anchor,
        commitSequence: state.payload.commit_sequence + 1,
        activeView: null,
        pendingTransaction: null,
      });
      const quarantined = await this.replaceControl(state.entry, quarantine);
      return { action: "REBUILD_REQUIRED", control: quarantined.payload, deleted_books: [] };
    }

    const deleted = await this.deleteBooks(pending.obsolete_books);
    const cleared = await this.encodeControl({
      identityAnchor: state.payload.identity_anchor,
      commitSequence: state.payload.commit_sequence,
      activeView: pending.target_view,
      pendingTransaction: null,
    });
    const finalState = await this.replaceControl((await this.readControlState()).entry, cleared);
    return {
      action: beganFromStaging ? "STAGING_COMMITTED" : "COMMITTED_CLEANED",
      control: finalState.payload,
      deleted_books: deleted,
    };
  }

  private validateCommitRequest(request: TavernFullSnapshotCommitRequest): void {
    for (const [label, value] of [
      ["transaction_id", request.transaction_id],
      ["writer_id", request.writer_id],
      ["build_id", request.build_id],
      ["view_id", request.view_id],
    ] as const) {
      assertSafeToken(label, value);
    }
    assertNonNegativeInteger("source_revision", request.source_revision);
    if (!SHA256_PATTERN.test(request.source_checksum)) {
      throw new TavernWorldbookStoreError("INVALID_INPUT", "source_checksum must be SHA-256");
    }
    assertNonNegativeInteger("expected_commit_sequence", request.expected_commit_sequence);
    const recordIds = new Set<string>();
    for (const record of request.records) {
      assertSafeToken("record_id", record.record_id);
      assertSafeToken("record_kind", record.record_kind);
      if (recordIds.has(record.record_id)) {
        throw new TavernWorldbookStoreError(
          "INVALID_INPUT",
          `Duplicate record_id ${record.record_id}`,
        );
      }
      recordIds.add(record.record_id);
      canonicalJson(record.payload);
    }
  }

  private assertExpectedBase(
    control: TavernControlPayload,
    request: TavernFullSnapshotCommitRequest,
  ): void {
    if (
      control.commit_sequence !== request.expected_commit_sequence ||
      (control.active_view?.view_id ?? null) !== request.expected_view_id
    ) {
      throw new TavernWorldbookStoreError("STALE_BASE", "Expected Control base is stale");
    }
    if (control.active_view !== null) {
      if (request.view_id === control.active_view.view_id) {
        throw new TavernWorldbookStoreError(
          "STALE_BASE",
          "A materialized view ID cannot be reused",
        );
      }
      if (
        request.source_revision < control.active_view.source_revision ||
        (request.source_revision === control.active_view.source_revision &&
          request.source_checksum !== control.active_view.source_checksum)
      ) {
        throw new TavernWorldbookStoreError(
          "STALE_BASE",
          "Source revision/checksum is older than or conflicts with the active view",
        );
      }
    }
  }

  private async prepareSegments(
    request: TavernFullSnapshotCommitRequest,
  ): Promise<readonly PreparedSegment[]> {
    const prepared: PreparedSegment[] = [];
    let current: TavernArchiveRecord[] = [];
    let currentRecordUtf8Bytes = 0;
    const flushCurrent = async (): Promise<void> => {
      if (current.length === 0) return;
      prepared.push(await this.encodeSegment(request, prepared.length, current));
      current = [];
      currentRecordUtf8Bytes = 0;
    };
    for (const record of request.records) {
      if (current.length >= this.options.max_records_per_segment) {
        await flushCurrent();
      }
      const recordUtf8Bytes = utf8ByteLength(canonicalJson(record));
      const candidateCount = current.length + 1;
      const candidateRecordUtf8Bytes = currentRecordUtf8Bytes + recordUtf8Bytes;
      const candidateUtf8Bytes =
        this.emptySegmentUtf8Bytes(request, prepared.length) +
        candidateRecordUtf8Bytes +
        Math.max(0, candidateCount - 1);
      if (candidateUtf8Bytes > this.options.max_segment_utf8_bytes) {
        if (current.length === 0) {
          throw new TavernWorldbookStoreError(
            "INVALID_INPUT",
            `Record ${record.record_id} exceeds max_segment_utf8_bytes`,
          );
        }
        await flushCurrent();
        current = [record];
        currentRecordUtf8Bytes = recordUtf8Bytes;
        const singleUtf8Bytes =
          this.emptySegmentUtf8Bytes(request, prepared.length) + recordUtf8Bytes;
        if (singleUtf8Bytes > this.options.max_segment_utf8_bytes) {
          throw new TavernWorldbookStoreError(
            "INVALID_INPUT",
            `Record ${record.record_id} exceeds max_segment_utf8_bytes`,
          );
        }
      } else {
        current.push(record);
        currentRecordUtf8Bytes = candidateRecordUtf8Bytes;
      }
    }
    await flushCurrent();
    return prepared;
  }

  private emptySegmentUtf8Bytes(request: TavernFullSnapshotCommitRequest, ordinal: number): number {
    const segmentId = `${request.build_id}_${ordinal.toString().padStart(4, "0")}`;
    return utf8ByteLength(
      canonicalJson({
        format: TAVERN_SEGMENT_FORMAT,
        schema_version: TAVERN_WORLDBOOK_STORE_VERSION,
        memory_set_id: this.options.memory_set_id,
        transaction_id: request.transaction_id,
        build_id: request.build_id,
        segment_id: segmentId,
        source_revision: request.source_revision,
        ordinal,
        records: [],
        checksum: "0".repeat(64),
      }),
    );
  }

  private async encodeSegment(
    request: TavernFullSnapshotCommitRequest,
    ordinal: number,
    records: readonly TavernArchiveRecord[],
  ): Promise<PreparedSegment> {
    const segmentId = `${request.build_id}_${ordinal.toString().padStart(4, "0")}`;
    const payload = await addChecksum({
      format: TAVERN_SEGMENT_FORMAT,
      schema_version: TAVERN_WORLDBOOK_STORE_VERSION,
      memory_set_id: this.options.memory_set_id,
      transaction_id: request.transaction_id,
      build_id: request.build_id,
      segment_id: segmentId,
      source_revision: request.source_revision,
      ordinal,
      records,
    });
    const content = canonicalJson(payload);
    return {
      payload,
      content,
      utf8Bytes: utf8ByteLength(content),
      bookName: `${this.options.segment_book_prefix}${request.transaction_id}`,
    };
  }

  private async stageSegments(prepared: readonly PreparedSegment[]): Promise<{
    readonly refs: readonly TavernSegmentRef[];
    readonly createdBooks: readonly string[];
  }> {
    const first = prepared[0];
    if (first === undefined) return { refs: [], createdBooks: [] };
    const bookName = first.bookName;
    if (prepared.some((segment) => segment.bookName !== bookName)) {
      throw new TavernWorldbookStoreError(
        "INVALID_INPUT",
        "A snapshot transaction must stage into exactly one Archive book",
      );
    }
    if (this.port.listWorldbooks().includes(bookName)) {
      throw new TavernWorldbookStoreError("BOOK_COLLISION", `${bookName} already exists`);
    }
    if (!(await this.port.createWorldbook(bookName))) {
      throw new TavernWorldbookStoreError("BOOK_COLLISION", `${bookName} creation collided`);
    }
    try {
      const appended = await this.port.appendWorldbookEntries(
        bookName,
        prepared.map((segment) =>
          machineEntryDraft(`NarraMem segment ${segment.payload.segment_id}`, segment.content, {
            narramem: {
              record_kind: "archive_segment",
              memory_set_id: this.options.memory_set_id,
              transaction_id: segment.payload.transaction_id,
              segment_id: segment.payload.segment_id,
              checksum: segment.payload.checksum,
            },
          }),
        ),
      );
      if (appended.new_entries.length !== prepared.length) {
        throw new TavernWorldbookStoreError(
          "SEGMENT_CORRUPT",
          `${bookName} did not create the expected segment entries`,
        );
      }
      const refs = prepared.map((segment, index): TavernSegmentRef => {
        const created = appended.new_entries[index];
        if (created === undefined) {
          throw new TavernWorldbookStoreError(
            "SEGMENT_CORRUPT",
            `${bookName} lost segment entry ${index}`,
          );
        }
        return {
          book_name: bookName,
          entry_uid: created.uid,
          segment_id: segment.payload.segment_id,
          checksum: segment.payload.checksum,
          record_count: segment.payload.records.length,
          utf8_bytes: segment.utf8Bytes,
        };
      });
      for (const ref of refs) await this.readAndVerifySegment(ref, appended.worldbook);
      return { refs, createdBooks: [bookName] };
    } catch (error) {
      await this.port.deleteWorldbook(bookName);
      throw error;
    }
  }

  private async readAndVerifySegment(
    ref: TavernSegmentRef,
    knownEntries?: readonly TavernWorldbookEntry[],
  ): Promise<TavernSegmentPayload> {
    if (!ref.book_name.startsWith(this.options.segment_book_prefix)) {
      throw new TavernWorldbookStoreError(
        "SEGMENT_CORRUPT",
        `Refusing to read non-NarraMem segment ${ref.book_name}`,
      );
    }
    const entries = knownEntries ?? (await this.port.readWorldbook(ref.book_name));
    const entry = entries.find((candidate) => candidate.uid === ref.entry_uid);
    if (entry === undefined) {
      throw new TavernWorldbookStoreError(
        "SEGMENT_CORRUPT",
        `${ref.book_name} entry identity mismatch`,
      );
    }
    assertMachineEntry(entry, ref.book_name);
    const payload = await parseSegmentPayload(entry.content, this.options.memory_set_id);
    if (
      payload.segment_id !== ref.segment_id ||
      payload.checksum !== ref.checksum ||
      payload.records.length !== ref.record_count ||
      utf8ByteLength(entry.content) !== ref.utf8_bytes
    ) {
      throw new TavernWorldbookStoreError(
        "SEGMENT_CORRUPT",
        `${ref.book_name} manifest reference mismatch`,
      );
    }
    return payload;
  }

  private async verifyView(view: TavernActiveView): Promise<readonly TavernSegmentPayload[]> {
    const entriesByBook = new Map<string, readonly TavernWorldbookEntry[]>();
    await Promise.all(
      [...new Set(view.segments.map((segment) => segment.book_name))].map(async (bookName) => {
        entriesByBook.set(bookName, await this.port.readWorldbook(bookName));
      }),
    );
    const payloads = await Promise.all(
      view.segments.map((segment) =>
        this.readAndVerifySegment(segment, entriesByBook.get(segment.book_name)),
      ),
    );
    const recordIds = new Set<string>();
    for (const [ordinal, payload] of payloads.entries()) {
      if (
        payload.ordinal !== ordinal ||
        payload.build_id !== view.build_id ||
        payload.source_revision !== view.source_revision
      ) {
        throw new TavernWorldbookStoreError(
          "SEGMENT_CORRUPT",
          `Segment ${payload.segment_id} does not belong to active view ${view.view_id}`,
        );
      }
      for (const record of payload.records) {
        if (recordIds.has(record.record_id)) {
          throw new TavernWorldbookStoreError(
            "SEGMENT_CORRUPT",
            `Duplicate record ${record.record_id} across active segments`,
          );
        }
        recordIds.add(record.record_id);
      }
    }
    return payloads;
  }

  private async isViewValid(view: TavernActiveView): Promise<boolean> {
    try {
      await this.verifyView(view);
      return true;
    } catch {
      return false;
    }
  }

  private async encodeView(input: {
    readonly viewId: string;
    readonly buildId: string;
    readonly sourceRevision: number;
    readonly sourceChecksum: string;
    readonly segments: readonly TavernSegmentRef[];
  }): Promise<TavernActiveView> {
    return addChecksum({
      view_id: input.viewId,
      build_id: input.buildId,
      source_revision: input.sourceRevision,
      source_checksum: input.sourceChecksum,
      segments: input.segments,
    });
  }

  private async encodeControl(input: {
    readonly identityAnchor: TavernMemoryIdentityAnchor;
    readonly commitSequence: number;
    readonly activeView: TavernActiveView | null;
    readonly pendingTransaction: TavernPendingTransaction | null;
  }): Promise<TavernControlPayload> {
    return addChecksum({
      format: TAVERN_CONTROL_FORMAT,
      schema_version: TAVERN_WORLDBOOK_STORE_VERSION,
      memory_set_id: this.options.memory_set_id,
      identity_anchor: input.identityAnchor,
      commit_sequence: input.commitSequence,
      active_view: input.activeView,
      pending_transaction: input.pendingTransaction,
    });
  }

  private async readControlState(): Promise<ControlState> {
    const entries = await this.port.readWorldbook(this.options.control_book_name);
    const entry = entries[0];
    if (entries.length !== 1 || entry === undefined) {
      throw new TavernWorldbookStoreError(
        "CONTROL_CORRUPT",
        "Control worldbook must contain exactly one entry",
      );
    }
    assertMachineEntry(entry, this.options.control_book_name);
    return {
      entry,
      payload: await parseControlPayload(entry.content, this.options.memory_set_id),
    };
  }

  private async tryReadControl(): Promise<TavernControlPayload | null> {
    try {
      return (await this.readControlState()).payload;
    } catch {
      return null;
    }
  }

  private async replaceControl(
    currentEntry: TavernWorldbookEntry,
    payload: TavernControlPayload,
  ): Promise<ControlState> {
    const draft = machineEntryDraft("NarraMem Control", canonicalJson(payload), {
      narramem: {
        record_kind: "control",
        memory_set_id: this.options.memory_set_id,
        commit_sequence: payload.commit_sequence,
        transaction_id: payload.pending_transaction?.transaction_id ?? null,
      },
    });
    await this.port.replaceWorldbook(this.options.control_book_name, [
      { ...draft, uid: currentEntry.uid },
    ]);
    const state = await this.readControlState();
    if (state.payload.checksum !== payload.checksum) {
      throw new TavernWorldbookStoreError("WRITE_CONFLICT", "Control read-back checksum mismatch");
    }
    return state;
  }

  private assertSameControl(
    actual: TavernControlPayload,
    expected: TavernControlPayload,
    message: string,
  ): void {
    if (actual.checksum !== expected.checksum) {
      throw new TavernWorldbookStoreError("WRITE_CONFLICT", message);
    }
  }

  private assertPending(
    control: TavernControlPayload,
    transactionId: string,
    phase: TavernPendingTransaction["phase"],
  ): void {
    if (
      control.pending_transaction?.transaction_id !== transactionId ||
      control.pending_transaction.phase !== phase
    ) {
      throw new TavernWorldbookStoreError(
        "WRITE_CONFLICT",
        `Expected pending transaction ${transactionId} at ${phase}`,
      );
    }
  }

  private async deleteBooks(bookNames: readonly string[]): Promise<string[]> {
    const deleted: string[] = [];
    for (const name of new Set(bookNames)) {
      if (!name.startsWith(this.options.segment_book_prefix)) {
        throw new TavernWorldbookStoreError("CLEANUP_FAILED", `Refusing to delete ${name}`);
      }
      if (!this.port.listWorldbooks().includes(name)) continue;
      if (!(await this.port.deleteWorldbook(name))) {
        throw new TavernWorldbookStoreError("CLEANUP_FAILED", `Could not delete ${name}`);
      }
      deleted.push(name);
    }
    return deleted;
  }

  private async deleteBooksBestEffort(bookNames: readonly string[]): Promise<void> {
    for (const name of new Set(bookNames)) {
      if (!name.startsWith(this.options.segment_book_prefix)) continue;
      try {
        await this.port.deleteWorldbook(name);
      } catch {
        // Recovery will inspect orphaned NarraMem segment books on the next exclusive load.
      }
    }
  }

  private async deleteViewBooksBestEffort(view: TavernActiveView): Promise<string[]> {
    const existing = new Set(this.port.listWorldbooks());
    const deleted: string[] = [];
    for (const name of new Set(view.segments.map((ref) => ref.book_name))) {
      if (!name.startsWith(this.options.segment_book_prefix)) continue;
      if (!existing.has(name)) continue;
      try {
        if (await this.port.deleteWorldbook(name)) deleted.push(name);
      } catch {
        // A later recovery pass will retry; the active pointer never uses this stale view.
      }
    }
    return deleted;
  }

  private async collectUnreferencedSegments(
    activeView: TavernActiveView | null,
  ): Promise<string[]> {
    const activeBooks = new Set(activeView?.segments.map((segment) => segment.book_name) ?? []);
    const candidates = this.port
      .listWorldbooks()
      .filter(
        (name) => name.startsWith(this.options.segment_book_prefix) && !activeBooks.has(name),
      );
    const owned: string[] = [];
    for (const name of candidates) {
      try {
        const entries = await this.port.readWorldbook(name);
        const entry = entries[0];
        if (entries.length !== 1 || entry === undefined) continue;
        const payload = await parseSegmentPayload(entry.content, this.options.memory_set_id);
        if (payload.memory_set_id === this.options.memory_set_id) owned.push(name);
      } catch {
        // Unknown or corrupt books are never deleted by the orphan collector.
      }
    }
    return this.deleteBooks(owned);
  }
}
