import type { TavernHostPort, TavernMessageSnapshot } from "./contracts.js";
import { stripHtmlComments } from "./narrative-text-projection.js";
import {
  TAVERN_SOURCE_SNAPSHOT_VERSION,
  type TavernDirtyBoundary,
  type TavernDirtyReason,
  type TavernMutationHint,
  type TavernSemanticMetadataNormalizer,
  type TavernSourceMessage,
  type TavernSourceReconciliationRequest,
  type TavernSourceReconciliationResult,
  type TavernSourceScope,
  type TavernSourceSnapshot,
  TavernSourceSnapshotError,
} from "./source-snapshot-contracts.js";
import { canonicalJson, checksumJson, sha256HexUtf8 } from "./worldbook-codec.js";

const SAFE_MEMORY_SET_PATTERN = /^[A-Za-z0-9_-]{1,96}$/u;
const SHA256_PATTERN = /^[a-f0-9]{64}$/u;
const MUTATION_HINTS = new Set<TavernMutationHint>([
  "message_sent",
  "message_received",
  "message_edited",
  "message_updated",
  "message_deleted",
  "swipe_changed",
  "swipe_deleted",
  "reroll",
  "chat_loaded",
  "unknown",
]);

type NormalizedCurrentMessage = Omit<TavernSourceMessage, "source_unit_id" | "chain_hash">;

const withoutChecksum = (
  snapshot: TavernSourceSnapshot,
): Omit<TavernSourceSnapshot, "checksum"> => {
  const { checksum: _checksum, ...unsigned } = snapshot;
  return unsigned;
};

const defaultMetadataNormalizer: TavernSemanticMetadataNormalizer = () => null;

function assertStrictMessageOrder(messages: readonly TavernMessageSnapshot[], label: string): void {
  for (const [index, message] of messages.entries()) {
    if (
      !Number.isInteger(message.message_id) ||
      message.message_id < 0 ||
      (index > 0 && message.message_id <= (messages[index - 1]?.message_id ?? -1))
    ) {
      throw new TavernSourceSnapshotError(
        "HOST_SNAPSHOT_MISMATCH",
        `${label} messages are not strictly ordered by unique non-negative IDs`,
      );
    }
  }
}

function currentScope(port: TavernHostPort): TavernSourceScope {
  const identity = port.getCurrentIdentity();
  if (identity.character_id === null || identity.chat_id === null) {
    throw new TavernSourceSnapshotError("NO_ACTIVE_CHAT", "No active character/chat identity");
  }
  return { character_id: identity.character_id, chat_id: identity.chat_id };
}

const sameScope = (left: TavernSourceScope, right: TavernSourceScope): boolean =>
  left.character_id === right.character_id && left.chat_id === right.chat_id;

function uniqueHints(hints: readonly TavernMutationHint[]): TavernMutationHint[] {
  const result: TavernMutationHint[] = [];
  for (const hint of hints) {
    if (!MUTATION_HINTS.has(hint)) {
      throw new TavernSourceSnapshotError("INVALID_INPUT", `Unknown mutation hint ${hint}`);
    }
    if (!result.includes(hint)) result.push(hint);
  }
  return result;
}

async function normalizeMessage(
  current: TavernMessageSnapshot,
  withSwipes: TavernMessageSnapshot,
  normalizeMetadata: TavernSemanticMetadataNormalizer,
): Promise<NormalizedCurrentMessage> {
  if (
    current.message_id !== withSwipes.message_id ||
    current.role !== withSwipes.role ||
    current.name !== withSwipes.name ||
    current.is_hidden !== withSwipes.is_hidden
  ) {
    throw new TavernSourceSnapshotError(
      "HOST_SNAPSHOT_MISMATCH",
      `Message ${current.message_id} metadata differs between current and swipe snapshots`,
    );
  }
  if (current.message === undefined) {
    throw new TavernSourceSnapshotError(
      "HOST_SNAPSHOT_MISMATCH",
      `Current message ${current.message_id} has no body`,
    );
  }
  const rawMessage = current.message;
  let selectedSwipeData: Readonly<Record<string, unknown>> | null = null;
  let selectedSwipeInfo: Readonly<Record<string, unknown>> | null = null;
  if (withSwipes.swipes !== undefined) {
    if (
      withSwipes.swipe_id === undefined ||
      withSwipes.swipe_id < 0 ||
      withSwipes.swipe_id >= withSwipes.swipes.length
    ) {
      throw new TavernSourceSnapshotError(
        "HOST_SNAPSHOT_MISMATCH",
        `Message ${current.message_id} has an invalid selected swipe`,
      );
    }
    if (withSwipes.swipes[withSwipes.swipe_id] !== rawMessage) {
      throw new TavernSourceSnapshotError(
        "HOST_SNAPSHOT_MISMATCH",
        `Message ${current.message_id} current body does not match its selected swipe`,
      );
    }
    selectedSwipeData = withSwipes.swipes_data?.[withSwipes.swipe_id] ?? null;
    selectedSwipeInfo = withSwipes.swipes_info?.[withSwipes.swipe_id] ?? null;
  }
  const semanticMetadata = normalizeMetadata({
    message_id: current.message_id,
    role: current.role,
    speaker_name: current.name,
    is_hidden: current.is_hidden,
    current_data: current.data ?? null,
    current_extra: current.extra ?? null,
    selected_swipe_data: selectedSwipeData,
    selected_swipe_info: selectedSwipeInfo,
  });
  canonicalJson(semanticMetadata);
  const selectedContentHash = await sha256HexUtf8(rawMessage);
  const projection = current.is_hidden
    ? {
        narrative_text: null,
        narrative_text_hash: null,
        narrative_projection: {
          strategy: "hidden" as const,
          raw_start_code_point: null,
          raw_end_code_point: null,
        },
      }
    : await (async () => {
        const projected = current.narrative_projection ?? {
          text: rawMessage,
          strategy: "raw_selected_content" as const,
          raw_start_code_point: 0,
          raw_end_code_point: [...rawMessage].length,
        };
        const rawProjectionSlice = [...rawMessage]
          .slice(projected.raw_start_code_point, projected.raw_end_code_point)
          .join("");
        const expectedProjectedText =
          projected.strategy === "assistant_configured_content_block_without_html_comments"
            ? stripHtmlComments(rawProjectionSlice)
            : rawProjectionSlice;
        if (
          !Number.isInteger(projected.raw_start_code_point) ||
          !Number.isInteger(projected.raw_end_code_point) ||
          projected.raw_start_code_point < 0 ||
          projected.raw_end_code_point < projected.raw_start_code_point ||
          expectedProjectedText !== projected.text ||
          (projected.strategy === "raw_selected_content" &&
            (projected.raw_start_code_point !== 0 ||
              projected.raw_end_code_point !== [...rawMessage].length))
        ) {
          throw new TavernSourceSnapshotError(
            "HOST_SNAPSHOT_MISMATCH",
            `Message ${current.message_id} has an invalid narrative projection`,
          );
        }
        return {
          narrative_text: projected.text,
          narrative_text_hash: await sha256HexUtf8(projected.text),
          narrative_projection: {
            strategy: projected.strategy,
            raw_start_code_point: projected.raw_start_code_point,
            raw_end_code_point: projected.raw_end_code_point,
          },
        };
      })();
  const fingerprintInput = {
    role: current.role,
    speaker_name: current.name,
    is_hidden: current.is_hidden,
    selected_content_hash: selectedContentHash,
    narrative_text_hash: projection.narrative_text_hash,
    narrative_projection: projection.narrative_projection,
    has_swipes: withSwipes.swipes !== undefined,
    semantic_metadata: semanticMetadata,
  };
  return {
    message_id_at_capture: current.message_id,
    role: current.role,
    speaker_name: current.name,
    is_hidden: current.is_hidden,
    narrative_text: projection.narrative_text,
    narrative_text_hash: projection.narrative_text_hash,
    narrative_projection: projection.narrative_projection,
    selected_content_hash: selectedContentHash,
    has_swipes: withSwipes.swipes !== undefined,
    semantic_metadata: semanticMetadata,
    content_fingerprint: await checksumJson(fingerprintInput),
  };
}

async function captureCurrentMessages(
  port: TavernHostPort,
  normalizeMetadata: TavernSemanticMetadataNormalizer,
): Promise<readonly NormalizedCurrentMessage[]> {
  const current = port.readCurrentMessages({ include_swipes: false });
  const withSwipes = port.readCurrentMessages({ include_swipes: true });
  assertStrictMessageOrder(current, "Current");
  assertStrictMessageOrder(withSwipes, "Swipe");
  if (
    current.length !== withSwipes.length ||
    current.some((message, index) => message.message_id !== withSwipes[index]?.message_id)
  ) {
    throw new TavernSourceSnapshotError(
      "HOST_SNAPSHOT_MISMATCH",
      "Current and swipe snapshots do not contain the same message IDs",
    );
  }
  return Promise.all(
    current.map((message, index) => {
      const swipeMessage = withSwipes[index];
      if (swipeMessage === undefined) {
        throw new TavernSourceSnapshotError(
          "HOST_SNAPSHOT_MISMATCH",
          `Missing swipe snapshot for message ${message.message_id}`,
        );
      }
      return normalizeMessage(message, swipeMessage, normalizeMetadata);
    }),
  );
}

async function initialChainHash(memorySetId: string, scope: TavernSourceScope): Promise<string> {
  return checksumJson({ memory_set_id: memorySetId, scope, chain: "empty" });
}

async function buildSnapshot(
  memorySetId: string,
  scope: TavernSourceScope,
  sourceRevision: number,
  normalized: readonly NormalizedCurrentMessage[],
  previous: TavernSourceSnapshot | null,
  earliestDivergence: number,
): Promise<TavernSourceSnapshot> {
  let priorChain = await initialChainHash(memorySetId, scope);
  const messages: TavernSourceMessage[] = [];
  for (const [index, message] of normalized.entries()) {
    const previousMessage = previous?.messages[index];
    const sourceUnitId =
      index < earliestDivergence && previousMessage !== undefined
        ? previousMessage.source_unit_id
        : `src_${await checksumJson({
            memory_set_id: memorySetId,
            source_revision: sourceRevision,
            ordinal: index,
            content_fingerprint: message.content_fingerprint,
          })}`;
    const chainHash = await checksumJson({
      prior_chain_hash: priorChain,
      source_unit_id: sourceUnitId,
      message_id_at_capture: message.message_id_at_capture,
      content_fingerprint: message.content_fingerprint,
    });
    messages.push({ ...message, source_unit_id: sourceUnitId, chain_hash: chainHash });
    priorChain = chainHash;
  }
  const unsigned = {
    schema_version: TAVERN_SOURCE_SNAPSHOT_VERSION,
    memory_set_id: memorySetId,
    scope,
    source_revision: sourceRevision,
    messages,
    root_chain_hash: priorChain,
  };
  return { ...unsigned, checksum: await checksumJson(unsigned) };
}

function earliestDivergence(
  previous: TavernSourceSnapshot,
  current: readonly NormalizedCurrentMessage[],
): number | null {
  const commonLength = Math.min(previous.messages.length, current.length);
  for (let index = 0; index < commonLength; index += 1) {
    const oldMessage = previous.messages[index];
    const newMessage = current[index];
    if (
      oldMessage === undefined ||
      newMessage === undefined ||
      oldMessage.message_id_at_capture !== newMessage.message_id_at_capture ||
      oldMessage.content_fingerprint !== newMessage.content_fingerprint
    ) {
      return index;
    }
  }
  return previous.messages.length === current.length ? null : commonLength;
}

function dirtyReason(
  hints: readonly TavernMutationHint[],
  previousCount: number,
  currentCount: number,
  fromIndex: number,
): TavernDirtyReason {
  const categories = new Set<TavernDirtyReason>();
  for (const hint of hints) {
    if (hint === "message_sent" || hint === "message_received") categories.add("append");
    else if (hint === "message_edited" || hint === "message_updated") {
      categories.add("edit_or_update");
    } else if (hint === "message_deleted") categories.add("delete");
    else if (hint === "swipe_changed" || hint === "swipe_deleted" || hint === "reroll") {
      categories.add("swipe_or_reroll");
    }
  }
  if (categories.size > 1) return "mixed";
  const hinted = [...categories][0];
  if (hinted !== undefined) return hinted;
  if (fromIndex === previousCount && currentCount > previousCount) return "append";
  if (currentCount < previousCount) return "delete";
  return "unknown_change";
}

export async function verifyTavernSourceSnapshot(snapshot: TavernSourceSnapshot): Promise<void> {
  if (
    snapshot.schema_version !== TAVERN_SOURCE_SNAPSHOT_VERSION ||
    !SAFE_MEMORY_SET_PATTERN.test(snapshot.memory_set_id) ||
    typeof snapshot.scope.character_id !== "string" ||
    typeof snapshot.scope.chat_id !== "string" ||
    snapshot.scope.character_id.trim().length === 0 ||
    snapshot.scope.chat_id.trim().length === 0 ||
    !Number.isInteger(snapshot.source_revision) ||
    snapshot.source_revision < 1
  ) {
    throw new TavernSourceSnapshotError(
      "PREVIOUS_SNAPSHOT_CORRUPT",
      "Invalid source snapshot header",
    );
  }
  let priorChain = await initialChainHash(snapshot.memory_set_id, snapshot.scope);
  const unitIds = new Set<string>();
  for (const [index, message] of snapshot.messages.entries()) {
    if (
      !Number.isInteger(message.message_id_at_capture) ||
      message.message_id_at_capture < 0 ||
      typeof message.source_unit_id !== "string" ||
      !message.source_unit_id.startsWith("src_") ||
      typeof message.speaker_name !== "string" ||
      message.speaker_name.trim().length === 0 ||
      !["system", "assistant", "user"].includes(message.role) ||
      typeof message.is_hidden !== "boolean" ||
      typeof message.has_swipes !== "boolean" ||
      (message.narrative_text !== null && typeof message.narrative_text !== "string") ||
      (message.narrative_text_hash !== null && !SHA256_PATTERN.test(message.narrative_text_hash)) ||
      !SHA256_PATTERN.test(message.selected_content_hash) ||
      !SHA256_PATTERN.test(message.content_fingerprint) ||
      !SHA256_PATTERN.test(message.chain_hash) ||
      (index > 0 &&
        message.message_id_at_capture <=
          (snapshot.messages[index - 1]?.message_id_at_capture ?? -1)) ||
      unitIds.has(message.source_unit_id)
    ) {
      throw new TavernSourceSnapshotError(
        "PREVIOUS_SNAPSHOT_CORRUPT",
        "Invalid source message identity or order",
      );
    }
    unitIds.add(message.source_unit_id);
    canonicalJson(message.semantic_metadata);
    if (
      message.is_hidden !== (message.narrative_text === null) ||
      message.is_hidden !== (message.narrative_text_hash === null) ||
      (message.narrative_text !== null &&
        (await sha256HexUtf8(message.narrative_text)) !== message.narrative_text_hash) ||
      (message.is_hidden &&
        (message.narrative_projection.strategy !== "hidden" ||
          message.narrative_projection.raw_start_code_point !== null ||
          message.narrative_projection.raw_end_code_point !== null)) ||
      (!message.is_hidden &&
        (message.narrative_projection.strategy === "hidden" ||
          !Number.isInteger(message.narrative_projection.raw_start_code_point) ||
          !Number.isInteger(message.narrative_projection.raw_end_code_point) ||
          (message.narrative_projection.raw_start_code_point ?? -1) < 0 ||
          (message.narrative_projection.raw_end_code_point ?? -1) <
            (message.narrative_projection.raw_start_code_point ?? 0) ||
          (message.narrative_projection.strategy !==
            "assistant_configured_content_block_without_html_comments" &&
            (message.narrative_projection.raw_end_code_point ?? 0) -
              (message.narrative_projection.raw_start_code_point ?? 0) !==
              [...(message.narrative_text ?? "")].length) ||
          (message.narrative_projection.strategy ===
            "assistant_configured_content_block_without_html_comments" &&
            (message.narrative_projection.raw_end_code_point ?? 0) -
              (message.narrative_projection.raw_start_code_point ?? 0) <
              [...(message.narrative_text ?? "")].length) ||
          (message.narrative_projection.strategy === "raw_selected_content" &&
            (message.narrative_projection.raw_start_code_point !== 0 ||
              message.narrative_projection.raw_end_code_point !==
                [...(message.narrative_text ?? "")].length ||
              message.narrative_text_hash !== message.selected_content_hash))))
    ) {
      throw new TavernSourceSnapshotError(
        "PREVIOUS_SNAPSHOT_CORRUPT",
        `Source message ${message.source_unit_id} text/hash mismatch`,
      );
    }
    const expectedFingerprint = await checksumJson({
      role: message.role,
      speaker_name: message.speaker_name,
      is_hidden: message.is_hidden,
      selected_content_hash: message.selected_content_hash,
      narrative_text_hash: message.narrative_text_hash,
      narrative_projection: message.narrative_projection,
      has_swipes: message.has_swipes,
      semantic_metadata: message.semantic_metadata,
    });
    const expectedChain = await checksumJson({
      prior_chain_hash: priorChain,
      source_unit_id: message.source_unit_id,
      message_id_at_capture: message.message_id_at_capture,
      content_fingerprint: message.content_fingerprint,
    });
    if (
      message.content_fingerprint !== expectedFingerprint ||
      message.chain_hash !== expectedChain
    ) {
      throw new TavernSourceSnapshotError(
        "PREVIOUS_SNAPSHOT_CORRUPT",
        `Source message ${message.source_unit_id} fingerprint mismatch`,
      );
    }
    priorChain = expectedChain;
  }
  if (
    snapshot.root_chain_hash !== priorChain ||
    (await checksumJson(withoutChecksum(snapshot))) !== snapshot.checksum
  ) {
    throw new TavernSourceSnapshotError(
      "PREVIOUS_SNAPSHOT_CORRUPT",
      "Source snapshot root checksum mismatch",
    );
  }
}

/** Builds and verifies an authenticated immutable prefix without rereading the host. */
export async function createTavernSourceSnapshotPrefix(
  snapshot: TavernSourceSnapshot,
  messageCount: number,
): Promise<TavernSourceSnapshot> {
  await verifyTavernSourceSnapshot(snapshot);
  if (
    !Number.isInteger(messageCount) ||
    messageCount < 1 ||
    messageCount > snapshot.messages.length
  ) {
    throw new TavernSourceSnapshotError(
      "INVALID_INPUT",
      "Source prefix message count must be within the verified snapshot",
    );
  }
  const messages = snapshot.messages.slice(0, messageCount);
  const rootChainHash = messages.at(-1)?.chain_hash;
  if (rootChainHash === undefined) {
    throw new TavernSourceSnapshotError("INVALID_INPUT", "Source prefix cannot be empty");
  }
  const unsigned = {
    schema_version: snapshot.schema_version,
    memory_set_id: snapshot.memory_set_id,
    scope: snapshot.scope,
    source_revision: snapshot.source_revision,
    messages,
    root_chain_hash: rootChainHash,
  };
  const prefix = { ...unsigned, checksum: await checksumJson(unsigned) };
  await verifyTavernSourceSnapshot(prefix);
  return prefix;
}

export async function reconcileTavernSourceSnapshot(
  port: TavernHostPort,
  request: TavernSourceReconciliationRequest,
): Promise<TavernSourceReconciliationResult> {
  if (!SAFE_MEMORY_SET_PATTERN.test(request.memory_set_id)) {
    throw new TavernSourceSnapshotError("INVALID_INPUT", "Invalid memory_set_id");
  }
  const hints = uniqueHints(request.observed_hints);
  const scope = currentScope(port);
  if (request.previous_snapshot !== null) {
    await verifyTavernSourceSnapshot(request.previous_snapshot);
    if (request.previous_snapshot.memory_set_id !== request.memory_set_id) {
      throw new TavernSourceSnapshotError(
        "SCOPE_CHANGED",
        "Previous source snapshot belongs to a different Memory Set",
      );
    }
    if (!sameScope(request.previous_snapshot.scope, scope)) {
      const confirmation = request.confirmed_scope_rebind;
      if (
        confirmation === undefined ||
        !sameScope(confirmation.expected_previous_scope, request.previous_snapshot.scope) ||
        confirmation.expected_previous_checksum !== request.previous_snapshot.checksum
      ) {
        throw new TavernSourceSnapshotError(
          "SCOPE_CHANGED",
          "Previous source snapshot belongs to a different character/chat",
        );
      }
    } else if (request.confirmed_scope_rebind !== undefined) {
      throw new TavernSourceSnapshotError(
        "INVALID_INPUT",
        "Scope rebind confirmation was supplied without a scope change",
      );
    }
  }
  const normalized = await captureCurrentMessages(
    port,
    request.normalize_semantic_metadata ?? defaultMetadataNormalizer,
  );
  if (request.previous_snapshot === null) {
    const snapshot = await buildSnapshot(request.memory_set_id, scope, 1, normalized, null, 0);
    return {
      status: "INITIAL",
      snapshot,
      dirty_boundary: {
        reason: "initial_snapshot",
        observed_hints: hints,
        from_index: 0,
        previous_message_id: null,
        current_message_id: snapshot.messages[0]?.message_id_at_capture ?? null,
        previous_message_count: 0,
        current_message_count: snapshot.messages.length,
        invalidated_source_unit_ids: [],
        requires_tail_rebuild: true,
      },
    };
  }
  const divergence = earliestDivergence(request.previous_snapshot, normalized);
  const scopeRebound = !sameScope(request.previous_snapshot.scope, scope);
  if (divergence === null && !scopeRebound) {
    return { status: "UNCHANGED", snapshot: request.previous_snapshot, dirty_boundary: null };
  }
  const nextRevision = request.previous_snapshot.source_revision + 1;
  const snapshot = await buildSnapshot(
    request.memory_set_id,
    scope,
    nextRevision,
    normalized,
    request.previous_snapshot,
    divergence ?? normalized.length,
  );
  const dirtyFrom = divergence ?? normalized.length;
  const dirtyBoundary: TavernDirtyBoundary = {
    reason: scopeRebound
      ? divergence === null
        ? "scope_rebind"
        : "mixed"
      : dirtyReason(hints, request.previous_snapshot.messages.length, normalized.length, dirtyFrom),
    observed_hints: hints,
    from_index: dirtyFrom,
    previous_message_id:
      request.previous_snapshot.messages[dirtyFrom]?.message_id_at_capture ?? null,
    current_message_id: snapshot.messages[dirtyFrom]?.message_id_at_capture ?? null,
    previous_message_count: request.previous_snapshot.messages.length,
    current_message_count: snapshot.messages.length,
    invalidated_source_unit_ids: request.previous_snapshot.messages
      .slice(dirtyFrom)
      .map((message) => message.source_unit_id),
    requires_tail_rebuild: true,
  };
  return { status: "CHANGED", snapshot, dirty_boundary: dirtyBoundary };
}
