import {
  TAVERN_MEMORY_MODULE_IDS,
  type TavernMemoryBatchWorkState,
  TavernMemoryBookError,
  type TavernMemoryModuleId,
  type TavernMemoryModuleWorkState,
} from "./memory-book-contracts.js";

export type TavernMemoryAttemptKind =
  | "base"
  | "transport_retry"
  | "continuation"
  | "targeted_repair"
  | "manual_repair";

export interface TavernMemoryAttemptLimits {
  readonly max_transport_retries: number;
  readonly max_continuations: number;
  readonly max_targeted_repairs: 0 | 1;
}

const modulePosition = (moduleId: TavernMemoryModuleId): number =>
  TAVERN_MEMORY_MODULE_IDS.indexOf(moduleId);

function replaceModule(
  batch: TavernMemoryBatchWorkState,
  next: TavernMemoryModuleWorkState,
): TavernMemoryBatchWorkState["modules"] {
  return { ...batch.modules, [next.module_id]: next };
}

function assertPriorModulesCommitted(
  batch: TavernMemoryBatchWorkState,
  moduleId: TavernMemoryModuleId,
): void {
  const position = modulePosition(moduleId);
  for (const prior of TAVERN_MEMORY_MODULE_IDS.slice(0, position)) {
    if (batch.modules[prior].status !== "COMMITTED") {
      throw new TavernMemoryBookError(
        "INVALID_INPUT",
        `${moduleId} cannot start before ${prior} commits`,
      );
    }
  }
}

function assertAttemptAllowed(
  module: TavernMemoryModuleWorkState,
  kind: TavernMemoryAttemptKind,
  limits: TavernMemoryAttemptLimits,
): void {
  if (kind === "base" && (module.status !== "PENDING" || module.base_calls !== 0)) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Base attempt can run exactly once");
  }
  if (kind === "transport_retry" && module.transport_retry_calls >= limits.max_transport_retries) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Transport retry limit reached");
  }
  if (kind === "continuation" && module.continuation_calls >= limits.max_continuations) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Continuation limit reached");
  }
  if (kind === "targeted_repair" && module.targeted_repair_calls >= limits.max_targeted_repairs) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Automatic targeted repair limit reached");
  }
  if (kind !== "base" && module.status !== "NEEDS_USER" && module.status !== "INTERRUPTED") {
    throw new TavernMemoryBookError(
      "INVALID_INPUT",
      `${kind} requires a failed or interrupted module`,
    );
  }
}

export function startTavernMemoryModuleAttempt(
  batch: TavernMemoryBatchWorkState,
  moduleId: TavernMemoryModuleId,
  kind: TavernMemoryAttemptKind,
  limits: TavernMemoryAttemptLimits,
): TavernMemoryBatchWorkState {
  if (
    batch.status === "INVALIDATED" ||
    batch.status === "FINALIZING" ||
    batch.status === "CHECKPOINT_VERIFIED" ||
    batch.status === "RECALL_READY" ||
    batch.status === "VISIBILITY_APPLIED" ||
    batch.status === "COMPLETE"
  ) {
    throw new TavernMemoryBookError("INVALID_INPUT", `Batch ${batch.status} cannot start a module`);
  }
  assertPriorModulesCommitted(batch, moduleId);
  const module = batch.modules[moduleId];
  if (
    module.status === "RUNNING" ||
    module.status === "COMMITTED" ||
    module.status === "INVALIDATED"
  ) {
    throw new TavernMemoryBookError("INVALID_INPUT", `${moduleId} is ${module.status}`);
  }
  assertAttemptAllowed(module, kind, limits);
  const next: TavernMemoryModuleWorkState = {
    ...module,
    status: "RUNNING",
    base_calls: module.base_calls + (kind === "base" ? 1 : 0),
    transport_retry_calls: module.transport_retry_calls + (kind === "transport_retry" ? 1 : 0),
    continuation_calls: module.continuation_calls + (kind === "continuation" ? 1 : 0),
    targeted_repair_calls: module.targeted_repair_calls + (kind === "targeted_repair" ? 1 : 0),
    manual_repair_calls: module.manual_repair_calls + (kind === "manual_repair" ? 1 : 0),
    last_error_code: null,
  };
  return { ...batch, status: "MODULE_RUNNING", modules: replaceModule(batch, next) };
}

export function settleTavernMemoryModuleAttempt(
  batch: TavernMemoryBatchWorkState,
  moduleId: TavernMemoryModuleId,
  result: {
    readonly accepted_record_ids: readonly string[];
    readonly pending_target_ids: readonly string[];
    readonly error_code: string | null;
    readonly partition_page_id?: string | null;
    readonly last_attempt_page_id?: string | null;
  },
): TavernMemoryBatchWorkState {
  const module = batch.modules[moduleId];
  if (batch.status !== "MODULE_RUNNING" || module.status !== "RUNNING") {
    throw new TavernMemoryBookError("INVALID_INPUT", `${moduleId} has no running attempt`);
  }
  const accepted = [...new Set([...module.accepted_record_ids, ...result.accepted_record_ids])];
  const pending = [...new Set(result.pending_target_ids)];
  if (pending.some((target) => accepted.includes(target))) {
    throw new TavernMemoryBookError("INVALID_INPUT", "A target cannot be accepted and pending");
  }
  if (pending.length > 0 || result.error_code !== null) {
    const failed: TavernMemoryModuleWorkState = {
      ...module,
      status: "NEEDS_USER",
      accepted_record_ids: accepted,
      pending_target_ids: pending,
      partition_page_id: result.partition_page_id ?? module.partition_page_id,
      last_attempt_page_id: result.last_attempt_page_id ?? module.last_attempt_page_id,
      last_error_code: result.error_code ?? "VALIDATION_FAILED",
    };
    return { ...batch, status: "NEEDS_USER", modules: replaceModule(batch, failed) };
  }
  const committed: TavernMemoryModuleWorkState = {
    ...module,
    status: "COMMITTED",
    module_revision: module.module_revision + 1,
    accepted_record_ids: accepted,
    pending_target_ids: [],
    partition_page_id: result.partition_page_id ?? module.partition_page_id,
    last_attempt_page_id: result.last_attempt_page_id ?? module.last_attempt_page_id,
    last_error_code: null,
  };
  const modules = replaceModule(batch, committed);
  const allCommitted = TAVERN_MEMORY_MODULE_IDS.every(
    (candidate) => modules[candidate].status === "COMMITTED",
  );
  const stillNeedsUser = TAVERN_MEMORY_MODULE_IDS.some((candidate) =>
    ["NEEDS_USER", "INTERRUPTED"].includes(modules[candidate].status),
  );
  return {
    ...batch,
    status: allCommitted ? "FINALIZING" : stillNeedsUser ? "NEEDS_USER" : "READY",
    modules,
  };
}

export function recoverInterruptedTavernMemoryBatch(
  batch: TavernMemoryBatchWorkState,
): TavernMemoryBatchWorkState {
  if (batch.status !== "MODULE_RUNNING") return batch;
  const running = TAVERN_MEMORY_MODULE_IDS.filter(
    (moduleId) => batch.modules[moduleId].status === "RUNNING",
  );
  if (running.length !== 1) {
    throw new TavernMemoryBookError("BOOK_CORRUPT", "Running batch must have exactly one module");
  }
  const moduleId = running[0];
  if (moduleId === undefined)
    throw new TavernMemoryBookError("BOOK_CORRUPT", "Missing running module");
  const interrupted: TavernMemoryModuleWorkState = {
    ...batch.modules[moduleId],
    status: "INTERRUPTED",
    last_error_code: "INTERRUPTED",
  };
  return { ...batch, status: "NEEDS_USER", modules: replaceModule(batch, interrupted) };
}

export function invalidateTavernMemoryBatch(
  batch: TavernMemoryBatchWorkState,
): TavernMemoryBatchWorkState {
  const modules = Object.fromEntries(
    TAVERN_MEMORY_MODULE_IDS.map((moduleId) => [
      moduleId,
      batch.modules[moduleId].status === "COMMITTED"
        ? batch.modules[moduleId]
        : { ...batch.modules[moduleId], status: "INVALIDATED" as const },
    ]),
  ) as unknown as TavernMemoryBatchWorkState["modules"];
  return { ...batch, status: "INVALIDATED", modules };
}

export function advanceTavernMemoryBatchDurability(
  batch: TavernMemoryBatchWorkState,
  step: "checkpoint_verified" | "recall_ready" | "visibility_applied" | "complete",
): TavernMemoryBatchWorkState {
  const expected = {
    checkpoint_verified: "FINALIZING",
    recall_ready: "CHECKPOINT_VERIFIED",
    visibility_applied: "RECALL_READY",
    complete: "VISIBILITY_APPLIED",
  } as const;
  const next = {
    checkpoint_verified: "CHECKPOINT_VERIFIED",
    recall_ready: "RECALL_READY",
    visibility_applied: "VISIBILITY_APPLIED",
    complete: "COMPLETE",
  } as const;
  if (batch.status !== expected[step]) {
    throw new TavernMemoryBookError(
      "INVALID_INPUT",
      `${step} requires ${expected[step]}, found ${batch.status}`,
    );
  }
  return { ...batch, status: next[step] };
}

export const canApplyTavernMemoryVisibility = (batch: TavernMemoryBatchWorkState): boolean =>
  batch.status === "RECALL_READY";
