function button(text: string, className = ""): HTMLButtonElement {
  const value = document.createElement("button");
  value.type = "button";
  value.className = `menu_button narramem-button ${className}`.trim();
  value.textContent = text;
  return value;
}

function textInput(value: string, placeholder = ""): HTMLInputElement {
  const input = document.createElement("input");
  input.type = "text";
  input.className = "text_pole";
  input.value = value;
  input.placeholder = placeholder;
  return input;
}

function numberInput(value: number, minimum: number, maximum: number): HTMLInputElement {
  const input = document.createElement("input");
  input.type = "number";
  input.className = "text_pole";
  input.value = String(value);
  input.min = String(minimum);
  input.max = String(maximum);
  input.step = "1";
  return input;
}

function checkbox(id: string, caption: string, checked: boolean): {
  readonly label: HTMLLabelElement;
  readonly input: HTMLInputElement;
} {
  const label = document.createElement("label");
  label.className = "checkbox_label narramem-checkbox";
  label.htmlFor = id;
  const input = document.createElement("input");
  input.id = id;
  input.name = id;
  input.type = "checkbox";
  input.checked = checked;
  const span = document.createElement("span");
  span.textContent = caption;
  label.append(input, span);
  return { label, input };
}

function field(labelText: string, control: HTMLElement, note?: string): HTMLLabelElement {
  const label = document.createElement("label");
  label.className = "narramem-field";
  const heading = document.createElement("span");
  heading.className = "narramem-field__label";
  heading.textContent = labelText;
  label.append(heading, control);
  if (note !== undefined) {
    const small = document.createElement("small");
    small.textContent = note;
    label.append(small);
  }
  return label;
}

function errorText(error: unknown): string {
  if (error instanceof NarraMemMemoryApiError) {
    return `${error.code}${error.http_status === null ? "" : ` · HTTP ${error.http_status}`}`;
  }
  return error instanceof Error ? `${error.name} · ${error.message}` : "未知错误";
}

function download(filename: string, value: unknown): void {
  const url = URL.createObjectURL(
    new Blob([JSON.stringify(value, null, 2)], { type: "application/json;charset=utf-8" }),
  );
  try {
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = filename;
    anchor.click();
  } finally {
    URL.revokeObjectURL(url);
  }
}

function exportName(kind: "diagnostics" | "core"): string {
  return `narramem-${kind}-${new Date().toISOString().replace(/[:.]/gu, "-")}.json`;
}

function flattenedText(value: unknown, depth = 0): string[] {
  if (value === null || value === undefined) return [];
  if (["string", "number", "boolean"].includes(typeof value)) return [String(value)];
  if (Array.isArray(value)) {
    return value.flatMap((item) =>
      flattenedText(item, depth + 1).map((line, index) => `${index === 0 ? "• " : "  "}${line}`),
    );
  }
  if (typeof value !== "object") return [String(value)];
  const lines: string[] = [];
  for (const [key, child] of Object.entries(value as Readonly<Record<string, unknown>>)) {
    if (TECHNICAL_FIELDS.has(key)) continue;
    const childLines = flattenedText(child, depth + 1);
    if (childLines.length === 0) continue;
    const label = FIELD_LABELS[key] ?? key.replaceAll("_", " ");
    if (childLines.length === 1 && !childLines[0]?.startsWith("• ")) {
      lines.push(`${label}：${childLines[0] ?? ""}`);
    } else {
      lines.push(`${label}：`, ...childLines.map((line) => `  ${line}`));
    }
  }
  return lines;
}

function runtimeHeadline(snapshot: NarraMemModularRuntimeSnapshot): string {
  if (snapshot.status === "disabled") return "自动记忆未启用";
  if (snapshot.status === "no_chat") return "当前没有可处理的角色聊天";
  if (snapshot.status === "waiting_for_user") return "本批有模块需要手动处理";
  if (snapshot.status === "failed") return "后台记忆任务失败，聊天不会受阻";
  if (["running", "finalizing"].includes(snapshot.status)) return "后台正在整理记忆";
  if (["recall_ready", "complete"].includes(snapshot.status)) return "最新记忆批次已完成";
  return "正在等待下一批剧情";
}

function collectionText(snapshot: NarraMemModularRuntimeSnapshot): string {
  if (snapshot.batch_id !== null) {
    return `当前批 AI 楼层 ${snapshot.batch_first_ai_ordinal ?? "?"}–${snapshot.batch_last_ai_ordinal ?? "?"}；最新 4 个 AI 楼层始终保留在聊天正文中。`;
  }
  if (snapshot.committed_ai_count === 0) {
    return `首次收集 ${Math.min(snapshot.valid_ai_count, 14)}/14 个 AI 楼层；到 14 时处理前 10 个，保留最新 4 个。`;
  }
  return `下一批已积累 ${Math.min(snapshot.pending_eligible_ai_count, 10)}/10 个可处理 AI 楼层；另有最新 4 个 AI 楼层受保护。`;
}

