import {
  canonicalJson,
  recallInjectionDepthBeforeLatestAiWindow,
  type TavernEventSubscription,
  type TavernHostPort,
  type TavernInjectionHandle,
  TAVERN_RECALL_INVALIDATION_EVENT_NAMES,
} from "@narramem/tavern-adapter";

import type { NarraMemModularMemoryRuntime } from "./modular-memory-runtime.js";

const RECALL_VARIABLE = "{{NARRAMEM:RECALL_CONTEXT_JSON}}";
const LATEST_AI_FLOORS = 4;

export type NarraMemModularRecallReport =
  | {
      readonly status: "INJECTION_INSTALLED";
      readonly sequence: number;
      readonly checkpoint_id: string;
      readonly bundle_id: string;
      readonly injection_depth: number;
      readonly source_alignment: "EXACT" | "APPEND_ONLY_LIVE_TAIL";
      readonly live_tail_message_count: number;
      readonly elapsed_ms: number;
    }
  | {
      readonly status: "DEFERRED_TO_MESSAGE_SENT" | "SKIPPED_DRY_RUN" | "INVALIDATED";
      readonly sequence: number;
      readonly reason?: string;
    }
  | {
      readonly status: "DEGRADED_NO_INJECTION";
      readonly sequence: number;
      readonly reason: "NO_COMMITTED_COVERAGE" | "UNSAFE_SOURCE_CHANGE" | "DEADLINE_EXCEEDED" | "RECALL_UNAVAILABLE";
      readonly error_name: string;
      readonly error_code: string | null;
      readonly elapsed_ms: number;
    };

export interface NarraMemModularRecallBarrierOptions {
  readonly port: TavernHostPort;
  readonly runtime: NarraMemModularMemoryRuntime;
  readonly prompt_body: string;
  readonly prompt_asset_ref: string;
  readonly deadline_ms?: number;
  on_report?(report: NarraMemModularRecallReport): void;
}

function errorDescriptor(error: unknown): {
  readonly name: string;
  readonly code: string | null;
} {
  if (!(error instanceof Error)) return { name: "UnknownError", code: null };
  const candidate = error as Error & { readonly code?: unknown };
  return {
    name: error.name,
    code: typeof candidate.code === "string" ? candidate.code : null,
  };
}

function isDryRun(args: readonly unknown[]): boolean {
  return args[2] === true;
}

function waitsForCommittedUserMessage(args: readonly unknown[]): boolean {
  if (args[0] !== undefined && args[0] !== "normal") return false;
  const parameters = args[1];
  if (parameters === null || typeof parameters !== "object") return true;
  return (parameters as Readonly<Record<string, unknown>>).automatic_trigger !== true;
}

type DegradedReason = Extract<
  NarraMemModularRecallReport,
  { readonly status: "DEGRADED_NO_INJECTION" }
>["reason"];

function reasonFor(errorCode: string | null): DegradedReason {
  if (errorCode === "SEMANTIC_COVERAGE_MISSING" || errorCode === "NO_CHECKPOINT") {
    return "NO_COMMITTED_COVERAGE";
  }
  if (errorCode === "SOURCE_CHANGED") return "UNSAFE_SOURCE_CHANGE";
  if (errorCode === "DEADLINE_EXCEEDED") return "DEADLINE_EXCEEDED";
  return "RECALL_UNAVAILABLE";
}

/**
 * Generation-scoped bridge for the v2 Checkpoint runtime. It never starts a
 * Memory model call: it only reads the latest verified Checkpoint and installs
 * one consumer-safe Recall Bundle immediately before the latest four AI floors.
 */
export class NarraMemModularRecallBarrier {
  private sequence = 0;
  private running = false;
  private waitingForMessage: number | null = null;
  private injection: TavernInjectionHandle | null = null;
  private readonly subscriptions: TavernEventSubscription[] = [];

  constructor(private readonly options: NarraMemModularRecallBarrierOptions) {
    const variableCount = options.prompt_body.split(RECALL_VARIABLE).length - 1;
    if (variableCount !== 1) {
      throw new TypeError("Recall Prompt 必须且只能包含一个 NarraMem Recall 变量");
    }
  }

  start(): void {
    if (this.running) return;
    if (this.options.port.installInjection === undefined) {
      throw new TypeError("当前酒馆不支持 NarraMem Recall 注入");
    }
    this.running = true;
    this.subscriptions.push(
      this.options.port.subscribe("generation_after_commands", (...args) => this.afterCommands(args)),
      this.options.port.subscribe("message_sent", () => this.afterMessageSent()),
    );
    for (const eventName of TAVERN_RECALL_INVALIDATION_EVENT_NAMES) {
      this.subscriptions.push(
        this.options.port.subscribe(eventName, () => this.invalidate(eventName)),
      );
    }
  }

  dispose(): void {
    this.running = false;
    this.invalidate("disposed");
    for (const subscription of this.subscriptions.splice(0)) subscription.stop();
  }

  private async afterCommands(args: readonly unknown[]): Promise<void> {
    if (!this.running) return;
    if (isDryRun(args)) {
      this.options.on_report?.({ status: "SKIPPED_DRY_RUN", sequence: this.sequence });
      return;
    }
    this.sequence += 1;
    const sequence = this.sequence;
    this.removeInjection();
    this.waitingForMessage = null;
    if (waitsForCommittedUserMessage(args)) {
      this.waitingForMessage = sequence;
      this.options.on_report?.({ status: "DEFERRED_TO_MESSAGE_SENT", sequence });
      return;
    }
    await this.prepare(sequence);
  }

  private async afterMessageSent(): Promise<void> {
    if (!this.running) return;
    const sequence = this.waitingForMessage;
    if (sequence === null) {
      this.invalidate("message_sent_without_deferred_generation");
      return;
    }
    this.waitingForMessage = null;
    await this.prepare(sequence);
  }

  private async prepare(sequence: number): Promise<void> {
    const startedAt = performance.now();
    const deadlineMs = this.options.deadline_ms ?? 300;
    let deadlineHandle: ReturnType<typeof setTimeout> | null = null;
    const deadline = new Promise<never>((_resolve, reject) => {
      deadlineHandle = globalThis.setTimeout(() => {
        reject(Object.assign(new Error("Recall preparation deadline exceeded"), { code: "DEADLINE_EXCEEDED" }));
      }, deadlineMs);
    });
    try {
      const recalled = await Promise.race([this.options.runtime.assembleRecall(), deadline]);
      if (!this.running || sequence !== this.sequence) return;
      const install = this.options.port.installInjection;
      if (install === undefined) throw new TypeError("Recall 注入能力在运行时消失");
      const depth = recallInjectionDepthBeforeLatestAiWindow(
        this.options.port.readCurrentMessages({ include_swipes: false }),
        LATEST_AI_FLOORS,
      );
      const content = this.options.prompt_body.replace(
        RECALL_VARIABLE,
        canonicalJson(recalled.bundle).replaceAll("&", "\\u0026").replaceAll("<", "\\u003c").replaceAll(">", "\\u003e"),
      );
      this.removeInjection();
      this.injection = install({
        id: `narramem_modular_recall_${sequence}`,
        position: "in_chat",
        depth,
        role: "system",
        content,
        should_scan: false,
        once: true,
        prompt_asset_ref: this.options.prompt_asset_ref,
      });
      this.options.on_report?.({
        status: "INJECTION_INSTALLED",
        sequence,
        checkpoint_id: recalled.manifest.checkpoint_id,
        bundle_id: recalled.bundle.bundle_id,
        injection_depth: depth,
        source_alignment: recalled.source_alignment.mode,
        live_tail_message_count: recalled.source_alignment.live_tail_message_count,
        elapsed_ms: Math.max(0, performance.now() - startedAt),
      });
    } catch (error) {
      if (!this.running || sequence !== this.sequence) return;
      const descriptor = errorDescriptor(error);
      this.removeInjection();
      this.options.on_report?.({
        status: "DEGRADED_NO_INJECTION",
        sequence,
        reason: reasonFor(descriptor.code),
        error_name: descriptor.name,
        error_code: descriptor.code,
        elapsed_ms: Math.max(0, performance.now() - startedAt),
      });
    } finally {
      if (deadlineHandle !== null) globalThis.clearTimeout(deadlineHandle);
    }
  }

  private invalidate(reason: string): void {
    this.sequence += 1;
    this.waitingForMessage = null;
    this.removeInjection();
    this.options.on_report?.({ status: "INVALIDATED", sequence: this.sequence, reason });
  }

  private removeInjection(): void {
    this.injection?.remove();
    this.injection = null;
  }
}
