import type {
  TavernHostPort,
  TavernJsonValue,
  TavernWorldbookEntry,
  TavernWorldbookEntryDraft,
} from "./contracts.js";
import {
  TAVERN_MEMORY_BOOK_ENTRY_FORMAT,
  TAVERN_MEMORY_BOOK_VERSION,
  TAVERN_MEMORY_MODULE_IDS,
  TAVERN_MEMORY_REGISTRY_BOOK_NAME,
  TAVERN_MEMORY_REGISTRY_FORMAT,
  TAVERN_MEMORY_REGISTRY_VERSION,
  type TavernMemoryBookCommitRequest,
  type TavernMemoryBookCompactionRequest,
  type TavernMemoryBookCompactionResult,
  TavernMemoryBookError,
  type TavernMemoryBookOptions,
  type TavernMemoryBookReadResult,
  type TavernMemoryColdHead,
  type TavernMemoryCorePage,
  type TavernMemoryModuleId,
  type TavernMemoryModuleViewIndex,
  type TavernMemoryModuleViewPage,
  type TavernMemoryPageRef,
  type TavernMemoryRegistryRecord,
  type TavernMemoryRegistrySnapshot,
  type TavernMemoryRegistryWriteRequest,
} from "./memory-book-contracts.js";
import { canonicalJson, checksumJson, utf8ByteLength } from "./worldbook-codec.js";

type MemoryEntryKind =
  | "CONTROL"
  | "SOURCE_INDEX"
  | "WORK_STATE"
  | "CHECKPOINT_INDEX"
  | "ACTIVE_STATE"
  | "EPISTEMIC_STATE"
  | "THREAD_IMPACT"
  | "MODULE_VIEW_INDEX"
  | "CORE_PAGE"
  | "MODULE_VIEW_PAGE"
  | "AUDIT_RING";

interface EncodedMemoryEntry {
  readonly format: typeof TAVERN_MEMORY_BOOK_ENTRY_FORMAT;
  readonly schema_version: typeof TAVERN_MEMORY_BOOK_VERSION;
  readonly memory_set_id: string;
  readonly generation: number;
  readonly kind: MemoryEntryKind;
  readonly logical_id: string;
  readonly payload: unknown;
  readonly payload_checksum: string;
  readonly generation_checksum: string;
}

interface PreparedPayload {
  readonly kind: MemoryEntryKind;
  readonly logical_id: string;
  readonly payload: unknown;
  readonly payload_checksum: string;
}

interface ControlPayload {
  readonly chain_root: boolean;
  readonly commit_id: string;
  readonly commit_payload_checksum: string;
  readonly previous_generation_checksum: string | null;
  readonly committed_at: string;
  readonly core_page_refs: readonly TavernMemoryPageRef[];
  readonly module_view_page_refs: readonly TavernMemoryPageRef[];
}

interface EncodedRegistryEntry {
  readonly format: typeof TAVERN_MEMORY_REGISTRY_FORMAT;
  readonly schema_version: typeof TAVERN_MEMORY_REGISTRY_VERSION;
  readonly generation: number;
  readonly previous_generation_checksum: string | null;
  readonly records: readonly TavernMemoryRegistryRecord[];
  readonly checksum: string;
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const isNonNegativeInteger = (value: unknown): value is number =>
  typeof value === "number" && Number.isInteger(value) && value >= 0;

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0;

const unique = (values: readonly string[]): boolean => new Set(values).size === values.length;

function assertSafeOptions(options: TavernMemoryBookOptions): void {
  if (
    !isNonEmptyString(options.memory_set_id) ||
    !isNonEmptyString(options.book_name) ||
    !Number.isInteger(options.max_cold_head_utf8_bytes) ||
    options.max_cold_head_utf8_bytes < 1024 ||
    !Number.isInteger(options.max_core_page_utf8_bytes) ||
    options.max_core_page_utf8_bytes < 256 ||
    !Number.isInteger(options.max_audit_items) ||
    options.max_audit_items < 1
  ) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Invalid Memory Book options");
  }
}

function machineEntryDraft(
  name: string,
  content: string,
  extra: Record<string, unknown>,
): TavernWorldbookEntryDraft {
  return {
    name,
    enabled: false,
    content,
    strategy: {
      type: "constant",
      keys: [],
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: { type: "after_character_definition", role: "system", depth: 0, order: 0 },
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra,
  };
}

function isSafeMachineEntry(entry: TavernWorldbookEntry): boolean {
  return (
    !entry.enabled &&
    entry.strategy.type === "constant" &&
    entry.strategy.keys.length === 0 &&
    entry.recursion.prevent_incoming &&
    entry.recursion.prevent_outgoing
  );
}

function parseJson(content: string): unknown {
  try {
    return JSON.parse(content);
  } catch {
    return null;
  }
}

async function preparePayload(
  kind: MemoryEntryKind,
  logicalId: string,
  payload: unknown,
): Promise<PreparedPayload> {
  return { kind, logical_id: logicalId, payload, payload_checksum: await checksumJson(payload) };
}

function assertModuleIndexes(
  value: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>,
): void {
  for (const moduleId of TAVERN_MEMORY_MODULE_IDS) {
    const index = value[moduleId];
    if (
      index?.module_id !== moduleId ||
      !isNonNegativeInteger(index.record_count) ||
      !isNonNegativeInteger(index.abnormal_count) ||
      !isNonNegativeInteger(index.page_count) ||
      index.abnormal_count > index.record_count ||
      (index.page_count === 0 &&
        (index.latest_page_id !== null ||
          index.oldest_page_id !== null ||
          index.record_count !== 0)) ||
      (index.page_count > 0 &&
        (!isNonEmptyString(index.latest_page_id) || !isNonEmptyString(index.oldest_page_id)))
    ) {
      throw new TavernMemoryBookError("INVALID_INPUT", `Invalid ${moduleId} view index`);
    }
  }
}

const cursorKey = (item: {
  readonly sort_time: string;
  readonly record_revision: number;
  readonly record_id: string;
}): string =>
  `${item.sort_time}\u0000${String(item.record_revision).padStart(12, "0")}\u0000${item.record_id}`;

function assertViewPageTopology(
  indexes: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>,
  pages: readonly TavernMemoryModuleViewPage[],
  corePageIds: ReadonlySet<string>,
  errorCode: "INVALID_INPUT" | "BOOK_CORRUPT",
): void {
  const pageById = new Map(pages.map((page) => [page.page_id, page] as const));
  for (const moduleId of TAVERN_MEMORY_MODULE_IDS) {
    const index = indexes[moduleId];
    const modulePages = pages.filter((page) => page.module_id === moduleId);
    if (modulePages.length !== index.page_count) {
      throw new TavernMemoryBookError(errorCode, `${moduleId} page count does not match its index`);
    }
    if (modulePages.length === 0) continue;
    const visited: TavernMemoryModuleViewPage[] = [];
    let pageId: string | null = index.latest_page_id;
    while (pageId !== null) {
      const page = pageById.get(pageId);
      if (page === undefined || page.module_id !== moduleId || page.newer_page_id !== null) {
        throw new TavernMemoryBookError(errorCode, `${moduleId} view page chain is broken`);
      }
      if (visited.some((item) => item.page_id === page.page_id)) {
        throw new TavernMemoryBookError(errorCode, `${moduleId} view page chain contains a cycle`);
      }
      visited.push(page);
      pageId = page.older_page_id;
    }
    if (
      visited.length !== modulePages.length ||
      visited.at(-1)?.page_id !== index.oldest_page_id ||
      visited[0]?.newer_page_id !== null ||
      visited.at(-1)?.older_page_id !== null
    ) {
      throw new TavernMemoryBookError(errorCode, `${moduleId} view page endpoints are invalid`);
    }
    const items = visited.flatMap((page) => page.items);
    if (
      items.length !== index.record_count ||
      !unique(items.map((item) => item.record_id)) ||
      items.some(
        (item) =>
          item.record_revision < 1 ||
          !isNonEmptyString(item.sort_time) ||
          !isNonEmptyString(item.title) ||
          !corePageIds.has(item.core_page_id),
      )
    ) {
      throw new TavernMemoryBookError(errorCode, `${moduleId} view records are invalid`);
    }
    for (let indexPosition = 1; indexPosition < items.length; indexPosition += 1) {
      const newer = items[indexPosition - 1];
      const older = items[indexPosition];
      if (newer === undefined || older === undefined || cursorKey(newer) < cursorKey(older)) {
        throw new TavernMemoryBookError(errorCode, `${moduleId} view records are not newest-first`);
      }
    }
    const newest = items[0];
    if (
      newest === undefined ||
      index.newest_cursor?.sort_time !== newest.sort_time ||
      index.newest_cursor.record_revision !== newest.record_revision ||
      index.newest_cursor.record_id !== newest.record_id
    ) {
      throw new TavernMemoryBookError(errorCode, `${moduleId} newest cursor is invalid`);
    }
  }
}

function assertCommitRequest(request: TavernMemoryBookCommitRequest): void {
  if (
    !isNonEmptyString(request.commit_id) ||
    !isNonNegativeInteger(request.expected_generation) ||
    (request.expected_generation === 0) !== (request.expected_generation_checksum === null) ||
    !isNonEmptyString(request.committed_at) ||
    request.audit_ring.length === 0 ||
    !unique(request.retained_core_page_ids) ||
    !unique(request.retained_module_view_page_ids) ||
    !unique(request.core_pages.map((page) => page.page_id)) ||
    !unique(request.module_view_pages.map((page) => page.page_id))
  ) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Invalid Memory Book commit request");
  }
  assertModuleIndexes(request.module_views);
  for (const page of request.core_pages) {
    if (
      !isNonEmptyString(page.page_id) ||
      !unique(page.records.map((record) => record.record_id))
    ) {
      throw new TavernMemoryBookError("INVALID_INPUT", "Invalid Core page");
    }
  }
  for (const page of request.module_view_pages) {
    if (
      !isNonEmptyString(page.page_id) ||
      !TAVERN_MEMORY_MODULE_IDS.includes(page.module_id) ||
      page.items.length === 0 ||
      !unique(page.items.map((item) => item.record_id))
    ) {
      throw new TavernMemoryBookError("INVALID_INPUT", "Invalid module view page");
    }
  }
}

function asJsonValue(value: unknown): TavernJsonValue {
  return value as TavernJsonValue;
}

export class TavernMemoryBookStore {
  constructor(
    private readonly host: TavernHostPort,
    private readonly options: TavernMemoryBookOptions,
  ) {
    assertSafeOptions(options);
  }

  async initialize(): Promise<TavernMemoryBookReadResult> {
    if (!this.host.listWorldbooks().includes(this.options.book_name)) {
      await this.host.createWorldbook(this.options.book_name);
    }
    return this.readColdHead();
  }

  async readColdHead(): Promise<TavernMemoryBookReadResult> {
    if (!this.host.listWorldbooks().includes(this.options.book_name)) {
      return { status: "EMPTY", head: null, rejected_generations: [] };
    }
    const entries = await this.host.readWorldbook(this.options.book_name);
    const grouped = new Map<number, EncodedMemoryEntry[]>();
    const decodedEntries: EncodedMemoryEntry[] = [];
    const rejected = new Set<number>();
    for (const entry of entries) {
      const extra = entry.extra;
      if (
        isSafeMachineEntry(entry) &&
        isObject(extra) &&
        extra.narramem_format === TAVERN_MEMORY_BOOK_ENTRY_FORMAT &&
        extra.memory_set_id === this.options.memory_set_id &&
        isNonNegativeInteger(extra.generation) &&
        (extra.kind === "CORE_PAGE" || extra.kind === "MODULE_VIEW_PAGE") &&
        isNonEmptyString(extra.logical_id) &&
        isNonEmptyString(extra.payload_checksum) &&
        isNonEmptyString(extra.generation_checksum)
      ) {
        const encoded: EncodedMemoryEntry = {
          format: TAVERN_MEMORY_BOOK_ENTRY_FORMAT,
          schema_version: TAVERN_MEMORY_BOOK_VERSION,
          memory_set_id: this.options.memory_set_id,
          generation: extra.generation,
          kind: extra.kind,
          logical_id: extra.logical_id,
          payload: null,
          payload_checksum: extra.payload_checksum,
          generation_checksum: extra.generation_checksum,
        };
        const bucket = grouped.get(encoded.generation) ?? [];
        bucket.push(encoded);
        grouped.set(encoded.generation, bucket);
        decodedEntries.push(encoded);
        continue;
      }
      const raw = parseJson(entry.content);
      const generation =
        isObject(raw) && isNonNegativeInteger(raw.generation) ? raw.generation : null;
      if (!isSafeMachineEntry(entry) || !isObject(raw) || generation === null) {
        if (generation !== null) rejected.add(generation);
        continue;
      }
      const encoded = raw as unknown as EncodedMemoryEntry;
      if (
        encoded.format !== TAVERN_MEMORY_BOOK_ENTRY_FORMAT ||
        encoded.schema_version !== TAVERN_MEMORY_BOOK_VERSION ||
        encoded.memory_set_id !== this.options.memory_set_id ||
        !isNonEmptyString(encoded.logical_id) ||
        !isNonEmptyString(encoded.payload_checksum) ||
        !isNonEmptyString(encoded.generation_checksum)
      ) {
        rejected.add(generation);
        continue;
      }
      const bucket = grouped.get(generation) ?? [];
      bucket.push(encoded);
      grouped.set(generation, bucket);
      decodedEntries.push(encoded);
    }

    const generations = [...grouped.entries()]
      .filter(([generation, generationEntries]) => {
        const hasControl = generationEntries.some(
          (entry) => entry.kind === "CONTROL" && entry.logical_id === "CONTROL",
        );
        if (
          !hasControl &&
          generationEntries.some(
            (entry) => entry.kind !== "CORE_PAGE" && entry.kind !== "MODULE_VIEW_PAGE",
          )
        ) {
          rejected.add(generation);
        }
        return hasControl;
      })
      .map(([generation]) => generation)
      .sort((left, right) => left - right);
    const validHeads = new Map<number, TavernMemoryColdHead>();
    for (const generation of generations) {
      try {
        const head = await this.validateGeneration(
          generation,
          grouped.get(generation) ?? [],
          decodedEntries,
        );
        const previousHead = [...validHeads.values()].at(-1);
        const expectedPrevious = previousHead?.generation_checksum ?? null;
        if (
          (head.chain_root && head.previous_generation_checksum !== null) ||
          (!head.chain_root && head.previous_generation_checksum !== expectedPrevious)
        ) {
          rejected.add(generation);
          continue;
        }
        validHeads.set(generation, head);
      } catch {
        rejected.add(generation);
      }
    }
    const latestGeneration = [...validHeads.keys()].sort((left, right) => right - left)[0];
    const latestHead =
      latestGeneration === undefined ? undefined : validHeads.get(latestGeneration);
    if (latestHead !== undefined) {
      return {
        status: "READY",
        head: latestHead,
        rejected_generations: [...rejected].sort((left, right) => left - right),
      };
    }
    return {
      status: "EMPTY",
      head: null,
      rejected_generations: [...rejected].sort((left, right) => left - right),
    };
  }

  async commit(request: TavernMemoryBookCommitRequest): Promise<TavernMemoryColdHead> {
    assertCommitRequest(request);
    const operation = async (): Promise<TavernMemoryColdHead> => {
      await this.initialize();
      const current = await this.readColdHead();
      const currentGeneration = current.head?.generation ?? 0;
      const currentChecksum = current.head?.generation_checksum ?? null;
      const commitPayloadChecksum = await checksumJson({
        commit_id: request.commit_id,
        committed_at: request.committed_at,
        source_index: request.source_index,
        work_state: request.work_state,
        checkpoint_index: request.checkpoint_index,
        active_state: request.active_state,
        epistemic_state: request.epistemic_state,
        thread_impact: request.thread_impact,
        module_views: request.module_views,
        audit_ring: request.audit_ring,
        retained_core_page_ids: request.retained_core_page_ids,
        retained_module_view_page_ids: request.retained_module_view_page_ids,
        core_pages: request.core_pages,
        module_view_pages: request.module_view_pages,
      });
      if (
        current.head?.commit_id === request.commit_id &&
        current.head.generation === request.expected_generation + 1 &&
        current.head.previous_generation_checksum === request.expected_generation_checksum
      ) {
        if (current.head.commit_payload_checksum !== commitPayloadChecksum) {
          throw new TavernMemoryBookError(
            "WRITE_CONFLICT",
            `Commit id ${request.commit_id} was reused with different content`,
          );
        }
        return current.head;
      }
      if (
        currentGeneration !== request.expected_generation ||
        currentChecksum !== request.expected_generation_checksum
      ) {
        throw new TavernMemoryBookError(
          "STALE_GENERATION",
          `Expected generation ${request.expected_generation}, found ${currentGeneration}`,
        );
      }

      const generation = currentGeneration + 1;
      const auditRing = request.audit_ring.slice(-this.options.max_audit_items);
      const retainedCoreRefs = request.retained_core_page_ids.map((pageId) => {
        const ref = current.head?.core_page_refs.find((candidate) => candidate.page_id === pageId);
        if (ref === undefined) {
          throw new TavernMemoryBookError(
            "INVALID_INPUT",
            `Cannot retain missing Core page ${pageId}`,
          );
        }
        return ref;
      });
      const retainedViewRefs = request.retained_module_view_page_ids.map((pageId) => {
        const ref = current.head?.module_view_page_refs.find(
          (candidate) => candidate.page_id === pageId,
        );
        if (ref === undefined) {
          throw new TavernMemoryBookError(
            "INVALID_INPUT",
            `Cannot retain missing view page ${pageId}`,
          );
        }
        return ref;
      });
      const existingPageIds = new Set(
        (await this.host.readWorldbook(this.options.book_name))
          .map((entry) => parseJson(entry.content))
          .filter(
            (raw): raw is EncodedMemoryEntry =>
              isObject(raw) &&
              raw.format === TAVERN_MEMORY_BOOK_ENTRY_FORMAT &&
              (raw.kind === "CORE_PAGE" || raw.kind === "MODULE_VIEW_PAGE") &&
              typeof raw.logical_id === "string",
          )
          .map((entry) => entry.logical_id),
      );
      for (const pageId of [
        ...request.core_pages.map((page) => page.page_id),
        ...request.module_view_pages.map((page) => page.page_id),
      ]) {
        if (existingPageIds.has(pageId)) {
          throw new TavernMemoryBookError(
            "WRITE_CONFLICT",
            `Immutable page id ${pageId} already exists`,
          );
        }
      }
      const newPagePayloads = await Promise.all([
        ...request.core_pages.map((page) => preparePayload("CORE_PAGE", page.page_id, page)),
        ...request.module_view_pages.map((page) =>
          preparePayload("MODULE_VIEW_PAGE", page.page_id, page),
        ),
      ]);
      const newCoreRefs = newPagePayloads
        .filter((item) => item.kind === "CORE_PAGE")
        .map((item) => ({
          page_id: item.logical_id,
          payload_checksum: item.payload_checksum,
          created_generation: generation,
        }));
      const newViewRefs = newPagePayloads
        .filter((item) => item.kind === "MODULE_VIEW_PAGE")
        .map((item) => ({
          page_id: item.logical_id,
          payload_checksum: item.payload_checksum,
          created_generation: generation,
        }));
      const corePageRefs = [...retainedCoreRefs, ...newCoreRefs];
      const moduleViewPageRefs = [...retainedViewRefs, ...newViewRefs];
      const retainedViewPages = await Promise.all(
        request.retained_module_view_page_ids.map((pageId) => this.readModuleViewPage(pageId)),
      );
      assertViewPageTopology(
        request.module_views,
        [...retainedViewPages, ...request.module_view_pages],
        new Set(corePageRefs.map((ref) => ref.page_id)),
        "INVALID_INPUT",
      );
      if (
        request.checkpoint_index.core_page_ids.some(
          (pageId) => !corePageRefs.some((ref) => ref.page_id === pageId),
        )
      ) {
        throw new TavernMemoryBookError(
          "INVALID_INPUT",
          "Checkpoint references a Core page that is not retained by the new head",
        );
      }
      const prepared = await Promise.all([
        preparePayload("CONTROL", "CONTROL", {
          chain_root: generation === 1,
          commit_id: request.commit_id,
          commit_payload_checksum: commitPayloadChecksum,
          previous_generation_checksum: currentChecksum,
          committed_at: request.committed_at,
          core_page_refs: corePageRefs,
          module_view_page_refs: moduleViewPageRefs,
        } satisfies ControlPayload),
        preparePayload("SOURCE_INDEX", "SOURCE_INDEX", request.source_index),
        preparePayload("WORK_STATE", "WORK_STATE", request.work_state),
        preparePayload("CHECKPOINT_INDEX", "CHECKPOINT_INDEX", request.checkpoint_index),
        preparePayload("ACTIVE_STATE", "ACTIVE_STATE", request.active_state),
        preparePayload("EPISTEMIC_STATE", "EPISTEMIC_STATE", request.epistemic_state),
        preparePayload("THREAD_IMPACT", "THREAD_IMPACT", request.thread_impact),
        ...TAVERN_MEMORY_MODULE_IDS.map((moduleId) =>
          preparePayload("MODULE_VIEW_INDEX", moduleId, request.module_views[moduleId]),
        ),
        preparePayload("AUDIT_RING", "AUDIT_RING", auditRing),
      ]);
      const appended = [...prepared, ...newPagePayloads];
      const fixedKinds = new Set<MemoryEntryKind>([
        "CONTROL",
        "SOURCE_INDEX",
        "WORK_STATE",
        "CHECKPOINT_INDEX",
        "ACTIVE_STATE",
        "EPISTEMIC_STATE",
        "THREAD_IMPACT",
        "MODULE_VIEW_INDEX",
        "AUDIT_RING",
      ]);
      const coldHeadBytes = prepared
        .filter((item) => fixedKinds.has(item.kind))
        .reduce((sum, item) => sum + utf8ByteLength(canonicalJson(item.payload)), 0);
      if (coldHeadBytes > this.options.max_cold_head_utf8_bytes) {
        throw new TavernMemoryBookError(
          "HEAD_TOO_LARGE",
          `Cold head is ${coldHeadBytes} bytes, limit ${this.options.max_cold_head_utf8_bytes}`,
        );
      }
      for (const item of newPagePayloads) {
        const bytes = utf8ByteLength(canonicalJson(item.payload));
        if (bytes > this.options.max_core_page_utf8_bytes) {
          throw new TavernMemoryBookError(
            "PAGE_TOO_LARGE",
            `${item.logical_id} is ${bytes} bytes, limit ${this.options.max_core_page_utf8_bytes}`,
          );
        }
      }
      const manifest = appended
        .map((item) => ({
          kind: item.kind,
          logical_id: item.logical_id,
          payload_checksum: item.payload_checksum,
        }))
        .sort((left, right) =>
          `${left.kind}\u0000${left.logical_id}`.localeCompare(
            `${right.kind}\u0000${right.logical_id}`,
          ),
        );
      const generationChecksum = await checksumJson({
        memory_set_id: this.options.memory_set_id,
        generation,
        previous_generation_checksum: currentChecksum,
        committed_at: request.committed_at,
        active_page_refs: [...corePageRefs, ...moduleViewPageRefs],
        entries: manifest,
      });
      const drafts = appended.map((item) => {
        const encoded: EncodedMemoryEntry = {
          format: TAVERN_MEMORY_BOOK_ENTRY_FORMAT,
          schema_version: TAVERN_MEMORY_BOOK_VERSION,
          memory_set_id: this.options.memory_set_id,
          generation,
          kind: item.kind,
          logical_id: item.logical_id,
          payload: item.payload,
          payload_checksum: item.payload_checksum,
          generation_checksum: generationChecksum,
        };
        return machineEntryDraft(
          `NarraMem__MEMORY_ENTRY__g${generation}__${item.kind}__${item.logical_id}`,
          canonicalJson(encoded),
          {
            narramem_format: TAVERN_MEMORY_BOOK_ENTRY_FORMAT,
            memory_set_id: this.options.memory_set_id,
            generation,
            kind: item.kind,
            logical_id: item.logical_id,
            payload_checksum: item.payload_checksum,
            generation_checksum: generationChecksum,
          },
        );
      });
      await this.host.appendWorldbookEntries(this.options.book_name, drafts);
      const verified = await this.readColdHead();
      if (
        verified.head?.generation !== generation ||
        verified.head.generation_checksum !== generationChecksum
      ) {
        throw new TavernMemoryBookError("VERIFY_FAILED", `Generation ${generation} did not verify`);
      }
      return verified.head;
    };
    return this.host.withWorldbookExclusiveLock === undefined
      ? operation()
      : this.host.withWorldbookExclusiveLock(this.options.book_name, operation);
  }

  async compact(
    request: TavernMemoryBookCompactionRequest,
  ): Promise<TavernMemoryBookCompactionResult> {
    if (
      !isNonEmptyString(request.operation_id) ||
      !isNonNegativeInteger(request.expected_generation) ||
      !isNonEmptyString(request.expected_generation_checksum) ||
      !isNonEmptyString(request.compacted_at)
    ) {
      throw new TavernMemoryBookError("INVALID_INPUT", "Invalid Memory Book compaction request");
    }
    const operation = async (): Promise<TavernMemoryBookCompactionResult> => {
      let current = await this.readColdHead();
      if (current.head === null) {
        throw new TavernMemoryBookError("BOOK_NOT_FOUND", "Memory Book has no valid generation");
      }
      const commitId = `compaction:${request.operation_id}`;
      let compactedHead = current.head;
      if (!(compactedHead.chain_root && compactedHead.commit_id === commitId)) {
        if (
          compactedHead.generation !== request.expected_generation ||
          compactedHead.generation_checksum !== request.expected_generation_checksum
        ) {
          throw new TavernMemoryBookError(
            "STALE_GENERATION",
            "Memory Book changed before compaction",
          );
        }

        const corePages = await Promise.all(
          compactedHead.core_page_ids.map((pageId) => this.readCorePage(pageId)),
        );
        const viewPages = await Promise.all(
          compactedHead.module_view_page_ids.map((pageId) => this.readModuleViewPage(pageId)),
        );
        assertViewPageTopology(
          compactedHead.module_views,
          viewPages,
          new Set(corePages.map((page) => page.page_id)),
          "BOOK_CORRUPT",
        );

        const generation = compactedHead.generation + 1;
        const commitPayloadChecksum = await checksumJson({
          operation_id: request.operation_id,
          compacted_at: request.compacted_at,
          source_generation: compactedHead.generation,
          source_generation_checksum: compactedHead.generation_checksum,
        });
        const prepared = await Promise.all([
          preparePayload("CONTROL", "CONTROL", {
            chain_root: true,
            commit_id: commitId,
            commit_payload_checksum: commitPayloadChecksum,
            previous_generation_checksum: null,
            committed_at: request.compacted_at,
            core_page_refs: compactedHead.core_page_refs,
            module_view_page_refs: compactedHead.module_view_page_refs,
          } satisfies ControlPayload),
          preparePayload("SOURCE_INDEX", "SOURCE_INDEX", compactedHead.source_index),
          preparePayload("WORK_STATE", "WORK_STATE", compactedHead.work_state),
          preparePayload("CHECKPOINT_INDEX", "CHECKPOINT_INDEX", compactedHead.checkpoint_index),
          preparePayload("ACTIVE_STATE", "ACTIVE_STATE", compactedHead.active_state),
          preparePayload("EPISTEMIC_STATE", "EPISTEMIC_STATE", compactedHead.epistemic_state),
          preparePayload("THREAD_IMPACT", "THREAD_IMPACT", compactedHead.thread_impact),
          ...TAVERN_MEMORY_MODULE_IDS.map((moduleId) =>
            preparePayload("MODULE_VIEW_INDEX", moduleId, compactedHead.module_views[moduleId]),
          ),
          preparePayload("AUDIT_RING", "AUDIT_RING", compactedHead.audit_ring),
        ]);
        const manifest = prepared
          .map((item) => ({
            kind: item.kind,
            logical_id: item.logical_id,
            payload_checksum: item.payload_checksum,
          }))
          .sort((left, right) =>
            `${left.kind}\u0000${left.logical_id}`.localeCompare(
              `${right.kind}\u0000${right.logical_id}`,
            ),
          );
        const generationChecksum = await checksumJson({
          memory_set_id: this.options.memory_set_id,
          generation,
          previous_generation_checksum: null,
          committed_at: request.compacted_at,
          active_page_refs: [
            ...compactedHead.core_page_refs,
            ...compactedHead.module_view_page_refs,
          ],
          entries: manifest,
        });
        const drafts = prepared.map((item) => {
          const encoded: EncodedMemoryEntry = {
            format: TAVERN_MEMORY_BOOK_ENTRY_FORMAT,
            schema_version: TAVERN_MEMORY_BOOK_VERSION,
            memory_set_id: this.options.memory_set_id,
            generation,
            kind: item.kind,
            logical_id: item.logical_id,
            payload: item.payload,
            payload_checksum: item.payload_checksum,
            generation_checksum: generationChecksum,
          };
          return machineEntryDraft(
            `NarraMem__MEMORY_ENTRY__g${generation}__${item.kind}__${item.logical_id}`,
            canonicalJson(encoded),
            {
              narramem_format: TAVERN_MEMORY_BOOK_ENTRY_FORMAT,
              memory_set_id: this.options.memory_set_id,
              generation,
              kind: item.kind,
              logical_id: item.logical_id,
              payload_checksum: item.payload_checksum,
              generation_checksum: generationChecksum,
            },
          );
        });
        await this.host.appendWorldbookEntries(this.options.book_name, drafts);
        current = await this.readColdHead();
        if (
          current.head?.generation !== generation ||
          current.head.generation_checksum !== generationChecksum ||
          !current.head.chain_root
        ) {
          throw new TavernMemoryBookError("VERIFY_FAILED", "Compaction root did not verify");
        }
        compactedHead = current.head;
      }

      const entriesBeforeCleanup = await this.host.readWorldbook(this.options.book_name);
      const activePageKeys = new Set(
        [
          ...compactedHead.core_page_refs.map((ref) => ({ kind: "CORE_PAGE" as const, ref })),
          ...compactedHead.module_view_page_refs.map((ref) => ({
            kind: "MODULE_VIEW_PAGE" as const,
            ref,
          })),
        ].map(
          ({ kind, ref }) =>
            `${kind}\u0000${ref.created_generation}\u0000${ref.page_id}\u0000${ref.payload_checksum}`,
        ),
      );
      const retainedEntries = entriesBeforeCleanup.filter((entry) => {
        const extra = entry.extra;
        const owned =
          isObject(extra) &&
          extra.narramem_format === TAVERN_MEMORY_BOOK_ENTRY_FORMAT &&
          extra.memory_set_id === this.options.memory_set_id;
        if (!owned) return true;
        if (extra.kind === "CORE_PAGE" || extra.kind === "MODULE_VIEW_PAGE") {
          return activePageKeys.has(
            `${extra.kind}\u0000${extra.generation}\u0000${extra.logical_id}\u0000${extra.payload_checksum}`,
          );
        }
        return (
          extra.generation === compactedHead.generation &&
          extra.generation_checksum === compactedHead.generation_checksum
        );
      });
      await this.host.replaceWorldbook(this.options.book_name, retainedEntries);
      const verified = await this.readColdHead();
      if (
        verified.head?.generation !== compactedHead.generation ||
        verified.head.generation_checksum !== compactedHead.generation_checksum ||
        !verified.head.chain_root
      ) {
        throw new TavernMemoryBookError("VERIFY_FAILED", "Compacted Memory Book did not verify");
      }
      return {
        head: verified.head,
        entries_before: entriesBeforeCleanup.length,
        entries_after: retainedEntries.length,
        removed_entries: entriesBeforeCleanup.length - retainedEntries.length,
      };
    };
    return this.host.withWorldbookExclusiveLock === undefined
      ? operation()
      : this.host.withWorldbookExclusiveLock(this.options.book_name, operation);
  }

  async readCorePage(pageId: string): Promise<TavernMemoryCorePage> {
    const payload = await this.readLatestPage("CORE_PAGE", pageId);
    return payload as unknown as TavernMemoryCorePage;
  }

  async readModuleViewPage(pageId: string): Promise<TavernMemoryModuleViewPage> {
    const payload = await this.readLatestPage("MODULE_VIEW_PAGE", pageId);
    return payload as unknown as TavernMemoryModuleViewPage;
  }

  private async readLatestPage(
    kind: "CORE_PAGE" | "MODULE_VIEW_PAGE",
    logicalId: string,
  ): Promise<unknown> {
    const current = await this.readColdHead();
    if (current.head === null) {
      throw new TavernMemoryBookError("BOOK_NOT_FOUND", "Memory Book has no valid generation");
    }
    const ref = (
      kind === "CORE_PAGE" ? current.head.core_page_refs : current.head.module_view_page_refs
    ).find((candidate) => candidate.page_id === logicalId);
    if (ref === undefined) {
      throw new TavernMemoryBookError("BOOK_NOT_FOUND", `${kind} ${logicalId} is not active`);
    }
    const entries = await this.host.readWorldbook(this.options.book_name);
    const matchingEntries = entries.filter(
      (entry) =>
        isSafeMachineEntry(entry) &&
        isObject(entry.extra) &&
        entry.extra.narramem_format === TAVERN_MEMORY_BOOK_ENTRY_FORMAT &&
        entry.extra.memory_set_id === this.options.memory_set_id &&
        entry.extra.generation === ref.created_generation &&
        entry.extra.kind === kind &&
        entry.extra.logical_id === logicalId &&
        entry.extra.payload_checksum === ref.payload_checksum,
    );
    const raw = matchingEntries[0] === undefined ? null : parseJson(matchingEntries[0].content);
    const match = isObject(raw) ? (raw as unknown as EncodedMemoryEntry) : null;
    if (
      matchingEntries.length !== 1 ||
      match === null ||
      match.format !== TAVERN_MEMORY_BOOK_ENTRY_FORMAT ||
      match.schema_version !== TAVERN_MEMORY_BOOK_VERSION ||
      match.memory_set_id !== this.options.memory_set_id ||
      match.generation !== ref.created_generation ||
      match.kind !== kind ||
      match.logical_id !== logicalId ||
      match.payload_checksum !== ref.payload_checksum ||
      (await checksumJson(match.payload)) !== match.payload_checksum
    ) {
      throw new TavernMemoryBookError("BOOK_CORRUPT", `${kind} ${logicalId} is unavailable`);
    }
    return match.payload;
  }

  private async validateGeneration(
    generation: number,
    entries: readonly EncodedMemoryEntry[],
    allEntries: readonly EncodedMemoryEntry[],
  ): Promise<TavernMemoryColdHead> {
    const keys = entries.map((entry) => `${entry.kind}\u0000${entry.logical_id}`);
    if (!unique(keys))
      throw new TavernMemoryBookError("WRITE_CONFLICT", "Duplicate generation entries");
    const checksums = new Set(entries.map((entry) => entry.generation_checksum));
    if (checksums.size !== 1) {
      throw new TavernMemoryBookError("WRITE_CONFLICT", "Conflicting generation checksums");
    }
    for (const entry of entries) {
      if (entry.kind === "CORE_PAGE" || entry.kind === "MODULE_VIEW_PAGE") continue;
      if ((await checksumJson(entry.payload)) !== entry.payload_checksum) {
        throw new TavernMemoryBookError("BOOK_CORRUPT", "Entry payload checksum mismatch");
      }
    }
    const byKey = new Map(keys.map((key, index) => [key, entries[index]] as const));
    const get = (kind: MemoryEntryKind, logicalId: string): EncodedMemoryEntry => {
      const entry = byKey.get(`${kind}\u0000${logicalId}`);
      if (entry === undefined) {
        throw new TavernMemoryBookError("BOOK_CORRUPT", `Missing ${kind}/${logicalId}`);
      }
      return entry;
    };
    const control = get("CONTROL", "CONTROL").payload;
    if (
      !isObject(control) ||
      !(
        control.previous_generation_checksum === null ||
        isNonEmptyString(control.previous_generation_checksum)
      ) ||
      !isNonEmptyString(control.committed_at) ||
      typeof control.chain_root !== "boolean" ||
      !isNonEmptyString(control.commit_id) ||
      !isNonEmptyString(control.commit_payload_checksum) ||
      !Array.isArray(control.core_page_refs) ||
      !Array.isArray(control.module_view_page_refs)
    ) {
      throw new TavernMemoryBookError("BOOK_CORRUPT", "Invalid CONTROL payload");
    }
    const assertRefs = (
      refs: readonly unknown[],
      kind: "CORE_PAGE" | "MODULE_VIEW_PAGE",
    ): { readonly refs: TavernMemoryPageRef[]; readonly pages: EncodedMemoryEntry[] } => {
      const typedRefs = refs as unknown as TavernMemoryPageRef[];
      if (
        !unique(typedRefs.map((ref) => ref.page_id)) ||
        typedRefs.some(
          (ref) =>
            !isObject(ref) ||
            !isNonEmptyString(ref.page_id) ||
            !isNonEmptyString(ref.payload_checksum) ||
            !isNonNegativeInteger(ref.created_generation) ||
            ref.created_generation > generation,
        )
      ) {
        throw new TavernMemoryBookError("BOOK_CORRUPT", `Invalid ${kind} references`);
      }
      const pages = typedRefs.map((ref) => {
        const matches = allEntries.filter(
          (entry) =>
            entry.kind === kind &&
            entry.logical_id === ref.page_id &&
            entry.generation === ref.created_generation &&
            entry.payload_checksum === ref.payload_checksum,
        );
        if (matches.length !== 1) {
          throw new TavernMemoryBookError("BOOK_CORRUPT", `Missing immutable page ${ref.page_id}`);
        }
        const match = matches[0];
        if (match === undefined) {
          throw new TavernMemoryBookError("BOOK_CORRUPT", `Missing immutable page ${ref.page_id}`);
        }
        return match;
      });
      return { refs: typedRefs, pages };
    };
    const coreResolved = assertRefs(control.core_page_refs, "CORE_PAGE");
    const viewResolved = assertRefs(control.module_view_page_refs, "MODULE_VIEW_PAGE");
    const moduleViews = Object.fromEntries(
      TAVERN_MEMORY_MODULE_IDS.map((moduleId) => [
        moduleId,
        get("MODULE_VIEW_INDEX", moduleId).payload,
      ]),
    ) as unknown as Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
    assertModuleIndexes(moduleViews);
    const corePages = coreResolved.refs.map((ref) => ref.page_id);
    const moduleViewPages = viewResolved.refs.map((ref) => ref.page_id);
    const manifest = entries
      .map((entry) => ({
        kind: entry.kind,
        logical_id: entry.logical_id,
        payload_checksum: entry.payload_checksum,
      }))
      .sort((left, right) =>
        `${left.kind}\u0000${left.logical_id}`.localeCompare(
          `${right.kind}\u0000${right.logical_id}`,
        ),
      );
    const expectedGenerationChecksum = await checksumJson({
      memory_set_id: this.options.memory_set_id,
      generation,
      previous_generation_checksum: control.previous_generation_checksum,
      committed_at: control.committed_at,
      active_page_refs: [...coreResolved.refs, ...viewResolved.refs],
      entries: manifest,
    });
    const generationChecksum = entries[0]?.generation_checksum;
    if (generationChecksum === undefined || generationChecksum !== expectedGenerationChecksum) {
      throw new TavernMemoryBookError("BOOK_CORRUPT", "Generation checksum mismatch");
    }
    const checkpoint = get("CHECKPOINT_INDEX", "CHECKPOINT_INDEX").payload;
    if (!isObject(checkpoint) || !Array.isArray(checkpoint.core_page_ids)) {
      throw new TavernMemoryBookError("BOOK_CORRUPT", "Invalid checkpoint index");
    }
    if (
      !checkpoint.core_page_ids.every(
        (pageId) => typeof pageId === "string" && corePages.includes(pageId),
      )
    ) {
      throw new TavernMemoryBookError("BOOK_CORRUPT", "Checkpoint references a missing Core page");
    }
    const head: TavernMemoryColdHead = {
      memory_set_id: this.options.memory_set_id,
      chain_root: control.chain_root,
      commit_id: control.commit_id as string,
      commit_payload_checksum: control.commit_payload_checksum as string,
      generation,
      generation_checksum: generationChecksum,
      previous_generation_checksum: control.previous_generation_checksum as string | null,
      committed_at: control.committed_at as string,
      source_index: get("SOURCE_INDEX", "SOURCE_INDEX")
        .payload as TavernMemoryColdHead["source_index"],
      work_state: get("WORK_STATE", "WORK_STATE").payload as TavernMemoryColdHead["work_state"],
      checkpoint_index: checkpoint as unknown as TavernMemoryColdHead["checkpoint_index"],
      active_state: asJsonValue(get("ACTIVE_STATE", "ACTIVE_STATE").payload),
      epistemic_state: asJsonValue(get("EPISTEMIC_STATE", "EPISTEMIC_STATE").payload),
      thread_impact: asJsonValue(get("THREAD_IMPACT", "THREAD_IMPACT").payload),
      module_views: moduleViews,
      audit_ring: get("AUDIT_RING", "AUDIT_RING").payload as TavernMemoryColdHead["audit_ring"],
      core_page_ids: corePages,
      module_view_page_ids: moduleViewPages,
      core_page_refs: coreResolved.refs,
      module_view_page_refs: viewResolved.refs,
    };
    if (
      utf8ByteLength(canonicalJson({ ...head, core_page_ids: [], module_view_page_ids: [] })) >
      this.options.max_cold_head_utf8_bytes
    ) {
      throw new TavernMemoryBookError(
        "HEAD_TOO_LARGE",
        "Stored cold head exceeds configured limit",
      );
    }
    return head;
  }
}

function registryKey(record: TavernMemoryRegistryRecord): string {
  return `${record.host_user_id}\u0000${record.chat_id}\u0000${record.character_or_group_id}`;
}

function assertRegistryRecords(records: readonly TavernMemoryRegistryRecord[]): void {
  const keys = records.map(registryKey);
  if (!unique(keys))
    throw new TavernMemoryBookError("REGISTRY_COLLISION", "Duplicate chat identity");
  const memorySets = records.map((record) => record.memory_set_id);
  const bookNames = records.map((record) => record.memory_book_name);
  if (!unique(memorySets) || !unique(bookNames)) {
    throw new TavernMemoryBookError(
      "REGISTRY_COLLISION",
      "A Memory Book cannot belong to two chats",
    );
  }
  for (const record of records) {
    if (
      (record.status !== "ACTIVE" && record.status !== "DELETE_PENDING") ||
      !isNonEmptyString(record.host_user_id) ||
      !isNonEmptyString(record.chat_id) ||
      !isNonEmptyString(record.character_or_group_id) ||
      !isNonEmptyString(record.memory_set_id) ||
      !isNonEmptyString(record.memory_book_name) ||
      !isNonEmptyString(record.chat_anchor_hash)
    ) {
      throw new TavernMemoryBookError("INVALID_INPUT", "Invalid Registry record");
    }
  }
}

export class TavernMemoryRegistryStore {
  constructor(
    private readonly host: TavernHostPort,
    private readonly bookName = TAVERN_MEMORY_REGISTRY_BOOK_NAME,
  ) {}

  async initialize(): Promise<TavernMemoryRegistrySnapshot> {
    if (!this.host.listWorldbooks().includes(this.bookName))
      await this.host.createWorldbook(this.bookName);
    return (
      (await this.readLatest()) ?? {
        generation: 0,
        mutation_id: null,
        previous_generation_checksum: null,
        records: [],
        checksum: await checksumJson({
          generation: 0,
          mutation_id: null,
          previous_generation_checksum: null,
          records: [],
        }),
      }
    );
  }

  async readLatest(): Promise<TavernMemoryRegistrySnapshot | null> {
    if (!this.host.listWorldbooks().includes(this.bookName)) return null;
    const candidates: TavernMemoryRegistrySnapshot[] = [];
    for (const entry of await this.host.readWorldbook(this.bookName)) {
      const raw = parseJson(entry.content);
      if (
        !isSafeMachineEntry(entry) ||
        !isObject(raw) ||
        raw.format !== TAVERN_MEMORY_REGISTRY_FORMAT ||
        raw.schema_version !== TAVERN_MEMORY_REGISTRY_VERSION ||
        !isNonNegativeInteger(raw.generation) ||
        !isNonEmptyString(raw.mutation_id) ||
        !(
          raw.previous_generation_checksum === null ||
          isNonEmptyString(raw.previous_generation_checksum)
        ) ||
        !Array.isArray(raw.records) ||
        !isNonEmptyString(raw.checksum)
      ) {
        continue;
      }
      const unsigned = {
        generation: raw.generation,
        mutation_id: raw.mutation_id,
        previous_generation_checksum: raw.previous_generation_checksum,
        records: raw.records,
      };
      if ((await checksumJson(unsigned)) !== raw.checksum) continue;
      try {
        assertRegistryRecords(raw.records as unknown as readonly TavernMemoryRegistryRecord[]);
      } catch {
        continue;
      }
      candidates.push({ ...unsigned, checksum: raw.checksum } as TavernMemoryRegistrySnapshot);
    }
    const byGeneration = new Map<number, TavernMemoryRegistrySnapshot[]>();
    for (const candidate of candidates) {
      const bucket = byGeneration.get(candidate.generation) ?? [];
      bucket.push(candidate);
      byGeneration.set(candidate.generation, bucket);
    }
    const valid = new Map<number, TavernMemoryRegistrySnapshot>();
    for (const generation of [...byGeneration.keys()].sort((left, right) => left - right)) {
      const bucket = byGeneration.get(generation) ?? [];
      if (bucket.length !== 1) {
        throw new TavernMemoryBookError(
          "WRITE_CONFLICT",
          `Registry generation ${generation} has conflicting heads`,
        );
      }
      const candidate = bucket[0];
      if (candidate === undefined) continue;
      const expectedPrevious = generation === 1 ? null : valid.get(generation - 1)?.checksum;
      if (
        expectedPrevious === undefined ||
        candidate.previous_generation_checksum !== expectedPrevious
      ) {
        continue;
      }
      valid.set(generation, candidate);
    }
    const latestGeneration = [...valid.keys()].sort((left, right) => right - left)[0];
    return latestGeneration === undefined ? null : (valid.get(latestGeneration) ?? null);
  }

  async write(request: TavernMemoryRegistryWriteRequest): Promise<TavernMemoryRegistrySnapshot> {
    if (!isNonEmptyString(request.mutation_id)) {
      throw new TavernMemoryBookError("INVALID_INPUT", "Registry mutation_id is required");
    }
    assertRegistryRecords(request.records);
    const operation = async (): Promise<TavernMemoryRegistrySnapshot> => {
      const current = await this.initialize();
      if (
        current.mutation_id === request.mutation_id &&
        current.generation === request.expected_generation + 1 &&
        current.previous_generation_checksum === request.expected_checksum
      ) {
        const expectedRecords = [...request.records].sort((left, right) =>
          registryKey(left).localeCompare(registryKey(right)),
        );
        if (canonicalJson(current.records) !== canonicalJson(expectedRecords)) {
          throw new TavernMemoryBookError(
            "WRITE_CONFLICT",
            `Registry mutation id ${request.mutation_id} was reused with different content`,
          );
        }
        return current;
      }
      if (
        current.generation !== request.expected_generation ||
        (current.generation === 0
          ? request.expected_checksum !== null
          : current.checksum !== request.expected_checksum)
      ) {
        throw new TavernMemoryBookError("STALE_GENERATION", "Registry base changed");
      }
      const unsigned = {
        generation: current.generation + 1,
        mutation_id: request.mutation_id,
        previous_generation_checksum: current.generation === 0 ? null : current.checksum,
        records: [...request.records].sort((left, right) =>
          registryKey(left).localeCompare(registryKey(right)),
        ),
      };
      const next: TavernMemoryRegistrySnapshot = {
        ...unsigned,
        checksum: await checksumJson(unsigned),
      };
      const encoded: EncodedRegistryEntry = {
        format: TAVERN_MEMORY_REGISTRY_FORMAT,
        schema_version: TAVERN_MEMORY_REGISTRY_VERSION,
        ...next,
      };
      await this.host.appendWorldbookEntries(this.bookName, [
        machineEntryDraft(`NarraMem__REGISTRY__g${next.generation}`, canonicalJson(encoded), {
          narramem_format: TAVERN_MEMORY_REGISTRY_FORMAT,
          generation: next.generation,
        }),
      ]);
      const verified = await this.readLatest();
      if (verified?.checksum !== next.checksum) {
        throw new TavernMemoryBookError("VERIFY_FAILED", "Registry generation did not verify");
      }
      return verified;
    };
    return this.host.withWorldbookExclusiveLock === undefined
      ? operation()
      : this.host.withWorldbookExclusiveLock(this.bookName, operation);
  }

  async upsert(
    record: TavernMemoryRegistryRecord,
    mutationId: string,
  ): Promise<TavernMemoryRegistrySnapshot> {
    if (record.status !== "ACTIVE") {
      throw new TavernMemoryBookError("INVALID_INPUT", "Only ACTIVE records can be upserted");
    }
    const current = await this.initialize();
    if (current.mutation_id === mutationId) {
      const existing = current.records.find((item) => registryKey(item) === registryKey(record));
      if (existing === undefined || canonicalJson(existing) !== canonicalJson(record)) {
        throw new TavernMemoryBookError(
          "WRITE_CONFLICT",
          `Registry mutation id ${mutationId} was reused with different content`,
        );
      }
      return current;
    }
    const key = registryKey(record);
    const records = [...current.records.filter((item) => registryKey(item) !== key), record];
    return this.write({
      mutation_id: mutationId,
      expected_generation: current.generation,
      expected_checksum: current.generation === 0 ? null : current.checksum,
      records,
    });
  }

  async deleteChat(input: {
    readonly host_user_id: string;
    readonly chat_id: string;
    readonly character_or_group_id?: string;
  }): Promise<{
    readonly status: "DELETED" | "ALREADY_DELETED";
    readonly removed: TavernMemoryRegistryRecord | null;
    readonly snapshot: TavernMemoryRegistrySnapshot;
  }> {
    let current = await this.initialize();
    const matches = current.records.filter(
      (record) =>
        record.host_user_id === input.host_user_id &&
        record.chat_id === input.chat_id &&
        (input.character_or_group_id === undefined ||
          record.character_or_group_id === input.character_or_group_id),
    );
    if (matches.length === 0) {
      return { status: "ALREADY_DELETED", removed: null, snapshot: current };
    }
    if (matches.length !== 1) {
      throw new TavernMemoryBookError(
        "REGISTRY_COLLISION",
        `Chat deletion requires exactly one Registry match, found ${matches.length}`,
      );
    }
    const match = matches[0];
    if (match === undefined) {
      throw new TavernMemoryBookError("REGISTRY_COLLISION", "Chat deletion target disappeared");
    }
    if (match.status === "ACTIVE") {
      current = await this.write({
        mutation_id: `delete_prepare:${match.memory_set_id}:${current.checksum}`,
        expected_generation: current.generation,
        expected_checksum: current.checksum,
        records: current.records.map((record) =>
          registryKey(record) === registryKey(match)
            ? { ...record, status: "DELETE_PENDING" as const }
            : record,
        ),
      });
    }
    if (this.host.listWorldbooks().includes(match.memory_book_name)) {
      const deleted = await this.host.deleteWorldbook(match.memory_book_name);
      if (!deleted || this.host.listWorldbooks().includes(match.memory_book_name)) {
        throw new TavernMemoryBookError(
          "DELETE_FAILED",
          `Memory Book ${match.memory_book_name} remains DELETE_PENDING`,
        );
      }
    }
    const snapshot = await this.write({
      mutation_id: `delete_complete:${match.memory_set_id}:${current.checksum}`,
      expected_generation: current.generation,
      expected_checksum: current.checksum,
      records: current.records.filter((record) => registryKey(record) !== registryKey(match)),
    });
    return { status: "DELETED", removed: match, snapshot };
  }

  async resumePendingDeletions(): Promise<readonly TavernMemoryRegistryRecord[]> {
    const pending = (await this.initialize()).records.filter(
      (record) => record.status === "DELETE_PENDING",
    );
    const completed: TavernMemoryRegistryRecord[] = [];
    for (const record of pending) {
      const result = await this.deleteChat({
        host_user_id: record.host_user_id,
        chat_id: record.chat_id,
        character_or_group_id: record.character_or_group_id,
      });
      if (result.removed !== null) completed.push(result.removed);
    }
    return completed;
  }
}
