import type {
  ModularEvidenceDisposition,
  ModularExtractionInput,
  ModularExtractionModuleId,
  ModularExtractionOutput,
} from "@narramem/core-domain";
import { getNarraMemIdKind } from "@narramem/core-domain";
import { validateModularExtractionOutput } from "@narramem/core-validator";

export const TAVERN_MODULAR_CANDIDATE_PARTITION_VERSION = "0.1.0" as const;

const RECORD_FIELDS: Readonly<Record<ModularExtractionModuleId, readonly string[]>> = {
  M1: ["entities"],
  M2: ["scenes", "episodes"],
  M3: ["events"],
  M4: ["state_transitions"],
  M5: ["epistemic_states"],
  M6: ["causal_links"],
  M7: [
    "prior_thread_dispositions",
    "prior_future_impact_dispositions",
    "threads",
    "future_impacts",
  ],
};

interface ModularRecordSlot {
  readonly field: string;
  readonly source_index: number;
  readonly target_key: string;
  readonly candidate_key: string | null;
  readonly value: unknown;
}

export interface TavernModularCandidateQuarantineItem {
  readonly target_kind: "record" | "evidence_disposition";
  readonly field: string;
  readonly source_index: number;
  readonly target_key: string;
  readonly candidate_key: string | null;
  readonly value: unknown;
  readonly diagnostic_codes: readonly string[];
  readonly diagnostic_paths: readonly string[];
}

export interface TavernModularCandidatePartition {
  readonly partition_version: typeof TAVERN_MODULAR_CANDIDATE_PARTITION_VERSION;
  readonly module_id: ModularExtractionModuleId;
  readonly source_revision_id: ModularExtractionInput["source_revision_id"];
  /** Maximal locally valid subset. It may remain incomplete while quarantine is non-empty. */
  readonly accepted_output: ModularExtractionOutput;
  readonly accepted_record_keys: readonly string[];
  readonly quarantined: readonly TavernModularCandidateQuarantineItem[];
  readonly pending_target_ids: readonly string[];
  readonly complete: boolean;
}

export interface TavernModularCompilerFinding {
  readonly candidate_key: string;
  readonly diagnostic_codes: readonly string[];
  readonly diagnostic_paths: readonly string[];
}

export class TavernModularCandidatePartitionError extends Error {
  constructor(
    readonly code: "MODULE_SHELL_INVALID" | "SOURCE_REVISION_MISMATCH",
    message: string,
  ) {
    super(message);
    this.name = "TavernModularCandidatePartitionError";
  }
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const candidateKey = (value: unknown): string | null => {
  if (!isObject(value) || typeof value.candidate_key !== "string") return null;
  const key = value.candidate_key.trim();
  return key.length === 0 ? null : key;
};

const unique = (values: readonly string[]): string[] => [...new Set(values)].sort();

function evidenceIdsForRecord(
  moduleId: ModularExtractionModuleId,
  field: string,
  record: unknown,
): string[] {
  if (!isObject(record)) return [];
  if (moduleId === "M2") {
    const values = field === "scenes" ? record.source_evidence_ids : record.evidence_ids;
    return Array.isArray(values)
      ? values.filter((item): item is string => typeof item === "string")
      : [];
  }
  if (moduleId === "M7") {
    return Array.isArray(record.evidence_ids)
      ? record.evidence_ids.filter((item): item is string => typeof item === "string")
      : [];
  }
  return Array.isArray(record.evidence_quotes)
    ? record.evidence_quotes.flatMap((quote) =>
        isObject(quote) && quote.support_role === "direct" && typeof quote.evidence_id === "string"
          ? [quote.evidence_id]
          : [],
      )
    : [];
}

function emptyOutput(input: ModularExtractionInput): Record<string, unknown> {
  const base: Record<string, unknown> = {
    contract_version: "0.1.0",
    source_revision_id: input.source_revision_id,
    module_id: input.module_id,
    result: "no_new_facts",
    evidence_dispositions: [],
  };
  for (const field of RECORD_FIELDS[input.module_id]) base[field] = [];
  return base;
}

function synthesizedDispositions(
  input: ModularExtractionInput,
  key: string,
  directEvidence: ReadonlySet<string>,
): ModularEvidenceDisposition[] {
  return input.current_evidence.map((evidence) =>
    directEvidence.has(evidence.evidence_id)
      ? { evidence_id: evidence.evidence_id, disposition: "recorded", record_keys: [key] }
      : { evidence_id: evidence.evidence_id, disposition: "context_only", record_keys: [] },
  );
}

function wireDiagnostics(
  input: ModularExtractionInput,
  slot: ModularRecordSlot,
): {
  readonly codes: string[];
  readonly paths: string[];
} {
  const key = slot.candidate_key ?? slot.target_key;
  const shell = {
    ...emptyOutput(input),
    result: "complete",
    [slot.field]: [slot.value],
    evidence_dispositions: synthesizedDispositions(
      input,
      key,
      new Set(evidenceIdsForRecord(input.module_id, slot.field, slot.value)),
    ),
  };
  const report = validateModularExtractionOutput(shell, input);
  return {
    codes: unique(report.issues.map((item) => item.code)),
    paths: unique(
      report.issues.map((item) =>
        item.path.replace(`/${slot.field}/0`, `/${slot.field}/${slot.source_index}`),
      ),
    ),
  };
}

function quoteOccurrenceExists(text: string, quote: string, occurrence: number): boolean {
  if (quote.length === 0 || !Number.isInteger(occurrence) || occurrence < 0) return false;
  let searchFrom = 0;
  for (let current = 0; current <= occurrence; current += 1) {
    const index = text.indexOf(quote, searchFrom);
    if (index < 0) return false;
    if (current === occurrence) return true;
    searchFrom = index + Math.max(1, quote.length);
  }
  return false;
}

function trustedEvidenceQuote(
  evidenceById: ReadonlyMap<string, string>,
  rawQuote: unknown,
): boolean {
  if (
    !isObject(rawQuote) ||
    typeof rawQuote.evidence_id !== "string" ||
    typeof rawQuote.quote !== "string"
  ) {
    return false;
  }
  const evidenceText = evidenceById.get(rawQuote.evidence_id);
  const occurrence = typeof rawQuote.occurrence === "number" ? rawQuote.occurrence : 0;
  return (
    evidenceText !== undefined && quoteOccurrenceExists(evidenceText, rawQuote.quote, occurrence)
  );
}

/**
 * Rejects only untrusted extra quote objects when the same candidate still has
 * literal direct support. This never rewrites text or rescues an unsupported
 * fact: a record with no trusted direct quote remains quarantined as a whole.
 */
function withoutUntrustedExtraQuotes(
  input: ModularExtractionInput,
  slot: ModularRecordSlot,
): ModularRecordSlot {
  if (input.module_id === "M2" || input.module_id === "M7" || !isObject(slot.value)) return slot;
  const quotes = Array.isArray(slot.value.evidence_quotes) ? slot.value.evidence_quotes : [];
  const evidenceById = new Map<string, string>(
    input.current_evidence.map((item) => [item.evidence_id, item.text]),
  );
  const trusted = quotes.filter((quote) => trustedEvidenceQuote(evidenceById, quote));
  if (
    trusted.length === quotes.length ||
    !trusted.some((quote) => isObject(quote) && quote.support_role === "direct")
  ) {
    return slot;
  }
  return { ...slot, value: { ...slot.value, evidence_quotes: trusted } };
}

/**
 * Modular Wire validation intentionally accepts quote-shaped objects. The
 * trusted partition boundary must additionally prove that every quote is a
 * literal span of the Evidence it names; otherwise a paraphrase can survive
 * staging and fail only after all seven model calls have completed.
 */
function evidenceQuoteDiagnostics(
  input: ModularExtractionInput,
  slot: ModularRecordSlot,
): {
  readonly codes: string[];
  readonly paths: string[];
} {
  if (input.module_id === "M2" || input.module_id === "M7" || !isObject(slot.value)) {
    return { codes: [], paths: [] };
  }
  const evidenceById = new Map<string, string>(
    input.current_evidence.map((item) => [item.evidence_id, item.text]),
  );
  const quotes = Array.isArray(slot.value.evidence_quotes) ? slot.value.evidence_quotes : [];
  const codes: string[] = [];
  const paths: string[] = [];
  quotes.forEach((rawQuote, quoteIndex) => {
    if (
      !isObject(rawQuote) ||
      typeof rawQuote.evidence_id !== "string" ||
      typeof rawQuote.quote !== "string"
    ) {
      return;
    }
    const evidenceText = evidenceById.get(rawQuote.evidence_id);
    const occurrence = typeof rawQuote.occurrence === "number" ? rawQuote.occurrence : 0;
    if (
      evidenceText !== undefined &&
      quoteOccurrenceExists(evidenceText, rawQuote.quote, occurrence)
    ) {
      return;
    }
    codes.push(
      evidenceText === undefined
        ? "MODULAR_EVIDENCE_QUOTE_SOURCE_UNKNOWN"
        : "MODULAR_EVIDENCE_QUOTE_NOT_FOUND",
    );
    paths.push(
      `/${slot.field}/${slot.source_index}/evidence_quotes/${quoteIndex}/${
        evidenceText === undefined ? "evidence_id" : "quote"
      }`,
    );
  });
  return { codes: unique(codes), paths: unique(paths) };
}

function collectEntityRefs(value: unknown, target: Set<string>): void {
  if (Array.isArray(value)) {
    for (const item of value) collectEntityRefs(item, target);
    return;
  }
  if (!isObject(value)) return;
  if (value.kind === "candidate_entity" && typeof value.candidate_key === "string") {
    target.add(value.candidate_key);
  }
  if (value.kind === "existing_entity" && typeof value.entity_id === "string") {
    target.add(value.entity_id);
  }
  for (const item of Object.values(value)) collectEntityRefs(item, target);
}

function collectActiveTypedRefs(
  value: unknown,
  target: {
    readonly entity: Set<string>;
    readonly thread: Set<string>;
    readonly impact: Set<string>;
  },
): void {
  if (typeof value === "string") {
    const kind = getNarraMemIdKind(value);
    if (kind === "entity") target.entity.add(value);
    if (kind === "narrative_thread") target.thread.add(value);
    if (kind === "future_impact") target.impact.add(value);
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectActiveTypedRefs(item, target);
    return;
  }
  if (isObject(value)) {
    for (const item of Object.values(value)) collectActiveTypedRefs(item, target);
  }
}

function refKey(ref: unknown, kind: string, field: string): string | null {
  return isObject(ref) && ref.kind === kind && typeof ref[field] === "string"
    ? (ref[field] as string)
    : null;
}

function candidateEntityRefValid(ref: unknown, entityKeys: ReadonlySet<string>): boolean {
  if (!isObject(ref) || typeof ref.kind !== "string") return false;
  if (ref.kind === "existing_entity") return typeof ref.entity_id === "string";
  return ref.kind === "candidate_entity" && typeof ref.candidate_key === "string"
    ? entityKeys.has(ref.candidate_key)
    : false;
}

function principalRefValid(ref: unknown, entityKeys: ReadonlySet<string>): boolean {
  if (!isObject(ref) || typeof ref.kind !== "string") return false;
  if (ref.kind === "existing_principal") return isObject(ref.principal);
  return ref.kind === "candidate_entity" && typeof ref.candidate_key === "string"
    ? entityKeys.has(ref.candidate_key)
    : false;
}

function allArray(values: unknown, predicate: (value: unknown) => boolean): boolean {
  return Array.isArray(values) && values.every(predicate);
}

function dependencyIssue(
  input: ModularExtractionInput,
  slot: ModularRecordSlot,
  accepted: readonly ModularRecordSlot[],
): { readonly code: string; readonly path: string } | null {
  if (!isObject(slot.value)) return null;
  const record = slot.value;
  const entityKeys = new Set<string>();
  const sceneKeys = new Set<string>();
  const eventKeys = new Set<string>();
  const stateKeys = new Set<string>();
  if ("accepted_m1" in input)
    for (const item of input.accepted_m1.entities) entityKeys.add(item.candidate_key);
  if ("accepted_m2" in input)
    for (const item of input.accepted_m2.scenes) sceneKeys.add(item.candidate_key);
  if ("accepted_m3" in input)
    for (const item of input.accepted_m3.events) eventKeys.add(item.candidate_key);
  if ("accepted_m4" in input)
    for (const item of input.accepted_m4.state_transitions) stateKeys.add(item.candidate_key);
  if ("accepted_m3" in input) collectEntityRefs(input.accepted_m3, entityKeys);
  if ("accepted_m4" in input) collectEntityRefs(input.accepted_m4, entityKeys);
  for (const item of accepted) {
    if (item.field === "scenes" && item.candidate_key !== null) sceneKeys.add(item.candidate_key);
  }

  const invalid = (path: string, code = "MODULAR_DEPENDENCY_UNKNOWN") => ({ code, path });
  if (input.module_id === "M2") {
    if (slot.field === "episodes") {
      return allArray(
        record.scene_candidate_keys,
        (key) => typeof key === "string" && sceneKeys.has(key),
      )
        ? null
        : invalid(`/${slot.field}/${slot.source_index}/scene_candidate_keys`);
    }
    const refs = [record.location_refs, record.participant_refs];
    if (refs.some((items) => !allArray(items, (ref) => candidateEntityRefValid(ref, entityKeys))))
      return invalid(`/${slot.field}/${slot.source_index}`);
    if (!allArray(record.focalizers, (ref) => principalRefValid(ref, entityKeys)))
      return invalid(`/${slot.field}/${slot.source_index}/focalizers`);
  }
  if (input.module_id === "M3") {
    if (
      typeof record.scene_candidate_key !== "string" ||
      !sceneKeys.has(record.scene_candidate_key)
    )
      return invalid(`/${slot.field}/${slot.source_index}/scene_candidate_key`);
    if (
      [record.actor_refs, record.patient_refs, record.location_refs].some(
        (items) => !allArray(items, (ref) => candidateEntityRefValid(ref, entityKeys)),
      )
    )
      return invalid(`/${slot.field}/${slot.source_index}`);
  }
  if (input.module_id === "M4") {
    if (
      !allArray(
        record.cooccurring_event_keys,
        (key) => typeof key === "string" && eventKeys.has(key),
      )
    )
      return invalid(`/${slot.field}/${slot.source_index}/cooccurring_event_keys`);
    if (isObject(record.subject)) {
      if (
        record.subject.kind === "entity" &&
        !candidateEntityRefValid(record.subject.entity, entityKeys)
      )
        return invalid(`/${slot.field}/${slot.source_index}/subject`);
      if (
        record.subject.kind === "relation" &&
        !allArray(record.subject.participants, (ref) => candidateEntityRefValid(ref, entityKeys))
      )
        return invalid(`/${slot.field}/${slot.source_index}/subject/participants`);
    }
  }
  if (input.module_id === "M5") {
    if (!principalRefValid(record.holder, entityKeys))
      return invalid(`/${slot.field}/${slot.source_index}/holder`);
    if (
      record.source_entity !== undefined &&
      !candidateEntityRefValid(record.source_entity, entityKeys)
    )
      return invalid(`/${slot.field}/${slot.source_index}/source_entity`);
    if (!allArray(record.source_event_keys, (key) => typeof key === "string" && eventKeys.has(key)))
      return invalid(`/${slot.field}/${slot.source_index}/source_event_keys`);
    if (isObject(record.target)) {
      if (
        record.target.kind === "event" &&
        (typeof record.target.event_candidate_key !== "string" ||
          !eventKeys.has(record.target.event_candidate_key))
      )
        return invalid(`/${slot.field}/${slot.source_index}/target/event_candidate_key`);
      if (record.target.kind === "state")
        return invalid(
          `/${slot.field}/${slot.source_index}/target/state_candidate_key`,
          "MODULAR_M5_STATE_TARGET_NOT_IN_INPUT",
        );
      if (record.target.kind === "claim" && isObject(record.target.claim)) {
        const args = Array.isArray(record.target.claim.arguments)
          ? record.target.claim.arguments
          : [];
        for (const argument of args) {
          if (!isObject(argument)) continue;
          if (argument.kind === "entity" && !candidateEntityRefValid(argument.entity, entityKeys))
            return invalid(`/${slot.field}/${slot.source_index}/target/claim/arguments`);
          if (
            argument.kind === "event" &&
            (typeof argument.event_candidate_key !== "string" ||
              !eventKeys.has(argument.event_candidate_key))
          )
            return invalid(`/${slot.field}/${slot.source_index}/target/claim/arguments`);
          if (argument.kind === "state_delta")
            return invalid(
              `/${slot.field}/${slot.source_index}/target/claim/arguments`,
              "MODULAR_M5_STATE_TARGET_NOT_IN_INPUT",
            );
        }
      }
    }
  }
  if (input.module_id === "M6") {
    const endpointValid = (ref: unknown): boolean => {
      if (!isObject(ref) || typeof ref.kind !== "string") return false;
      if (ref.kind === "event")
        return eventKeys.has(refKey(ref, "event", "event_candidate_key") ?? "");
      if (ref.kind === "state_delta")
        return stateKeys.has(refKey(ref, "state_delta", "state_candidate_key") ?? "");
      if (ref.kind === "existing_event") return typeof ref.event_id === "string";
      if (ref.kind === "existing_state_delta") return typeof ref.delta_id === "string";
      if (ref.kind === "existing_epistemic_state") return typeof ref.epistemic_id === "string";
      return false;
    };
    if (!allArray(record.cause_refs, endpointValid) || !allArray(record.effect_refs, endpointValid))
      return invalid(`/${slot.field}/${slot.source_index}`, "MODULAR_CAUSAL_ENDPOINT_UNKNOWN");
  }
  if (input.module_id === "M7") {
    const activeRefs = {
      entity: new Set<string>(),
      thread: new Set<string>(),
      impact: new Set<string>(),
    };
    collectActiveTypedRefs(input.active_threads_and_impacts, activeRefs);
    const entityRefs = new Set([...entityKeys, ...activeRefs.entity]);
    const acceptedThreadKeys = accepted.flatMap((item) =>
      item.field === "threads" && item.candidate_key !== null ? [item.candidate_key] : [],
    );
    const originRefs = new Set([
      ...eventKeys,
      ...stateKeys,
      ...activeRefs.thread,
      ...acceptedThreadKeys,
    ]);
    if (slot.field === "prior_thread_dispositions") {
      if (
        typeof record.prior_thread_ref !== "string" ||
        !activeRefs.thread.has(record.prior_thread_ref)
      ) {
        return invalid(`/${slot.field}/${slot.source_index}/prior_thread_ref`);
      }
      if (
        !allArray(
          record.transition_event_refs,
          (ref) => typeof ref === "string" && eventKeys.has(ref),
        )
      ) {
        return invalid(`/${slot.field}/${slot.source_index}/transition_event_refs`);
      }
    } else if (slot.field === "prior_future_impact_dispositions") {
      if (
        typeof record.prior_impact_ref !== "string" ||
        !activeRefs.impact.has(record.prior_impact_ref)
      ) {
        return invalid(`/${slot.field}/${slot.source_index}/prior_impact_ref`);
      }
      if (
        !allArray(
          record.transition_refs,
          (ref) => typeof ref === "string" && (eventKeys.has(ref) || stateKeys.has(ref)),
        )
      ) {
        return invalid(`/${slot.field}/${slot.source_index}/transition_refs`);
      }
    } else if (slot.field === "threads") {
      if (
        !allArray(
          record.opened_by_event_refs,
          (ref) => typeof ref === "string" && eventKeys.has(ref),
        )
      )
        return invalid(`/${slot.field}/${slot.source_index}/opened_by_event_refs`);
      if (
        !allArray(record.participant_refs, (ref) => typeof ref === "string" && entityRefs.has(ref))
      ) {
        return invalid(`/${slot.field}/${slot.source_index}/participant_refs`);
      }
    } else if (
      !allArray(record.origin_refs, (ref) => typeof ref === "string" && originRefs.has(ref))
    ) {
      return invalid(`/${slot.field}/${slot.source_index}/origin_refs`);
    } else if (
      !allArray(record.target_refs, (ref) => typeof ref === "string" && entityRefs.has(ref))
    ) {
      return invalid(`/${slot.field}/${slot.source_index}/target_refs`);
    } else if (
      Array.isArray(record.possible_effects) &&
      record.possible_effects.some(
        (effect) =>
          !isObject(effect) ||
          !allArray(effect.target_refs, (ref) => typeof ref === "string" && entityRefs.has(ref)),
      )
    ) {
      return invalid(`/${slot.field}/${slot.source_index}/possible_effects`);
    }
  }
  return null;
}

function dispositionQuarantine(
  input: ModularExtractionInput,
  raw: readonly unknown[],
  accepted: readonly ModularRecordSlot[],
): {
  readonly accepted: ModularEvidenceDisposition[];
  readonly quarantined: TavernModularCandidateQuarantineItem[];
} {
  const acceptedKeys = new Set(accepted.flatMap((slot) => slot.candidate_key ?? []));
  const recordEvidence = new Map<string, Set<string>>(
    accepted.flatMap((slot) =>
      slot.candidate_key === null
        ? []
        : [
            [
              slot.candidate_key,
              new Set(evidenceIdsForRecord(input.module_id, slot.field, slot.value)),
            ],
          ],
    ),
  );
  let result: ModularEvidenceDisposition[] = [];
  const quarantined: TavernModularCandidateQuarantineItem[] = [];
  input.current_evidence.forEach((evidence, sourceIndex) => {
    const matches = raw.filter(
      (item) => isObject(item) && item.evidence_id === evidence.evidence_id,
    );
    const item = matches[0];
    let valid = false;
    let normalized: ModularEvidenceDisposition | null = null;
    if (matches.length === 1 && isObject(item) && Array.isArray(item.record_keys)) {
      const rawKeys = item.record_keys as readonly unknown[];
      const keys = rawKeys.filter((key): key is string => typeof key === "string");
      valid = keys.length === rawKeys.length;
      if (item.disposition === "recorded") {
        const supportedKeys = unique(
          keys.filter(
            (key) => acceptedKeys.has(key) && recordEvidence.get(key)?.has(evidence.evidence_id),
          ),
        );
        valid = valid && supportedKeys.length > 0;
        if (valid) {
          normalized = {
            evidence_id: evidence.evidence_id,
            disposition: "recorded",
            record_keys: supportedKeys,
          };
        }
      } else {
        valid =
          valid &&
          (item.disposition === "duplicate" ||
            item.disposition === "context_only" ||
            item.disposition === "not_applicable") &&
          keys.length === 0;
      }
    }
    if (valid) {
      result.push(normalized ?? (item as unknown as ModularEvidenceDisposition));
      return;
    }
    quarantined.push({
      target_kind: "evidence_disposition",
      field: "evidence_dispositions",
      source_index: sourceIndex,
      target_key: `evidence:${evidence.evidence_id}`,
      candidate_key: null,
      value: item ?? null,
      diagnostic_codes: ["MODULAR_EVIDENCE_DISPOSITION_INVALID"],
      diagnostic_paths: [`/evidence_dispositions/${sourceIndex}`],
    });
  });
  // A single Evidence item may support several accepted sibling records (for
  // example, a Scene and the Episode that groups it). Models often name only
  // one of those siblings in record_keys even though every record already
  // carries the same Evidence ID. Complete the cross-reference locally when,
  // and only when, the disposition is already valid `recorded` Evidence for
  // every Evidence ID carried by that accepted record. This is deterministic
  // bookkeeping; it does not invent facts or turn context-only Evidence into
  // support.
  const claimedBeforeNormalization = new Set(
    result.flatMap((item) => (item.disposition === "recorded" ? item.record_keys : [])),
  );
  for (const slot of accepted) {
    const key = slot.candidate_key;
    if (key === null || claimedBeforeNormalization.has(key)) continue;
    const evidenceIds = unique(evidenceIdsForRecord(input.module_id, slot.field, slot.value));
    if (
      evidenceIds.length === 0 ||
      !evidenceIds.every((evidenceId) =>
        result.some((item) => item.evidence_id === evidenceId && item.disposition === "recorded"),
      )
    ) {
      continue;
    }
    const evidenceSet = new Set(evidenceIds);
    result = result.map((item) =>
      item.disposition === "recorded" && evidenceSet.has(item.evidence_id)
        ? { ...item, record_keys: unique([...item.record_keys, key]) }
        : item,
    );
    claimedBeforeNormalization.add(key);
  }
  const claimedKeys = new Set(
    result.flatMap((item) => (item.disposition === "recorded" ? item.record_keys : [])),
  );
  const unclaimedEvidence = new Set(
    accepted.flatMap((slot) =>
      slot.candidate_key !== null && !claimedKeys.has(slot.candidate_key)
        ? evidenceIdsForRecord(input.module_id, slot.field, slot.value)
        : [],
    ),
  );
  if (unclaimedEvidence.size > 0) {
    result = result.filter((item) => !unclaimedEvidence.has(item.evidence_id));
    for (const evidenceId of unclaimedEvidence) {
      if (quarantined.some((item) => item.target_key === `evidence:${evidenceId}`)) continue;
      const sourceIndex = input.current_evidence.findIndex(
        (evidence) => evidence.evidence_id === evidenceId,
      );
      quarantined.push({
        target_kind: "evidence_disposition",
        field: "evidence_dispositions",
        source_index: sourceIndex,
        target_key: `evidence:${evidenceId}`,
        candidate_key: null,
        value: raw.find((item) => isObject(item) && item.evidence_id === evidenceId) ?? null,
        diagnostic_codes: ["MODULAR_RECORD_DISPOSITION_MISSING"],
        diagnostic_paths: ["/evidence_dispositions"],
      });
    }
  }
  return { accepted: result, quarantined };
}

/**
 * Keeps valid sibling records, quarantines only malformed/dependency-invalid
 * records and Evidence dispositions, and never asks a repair to rewrite success.
 */
export function partitionTavernModularExtractionOutput(
  value: unknown,
  input: ModularExtractionInput,
): TavernModularCandidatePartition {
  const fields = RECORD_FIELDS[input.module_id];
  if (
    !isObject(value) ||
    value.contract_version !== "0.1.0" ||
    value.module_id !== input.module_id ||
    typeof value.source_revision_id !== "string" ||
    !fields.every((field) => Array.isArray(value[field])) ||
    !Array.isArray(value.evidence_dispositions)
  ) {
    throw new TavernModularCandidatePartitionError(
      "MODULE_SHELL_INVALID",
      "Module response must expose the exact module shell and candidate arrays",
    );
  }
  if (value.source_revision_id !== input.source_revision_id) {
    throw new TavernModularCandidatePartitionError(
      "SOURCE_REVISION_MISMATCH",
      "Module response belongs to another Source revision",
    );
  }
  const allSlots: ModularRecordSlot[] = fields.flatMap((field) =>
    (value[field] as readonly unknown[]).map((record, sourceIndex) =>
      withoutUntrustedExtraQuotes(input, {
        field,
        source_index: sourceIndex,
        candidate_key: candidateKey(record),
        target_key: candidateKey(record) ?? `slot:${field}:${sourceIndex}`,
        value: record,
      }),
    ),
  );
  const quarantined: TavernModularCandidateQuarantineItem[] = [];
  let accepted = allSlots.filter((slot) => {
    const wire = wireDiagnostics(input, slot);
    const quotes = evidenceQuoteDiagnostics(input, slot);
    const diagnostics = {
      codes: unique([...wire.codes, ...quotes.codes]),
      paths: unique([...wire.paths, ...quotes.paths]),
    };
    if (diagnostics.codes.length === 0) return true;
    quarantined.push({
      target_kind: "record",
      field: slot.field,
      source_index: slot.source_index,
      target_key: slot.target_key,
      candidate_key: slot.candidate_key,
      value: slot.value,
      diagnostic_codes: diagnostics.codes,
      diagnostic_paths: diagnostics.paths,
    });
    return false;
  });

  const duplicates = new Map<string, ModularRecordSlot[]>();
  for (const slot of accepted) {
    if (slot.candidate_key === null) continue;
    const group = duplicates.get(slot.candidate_key) ?? [];
    group.push(slot);
    duplicates.set(slot.candidate_key, group);
  }
  const duplicateSlots = new Set(
    [...duplicates.values()].filter((items) => items.length > 1).flat(),
  );
  if (duplicateSlots.size > 0) {
    accepted = accepted.filter((slot) => {
      if (!duplicateSlots.has(slot)) return true;
      quarantined.push({
        target_kind: "record",
        field: slot.field,
        source_index: slot.source_index,
        target_key: slot.target_key,
        candidate_key: slot.candidate_key,
        value: slot.value,
        diagnostic_codes: ["MODULAR_RECORD_KEY_DUPLICATE"],
        diagnostic_paths: [`/${slot.field}/${slot.source_index}/candidate_key`],
      });
      return false;
    });
  }

  for (;;) {
    const failures = accepted.flatMap((slot) => {
      const problem = dependencyIssue(input, slot, accepted);
      return problem === null ? [] : [{ slot, problem }];
    });
    if (failures.length === 0) break;
    const failed = new Set(failures.map((item) => item.slot));
    for (const { slot, problem } of failures) {
      quarantined.push({
        target_kind: "record",
        field: slot.field,
        source_index: slot.source_index,
        target_key: slot.target_key,
        candidate_key: slot.candidate_key,
        value: slot.value,
        diagnostic_codes: [problem.code],
        diagnostic_paths: [problem.path],
      });
    }
    accepted = accepted.filter((slot) => !failed.has(slot));
  }

  const disposition = dispositionQuarantine(
    input,
    value.evidence_dispositions as readonly unknown[],
    accepted,
  );
  quarantined.push(...disposition.quarantined);
  const acceptedOutput = {
    ...emptyOutput(input),
    result: accepted.length === 0 ? "no_new_facts" : "complete",
    ...Object.fromEntries(
      fields.map((field) => [
        field,
        accepted.filter((slot) => slot.field === field).map((slot) => slot.value),
      ]),
    ),
    evidence_dispositions: disposition.accepted,
  } as unknown as ModularExtractionOutput;
  const completeReport =
    quarantined.length === 0 ? validateModularExtractionOutput(acceptedOutput, input) : null;
  if (completeReport !== null && !completeReport.accepted) {
    throw new TavernModularCandidatePartitionError(
      "MODULE_SHELL_INVALID",
      `Complete partition failed invariant: ${completeReport.issues.map((item) => item.code).join(",")}`,
    );
  }
  return {
    partition_version: TAVERN_MODULAR_CANDIDATE_PARTITION_VERSION,
    module_id: input.module_id,
    source_revision_id: input.source_revision_id,
    accepted_output: acceptedOutput,
    accepted_record_keys: unique(accepted.flatMap((slot) => slot.candidate_key ?? [])),
    quarantined,
    pending_target_ids: unique(quarantined.map((item) => item.target_key)),
    complete: quarantined.length === 0,
  };
}

function outputRecords(output: ModularExtractionOutput): Record<string, readonly unknown[]> {
  return Object.fromEntries(
    RECORD_FIELDS[output.module_id].map((field) => [
      field,
      Array.isArray((output as unknown as Record<string, unknown>)[field])
        ? ((output as unknown as Record<string, readonly unknown[]>)[field] ?? [])
        : [],
    ]),
  );
}

/**
 * Applies only replacements authorized by the saved quarantine. Existing valid
 * records win on key collision, so a repair response cannot rewrite success.
 */
export function applyTavernModularExtractionRepair(
  current: TavernModularCandidatePartition,
  repairValue: unknown,
  input: ModularExtractionInput,
): TavernModularCandidatePartition {
  if (
    current.module_id !== input.module_id ||
    current.source_revision_id !== input.source_revision_id
  ) {
    throw new TavernModularCandidatePartitionError(
      "SOURCE_REVISION_MISMATCH",
      "Saved partition and repair input do not share a Source revision",
    );
  }
  if (!isObject(repairValue) || repairValue.module_id !== input.module_id) {
    throw new TavernModularCandidatePartitionError(
      "MODULE_SHELL_INVALID",
      "Repair response must use the same module shell",
    );
  }
  const acceptedRecords = outputRecords(current.accepted_output);
  const acceptedKeys = new Set(current.accepted_record_keys);
  const pendingKeys = new Set(current.quarantined.flatMap((item) => item.candidate_key ?? []));
  const pendingRecordEvidence = new Set(
    current.quarantined.flatMap((item) =>
      item.target_kind === "record"
        ? evidenceIdsForRecord(input.module_id, item.field, item.value)
        : [],
    ),
  );
  const pendingEvidence = new Set(
    current.quarantined.flatMap((item) =>
      item.target_kind === "evidence_disposition"
        ? [item.target_key.slice("evidence:".length)]
        : evidenceIdsForRecord(input.module_id, item.field, item.value),
    ),
  );
  const mergedFields = Object.fromEntries(
    RECORD_FIELDS[input.module_id].map((field) => {
      const repairRecords = Array.isArray(repairValue[field])
        ? (repairValue[field] as readonly unknown[]).filter((record) => {
            const key = candidateKey(record);
            if (key === null || acceptedKeys.has(key)) return false;
            return (
              pendingKeys.has(key) ||
              evidenceIdsForRecord(input.module_id, field, record).some((id) =>
                pendingRecordEvidence.has(id),
              )
            );
          })
        : [];
      return [field, [...(acceptedRecords[field] ?? []), ...repairRecords]];
    }),
  );
  const dispositionsByEvidence = new Map<string, unknown>();
  for (const disposition of current.accepted_output.evidence_dispositions) {
    dispositionsByEvidence.set(disposition.evidence_id, disposition);
  }
  if (Array.isArray(repairValue.evidence_dispositions)) {
    for (const disposition of repairValue.evidence_dispositions) {
      if (
        isObject(disposition) &&
        typeof disposition.evidence_id === "string" &&
        pendingEvidence.has(disposition.evidence_id)
      ) {
        dispositionsByEvidence.set(disposition.evidence_id, disposition);
      }
    }
  }
  return partitionTavernModularExtractionOutput(
    {
      contract_version: "0.1.0",
      source_revision_id: input.source_revision_id,
      module_id: input.module_id,
      result: Object.values(mergedFields).some(
        (records) => Array.isArray(records) && records.length > 0,
      )
        ? "complete"
        : "no_new_facts",
      ...mergedFields,
      evidence_dispositions: [...dispositionsByEvidence.values()],
    },
    input,
  );
}

/** Removes compiler-invalid candidates and revalidates the remaining closure locally. */
export function quarantineTavernModularCompilerFindings(
  current: TavernModularCandidatePartition,
  findings: readonly TavernModularCompilerFinding[],
  input: ModularExtractionInput,
): TavernModularCandidatePartition {
  const byKey = new Map(
    findings
      .filter((finding) => finding.candidate_key.trim().length > 0)
      .map((finding) => [finding.candidate_key, finding]),
  );
  if (byKey.size === 0) return current;
  const currentRecords = outputRecords(current.accepted_output);
  const forced: TavernModularCandidateQuarantineItem[] = [];
  const fields = Object.fromEntries(
    RECORD_FIELDS[input.module_id].map((field) => [
      field,
      (currentRecords[field] ?? []).filter((record, sourceIndex) => {
        const key = candidateKey(record);
        const finding = key === null ? undefined : byKey.get(key);
        if (key === null || finding === undefined) return true;
        forced.push({
          target_kind: "record",
          field,
          source_index: sourceIndex,
          target_key: key,
          candidate_key: key,
          value: record,
          diagnostic_codes: unique(finding.diagnostic_codes),
          diagnostic_paths:
            finding.diagnostic_paths.length === 0
              ? [`/${field}/${sourceIndex}`]
              : unique(finding.diagnostic_paths),
        });
        return false;
      }),
    ]),
  );
  if (forced.length === 0) return current;
  const repartitioned = partitionTavernModularExtractionOutput(
    {
      contract_version: "0.1.0",
      source_revision_id: input.source_revision_id,
      module_id: input.module_id,
      result: Object.values(fields).some((records) => Array.isArray(records) && records.length > 0)
        ? "complete"
        : "no_new_facts",
      ...fields,
      evidence_dispositions: current.accepted_output.evidence_dispositions,
    },
    input,
  );
  const forcedKeys = new Set(forced.map((item) => item.target_key));
  const quarantined = [
    ...forced,
    ...current.quarantined.filter((item) => !forcedKeys.has(item.target_key)),
    ...repartitioned.quarantined,
  ];
  return {
    ...repartitioned,
    quarantined,
    pending_target_ids: unique(quarantined.map((item) => item.target_key)),
    complete: false,
  };
}
