import type { ModularExtractionInput } from "@narramem/core-domain";

import type { TavernJsonSchemaRequest, TavernJsonValue, TavernRolePrompt } from "./contracts.js";
import type {
  TavernMemoryAuditItem,
  TavernMemoryBatchWorkState,
  TavernMemoryColdHead,
  TavernMemoryCorePage,
  TavernMemoryModuleId,
  TavernMemoryModuleViewIndex,
  TavernMemoryModuleViewPage,
} from "./memory-book-contracts.js";
import type { TavernMemoryBookStore } from "./memory-book-store.js";
import type { TavernMemoryModulePromptAssembly } from "./memory-module-prompt.js";
import type { TavernMemoryAttemptKind, TavernMemoryAttemptLimits } from "./memory-module-state.js";
import {
  settleTavernMemoryModuleAttempt,
  startTavernMemoryModuleAttempt,
} from "./memory-module-state.js";
import {
  applyTavernModularExtractionRepair,
  partitionTavernModularExtractionOutput,
  quarantineTavernModularCompilerFindings,
  type TavernModularCandidatePartition,
  TavernModularCandidatePartitionError,
  type TavernModularCompilerFinding,
} from "./modular-candidate-partition.js";
import { sha256HexUtf8, utf8ByteLength } from "./worldbook-codec.js";

export const TAVERN_MEMORY_MODULE_RUNNER_VERSION = "0.1.0" as const;

export interface TavernMemoryModuleGenerationRequest {
  readonly generation_id: string;
  readonly requested_model_id: string;
  readonly messages: readonly TavernRolePrompt[];
  readonly prompt_asset_refs: readonly string[];
  readonly json_schema: TavernJsonSchemaRequest;
  /** Continuation fragments must not be forced through structured-output mode. */
  readonly response_format?: "structured_json" | "text_fragment";
  readonly should_stream: false;
  readonly max_chat_history: 0;
}

export interface TavernMemoryModuleGenerationPort {
  generate(request: TavernMemoryModuleGenerationRequest): Promise<{ readonly content: string }>;
}

export interface TavernMemoryPreparedModuleCommit {
  readonly accepted_record_ids: readonly string[];
  readonly compiler_findings: readonly TavernModularCompilerFinding[];
  readonly core_pages: readonly TavernMemoryCorePage[];
  readonly module_view_pages: readonly TavernMemoryModuleViewPage[];
  readonly module_views?: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
  readonly active_state?: TavernJsonValue;
  readonly epistemic_state?: TavernJsonValue;
  readonly thread_impact?: TavernJsonValue;
}

export interface TavernMemoryModuleCompilerPort {
  /** Pure preparation only. The Runner owns the single atomic World Book commit. */
  prepare(
    partition: TavernModularCandidatePartition,
    input: ModularExtractionInput,
    previous: TavernModularCandidatePartition | null,
  ): Promise<TavernMemoryPreparedModuleCommit>;
}

export interface TavernMemoryModuleRunRequest {
  readonly book_store: TavernMemoryBookStore;
  readonly generation_port: TavernMemoryModuleGenerationPort;
  readonly compiler: TavernMemoryModuleCompilerPort;
  readonly input: ModularExtractionInput;
  readonly prompt: TavernMemoryModulePromptAssembly;
  readonly requested_model_id: string;
  readonly attempt_kind: TavernMemoryAttemptKind;
  readonly attempt_limits: TavernMemoryAttemptLimits;
  readonly operation_id: string;
  readonly now: () => string;
  /** Required for targeted/manual repair so accepted siblings cannot be rewritten. */
  readonly prior_partition?: TavernModularCandidatePartition;
  /** Volatile prefix from an immediately preceding truncated response. Never persisted by the Runner. */
  readonly response_prefix?: string;
}

export interface TavernMemoryModuleRunResult {
  readonly runner_version: typeof TAVERN_MEMORY_MODULE_RUNNER_VERSION;
  readonly status:
    | "MODULE_COMMITTED"
    | "NEEDS_USER"
    | "PROVIDER_FAILED"
    | "JSON_FAILED"
    | "MODULE_SHELL_FAILED"
    | "COMPILER_FAILED";
  readonly provider_dispatched: boolean;
  readonly model_call_increment: 0 | 1;
  readonly batch: TavernMemoryBatchWorkState;
  readonly head: TavernMemoryColdHead;
  readonly partition: TavernModularCandidatePartition | null;
  readonly error_code: string | null;
  /** Present only for an in-process, plausibly truncated JSON response. */
  readonly incomplete_content: string | null;
}

export interface TavernMemoryModuleRecoveryRunRequest
  extends Omit<TavernMemoryModuleRunRequest, "attempt_kind" | "operation_id" | "prior_partition"> {
  readonly operation_id_prefix: string;
  readonly automatic_targeted_repair: boolean;
  readonly repair_prompt: (
    partition: TavernModularCandidatePartition,
  ) => TavernMemoryModulePromptAssembly;
  readonly continuation_prompt?: {
    readonly prompt_asset_ref: string;
    readonly body: string;
  };
}

export interface TavernMemoryModuleRecoveryRunResult {
  readonly attempts: readonly TavernMemoryModuleRunResult[];
  readonly final: TavernMemoryModuleRunResult;
  readonly model_call_increment: number;
}

function isSavedPartition(
  value: unknown,
  batch: TavernMemoryBatchWorkState,
  moduleId: ModularExtractionInput["module_id"],
): value is TavernModularCandidatePartition {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  const candidate = value as Partial<TavernModularCandidatePartition>;
  return (
    candidate.partition_version === "0.1.0" &&
    candidate.module_id === moduleId &&
    candidate.source_revision_id === batch.source_revision_id &&
    Array.isArray(candidate.accepted_record_keys) &&
    Array.isArray(candidate.quarantined) &&
    Array.isArray(candidate.pending_target_ids) &&
    typeof candidate.complete === "boolean"
  );
}

/** Loads the last trusted partition from the same Memory Book; model calls: zero. */
export async function readTavernMemoryModulePartition(
  store: Pick<TavernMemoryBookStore, "readCorePage">,
  batch: TavernMemoryBatchWorkState,
  moduleId: ModularExtractionInput["module_id"],
): Promise<TavernModularCandidatePartition | null> {
  const pageId = batch.modules[moduleId].partition_page_id;
  if (pageId === null) return null;
  const page = await store.readCorePage(pageId);
  const record = page.records.find((item) => item.record_kind === "module_candidate_partition");
  if (record === undefined || !isSavedPartition(record.payload, batch, moduleId)) {
    throw new TypeError(`Partition page ${pageId} does not match ${batch.batch_id}/${moduleId}`);
  }
  return record.payload;
}

function asJsonValue(value: unknown): TavernJsonValue {
  return value as TavernJsonValue;
}

function appendAudit(
  head: TavernMemoryColdHead,
  item: TavernMemoryAuditItem,
): readonly TavernMemoryAuditItem[] {
  return [...head.audit_ring, item];
}

async function commitHead(
  store: TavernMemoryBookStore,
  head: TavernMemoryColdHead,
  request: {
    readonly commit_id: string;
    readonly committed_at: string;
    readonly work_state: TavernMemoryBatchWorkState;
    readonly audit: TavernMemoryAuditItem;
    readonly core_pages?: readonly TavernMemoryCorePage[];
    readonly module_view_pages?: readonly TavernMemoryModuleViewPage[];
    readonly prepared?: TavernMemoryPreparedModuleCommit;
  },
): Promise<TavernMemoryColdHead> {
  const commitRequest = {
    commit_id: request.commit_id,
    expected_generation: head.generation,
    expected_generation_checksum: head.generation_checksum,
    committed_at: request.committed_at,
    source_index: head.source_index,
    work_state: request.work_state,
    checkpoint_index: head.checkpoint_index,
    active_state: request.prepared?.active_state ?? head.active_state,
    epistemic_state: request.prepared?.epistemic_state ?? head.epistemic_state,
    thread_impact: request.prepared?.thread_impact ?? head.thread_impact,
    module_views:
      (request.prepared?.module_views as typeof head.module_views | undefined) ?? head.module_views,
    audit_ring: appendAudit(head, request.audit),
    retained_core_page_ids: head.core_page_ids,
    retained_module_view_page_ids: head.module_view_page_ids,
    core_pages: request.core_pages ?? [],
    module_view_pages: request.module_view_pages ?? [],
  } as const;
  try {
    return await store.commit(commitRequest);
  } catch (error) {
    // The Store verifies the same idempotency key and payload; this recovers only
    // the common "durable save succeeded but response was lost" case.
    return store.commit(commitRequest).catch(() => Promise.reject(error));
  }
}

function totalCalls(
  batch: TavernMemoryBatchWorkState,
  moduleId: ModularExtractionInput["module_id"],
): number {
  const state = batch.modules[moduleId];
  return (
    state.base_calls +
    state.transport_retry_calls +
    state.continuation_calls +
    state.targeted_repair_calls +
    state.manual_repair_calls
  );
}

function parseJson(content: string): unknown {
  const trimmed = content.trim();
  if (trimmed.length === 0) throw new SyntaxError("Empty module response");
  return JSON.parse(trimmed) as unknown;
}

function plausiblyTruncatedJson(content: string): boolean {
  const trimmed = content.trim();
  if (trimmed.length === 0 || (trimmed[0] !== "{" && trimmed[0] !== "[")) return false;
  const stack: string[] = [];
  let inString = false;
  let escaping = false;
  for (const character of trimmed) {
    if (inString) {
      if (escaping) escaping = false;
      else if (character === "\\") escaping = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') {
      inString = true;
      continue;
    }
    if (character === "{" || character === "[") stack.push(character);
    else if (character === "}" || character === "]") {
      const expected = character === "}" ? "{" : "[";
      if (stack.pop() !== expected) return false;
    }
  }
  return inString || stack.length > 0;
}

async function settleFailure(
  request: TavernMemoryModuleRunRequest,
  head: TavernMemoryColdHead,
  running: TavernMemoryBatchWorkState,
  errorCode: string,
  status: TavernMemoryModuleRunResult["status"],
  incompleteContent: string | null = null,
): Promise<TavernMemoryModuleRunResult> {
  const batch = settleTavernMemoryModuleAttempt(running, request.input.module_id, {
    accepted_record_ids: [],
    pending_target_ids: [],
    error_code: errorCode,
  });
  const at = request.now();
  const settled = await commitHead(request.book_store, head, {
    commit_id: `${request.operation_id}:settled:${errorCode}`,
    committed_at: at,
    work_state: batch,
    audit: {
      at,
      batch_id: batch.batch_id,
      module_id: request.input.module_id,
      event: "module_attempt_failed",
      error_code: errorCode,
    },
  });
  return {
    runner_version: TAVERN_MEMORY_MODULE_RUNNER_VERSION,
    status,
    provider_dispatched: true,
    model_call_increment: 1,
    batch,
    head: settled,
    partition: null,
    error_code: errorCode,
    incomplete_content: incompleteContent,
  };
}

/** Runs exactly one durable module attempt. Automatic/manual policy stays above this boundary. */
export async function runTavernMemoryModuleAttempt(
  request: TavernMemoryModuleRunRequest,
): Promise<TavernMemoryModuleRunResult> {
  if (request.prompt.module_id !== request.input.module_id) {
    throw new TypeError("Module Prompt and input do not match");
  }
  if (request.requested_model_id.trim().length === 0 || request.operation_id.trim().length === 0) {
    throw new TypeError("Model ID and operation ID must be non-empty");
  }
  const cold = await request.book_store.readColdHead();
  const initialHead = cold.head;
  if (initialHead === null || initialHead.work_state === null) {
    throw new TypeError("Memory Book has no active batch work state");
  }
  if (
    initialHead.work_state.batch_id !== request.input.batch_id ||
    initialHead.work_state.source_revision_id !== request.input.source_revision_id
  ) {
    throw new TypeError("Module input does not match the durable batch");
  }
  const running = startTavernMemoryModuleAttempt(
    initialHead.work_state,
    request.input.module_id,
    request.attempt_kind,
    request.attempt_limits,
  );
  const startedAt = request.now();
  const startedHead = await commitHead(request.book_store, initialHead, {
    commit_id: `${request.operation_id}:started`,
    committed_at: startedAt,
    work_state: running,
    audit: {
      at: startedAt,
      batch_id: running.batch_id,
      module_id: request.input.module_id,
      event: `module_attempt_started:${request.attempt_kind}`,
      error_code: null,
    },
  });
  const attemptNumber = totalCalls(running, request.input.module_id);
  const attemptId = `${running.batch_id}:${request.input.module_id}:${attemptNumber}`;
  const generationId = `${request.operation_id}:generation`;
  let response: { readonly content: string };
  try {
    response = await request.generation_port.generate({
      generation_id: generationId,
      requested_model_id: request.requested_model_id,
      messages: request.prompt.messages,
      prompt_asset_refs: request.prompt.prompt_asset_refs,
      json_schema: request.prompt.output_json_schema,
      response_format:
        request.attempt_kind === "continuation" ? "text_fragment" : "structured_json",
      should_stream: false,
      max_chat_history: 0,
    });
  } catch {
    return settleFailure(request, startedHead, running, "PROVIDER_FAILED", "PROVIDER_FAILED");
  }
  let parsed: unknown;
  const combinedContent = `${request.response_prefix ?? ""}${response.content}`;
  try {
    parsed = parseJson(combinedContent);
  } catch {
    const incompleteContent = plausiblyTruncatedJson(combinedContent) ? combinedContent : null;
    const trimmed = combinedContent.trim();
    const errorCode =
      incompleteContent !== null
        ? "JSON_TRUNCATED"
        : trimmed.startsWith("```")
          ? "JSON_FENCED"
          : "JSON_INVALID";
    return settleFailure(
      request,
      startedHead,
      running,
      errorCode,
      "JSON_FAILED",
      incompleteContent,
    );
  }
  let partition: TavernModularCandidatePartition;
  try {
    partition =
      request.prior_partition === undefined
        ? partitionTavernModularExtractionOutput(parsed, request.input)
        : applyTavernModularExtractionRepair(request.prior_partition, parsed, request.input);
  } catch (error) {
    const code =
      error instanceof TavernModularCandidatePartitionError ? error.code : "MODULE_SHELL_INVALID";
    return settleFailure(request, startedHead, running, code, "MODULE_SHELL_FAILED");
  }

  let prepared: TavernMemoryPreparedModuleCommit;
  try {
    for (;;) {
      prepared = await request.compiler.prepare(
        partition,
        request.input,
        request.prior_partition ?? null,
      );
      if (prepared.compiler_findings.length === 0) break;
      const next = quarantineTavernModularCompilerFindings(
        partition,
        prepared.compiler_findings,
        request.input,
      );
      if (next.accepted_record_keys.length === partition.accepted_record_keys.length) {
        throw new Error("Compiler findings did not localize an accepted candidate");
      }
      partition = next;
    }
  } catch {
    return settleFailure(request, startedHead, running, "COMPILER_FAILED", "COMPILER_FAILED");
  }

  const responseHash = await sha256HexUtf8(combinedContent);
  const pageId = `module_attempt_${running.batch_id}_${request.input.module_id}_${attemptNumber}`;
  const provenanceId = `module_provenance_${attemptId}`;
  const partitionId = `module_partition_${attemptId}`;
  const runnerPage: TavernMemoryCorePage = {
    page_id: pageId,
    records: [
      {
        record_id: provenanceId,
        record_kind: "module_attempt_provenance",
        payload: asJsonValue({
          version: TAVERN_MEMORY_MODULE_RUNNER_VERSION,
          attempt_id: attemptId,
          attempt_kind: request.attempt_kind,
          batch_id: running.batch_id,
          module_id: request.input.module_id,
          source_revision_id: request.input.source_revision_id,
          requested_model_id: request.requested_model_id,
          prompt_asset_refs: request.prompt.prompt_asset_refs,
          output_schema: request.prompt.output_json_schema.name,
          response_sha256: responseHash,
          response_utf8_bytes: utf8ByteLength(combinedContent),
          accepted_record_count: partition.accepted_record_keys.length,
          pending_target_count: partition.pending_target_ids.length,
        }),
      },
      {
        record_id: partitionId,
        record_kind: "module_candidate_partition",
        payload: asJsonValue(partition),
      },
    ],
  };
  const batch = settleTavernMemoryModuleAttempt(running, request.input.module_id, {
    accepted_record_ids: prepared.accepted_record_ids,
    pending_target_ids: partition.pending_target_ids,
    error_code: partition.complete ? null : "MODULE_TARGETS_PENDING",
    partition_page_id: pageId,
    last_attempt_page_id: pageId,
  });
  const settledAt = request.now();
  const settledHead = await commitHead(request.book_store, startedHead, {
    commit_id: `${request.operation_id}:settled`,
    committed_at: settledAt,
    work_state: batch,
    audit: {
      at: settledAt,
      batch_id: batch.batch_id,
      module_id: request.input.module_id,
      event: partition.complete ? "module_committed" : "module_needs_user",
      error_code: partition.complete ? null : "MODULE_TARGETS_PENDING",
    },
    core_pages: [runnerPage, ...prepared.core_pages],
    module_view_pages: prepared.module_view_pages,
    prepared,
  });
  return {
    runner_version: TAVERN_MEMORY_MODULE_RUNNER_VERSION,
    status: partition.complete ? "MODULE_COMMITTED" : "NEEDS_USER",
    provider_dispatched: true,
    model_call_increment: 1,
    batch,
    head: settledHead,
    partition,
    error_code: partition.complete ? null : "MODULE_TARGETS_PENDING",
    incomplete_content: null,
  };
}

/**
 * Executes base + bounded transport retries + at most one automatic targeted
 * repair. It never loops on success or silently consumes a second repair.
 */
export async function runTavernMemoryModuleWithRecovery(
  request: TavernMemoryModuleRecoveryRunRequest,
): Promise<TavernMemoryModuleRecoveryRunResult> {
  const attempts: TavernMemoryModuleRunResult[] = [];
  let current = await runTavernMemoryModuleAttempt({
    ...request,
    attempt_kind: "base",
    operation_id: `${request.operation_id_prefix}:base`,
  });
  attempts.push(current);
  for (
    let retry = 1;
    current.status === "PROVIDER_FAILED" && retry <= request.attempt_limits.max_transport_retries;
    retry += 1
  ) {
    current = await runTavernMemoryModuleAttempt({
      ...request,
      attempt_kind: "transport_retry",
      operation_id: `${request.operation_id_prefix}:transport:${retry}`,
    });
    attempts.push(current);
  }
  if (request.continuation_prompt !== undefined && request.attempt_limits.max_continuations > 0) {
    for (
      let continuation = 1;
      current.status === "JSON_FAILED" &&
      current.incomplete_content !== null &&
      continuation <= request.attempt_limits.max_continuations;
      continuation += 1
    ) {
      const prefix = current.incomplete_content;
      current = await runTavernMemoryModuleAttempt({
        ...request,
        prompt: {
          ...request.prompt,
          messages: [
            ...request.prompt.messages,
            { role: "assistant", content: prefix },
            { role: "user", content: request.continuation_prompt.body },
          ],
          prompt_asset_refs: [
            ...request.prompt.prompt_asset_refs,
            request.continuation_prompt.prompt_asset_ref,
          ],
        },
        attempt_kind: "continuation",
        operation_id: `${request.operation_id_prefix}:continuation:${continuation}`,
        response_prefix: prefix,
      });
      attempts.push(current);
    }
  }
  const repairable =
    current.status === "NEEDS_USER" ||
    current.status === "JSON_FAILED" ||
    current.status === "MODULE_SHELL_FAILED";
  if (
    repairable &&
    request.automatic_targeted_repair &&
    request.attempt_limits.max_targeted_repairs === 1
  ) {
    const prior = current.partition ?? undefined;
    current = await runTavernMemoryModuleAttempt({
      ...request,
      prompt: prior === undefined ? request.prompt : request.repair_prompt(prior),
      attempt_kind: "targeted_repair",
      operation_id: `${request.operation_id_prefix}:targeted:1`,
      ...(prior === undefined ? {} : { prior_partition: prior }),
    });
    attempts.push(current);
  }
  return {
    attempts,
    final: current,
    model_call_increment: attempts.reduce((sum, attempt) => sum + attempt.model_call_increment, 0),
  };
}
