import type {
  CandidateEvidenceQuote,
  CandidatePrincipalRef,
  EvidenceItem,
  NarraMemId,
  NarrativeExtractionCandidateBatch,
  NarrativeIncrementalCausalEndpointRef,
  NarrativeIncrementalExistingSemanticContext,
  NarrativeIncrementalExtractionCandidateBatch,
} from "@narramem/core-domain";

import {
  type ExtractionCandidateIssue,
  type ExtractionCandidateValidationContext,
  validateNarrativeExtractionCandidateBatch,
} from "./validate-extraction.js";
import { validateWireValue } from "./wire-schema-registry.js";

export interface NarrativeIncrementalCandidateValidationContext
  extends ExtractionCandidateValidationContext {
  readonly novel_evidence_ids: readonly NarraMemId<"evidence">[];
  readonly existing_semantic_context: NarrativeIncrementalExistingSemanticContext;
}

export interface NarrativeIncrementalCandidateValidationReport {
  readonly validator_version: "0.1.0";
  readonly accepted: boolean;
  readonly issues: readonly ExtractionCandidateIssue[];
}

function issue(code: string, path: string, message: string): ExtractionCandidateIssue {
  return { code, path, message };
}

function quoteOccurrenceExists(text: string, quote: string, requestedOccurrence: number): boolean {
  let searchFrom = 0;
  let occurrence = 0;
  while (searchFrom <= text.length) {
    const index = text.indexOf(quote, searchFrom);
    if (index < 0) return false;
    if (occurrence === requestedOccurrence) return true;
    occurrence += 1;
    searchFrom = index + Math.max(1, quote.length);
  }
  return false;
}

function validateEvidenceQuote(
  quote: CandidateEvidenceQuote,
  path: string,
  evidenceById: ReadonlyMap<string, EvidenceItem>,
  activeRevisionId: NarraMemId<"source_revision">,
): ExtractionCandidateIssue[] {
  const evidence = evidenceById.get(quote.evidence_id);
  if (evidence === undefined || evidence.revision_id !== activeRevisionId) {
    return [
      issue(
        "INCREMENTAL_CANDIDATE_EVIDENCE_NOT_CURRENT",
        path,
        "Incremental candidates may only quote supplied Evidence in the active revision",
      ),
    ];
  }
  if (evidence.raw_content.kind !== "text") {
    return [
      issue(
        "INCREMENTAL_CANDIDATE_QUOTE_REQUIRES_TEXT",
        path,
        "Incremental text quotes require text Evidence",
      ),
    ];
  }
  if (!quoteOccurrenceExists(evidence.raw_content.text, quote.quote, quote.occurrence ?? 0)) {
    return [
      issue(
        "INCREMENTAL_CANDIDATE_QUOTE_NOT_FOUND",
        path,
        "Incremental candidate quotes must exactly match supplied Evidence",
      ),
    ];
  }
  return [];
}

function endpointKey(reference: NarrativeIncrementalCausalEndpointRef): string {
  if (reference.kind === "event") return `event:${reference.event_candidate_key}`;
  if (reference.kind === "state_delta") return `state:${reference.state_candidate_key}`;
  if (reference.kind === "epistemic_state") {
    return `epistemic:${reference.epistemic_candidate_key}`;
  }
  if (reference.kind === "existing_event") return `event:${reference.event_id}`;
  if (reference.kind === "existing_state_delta") return `state:${reference.delta_id}`;
  return `epistemic:${reference.epistemic_id}`;
}

function candidateEvidenceIds(batch: NarrativeIncrementalExtractionCandidateBatch): readonly {
  readonly path: string;
  readonly direct_support_ids: readonly NarraMemId<"evidence">[];
}[] {
  return [
    ...batch.entities.map((candidate, index) => ({
      path: `/entities/${index}/evidence_quotes`,
      direct_support_ids: candidate.evidence_quotes.flatMap((quote) =>
        quote.support_role === "direct" ? [quote.evidence_id] : [],
      ),
    })),
    ...batch.scenes.map((candidate, index) => ({
      path: `/scenes/${index}/source_evidence_ids`,
      direct_support_ids: candidate.source_evidence_ids,
    })),
    ...batch.events.map((candidate, index) => ({
      path: `/events/${index}/evidence_quotes`,
      direct_support_ids: candidate.evidence_quotes.flatMap((quote) =>
        quote.support_role === "direct" ? [quote.evidence_id] : [],
      ),
    })),
    ...batch.state_transitions.map((candidate, index) => ({
      path: `/state_transitions/${index}/evidence_quotes`,
      direct_support_ids: candidate.evidence_quotes.flatMap((quote) =>
        quote.support_role === "direct" ? [quote.evidence_id] : [],
      ),
    })),
    ...batch.epistemic_states.map((candidate, index) => ({
      path: `/epistemic_states/${index}/evidence_quotes`,
      direct_support_ids: candidate.evidence_quotes.flatMap((quote) =>
        quote.support_role === "direct" ? [quote.evidence_id] : [],
      ),
    })),
    ...batch.causal_links.map((candidate, index) => ({
      path: `/causal_links/${index}/evidence_quotes`,
      direct_support_ids: candidate.evidence_quotes.flatMap((quote) =>
        quote.support_role === "direct" ? [quote.evidence_id] : [],
      ),
    })),
  ];
}

function validateAttributionHolder(
  holder: CandidatePrincipalRef,
  path: string,
  entityKeys: ReadonlySet<string>,
  knownEntityIds: ReadonlySet<string>,
): ExtractionCandidateIssue[] {
  if (holder.kind === "candidate_entity" && !entityKeys.has(holder.candidate_key)) {
    return [
      issue(
        "INCREMENTAL_CANDIDATE_ENTITY_REF_UNKNOWN",
        path,
        "Causal attribution candidate entities must resolve in the same chunk",
      ),
    ];
  }
  if (
    holder.kind === "existing_principal" &&
    holder.principal.kind === "entity" &&
    !knownEntityIds.has(holder.principal.entity_id)
  ) {
    return [
      issue(
        "INCREMENTAL_EXISTING_ENTITY_REF_UNKNOWN",
        path,
        "Causal attribution existing entities must be in the trusted entity catalog",
      ),
    ];
  }
  return [];
}

/**
 * Validates one bounded candidate batch. All newly authored semantic records must
 * touch novel Evidence, and cross-chunk causal endpoints must be in the exact
 * authenticated context supplied by the trusted Runner.
 */
export function validateNarrativeIncrementalExtractionCandidateBatch(
  value: unknown,
  context: NarrativeIncrementalCandidateValidationContext,
): NarrativeIncrementalCandidateValidationReport {
  const schemaResult = validateWireValue("narrative_incremental_extraction_candidate_batch", value);
  if (!schemaResult.valid) {
    const details = schemaResult.errors
      .slice(0, 12)
      .map((error) => `${error.instancePath || "/"} ${error.message ?? "is invalid"}`)
      .join("; ");
    return {
      validator_version: "0.1.0",
      accepted: false,
      issues: [issue("INCREMENTAL_CANDIDATE_SCHEMA_INVALID", "/", details)],
    };
  }

  const batch = value as NarrativeIncrementalExtractionCandidateBatch;
  const baseBatch: NarrativeExtractionCandidateBatch = {
    contract_version: "0.3.0",
    source_revision_id: batch.source_revision_id,
    entities: batch.entities,
    scenes: batch.scenes,
    events: batch.events,
    state_transitions: batch.state_transitions,
    epistemic_states: batch.epistemic_states,
    causal_links: [],
    unresolved_items: [],
  };
  const baseReport = validateNarrativeExtractionCandidateBatch(baseBatch, context);
  const issues: ExtractionCandidateIssue[] = [...baseReport.issues];
  const evidenceById = new Map(context.evidence_items.map((item) => [item.evidence_id, item]));
  const novelEvidenceIds = new Set<string>(context.novel_evidence_ids);
  const knownEntityIds = new Set<string>(context.known_entity_ids);
  const entityKeys = new Set(batch.entities.map((candidate) => candidate.candidate_key));
  const eventKeys = new Set(batch.events.map((candidate) => candidate.candidate_key));
  const stateKeys = new Set(batch.state_transitions.map((candidate) => candidate.candidate_key));
  const epistemicKeys = new Set(batch.epistemic_states.map((candidate) => candidate.candidate_key));
  const existingEventIds = new Set(
    context.existing_semantic_context.events.map((record) => record.event_id),
  );
  const existingDeltaIds = new Set(
    context.existing_semantic_context.state_deltas.map((record) => record.delta_id),
  );
  const existingEpistemicIds = new Set(
    context.existing_semantic_context.epistemic_states.map((record) => record.epistemic_id),
  );

  for (const [index, evidenceId] of context.novel_evidence_ids.entries()) {
    const evidence = evidenceById.get(evidenceId);
    if (evidence === undefined || evidence.revision_id !== context.active_revision_id) {
      issues.push(
        issue(
          "INCREMENTAL_NOVEL_EVIDENCE_NOT_CURRENT",
          `/validation_context/novel_evidence_ids/${index}`,
          "The novel Evidence whitelist must be a subset of supplied active-revision Evidence",
        ),
      );
    }
  }

  for (const candidate of candidateEvidenceIds(batch)) {
    if (!candidate.direct_support_ids.some((evidenceId) => novelEvidenceIds.has(evidenceId))) {
      issues.push(
        issue(
          "INCREMENTAL_NOVEL_SUPPORT_MISSING",
          candidate.path,
          "Every new semantic record must have direct support from at least one Evidence item in the novel chunk",
        ),
      );
    }
  }

  const allKeys = [
    ...batch.entities.map((candidate) => candidate.candidate_key),
    ...batch.scenes.map((candidate) => candidate.candidate_key),
    ...batch.events.map((candidate) => candidate.candidate_key),
    ...batch.state_transitions.map((candidate) => candidate.candidate_key),
    ...batch.epistemic_states.map((candidate) => candidate.candidate_key),
    ...batch.causal_links.map((candidate) => candidate.candidate_key),
  ];
  if (new Set(allKeys).size !== allKeys.length) {
    issues.push(
      issue(
        "INCREMENTAL_CANDIDATE_KEY_DUPLICATE",
        "/",
        "Candidate keys must be unique across all incremental semantic kinds",
      ),
    );
  }

  const validateEndpoint = (
    reference: NarrativeIncrementalCausalEndpointRef,
    path: string,
  ): void => {
    const valid =
      (reference.kind === "event" && eventKeys.has(reference.event_candidate_key)) ||
      (reference.kind === "state_delta" && stateKeys.has(reference.state_candidate_key)) ||
      (reference.kind === "epistemic_state" &&
        epistemicKeys.has(reference.epistemic_candidate_key)) ||
      (reference.kind === "existing_event" && existingEventIds.has(reference.event_id)) ||
      (reference.kind === "existing_state_delta" && existingDeltaIds.has(reference.delta_id)) ||
      (reference.kind === "existing_epistemic_state" &&
        existingEpistemicIds.has(reference.epistemic_id));
    if (!valid) {
      issues.push(
        issue(
          "INCREMENTAL_CAUSAL_ENDPOINT_UNKNOWN",
          path,
          "Causal endpoints must resolve in the current chunk or authenticated semantic context",
        ),
      );
    }
  };

  batch.causal_links.forEach((candidate, index) => {
    const path = `/causal_links/${index}`;
    if (candidate.support_level !== "explicit") {
      issues.push(
        issue(
          "INCREMENTAL_CAUSAL_NOT_EXPLICIT",
          `${path}/support_level`,
          "Incremental Tavern causal candidates must be explicitly stated",
        ),
      );
    }
    if (candidate.mechanism.trim().length < 8) {
      issues.push(
        issue(
          "INCREMENTAL_CAUSAL_MECHANISM_INSUFFICIENT",
          `${path}/mechanism`,
          "An incremental causal candidate must explain its supported mechanism",
        ),
      );
    }
    if (
      !candidate.evidence_quotes.some(
        (quote) => quote.support_role === "direct" && novelEvidenceIds.has(quote.evidence_id),
      )
    ) {
      issues.push(
        issue(
          "INCREMENTAL_CAUSAL_NOVEL_DIRECT_SUPPORT_MISSING",
          `${path}/evidence_quotes`,
          "A cross-chunk causal claim requires an exact direct-support quote from novel Evidence",
        ),
      );
    }
    candidate.evidence_quotes.forEach((quote, quoteIndex) => {
      issues.push(
        ...validateEvidenceQuote(
          quote,
          `${path}/evidence_quotes/${quoteIndex}`,
          evidenceById,
          context.active_revision_id,
        ),
      );
    });
    candidate.cause_refs.forEach((reference, refIndex) => {
      validateEndpoint(reference, `${path}/cause_refs/${refIndex}`);
    });
    candidate.effect_refs.forEach((reference, refIndex) => {
      validateEndpoint(reference, `${path}/effect_refs/${refIndex}`);
    });
    const causeKeys = new Set(candidate.cause_refs.map(endpointKey));
    if (candidate.effect_refs.some((reference) => causeKeys.has(endpointKey(reference)))) {
      issues.push(
        issue(
          "INCREMENTAL_CAUSAL_SELF_LOOP",
          path,
          "The same semantic record cannot be both cause and effect in one CausalLink",
        ),
      );
    }
    if (candidate.attribution.kind === "character_belief") {
      issues.push(
        ...validateAttributionHolder(
          candidate.attribution.holder,
          `${path}/attribution/holder`,
          entityKeys,
          knownEntityIds,
        ),
      );
    }
  });

  const allKeySet = new Set(allKeys);
  batch.unresolved_items.forEach((item, index) => {
    item.evidence_ids.forEach((evidenceId, evidenceIndex) => {
      const evidence = evidenceById.get(evidenceId);
      if (evidence === undefined || evidence.revision_id !== context.active_revision_id) {
        issues.push(
          issue(
            "INCREMENTAL_UNRESOLVED_EVIDENCE_UNKNOWN",
            `/unresolved_items/${index}/evidence_ids/${evidenceIndex}`,
            "Unresolved items may only cite supplied active-revision Evidence",
          ),
        );
      }
    });
    item.related_candidate_keys.forEach((candidateKey, keyIndex) => {
      if (!allKeySet.has(candidateKey)) {
        issues.push(
          issue(
            "INCREMENTAL_UNRESOLVED_CANDIDATE_UNKNOWN",
            `/unresolved_items/${index}/related_candidate_keys/${keyIndex}`,
            "Unresolved candidate references must resolve in the same chunk",
          ),
        );
      }
    });
  });

  return { validator_version: "0.1.0", accepted: issues.length === 0, issues };
}
