export interface TavernWindowMessage {
  readonly role: "system" | "assistant" | "user";
}

/**
 * Returns the start of the continuous context window containing the latest N AI
 * floors. The boundary rewinds from the oldest protected AI to its nearest
 * preceding user message, so a user→AI turn or a group reply chain is never cut.
 */
export function findTavernProtectedWindowStartIndex(
  messages: readonly TavernWindowMessage[],
  latestAiCount: number,
): number {
  if (!Number.isInteger(latestAiCount) || latestAiCount < 1) {
    throw new TypeError("latestAiCount must be a positive integer");
  }
  let remaining = latestAiCount;
  let oldestProtectedAi = -1;
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if (messages[index]?.role !== "assistant") continue;
    remaining -= 1;
    if (remaining === 0) {
      oldestProtectedAi = index;
      break;
    }
  }
  if (oldestProtectedAi < 0) return 0;
  for (let index = oldestProtectedAi - 1; index >= 0; index -= 1) {
    if (messages[index]?.role === "user") return index;
  }
  return 0;
}
