import type {
  AuthorizedChangeSet,
  CausalLink,
  EffectCandidate,
  Entity,
  Episode,
  EventAtom,
  FlatLifecycleTransitionRef,
  FutureImpact,
  FutureImpactState,
  HashDigest,
  ImpactDirection,
  ImpactPriority,
  ModelChangeSetProposal,
  NarraMemId,
  NarrativeThread,
  NarrativeThreadKind,
  NarrativeThreadState,
  StateAssertion,
  StateDelta,
  TriggerRule,
  ValidationReport,
} from "@narramem/core-domain";
import type { TavernIncrementalSemanticCoveragePayload } from "./incremental-semantic-coverage-contracts.js";
import type { TavernSemanticExtractorDescriptor } from "./semantic-archive-contracts.js";
import type {
  TavernSemanticMetadataNormalizer,
  TavernSourceSnapshot,
} from "./source-snapshot-contracts.js";
import type {
  TavernArchiveRecord,
  TavernControlPayload,
  TavernDurableCommitPhase,
} from "./worldbook-store-contracts.js";

export const TAVERN_NARRATIVE_LIFECYCLE_LEGACY_VERSION = "0.1.0" as const;
export const TAVERN_NARRATIVE_LIFECYCLE_VERSION = "0.2.0" as const;
export const TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_ID =
  "narrative_lifecycle_manifest" as const;
export const TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_KIND =
  "narrative_lifecycle_manifest_v1" as const;
export const TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_LEGACY_VERSION = "0.1.0" as const;
export const TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION = "0.2.0" as const;
export const TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_ID =
  "narrative_lifecycle_continuity_baseline" as const;
export const TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_KIND =
  "narrative_lifecycle_continuity_baseline_v1" as const;

interface TavernNarrativeLifecycleContinuityBaselineBase {
  readonly memory_set_id: string;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly source_checksum: string;
  readonly narrative_thread_count: number;
  readonly future_impact_count: number;
}

export interface TavernNarrativeLifecycleContinuityBaselineLegacyPayload
  extends TavernNarrativeLifecycleContinuityBaselineBase {
  readonly version: typeof TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_LEGACY_VERSION;
}

export interface TavernNarrativeLifecycleContinuityBaselineV020Payload
  extends TavernNarrativeLifecycleContinuityBaselineBase {
  readonly version: typeof TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION;
  readonly previous_source_max_ordinal: number | null;
  readonly narrative_threads: readonly NarrativeThread[];
  readonly future_impacts: readonly FutureImpact[];
  readonly semantic_events: readonly EventAtom[];
  readonly semantic_state_deltas: readonly StateDelta[];
}

export type TavernNarrativeLifecycleContinuityBaselinePayload =
  | TavernNarrativeLifecycleContinuityBaselineLegacyPayload
  | TavernNarrativeLifecycleContinuityBaselineV020Payload;

export interface TavernThreadLifecycleSpec {
  readonly spec_key: string;
  readonly kind: NarrativeThreadKind;
  readonly title: string;
  readonly participant_ids: readonly NarraMemId<"entity">[];
  readonly opened_by: readonly NarraMemId<"event">[];
  readonly initial_state: "open" | "armed";
  readonly expected_payoff?: string;
  readonly trigger_rules: readonly TriggerRule[];
}

export interface TavernFutureImpactLifecycleSpec {
  readonly spec_key: string;
  readonly origin_refs: FutureImpact["origin_refs"];
  readonly target_refs: FutureImpact["target_refs"];
  readonly initial_state: "candidate" | "armed";
  readonly trigger: TriggerRule;
  readonly possible_effects: readonly EffectCandidate[];
  readonly direction: ImpactDirection;
  readonly priority: ImpactPriority;
  readonly expires_when?: TriggerRule;
}

export interface TavernPriorThreadDispositionSpec {
  readonly prior_thread_id: NarraMemId<"narrative_thread">;
  readonly next_state: NarrativeThreadState;
  readonly transition_event_ids: readonly NarraMemId<"event">[];
}

export interface TavernPriorFutureImpactDispositionSpec {
  readonly prior_impact_id: NarraMemId<"future_impact">;
  readonly next_state: FutureImpactState;
  readonly transition_refs: readonly FlatLifecycleTransitionRef[];
}

/** Trusted, ID-resolved compiler output. Raw model output cannot be committed as this type. */
export interface TavernNarrativeLifecycleSpec {
  readonly contract_version: typeof TAVERN_NARRATIVE_LIFECYCLE_VERSION;
  readonly spec_id: string;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly prior_thread_dispositions: readonly TavernPriorThreadDispositionSpec[];
  readonly prior_future_impact_dispositions: readonly TavernPriorFutureImpactDispositionSpec[];
  readonly threads: readonly TavernThreadLifecycleSpec[];
  readonly future_impacts: readonly TavernFutureImpactLifecycleSpec[];
}

export interface TavernNarrativeLifecycleModelInput {
  readonly contract_version: typeof TAVERN_NARRATIVE_LIFECYCLE_VERSION;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly append_evidence_boundary_ordinal: number | null;
  readonly prior_threads: readonly NarrativeThread[];
  readonly prior_future_impacts: readonly FutureImpact[];
  readonly entities: readonly Entity[];
  readonly events: readonly EventAtom[];
  readonly episodes: readonly Episode[];
  readonly state_assertions: readonly StateAssertion[];
  readonly state_deltas: readonly StateDelta[];
  readonly causal_links: readonly CausalLink[];
}

export interface TavernNarrativeLifecycleTask {
  readonly task_version: typeof TAVERN_NARRATIVE_LIFECYCLE_VERSION;
  readonly task_fingerprint: string;
  readonly memory_set_id: string;
  readonly control_book_name: string;
  readonly identity_anchor: TavernControlPayload["identity_anchor"];
  readonly control_checksum: string;
  readonly commit_sequence: number;
  readonly active_view_id: string;
  readonly source_snapshot: TavernSourceSnapshot;
  readonly semantic_changeset_id: NarraMemId<"change_set">;
  readonly active_records: readonly TavernArchiveRecord[];
  readonly model_input: TavernNarrativeLifecycleModelInput;
  readonly existing_manifest: TavernNarrativeLifecycleManifestPayload | null;
  readonly continuity_baseline: TavernNarrativeLifecycleContinuityBaselinePayload | null;
  readonly incremental_coverage: TavernIncrementalSemanticCoveragePayload | null;
  readonly normalize_semantic_metadata?: TavernSemanticMetadataNormalizer;
}

export interface TavernNarrativeLifecycleCommitRequest {
  readonly task: TavernNarrativeLifecycleTask;
  readonly spec: TavernNarrativeLifecycleSpec;
  readonly extractor: TavernSemanticExtractorDescriptor;
  readonly compiled_at: string;
  readonly writer_id: string;
  readonly transaction_id: string;
  readonly build_id: string;
  readonly view_id: string;
  readonly after_durable_phase?: (phase: TavernDurableCommitPhase) => void | Promise<void>;
}

export interface TavernNarrativeLifecycleManifestPayload {
  readonly version:
    | typeof TAVERN_NARRATIVE_LIFECYCLE_LEGACY_VERSION
    | typeof TAVERN_NARRATIVE_LIFECYCLE_VERSION;
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly source_checksum: string;
  readonly semantic_changeset_id: NarraMemId<"change_set">;
  readonly spec_checksum: string;
  readonly lifecycle_changeset_id: NarraMemId<"change_set">;
  readonly model_id: string;
  readonly model_identity_assurance: "requested_not_attested";
  readonly prompt_contract_version: string;
  readonly prompt_body_sha256: HashDigest;
  readonly parameters_hash: HashDigest;
  readonly validator_version: string;
}

export interface TavernNarrativeLifecycleCommitResult {
  readonly control: TavernControlPayload;
  readonly proposal: ModelChangeSetProposal;
  readonly validation_report: ValidationReport & { readonly accepted: true };
  readonly authorized_changeset: AuthorizedChangeSet;
  readonly narrative_thread_count: number;
  readonly future_impact_count: number;
  readonly incremental_coverage: TavernIncrementalSemanticCoveragePayload | null;
}

export class TavernNarrativeLifecycleError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "MEMORY_SET_NOT_EXACT"
      | "NO_SEMANTIC_SOURCE"
      | "STALE_TASK"
      | "PROPOSAL_REJECTED"
      | "LIFECYCLE_CONTINUITY_UNEXPLAINED"
      | "SOURCE_CHANGED_DURING_COMMIT",
    message: string,
  ) {
    super(message);
    this.name = "TavernNarrativeLifecycleError";
  }
}
