const SEMANTIC_SCHEMAS = new Map<string, Parameters<typeof validateWireValue>[0]>([
  ["core_entity_v1", "entity"],
  ["core_scene_v1", "scene"],
  ["core_episode_v1", "episode"],
  ["core_event_v1", "event_atom"],
  ["core_state_assertion_v1", "state_assertion"],
  ["core_state_delta_v1", "state_delta"],
  ["core_proposition_v1", "proposition"],
  ["core_epistemic_state_v1", "epistemic_state"],
  ["core_causal_link_v1", "causal_link"],
  ["core_current_state_view_v1", "current_state_view"],
]);

const TERMINAL_THREAD_STATES = new Set(["resolved", "failed", "abandoned", "superseded"]);
const TERMINAL_IMPACT_STATES = new Set(["realized", "expired", "cancelled", "superseded"]);

const asJsonValue = (value: unknown): TavernJsonValue => {
  canonicalJson(value);
  return value as TavernJsonValue;
};

function derivedRecordId(record: DerivedRecord): NarraMemId {
  const value = record as unknown as Readonly<Record<string, unknown>>;
  for (const field of [
    "entity_id",
    "scene_id",
    "episode_id",
    "event_id",
    "assertion_id",
    "delta_id",
    "epistemic_id",
    "proposition_id",
    "causal_id",
    "view_id",
    "thread_id",
    "impact_id",
  ]) {
    if (getNarraMemIdKind(value[field]) !== undefined) return value[field] as NarraMemId;
  }
  throw new TypeError("Final record has no typed NarraMem ID");
}

const semanticKind = (record: NarrativeIncrementalSemanticRecord): string =>
  `core_${getNarraMemIdKind(derivedRecordId(record))}_v1`;

function assertWire(name: Parameters<typeof validateWireValue>[0], value: unknown): void {
  const report = validateWireValue(name, value);
  if (!report.valid) {
    throw new TypeError(
      `${name} failed Core wire schema: ${report.errors[0]?.message ?? "unknown"}`,
    );
  }
}

function assertRequest(request: TavernMemoryBatchFinalizationRequest): void {
  if (
    request.memory_set_id.trim().length === 0 ||
    request.operation_id.trim().length === 0 ||
    request.evidence_items.length === 0 ||
    request.novel_evidence_ids.length === 0 ||
    !Number.isInteger(request.max_records_per_page) ||
    request.max_records_per_page < 1 ||
    !Number.isInteger(request.max_page_utf8_bytes) ||
    request.max_page_utf8_bytes < 1024
  ) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Invalid batch finalization request");
  }
  const evidenceIds = new Set(request.evidence_items.map((item) => item.evidence_id));
  if (
    evidenceIds.size !== request.evidence_items.length ||
    request.evidence_items.some((item) => item.revision_id !== request.source_revision_id) ||
    request.novel_evidence_ids.some((id) => !evidenceIds.has(id))
  ) {
    throw new TavernMemoryBookError(
      "INVALID_INPUT",
      "Finalization Evidence Ledger is stale or incomplete",
    );
  }
  for (const evidence of request.evidence_items) assertWire("evidence_item", evidence);
  assertWire("memory_space", request.memory_space);
  assertWire("source_revision", request.source_revision);
  for (const entity of request.source_entities) assertWire("entity", entity);
  if (
    request.memory_space.memory_space_id !== request.memory_space_id ||
    request.memory_space.branch_id !== request.branch_id ||
    request.memory_space.active_source_revision_id !== request.source_revision_id ||
    request.source_revision.revision_id !== request.source_revision_id ||
    request.source_revision.memory_space_id !== request.memory_space_id ||
    request.source_revision.branch_id !== request.branch_id ||
    request.source_revision.snapshot_fingerprint.value !== request.source_snapshot.checksum ||
    request.source_snapshot.memory_set_id !== request.memory_set_id ||
    request.checkpoint_source_prefix.memory_set_id !== request.memory_set_id ||
    request.checkpoint_source_prefix.messages.length >= request.source_snapshot.messages.length
  ) {
    throw new TavernMemoryBookError(
      "INVALID_INPUT",
      "Core Source projection does not match finalization",
    );
  }
}

async function readCompletePartitions(
  store: TavernMemoryCheckpointStorePort,
  batch: TavernMemoryBatchWorkState,
) {
  const partitions = await Promise.all(
    TAVERN_MEMORY_MODULE_IDS.map(async (moduleId) => {
      if (batch.modules[moduleId].status !== "COMMITTED") {
        throw new TypeError(`${moduleId} is not durably committed`);
      }
      const partition = await readTavernMemoryModulePartition(store, batch, moduleId);
      if (partition === null || !partition.complete || partition.pending_target_ids.length > 0) {
        throw new TypeError(`${moduleId} has no complete cold-readable partition`);
      }
      return [moduleId, partition] as const;
    }),
  );
  return new Map(partitions);
}

async function readStableSemanticRecords(
  store: TavernMemoryCheckpointStorePort,
  head: TavernMemoryColdHead,
): Promise<readonly NarrativeIncrementalSemanticRecord[]> {
  const byId = new Map<string, NarrativeIncrementalSemanticRecord>();
  for (const pageId of head.checkpoint_index.core_page_ids) {
    const page = await store.readCorePage(pageId);
    for (const record of page.records) {
      const schema = SEMANTIC_SCHEMAS.get(record.record_kind);
      if (schema === undefined) continue;
      assertWire(schema, record.payload);
      const value = record.payload as unknown as NarrativeIncrementalSemanticRecord;
      if (derivedRecordId(value) !== record.record_id || byId.has(record.record_id)) {
        throw new TypeError(
          `Checkpoint semantic record ${record.record_id} is duplicated or misidentified`,
        );
      }
      byId.set(record.record_id, value);
    }
  }
  return [...byId.values()].sort((left, right) =>
    derivedRecordId(left).localeCompare(derivedRecordId(right)),
  );
}

function existingSemanticContext(records: readonly NarrativeIncrementalSemanticRecord[]) {
  const kind = (value: NarrativeIncrementalSemanticRecord) =>
    getNarraMemIdKind(derivedRecordId(value));
  const ofKind = <T extends NarrativeIncrementalSemanticRecord>(wanted: string): T[] =>
    records.filter((record) => kind(record) === wanted) as T[];
  return {
    scenes: ofKind<Scene>("scene"),
    episodes: ofKind<Episode>("episode"),
    events: ofKind<EventAtom>("event"),
    state_assertions: ofKind<StateAssertion>("state_assertion"),
    state_deltas: ofKind<StateDelta>("state_delta"),
    propositions: ofKind<Proposition>("proposition"),
    epistemic_states: ofKind<EpistemicState>("epistemic_state"),
    causal_links: ofKind<CausalLink>("causal_link"),
  };
}

function typedCandidateMaps(
  recordToCandidate: ReadonlyMap<string, string>,
): Readonly<Record<string, ReadonlyMap<string, NarraMemId>>> {
  const result = new Map<string, Map<string, NarraMemId>>();
  for (const [recordId, candidateKey] of recordToCandidate) {
    const kind = getNarraMemIdKind(recordId);
    if (kind === undefined) continue;
    const values = result.get(kind) ?? new Map<string, NarraMemId>();
    values.set(candidateKey, recordId as NarraMemId);
    result.set(kind, values);
  }
  return Object.fromEntries(result) as Readonly<Record<string, ReadonlyMap<string, NarraMemId>>>;
}

function resolveTyped(
  reference: string,
  allowedKinds: readonly string[],
  candidateMaps: Readonly<Record<string, ReadonlyMap<string, NarraMemId>>>,
): NarraMemId {
  const directKind = getNarraMemIdKind(reference);
  if (directKind !== undefined && allowedKinds.includes(directKind)) return reference as NarraMemId;
  for (const kind of allowedKinds) {
    const id = candidateMaps[kind]?.get(reference);
    if (id !== undefined) return id;
  }
  throw new TypeError(`Unresolved ${allowedKinds.join("/")} reference`);
}

function priorLifecycle(value: TavernJsonValue): {
  readonly threads: readonly NarrativeThread[];
  readonly impacts: readonly FutureImpact[];
} {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError("THREAD_IMPACT head is not an object");
  }
  const object = value as Readonly<Record<string, unknown>>;
  const threads = Array.isArray(object.threads) ? object.threads : [];
  const impacts = Array.isArray(object.impacts) ? object.impacts : [];
  for (const thread of threads) assertWire("narrative_thread", thread);
  for (const impact of impacts) assertWire("future_impact", impact);
  return { threads: threads as NarrativeThread[], impacts: impacts as FutureImpact[] };
}

async function lifecycleProjection(request: {
  readonly finalization: TavernMemoryBatchFinalizationRequest;
  readonly head: TavernMemoryColdHead;
  readonly batch: TavernMemoryBatchWorkState;
  readonly m7: ModularExtractionM7Output;
  readonly merged_records: readonly NarrativeIncrementalSemanticRecord[];
  readonly stable_records: readonly NarrativeIncrementalSemanticRecord[];
  readonly candidate_maps: Readonly<Record<string, ReadonlyMap<string, NarraMemId>>>;
}): Promise<{
  readonly threads: readonly NarrativeThread[];
  readonly impacts: readonly FutureImpact[];
  readonly proposal: ModelChangeSetProposal;
  readonly authorized: AuthorizedChangeSet;
}> {
  const prior = priorLifecycle(request.head.thread_impact);
  const activeThreads = prior.threads.filter((thread) => !TERMINAL_THREAD_STATES.has(thread.state));
  const activeImpacts = prior.impacts.filter((impact) => !TERMINAL_IMPACT_STATES.has(impact.state));
  const records = request.merged_records;
  const entities = records.filter((record): record is Entity => "entity_id" in record);
  const events = records.filter((record): record is EventAtom => "event_id" in record);
  const episodes = records.filter((record): record is Episode => "episode_id" in record);
  const assertions = records.filter((record): record is StateAssertion => "assertion_id" in record);
  const deltas = records.filter((record): record is StateDelta => "delta_id" in record);
  const causals = records.filter((record) => "causal_id" in record);
  const novel = new Set(request.finalization.novel_evidence_ids);
  const priorOrdinals = request.finalization.evidence_items
    .filter((item) => !novel.has(item.evidence_id))
    .map((item) => item.source_order.ordinal);
  const previousBoundary = priorOrdinals.length === 0 ? null : Math.max(...priorOrdinals);
  const hasContinuity =
    request.stable_records.length > 0 || prior.threads.length > 0 || prior.impacts.length > 0;
  const baseline: TavernNarrativeLifecycleContinuityBaselineV020Payload | null = hasContinuity
    ? {
        version: TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_VERSION,
        memory_set_id: request.finalization.memory_set_id,
        source_revision_id: request.finalization.source_revision_id,
        source_checksum: request.head.source_index.source_checksum,
        previous_source_max_ordinal: previousBoundary,
        narrative_thread_count: prior.threads.length,
        future_impact_count: prior.impacts.length,
        narrative_threads: prior.threads,
        future_impacts: prior.impacts,
        semantic_events: request.stable_records.filter(
          (record): record is EventAtom => "event_id" in record,
        ),
        semantic_state_deltas: request.stable_records.filter(
          (record): record is StateDelta => "delta_id" in record,
        ),
      }
    : null;
  const input: TavernNarrativeLifecycleModelInput = {
    contract_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
    source_revision_id: request.finalization.source_revision_id,
    append_evidence_boundary_ordinal: previousBoundary,
    prior_threads: activeThreads,
    prior_future_impacts: activeImpacts,
    entities,
    events,
    episodes,
    state_assertions: assertions,
    state_deltas: deltas,
    causal_links: causals,
  };
  assertWire("flat_narrative_lifecycle_model_input_v020", input);

  const suppliedThread = new Map(
    request.m7.prior_thread_dispositions.map((item) => [item.prior_thread_ref, item]),
  );
  const suppliedImpact = new Map(
    request.m7.prior_future_impact_dispositions.map((item) => [item.prior_impact_ref, item]),
  );
  const newThreadIds = new Map<string, NarraMemId<"narrative_thread">>();
  for (const thread of request.m7.threads) {
    newThreadIds.set(
      thread.candidate_key,
      await createTavernLifecycleThreadId(request.finalization.memory_set_id, thread.candidate_key),
    );
  }
  const maps = {
    ...request.candidate_maps,
    narrative_thread: new Map([
      ...activeThreads.map((thread) => [thread.thread_id, thread.thread_id] as const),
      ...newThreadIds,
    ]),
  };
  const resolve = (value: string, kinds: readonly string[]) => resolveTyped(value, kinds, maps);
  const spec: TavernNarrativeLifecycleSpec = {
    contract_version: TAVERN_NARRATIVE_LIFECYCLE_VERSION,
    spec_id: `${request.batch.batch_id}:M7`,
    source_revision_id: request.finalization.source_revision_id,
    prior_thread_dispositions: activeThreads.map((priorThread) => {
      const item = suppliedThread.get(priorThread.thread_id);
      return item === undefined
        ? {
            prior_thread_id: priorThread.thread_id,
            next_state: priorThread.state,
            transition_event_ids: [],
          }
        : {
            prior_thread_id: priorThread.thread_id,
            next_state: item.next_state,
            transition_event_ids: item.transition_event_refs.map(
              (ref) => resolve(ref, ["event"]) as NarraMemId<"event">,
            ),
          };
    }),
    prior_future_impact_dispositions: activeImpacts.map((priorImpact) => {
      const item = suppliedImpact.get(priorImpact.impact_id);
      return item === undefined
        ? {
            prior_impact_id: priorImpact.impact_id,
            next_state: priorImpact.state,
            transition_refs: [],
          }
        : {
            prior_impact_id: priorImpact.impact_id,
            next_state: item.next_state,
            transition_refs: item.transition_refs.map((ref) => {
              const id = resolve(ref, ["event", "state_delta"]);
              return getNarraMemIdKind(id) === "event"
                ? { kind: "event" as const, event_id: id as NarraMemId<"event"> }
                : { kind: "state_delta" as const, delta_id: id as NarraMemId<"state_delta"> };
            }),
          };
    }),
    threads: request.m7.threads.map((thread) => ({
      spec_key: thread.candidate_key,
      kind: thread.kind,
      title: thread.title,
      participant_ids: thread.participant_refs.map(
        (ref) => resolve(ref, ["entity"]) as NarraMemId<"entity">,
      ),
      opened_by: thread.opened_by_event_refs.map(
        (ref) => resolve(ref, ["event"]) as NarraMemId<"event">,
      ),
      initial_state: thread.initial_state,
      ...(thread.expected_payoff === undefined ? {} : { expected_payoff: thread.expected_payoff }),
      trigger_rules: [{ op: "semantic_cue", cue: thread.trigger_summary, strength: "soft" }],
    })),
    future_impacts: request.m7.future_impacts.map((impact) => ({
      spec_key: impact.candidate_key,
      origin_refs: impact.origin_refs.map((ref) =>
        resolve(ref, ["event", "state_delta", "narrative_thread"]),
      ) as FutureImpact["origin_refs"],
      target_refs: impact.target_refs.map(
        (ref) => resolve(ref, ["entity"]) as NarraMemId<"entity">,
      ),
      initial_state: impact.initial_state,
      trigger: { op: "semantic_cue", cue: impact.trigger_summary, strength: "soft" },
      possible_effects: impact.possible_effects.map((effect) => ({
        epistemic_status: "hypothetical",
        kind: effect.kind,
        description: effect.description,
        target_refs: effect.target_refs.map(
          (ref) => resolve(ref, ["entity"]) as NarraMemId<"entity">,
        ),
        ...(effect.state_key === undefined ? {} : { state_key: effect.state_key }),
        ...(effect.proposed_value === undefined ? {} : { proposed_value: effect.proposed_value }),
      })),
      direction: impact.direction,
      priority: impact.priority,
    })),
  };
  validateTavernNarrativeLifecycleSpec(spec, input);
  const projected = await projectTavernNarrativeLifecycleRecords(spec, input, {
    memory_set_id: request.finalization.memory_set_id,
    extractor: request.finalization.extractor,
    compiled_at: request.finalization.compiled_at,
    memory_space_id: request.finalization.memory_space_id,
    branch_id: request.finalization.branch_id,
    continuity_baseline: baseline,
  });
  const lifecycleChangesetId = await createDeterministicNarraMemId(
    "change_set",
    `tavern-memory-finalizer:${request.finalization.source_revision_id}:${request.batch.batch_id}:lifecycle`,
  );
  const proposal: ModelChangeSetProposal = {
    stage: "proposal",
    changeset_id: lifecycleChangesetId,
    memory_space_id: request.finalization.memory_space_id,
    branch_id: request.finalization.branch_id,
    based_on_revision_id: request.finalization.source_revision_id,
    producer: "hybrid",
    operations: [...projected.threads, ...projected.impacts].map((record) => ({
      op: "add_derived" as const,
      record,
    })),
    unresolved_items: [],
    created_at: request.finalization.compiled_at,
  };
  const semanticKnown = records.map((record) => ({
    record_id: derivedRecordId(record),
    memory_space_id: request.finalization.memory_space_id,
    branch_id: request.finalization.branch_id,
  }));
  const report = validateChangeSetProposal(proposal, {
    memory_space_id: request.finalization.memory_space_id,
    branch_id: request.finalization.branch_id,
    active_revision_id: request.finalization.source_revision_id,
    known_evidence_ids: request.finalization.evidence_items.map((item) => item.evidence_id),
    known_records: semanticKnown,
  });
  if (!report.accepted) {
    throw new TypeError(
      `Core Validator rejected lifecycle proposal: ${report.issues.map((item) => item.code).join(",")}`,
    );
  }
  const authorized: AuthorizedChangeSet = {
    stage: "authorized",
    changeset_id: proposal.changeset_id,
    memory_space_id: proposal.memory_space_id,
    branch_id: proposal.branch_id,
    based_on_revision_id: proposal.based_on_revision_id,
    producer: proposal.producer,
    operations: proposal.operations,
    validation_report: { ...report, accepted: true },
    authorization: {
      committer_version: `tavern-memory-batch-finalizer@${TAVERN_MEMORY_BATCH_FINALIZER_VERSION}`,
      policy_hash: createSha256Digest(
        await checksumJson({
          allowed_operations: ["add_derived"],
          batch_id: request.batch.batch_id,
        }),
      ),
      authorized_at: request.finalization.compiled_at,
    },
  };
  assertWire("authorized_change_set", authorized);
  return { ...projected, proposal, authorized };
}

function finalizationError(error: unknown): {
  readonly code: string;
  readonly targets: readonly string[];
} {
  if (error instanceof CandidateCompilationError) {
    return {
      code: error.codes[0] ?? "FINALIZER_COMPILER_FAILED",
      targets: [...new Set([...error.candidate_keys, ...error.record_ids])].slice(0, 64),
    };
  }
  if (error instanceof TavernMemoryBookError) return { code: error.code, targets: [] };
  if (
    error instanceof TypeError &&
    error.message.startsWith("Final checkpoint contains duplicate")
  ) {
    return {
      code: "FINALIZER_DUPLICATE_RECORD_ID",
      targets: [...error.message.matchAll(/(nm_[a-z_]+_[0-9a-f-]+)\[/gu)]
        .map((match) => match[1])
        .filter((target): target is string => target !== undefined)
        .slice(0, 64),
    };
  }
  if (error instanceof TypeError) {
    const page = /^Final checkpoint record page (\d+) exceeds/u.exec(error.message);
    if (page !== null) {
      return {
        code: "FINALIZER_PAGE_LIMIT_EXCEEDED",
        targets: page[1] === undefined ? [] : [`page:${page[1]}`],
      };
    }
    const wire = /^([a-z0-9_]+) failed Core wire schema:/u.exec(error.message);
    if (wire !== null) {
      return {
        code: "FINALIZER_WIRE_SCHEMA_FAILED",
        targets: wire[1] === undefined ? [] : [`schema:${wire[1]}`],
      };
    }
    for (const [prefix, code] of [
      ["Core Validator rejected final semantic proposal:", "FINALIZER_SEMANTIC_VALIDATION_FAILED"],
      ["Core Validator rejected lifecycle proposal:", "FINALIZER_LIFECYCLE_VALIDATION_FAILED"],
    ] as const) {
      if (error.message.startsWith(prefix)) {
        return {
          code,
          targets: error.message
            .slice(prefix.length)
            .split(",")
            .map((target) => target.trim())
            .filter((target) => /^[A-Z0-9_]+$/u.test(target))
            .slice(0, 64),
        };
      }
    }
    if (error.message.startsWith("Unresolved ")) {
      return { code: "FINALIZER_REFERENCE_UNRESOLVED", targets: [] };
    }
    if (error.message === "Final batch has no novel Evidence boundary") {
      return { code: "FINALIZER_EVIDENCE_BOUNDARY_MISSING", targets: [] };
    }
    if (error.message === "Final record has no typed NarraMem ID") {
      return { code: "FINALIZER_RECORD_ID_MISSING", targets: [] };
    }
  }
  return {
    code: error instanceof TypeError ? "FINALIZER_CONTRACT_FAILED" : "FINALIZER_FAILED",
    targets: [],
  };
}

async function packFinalPages(
  records: readonly FinalRecord[],
  request: TavernMemoryBatchFinalizationRequest,
  batchId: string,
): Promise<readonly TavernMemoryCorePage[]> {
  const chunks: FinalRecord[][] = [];
  let current: FinalRecord[] = [];
  for (const record of records) {
    const proposed = [...current, record];
    if (
      current.length > 0 &&
      (proposed.length > request.max_records_per_page ||
        utf8ByteLength(canonicalJson({ records: proposed })) > request.max_page_utf8_bytes)
    ) {
      chunks.push(current);
      current = [record];
    } else {
      current = proposed;
    }
  }
  if (current.length > 0) chunks.push(current);
  const pages = await Promise.all(
    chunks.map(async (chunk, index): Promise<TavernMemoryCorePage> => {
      const pageId = `checkpoint_page_${(
        await sha256HexUtf8(
          canonicalJson({
            memory_set_id: request.memory_set_id,
            source_revision_id: request.source_revision_id,
            batch_id: batchId,
            index,
            records: chunk,
          }),
        )
      ).slice(0, 40)}`;
      const page = { page_id: pageId, records: chunk };
      if (utf8ByteLength(canonicalJson(page)) > request.max_page_utf8_bytes) {
        throw new TypeError(`Final checkpoint record page ${index} exceeds the configured limit`);
      }
      return page;
    }),
  );
  return pages;
}

export async function readVerifiedTavernMemoryCheckpoint(
  store: TavernMemoryCheckpointStorePort,
  expectedCheckpointId?: string,
): Promise<TavernVerifiedMemoryCheckpoint> {
  const cold = await store.readColdHead();
  const head = cold.head;
  const checkpointId = expectedCheckpointId ?? head?.checkpoint_index.checkpoint_id;
  if (
    cold.status !== "READY" ||
    head === null ||
    checkpointId === null ||
    checkpointId === undefined ||
    head.checkpoint_index.checkpoint_id !== checkpointId
  ) {
    throw new TavernMemoryBookError(
      "VERIFY_FAILED",
      "Cold head did not expose the finalized checkpoint",
    );
  }
  const records = (
    await Promise.all(
      head.checkpoint_index.core_page_ids.map((pageId) => store.readCorePage(pageId)),
    )
  ).flatMap((page) => page.records);
  const manifestRecord = records.find(
    (record) =>
      record.record_kind === TAVERN_MEMORY_CHECKPOINT_MANIFEST_KIND &&
      record.record_id === `checkpoint_manifest:${checkpointId}`,
  );
  if (manifestRecord === undefined) {
    throw new TavernMemoryBookError("VERIFY_FAILED", "Final checkpoint manifest is missing");
  }
  const manifest = manifestRecord.payload as unknown as TavernMemoryCheckpointManifest;
  const body = records.filter((record) => record !== manifestRecord);
  if (
    manifest.version !== TAVERN_MEMORY_BATCH_FINALIZER_VERSION ||
    manifest.checkpoint_id !== checkpointId ||
    !Number.isInteger(manifest.source_message_count) ||
    manifest.source_message_count < 1 ||
    !Number.isInteger(manifest.source_snapshot_revision) ||
    manifest.source_snapshot_revision < 1 ||
    typeof manifest.source_scope?.character_id !== "string" ||
    typeof manifest.source_scope?.chat_id !== "string" ||
    !/^[a-f0-9]{64}$/u.test(manifest.source_root_chain_hash) ||
    getNarraMemIdKind(manifest.principal_entity_id) !== "entity" ||
    manifest.final_records_sha256 !== (await checksumJson(body)) ||
    canonicalJson(manifest.final_record_ids) !==
      canonicalJson(body.map((record) => record.record_id))
  ) {
    throw new TavernMemoryBookError(
      "VERIFY_FAILED",
      "Final checkpoint manifest does not match its pages",
    );
  }
  for (const record of body) {
    const schema = SEMANTIC_SCHEMAS.get(record.record_kind);
    if (schema !== undefined) assertWire(schema, record.payload);
    if (record.record_kind === "core_evidence_v1") assertWire("evidence_item", record.payload);
    if (record.record_kind === "core_narrative_thread_v1")
      assertWire("narrative_thread", record.payload);
    if (record.record_kind === "core_future_impact_v1") assertWire("future_impact", record.payload);
    if (record.record_kind === "core_authorized_changeset_v1") {
      assertWire("authorized_change_set", record.payload);
    }
    if (record.record_kind === "core_memory_space_v1") assertWire("memory_space", record.payload);
    if (record.record_kind === "core_source_revision_v1")
      assertWire("source_revision", record.payload);
  }
  return { head, manifest, records: body };
}

async function verifyCheckpoint(
  store: TavernMemoryCheckpointStorePort,
  expectedCheckpointId: string,
): Promise<TavernMemoryColdHead> {
  const head = (await readVerifiedTavernMemoryCheckpoint(store, expectedCheckpointId)).head;
  if (head.work_state?.status !== "CHECKPOINT_VERIFIED") {
    throw new TavernMemoryBookError(
      "VERIFY_FAILED",
      "Finalization commit did not expose CHECKPOINT_VERIFIED",
    );
  }
  return head;
}

async function commitFailure(
  request: TavernMemoryBatchFinalizationRequest,
  head: TavernMemoryColdHead,
  batch: TavernMemoryBatchWorkState,
  error: unknown,
): Promise<TavernMemoryBatchFinalizationResult> {
  const failure = finalizationError(error);
  const failedBatch: TavernMemoryBatchWorkState = {
    ...batch,
    finalization_error_code: failure.code,
    finalization_error_target_ids: failure.targets,
  };
  const committed = await request.book_store.commit({
    commit_id: `${request.operation_id}:finalization_failed:${head.generation}:${failure.code}`,
    expected_generation: head.generation,
    expected_generation_checksum: head.generation_checksum,
    committed_at: request.compiled_at,
    source_index: head.source_index,
    work_state: failedBatch,
    checkpoint_index: head.checkpoint_index,
    active_state: head.active_state,
    epistemic_state: head.epistemic_state,
    thread_impact: head.thread_impact,
    module_views: head.module_views,
    audit_ring: [
      ...head.audit_ring,
      {
        at: request.compiled_at,
        batch_id: batch.batch_id,
        module_id: null,
        event: "batch_finalization_failed",
        error_code: failure.code,
      },
    ],
    retained_core_page_ids: head.core_page_ids,
    retained_module_view_page_ids: head.module_view_page_ids,
    core_pages: [],
    module_view_pages: [],
  });
  return {
    finalizer_version: TAVERN_MEMORY_BATCH_FINALIZER_VERSION,
    status: "FINALIZATION_FAILED",
    head: committed,
    checkpoint_id: head.checkpoint_index.checkpoint_id,
    error_code: failure.code,
  };
}

/**
 * D8: cold-loads seven accepted module partitions, compiles one trusted graph,
 * commits it atomically, then cold-reads it before downstream Recall may proceed.
 */
export async function finalizeTavernMemoryBatch(
  request: TavernMemoryBatchFinalizationRequest,
): Promise<TavernMemoryBatchFinalizationResult> {
  assertRequest(request);
  await verifyTavernSourceSnapshot(request.source_snapshot);
  await verifyTavernSourceSnapshot(request.checkpoint_source_prefix);
  const prefixMessages = request.source_snapshot.messages.slice(
    0,
    request.checkpoint_source_prefix.messages.length,
  );
  if (
    request.checkpoint_source_prefix.scope.character_id !==
      request.source_snapshot.scope.character_id ||
    request.checkpoint_source_prefix.scope.chat_id !== request.source_snapshot.scope.chat_id ||
    canonicalJson(prefixMessages) !== canonicalJson(request.checkpoint_source_prefix.messages)
  ) {
    throw new TavernMemoryBookError(
      "INVALID_INPUT",
      "Checkpoint Source prefix is not an authenticated prefix of the active Source",
    );
  }
  const cold = await request.book_store.readColdHead();
  const head = cold.head;
  if (cold.status !== "READY" || head === null || head.work_state === null) {
    throw new TavernMemoryBookError("INVALID_INPUT", "Memory Book has no active batch");
  }
  const batch = head.work_state;
  if (
    head.memory_set_id !== request.memory_set_id ||
    batch.source_revision_id !== request.source_revision_id ||
    head.source_index.source_revision_id !== request.source_revision_id ||
    head.source_index.source_checksum !== request.source_snapshot.checksum ||
    !request.source_entities.some(
      (entity) =>
        entity.entity_id === request.principal_entity_id && entity.entity_type === "character",
    )
  ) {
    throw new TavernMemoryBookError(
      "INVALID_INPUT",
      "Finalization does not match the cold Memory Book head",
    );
  }
  if (batch.status === "CHECKPOINT_VERIFIED") {
    const checkpointId = head.checkpoint_index.checkpoint_id;
    if (checkpointId === null) {
      throw new TavernMemoryBookError("BOOK_CORRUPT", "Verified batch has no checkpoint");
    }
    return {
      finalizer_version: TAVERN_MEMORY_BATCH_FINALIZER_VERSION,
      status: "ALREADY_VERIFIED",
      head: await verifyCheckpoint(request.book_store, checkpointId),
      checkpoint_id: checkpointId,
      error_code: null,
    };
  }
  if (batch.status !== "FINALIZING") {
    throw new TavernMemoryBookError("INVALID_INPUT", `Batch ${batch.status} cannot be finalized`);
  }

  try {
    const partitions = await readCompletePartitions(request.book_store, batch);
    const m1 = partitions.get("M1")?.accepted_output as ModularExtractionM1Output;
    const m2 = partitions.get("M2")?.accepted_output as ModularExtractionM2Output;
    const m3 = partitions.get("M3")?.accepted_output as ModularExtractionM3Output;
    const m4 = partitions.get("M4")?.accepted_output as ModularExtractionM4Output;
    const m5 = partitions.get("M5")?.accepted_output as ModularExtractionM5Output;
    const m6 = partitions.get("M6")?.accepted_output as ModularExtractionM6Output;
    const m7 = partitions.get("M7")?.accepted_output as ModularExtractionM7Output;
    const candidateBatch: NarrativeIncrementalExtractionCandidateBatch = {
      contract_version: "0.1.0",
      source_revision_id: request.source_revision_id,
      entities: m1.entities,
      scenes: m2.scenes,
      events: m3.events,
      state_transitions: m4.state_transitions,
      epistemic_states: m5.epistemic_states,
      causal_links: m6.causal_links,
      unresolved_items: [],
    };
    const persistedStableRecords = await readStableSemanticRecords(request.book_store, head);
    const stableById = new Map(
      persistedStableRecords.map((record) => [derivedRecordId(record), record] as const),
    );
    for (const entity of request.source_entities) stableById.set(entity.entity_id, entity);
    const stableRecords = [...stableById.values()].sort((left, right) =>
      derivedRecordId(left).localeCompare(derivedRecordId(right)),
    );
    const context: NarrativeIncrementalCandidateCompilerContext = {
      memory_space_id: request.memory_space_id,
      branch_id: request.branch_id,
      compilation_key: `${request.operation_id}:${batch.batch_id}`,
      active_revision_id: request.source_revision_id,
      evidence_items: request.evidence_items,
      known_entity_ids: stableRecords
        .filter((record): record is Entity => "entity_id" in record)
        .map((record) => record.entity_id),
      extractor: request.extractor,
      novel_evidence_ids: request.novel_evidence_ids,
      existing_semantic_context: existingSemanticContext(stableRecords),
    };
    const compilerPorts = await createTavernDeterministicCompilerPorts(
      candidateBatch,
      context,
      request.compiled_at,
    );
    const compiled = await compileNarrativeIncrementalExtractionCandidateBatch(
      candidateBatch,
      context,
      compilerPorts,
    );
    const recordToCandidate = incrementalCandidateKeyByRecordId(
      candidateBatch,
      context,
      compilerPorts,
    );
    const candidateMaps = typedCandidateMaps(recordToCandidate);
    const compiledDerived = compiled.operations.flatMap((operation) =>
      operation.op === "add_derived" ? [operation.record] : [],
    );
    const episodes = await projectTavernSceneEpisodes({
      source_revision_id: request.source_revision_id,
      derived_records: compiledDerived,
      created_at: request.compiled_at,
      episode_anchors: m2.episodes,
      scene_id_by_candidate_key: candidateMaps.scene as ReadonlyMap<string, NarraMemId<"scene">>,
    });
    const chunkProposal: ModelChangeSetProposal = {
      ...compiled,
      operations: [
        ...compiled.operations,
        ...episodes.map((record) => ({ op: "add_derived" as const, record })),
      ],
    };
    const novelSet = new Set(request.novel_evidence_ids);
    const novelEvidence = request.evidence_items.filter((item) => novelSet.has(item.evidence_id));
    const orderedNovel = [...novelEvidence].sort(
      (left, right) =>
        left.source_order.ordinal - right.source_order.ordinal ||
        left.source_order.component - right.source_order.component,
    );
    const checkpoint = orderedNovel.at(-1)?.source_order;
    const replaceFromOrdinal = orderedNovel[0]?.source_order.ordinal;
    if (checkpoint === undefined || replaceFromOrdinal === undefined) {
      throw new TypeError("Final batch has no novel Evidence boundary");
    }
    const mergeKey = `${request.operation_id}:${batch.batch_id}:merge`;
    const mergePorts = await createTavernDeterministicMergePorts({
      source_revision_id: request.source_revision_id,
      stable_semantic_records: stableRecords,
      merge_key: mergeKey,
      compiled_at: request.compiled_at,
    });
    const merged = await mergeNarrativeIncrementalSemanticCorpus(
      {
        memory_space_id: request.memory_space_id,
        branch_id: request.branch_id,
        source_revision_id: request.source_revision_id,
        checkpoint,
        replace_from_ordinal: replaceFromOrdinal,
        stable_records: stableRecords,
        chunk_proposal: chunkProposal,
        current_evidence_items: request.evidence_items,
        merge_key: mergeKey,
      },
      mergePorts,
    );
    const finalSemanticRecords = merged.records.filter(
      (record) =>
        !(
          "view_id" in record &&
          record.derivation.evidence_refs.length === 0 &&
          record.derivation.dependency_refs.length === 0
        ),
    );
    const semanticProposal: ModelChangeSetProposal = {
      ...compiled,
      producer: "hybrid",
      operations: finalSemanticRecords.map((record) => ({ op: "add_derived" as const, record })),
    };
    const semanticReport = validateChangeSetProposal(semanticProposal, {
      memory_space_id: request.memory_space_id,
      branch_id: request.branch_id,
      active_revision_id: request.source_revision_id,
      known_evidence_ids: request.evidence_items.map((item) => item.evidence_id),
      known_records: [],
    });
    if (!semanticReport.accepted) {
      throw new TypeError(
        `Core Validator rejected final semantic proposal: ${semanticReport.issues.map((item) => item.code).join(",")}`,
      );
    }
    const semanticAuthorized: AuthorizedChangeSet = {
      stage: "authorized",
      changeset_id: semanticProposal.changeset_id,
      memory_space_id: semanticProposal.memory_space_id,
      branch_id: semanticProposal.branch_id,
      based_on_revision_id: semanticProposal.based_on_revision_id,
      producer: semanticProposal.producer,
      operations: semanticProposal.operations,
      validation_report: { ...semanticReport, accepted: true },
      authorization: {
        committer_version: `tavern-memory-batch-finalizer@${TAVERN_MEMORY_BATCH_FINALIZER_VERSION}`,
        policy_hash: createSha256Digest(
          await checksumJson({ allowed_operations: ["add_derived"], batch_id: batch.batch_id }),
        ),
        authorized_at: request.compiled_at,
      },
    };
    assertWire("authorized_change_set", semanticAuthorized);
    const lifecycle = await lifecycleProjection({
      finalization: request,
      head,
      batch,
      m7,
      merged_records: finalSemanticRecords,
      stable_records: stableRecords,
      candidate_maps: candidateMaps,
    });
    const bodyRecords: FinalRecord[] = [
      {
        record_id: request.memory_space.memory_space_id,
        record_kind: "core_memory_space_v1",
        payload: asJsonValue(request.memory_space),
      },
      {
        record_id: request.source_revision.revision_id,
        record_kind: "core_source_revision_v1",
        payload: asJsonValue(request.source_revision),
      },
      ...request.evidence_items.map((record) => ({
        record_id: record.evidence_id,
        record_kind: "core_evidence_v1",
        payload: asJsonValue(record),
      })),
      ...finalSemanticRecords.map((record) => ({
        record_id: derivedRecordId(record),
        record_kind: semanticKind(record),
        payload: asJsonValue(record),
      })),
      {
        record_id: semanticAuthorized.changeset_id,
        record_kind: "core_authorized_changeset_v1",
        payload: asJsonValue(semanticAuthorized),
      },
      ...lifecycle.threads.map((record) => ({
        record_id: record.thread_id,
        record_kind: "core_narrative_thread_v1",
        payload: asJsonValue(record),
      })),
      ...lifecycle.impacts.map((record) => ({
        record_id: record.impact_id,
        record_kind: "core_future_impact_v1",
        payload: asJsonValue(record),
      })),
      {
        record_id: lifecycle.authorized.changeset_id,
        record_kind: "core_authorized_changeset_v1",
        payload: asJsonValue(lifecycle.authorized),
      },
    ];
    if (new Set(bodyRecords.map((record) => record.record_id)).size !== bodyRecords.length) {
      const byId = new Map<string, FinalRecord[]>();
      for (const record of bodyRecords) {
        byId.set(record.record_id, [...(byId.get(record.record_id) ?? []), record]);
      }
      const duplicates = [...byId.entries()]
        .filter(([, records]) => records.length > 1)
        .map(
          ([recordId, records]) =>
            `${recordId}[${records.map((record) => record.record_kind).join("+")}]`,
        );
      throw new TypeError(
        `Final checkpoint contains duplicate record IDs: ${duplicates.join(",")}`,
      );
    }
    const checkpointId = `checkpoint_${(
      await sha256HexUtf8(
        canonicalJson({
          memory_set_id: request.memory_set_id,
          source_revision_id: request.source_revision_id,
          batch_id: batch.batch_id,
          semantic_corpus_sha256: merged.semantic_corpus_hash.value,
          record_ids: bodyRecords.map((record) => record.record_id),
        }),
      )
    ).slice(0, 40)}`;
    const manifest: TavernMemoryCheckpointManifest = {
      version: TAVERN_MEMORY_BATCH_FINALIZER_VERSION,
      checkpoint_id: checkpointId,
      batch_id: batch.batch_id,
      memory_set_id: request.memory_set_id,
      source_revision_id: request.source_revision_id,
      source_checksum: request.checkpoint_source_prefix.checksum,
      source_snapshot_revision: request.checkpoint_source_prefix.source_revision,
      source_scope: request.checkpoint_source_prefix.scope,
      source_message_count: request.checkpoint_source_prefix.messages.length,
      source_root_chain_hash: request.checkpoint_source_prefix.root_chain_hash,
      principal_entity_id: request.principal_entity_id,
      covered_ai_ordinal: batch.last_ai_ordinal,
      semantic_corpus_sha256: merged.semantic_corpus_hash.value,
      final_records_sha256: await checksumJson(bodyRecords),
      final_record_ids: bodyRecords.map((record) => record.record_id),
      semantic_changeset_id: semanticAuthorized.changeset_id,
      lifecycle_changeset_id: lifecycle.authorized.changeset_id,
      module_provenance: request.module_provenance,
      compiled_at: request.compiled_at,
    };
    const pages = await packFinalPages(
      [
        ...bodyRecords,
        {
          record_id: `checkpoint_manifest:${checkpointId}`,
          record_kind: TAVERN_MEMORY_CHECKPOINT_MANIFEST_KIND,
          payload: asJsonValue(manifest),
        },
      ],
      request,
      batch.batch_id,
    );
    const verifiedBatch: TavernMemoryBatchWorkState = {
      ...advanceTavernMemoryBatchDurability(batch, "checkpoint_verified"),
      finalization_error_code: null,
      finalization_error_target_ids: [],
    };
    const completed = head.source_index.completed_batches.some(
      (item) => item.batch_id === batch.batch_id,
    )
      ? head.source_index.completed_batches
      : [
          ...head.source_index.completed_batches,
          {
            batch_id: batch.batch_id,
            first_ai_ordinal: batch.first_ai_ordinal,
            last_ai_ordinal: batch.last_ai_ordinal,
            checkpoint_id: checkpointId,
            source_revision_id: request.source_revision_id,
            core_page_ids: pages.map((page) => page.page_id),
            recall_version: null,
            hidden_through_message_id: null,
          },
        ];
    await request.book_store.commit({
      commit_id: `${request.operation_id}:checkpoint:${checkpointId}`,
      expected_generation: head.generation,
      expected_generation_checksum: head.generation_checksum,
      committed_at: request.compiled_at,
      source_index: {
        ...head.source_index,
        committed_eligible_count: Math.max(
          head.source_index.committed_eligible_count,
          batch.last_ai_ordinal,
        ),
        completed_batches: completed,
      },
      work_state: verifiedBatch,
      checkpoint_index: {
        checkpoint_id: checkpointId,
        source_revision_id: request.source_revision_id,
        covered_ai_ordinal: batch.last_ai_ordinal,
        recall_version: null,
        hidden_through_message_id: head.checkpoint_index.hidden_through_message_id,
        core_page_ids: pages.map((page) => page.page_id),
      },
      active_state: finalSemanticRecords.includes(merged.current_state_view)
        ? asJsonValue(merged.current_state_view)
        : head.active_state,
      epistemic_state: asJsonValue({
        version: TAVERN_MEMORY_BATCH_FINALIZER_VERSION,
        states: finalSemanticRecords.filter((record) => "epistemic_id" in record),
      }),
      thread_impact: asJsonValue({
        version: TAVERN_MEMORY_BATCH_FINALIZER_VERSION,
        threads: lifecycle.threads,
        impacts: lifecycle.impacts,
      }),
      module_views: head.module_views,
      audit_ring: [
        ...head.audit_ring,
        {
          at: request.compiled_at,
          batch_id: batch.batch_id,
          module_id: null,
          event: "batch_checkpoint_committed",
          error_code: null,
        },
      ],
      retained_core_page_ids: head.core_page_ids,
      retained_module_view_page_ids: head.module_view_page_ids,
      core_pages: pages,
      module_view_pages: [],
    });
    const verifiedHead = await verifyCheckpoint(request.book_store, checkpointId);
    return {
      finalizer_version: TAVERN_MEMORY_BATCH_FINALIZER_VERSION,
      status: "CHECKPOINT_VERIFIED",
      head: verifiedHead,
      checkpoint_id: checkpointId,
      error_code: null,
    };
  } catch (error) {
    request.on_failure_diagnostic?.(error);
    return commitFailure(request, head, batch, error);
  }
}
