export const MEMORY_AGENT_ACTIVATION_POLICY_VERSION = "0.1.0" as const;

export const MEMORY_AGENT_ACTIVATION_KINDS = [
  "explicit_causal_completeness_gap",
  "relevant_record_conflict",
  "future_impact_trigger_gap",
  "narrative_thread_echo_gap",
] as const;

export type MemoryAgentActivationKind = (typeof MEMORY_AGENT_ACTIVATION_KINDS)[number];
export type MemoryAgentActivationRelevance = "background" | "current_scene" | "must_consider";

interface MemoryAgentActivationCandidateBase {
  readonly candidate_id: string;
  readonly source_revision_id: string;
  readonly durable_record_refs: readonly string[];
  readonly relevance: MemoryAgentActivationRelevance;
  readonly already_active: boolean;
  readonly cooldown_remaining_revisions: number;
  readonly estimated_model_calls: number;
  readonly estimated_input_tokens: number;
}

export type MemoryAgentActivationCandidate =
  | (MemoryAgentActivationCandidateBase & {
      readonly kind: "explicit_causal_completeness_gap";
      readonly detector: "deterministic_causal_completeness";
      readonly uncovered_cue_count: number;
      readonly already_covered: boolean;
    })
  | (MemoryAgentActivationCandidateBase & {
      readonly kind: "relevant_record_conflict";
      readonly detector: "trusted_projection_conflict_detector";
      readonly conflict_count: number;
      readonly resolution_state: "unresolved" | "resolved";
    })
  | (MemoryAgentActivationCandidateBase & {
      readonly kind: "future_impact_trigger_gap";
      readonly detector: "future_impact_trigger_evaluation";
      readonly impact_state: "candidate" | "armed" | "matched" | "surfaced" | "realized";
      readonly trigger_result: "eligible" | "ineligible" | "unknown";
      readonly already_surfaced: boolean;
    })
  | (MemoryAgentActivationCandidateBase & {
      readonly kind: "narrative_thread_echo_gap";
      readonly detector: "narrative_thread_state_machine";
      readonly thread_state: "latent" | "open" | "armed" | "triggered" | "resolved";
      readonly narrative_function: "echo" | "payoff";
      readonly already_covered: boolean;
    });

export interface MemoryAgentActivationPolicy {
  readonly policy_version: typeof MEMORY_AGENT_ACTIVATION_POLICY_VERSION;
  readonly minimum_score: number;
  readonly allow_background_relevance: boolean;
  readonly max_candidates_per_cycle: number;
  readonly max_model_calls_per_cycle: number;
  readonly max_input_tokens_per_cycle: number;
}

export interface MemoryAgentActivationCycleContext {
  readonly current_source_revision_id: string;
  readonly candidates_selected_in_cycle: number;
  readonly model_calls_reserved_in_cycle: number;
  readonly input_tokens_reserved_in_cycle: number;
}

export const MEMORY_AGENT_ACTIVATION_DEFERRAL_REASONS = [
  "STALE_SOURCE_REVISION",
  "MISSING_DURABLE_PROVENANCE",
  "DUPLICATE_CANDIDATE",
  "ALREADY_ACTIVE",
  "COOLDOWN_ACTIVE",
  "ALREADY_COVERED",
  "UNSUPPORTED_SIGNAL_STATE",
  "BACKGROUND_RELEVANCE_DISABLED",
  "BELOW_SCORE_THRESHOLD",
  "CYCLE_CANDIDATE_BUDGET_EXHAUSTED",
  "CYCLE_MODEL_BUDGET_EXHAUSTED",
  "CYCLE_INPUT_TOKEN_BUDGET_EXHAUSTED",
] as const;

export type MemoryAgentActivationDeferralReason =
  (typeof MEMORY_AGENT_ACTIVATION_DEFERRAL_REASONS)[number];

export interface SelectedMemoryAgentActivation {
  readonly candidate: MemoryAgentActivationCandidate;
  readonly score: number;
  readonly authorization: "readonly_investigation_only";
  readonly persistent_write_authorized: false;
}

export interface DeferredMemoryAgentActivation {
  readonly candidate: MemoryAgentActivationCandidate;
  readonly score: number;
  readonly reason: MemoryAgentActivationDeferralReason;
}

export interface MemoryAgentActivationSelection {
  readonly policy_version: typeof MEMORY_AGENT_ACTIVATION_POLICY_VERSION;
  readonly selected: readonly SelectedMemoryAgentActivation[];
  readonly deferred: readonly DeferredMemoryAgentActivation[];
  readonly reserved_model_calls: number;
  readonly reserved_input_tokens: number;
}

const KIND_SCORE: Readonly<Record<MemoryAgentActivationKind, number>> = {
  explicit_causal_completeness_gap: 3,
  relevant_record_conflict: 4,
  future_impact_trigger_gap: 3,
  narrative_thread_echo_gap: 2,
};

const RELEVANCE_SCORE: Readonly<Record<MemoryAgentActivationRelevance, number>> = {
  background: 0,
  current_scene: 1,
  must_consider: 2,
};

const KIND_ORDER = new Map(MEMORY_AGENT_ACTIVATION_KINDS.map((kind, index) => [kind, index]));

function assertNonNegativeInteger(value: number, field: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(`${field} must be a non-negative safe integer`);
  }
}

function assertPositiveInteger(value: number, field: string): void {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new TypeError(`${field} must be a positive safe integer`);
  }
}

function assertExactIdentifier(value: string, field: string): void {
  if (value.length === 0 || value !== value.trim()) {
    throw new TypeError(`${field} must be a non-empty exact identifier`);
  }
}

function scoreCandidate(candidate: MemoryAgentActivationCandidate): number {
  let score = KIND_SCORE[candidate.kind] + RELEVANCE_SCORE[candidate.relevance];
  if (
    candidate.kind === "future_impact_trigger_gap" &&
    candidate.impact_state === "matched" &&
    candidate.trigger_result === "eligible"
  ) {
    score += 1;
  }
  if (candidate.kind === "narrative_thread_echo_gap" && candidate.thread_state === "triggered") {
    score += 1;
  }
  return score;
}

function preBudgetDeferral(
  candidate: MemoryAgentActivationCandidate,
  policy: MemoryAgentActivationPolicy,
  context: MemoryAgentActivationCycleContext,
  score: number,
): MemoryAgentActivationDeferralReason | undefined {
  if (candidate.source_revision_id !== context.current_source_revision_id) {
    return "STALE_SOURCE_REVISION";
  }
  if (candidate.durable_record_refs.length === 0) return "MISSING_DURABLE_PROVENANCE";
  if (candidate.already_active) return "ALREADY_ACTIVE";
  if (candidate.cooldown_remaining_revisions > 0) return "COOLDOWN_ACTIVE";

  switch (candidate.kind) {
    case "explicit_causal_completeness_gap":
      if (candidate.already_covered) return "ALREADY_COVERED";
      if (candidate.uncovered_cue_count < 1) return "UNSUPPORTED_SIGNAL_STATE";
      break;
    case "relevant_record_conflict":
      if (candidate.resolution_state === "resolved") return "ALREADY_COVERED";
      if (candidate.conflict_count < 1) return "UNSUPPORTED_SIGNAL_STATE";
      break;
    case "future_impact_trigger_gap":
      if (
        candidate.already_surfaced ||
        candidate.impact_state === "surfaced" ||
        candidate.impact_state === "realized"
      ) {
        return "ALREADY_COVERED";
      }
      if (
        (candidate.impact_state !== "armed" && candidate.impact_state !== "matched") ||
        candidate.trigger_result === "ineligible"
      ) {
        return "UNSUPPORTED_SIGNAL_STATE";
      }
      break;
    case "narrative_thread_echo_gap":
      if (candidate.already_covered || candidate.thread_state === "resolved") {
        return "ALREADY_COVERED";
      }
      if (candidate.thread_state !== "armed" && candidate.thread_state !== "triggered") {
        return "UNSUPPORTED_SIGNAL_STATE";
      }
      break;
  }

  if (candidate.relevance === "background" && !policy.allow_background_relevance) {
    return "BACKGROUND_RELEVANCE_DISABLED";
  }
  if (score < policy.minimum_score) return "BELOW_SCORE_THRESHOLD";
  return undefined;
}

/**
 * Deterministic admission only. It reserves a bounded read-only investigation budget,
 * but it never creates a task, calls a model, or authorizes a persistent write.
 */
export function selectMemoryAgentActivations(
  policy: MemoryAgentActivationPolicy,
  context: MemoryAgentActivationCycleContext,
  candidates: readonly MemoryAgentActivationCandidate[],
): MemoryAgentActivationSelection {
  if (policy.policy_version !== MEMORY_AGENT_ACTIVATION_POLICY_VERSION) {
    throw new TypeError("Unsupported memory Agent activation policy version");
  }
  assertPositiveInteger(policy.minimum_score, "minimum_score");
  assertPositiveInteger(policy.max_candidates_per_cycle, "max_candidates_per_cycle");
  assertPositiveInteger(policy.max_model_calls_per_cycle, "max_model_calls_per_cycle");
  assertPositiveInteger(policy.max_input_tokens_per_cycle, "max_input_tokens_per_cycle");
  assertNonNegativeInteger(context.candidates_selected_in_cycle, "candidates_selected_in_cycle");
  assertNonNegativeInteger(context.model_calls_reserved_in_cycle, "model_calls_reserved_in_cycle");
  assertNonNegativeInteger(
    context.input_tokens_reserved_in_cycle,
    "input_tokens_reserved_in_cycle",
  );
  assertExactIdentifier(context.current_source_revision_id, "current_source_revision_id");

  const ranked = candidates
    .map((candidate) => {
      assertExactIdentifier(candidate.candidate_id, "candidate_id");
      assertExactIdentifier(
        candidate.source_revision_id,
        `${candidate.candidate_id}.source_revision_id`,
      );
      for (const [index, reference] of candidate.durable_record_refs.entries()) {
        assertExactIdentifier(reference, `${candidate.candidate_id}.durable_record_refs[${index}]`);
      }
      assertPositiveInteger(
        candidate.estimated_model_calls,
        `${candidate.candidate_id}.estimated_model_calls`,
      );
      assertPositiveInteger(
        candidate.estimated_input_tokens,
        `${candidate.candidate_id}.estimated_input_tokens`,
      );
      assertNonNegativeInteger(
        candidate.cooldown_remaining_revisions,
        `${candidate.candidate_id}.cooldown_remaining_revisions`,
      );
      return { candidate, score: scoreCandidate(candidate) };
    })
    .sort(
      (left, right) =>
        right.score - left.score ||
        (KIND_ORDER.get(left.candidate.kind) ?? 0) - (KIND_ORDER.get(right.candidate.kind) ?? 0) ||
        left.candidate.candidate_id.localeCompare(right.candidate.candidate_id),
    );

  const selected: SelectedMemoryAgentActivation[] = [];
  const deferred: DeferredMemoryAgentActivation[] = [];
  let selectedCount = context.candidates_selected_in_cycle;
  let reservedModelCalls = context.model_calls_reserved_in_cycle;
  let reservedInputTokens = context.input_tokens_reserved_in_cycle;
  const seenCandidateIds = new Set<string>();

  for (const rankedCandidate of ranked) {
    const { candidate, score } = rankedCandidate;
    let reason: MemoryAgentActivationDeferralReason | undefined;
    if (seenCandidateIds.has(candidate.candidate_id)) {
      reason = "DUPLICATE_CANDIDATE";
    } else {
      seenCandidateIds.add(candidate.candidate_id);
      reason = preBudgetDeferral(candidate, policy, context, score);
    }
    if (reason === undefined && selectedCount >= policy.max_candidates_per_cycle) {
      reason = "CYCLE_CANDIDATE_BUDGET_EXHAUSTED";
    }
    if (
      reason === undefined &&
      reservedModelCalls + candidate.estimated_model_calls > policy.max_model_calls_per_cycle
    ) {
      reason = "CYCLE_MODEL_BUDGET_EXHAUSTED";
    }
    if (
      reason === undefined &&
      reservedInputTokens + candidate.estimated_input_tokens > policy.max_input_tokens_per_cycle
    ) {
      reason = "CYCLE_INPUT_TOKEN_BUDGET_EXHAUSTED";
    }

    if (reason !== undefined) {
      deferred.push({ candidate, score, reason });
      continue;
    }
    selected.push({
      candidate,
      score,
      authorization: "readonly_investigation_only",
      persistent_write_authorized: false,
    });
    selectedCount += 1;
    reservedModelCalls += candidate.estimated_model_calls;
    reservedInputTokens += candidate.estimated_input_tokens;
  }

  return {
    policy_version: MEMORY_AGENT_ACTIVATION_POLICY_VERSION,
    selected,
    deferred,
    reserved_model_calls: reservedModelCalls,
    reserved_input_tokens: reservedInputTokens,
  };
}
