import {
  REJECTION_REASONS,
  type RecallTrace,
  type RejectionReasonCode,
} from "@narramem/core-domain";

import type { TavernEventSubscription, TavernHostPort } from "./contracts.js";
import { findTavernProtectedWindowStartIndex } from "./protected-chat-window.js";
import {
  TAVERN_RECALL_GENERATION_BARRIER_VERSION,
  TAVERN_RECALL_INVALIDATION_EVENT_NAMES,
  type TavernRecallBarrierAssemblyService,
  type TavernRecallBarrierInstalledInjection,
  type TavernRecallBarrierObserverService,
  type TavernRecallBarrierPreparation,
  type TavernRecallBarrierReportListener,
  type TavernRecallBarrierRuntime,
  type TavernRecallBarrierTrigger,
  type TavernRecallGenerationBarrierConfig,
  TavernRecallGenerationBarrierError,
  type TavernRecallGenerationBarrierReport,
  type TavernRecallGenerationBarrierSnapshot,
} from "./recall-generation-barrier-contracts.js";
import { renderTavernRecallPrompt } from "./recall-prompt.js";

const MAX_INJECTION_DEPTH = 10_000;
const DEFAULT_MAX_PREPARE_MS = 150;
const MAX_PREPARE_MS = 5_000;

function assertConfig(config: TavernRecallGenerationBarrierConfig): void {
  if (
    !Number.isInteger(config.token_budget) ||
    config.token_budget < 64 ||
    config.token_budget > 32_768 ||
    !Number.isInteger(config.latest_ai_floor_count) ||
    config.latest_ai_floor_count < 1 ||
    config.latest_ai_floor_count > 100 ||
    (config.max_prepare_ms !== undefined &&
      (!Number.isInteger(config.max_prepare_ms) ||
        config.max_prepare_ms < 1 ||
        config.max_prepare_ms > MAX_PREPARE_MS))
  ) {
    throw new TavernRecallGenerationBarrierError(
      "INVALID_CONFIG",
      "Recall barrier requires token budget 64-32768, latest AI floor count 1-100, and deadline 1-5000 ms",
    );
  }
}

export function recallInjectionDepthBeforeLatestAiWindow(
  messages: ReturnType<TavernHostPort["readCurrentMessages"]>,
  latestAiFloorCount: number,
): number {
  const windowStart = findTavernProtectedWindowStartIndex(messages, latestAiFloorCount);
  return messages.slice(windowStart).filter((message) => !message.is_hidden).length;
}

function isDryRun(args: readonly unknown[]): boolean {
  return args[2] === true;
}

function shouldWaitForCommittedUserMessage(args: readonly unknown[]): boolean {
  const generationType = args[0];
  if (generationType !== undefined && generationType !== "normal") return false;
  const parameters = args[1];
  if (parameters === null || typeof parameters !== "object") return true;
  return (parameters as Readonly<Record<string, unknown>>).automatic_trigger !== true;
}

function errorDescriptor(error: unknown): {
  readonly error_name: string;
  readonly error_message: string;
  readonly error_code?: string;
} {
  if (error instanceof Error) {
    const candidate = error as Error & { readonly code?: unknown };
    return {
      error_name: error.name,
      error_message: error.message,
      ...(typeof candidate.code === "string" ? { error_code: candidate.code } : {}),
    };
  }
  return { error_name: "UnknownError", error_message: String(error) };
}

function requireSemanticCoverage(
  report: Awaited<ReturnType<TavernRecallBarrierObserverService["prepareForMainGeneration"]>>,
): TavernRecallBarrierPreparation {
  if (report.status !== "COMMITTED_COVERAGE_READY") {
    throw new TavernRecallGenerationBarrierError(
      "SEMANTIC_COVERAGE_NOT_READY",
      "No previously committed semantic coverage is ready for bounded Recall",
    );
  }
  return { extraction_audit: report.extraction_audit };
}

function rejectionReasonCounts(trace: RecallTrace): Readonly<Record<RejectionReasonCode, number>> {
  const counts = Object.fromEntries(REJECTION_REASONS.map((reason) => [reason, 0])) as Record<
    RejectionReasonCode,
    number
  >;
  for (const rejection of trace.rejection_reasons) counts[rejection.reason] += 1;
  return counts;
}

export function createBrowserTavernRecallBarrierRuntime(): TavernRecallBarrierRuntime {
  return {
    now_ms: () => globalThis.performance?.now() ?? Date.now(),
    set_timer: (callback, delayMs) => globalThis.setTimeout(callback, delayMs),
    clear_timer: (handle) => globalThis.clearTimeout(handle as ReturnType<typeof setTimeout>),
  };
}

/**
 * Fail-open, deadline-bounded bridge from public generation lifecycle events to
 * one generation-scoped Tavern Helper injection. Normal user turns wait until
 * message_sent has committed the current message; generation modes without a
 * new user message prepare at generation_after_commands. RecallTrace never
 * enters this class: the renderer accepts only the consumer-safe Bundle.
 */
export class TavernRecallGenerationBarrier {
  private lifecycle: "idle" | "running" | "stopped" | "disposed" = "idle";
  private latestSequence = 0;
  private preparation: Promise<void> | null = null;
  private waitingForUserMessage: { readonly sequence: number } | null = null;
  private installed: TavernRecallBarrierInstalledInjection | null = null;
  private readonly subscriptions: TavernEventSubscription[] = [];
  private readonly listeners = new Set<TavernRecallBarrierReportListener>();
  private lastReport: TavernRecallGenerationBarrierReport | null = null;

  constructor(
    private readonly port: TavernHostPort,
    private readonly observer: TavernRecallBarrierObserverService,
    private readonly recall: TavernRecallBarrierAssemblyService,
    private readonly config: TavernRecallGenerationBarrierConfig,
    private readonly runtime: TavernRecallBarrierRuntime = createBrowserTavernRecallBarrierRuntime(),
  ) {
    assertConfig(config);
    if (port.installInjection === undefined) {
      throw new TavernRecallGenerationBarrierError(
        "HOST_INJECTION_UNAVAILABLE",
        "Tavern Helper Prompt injection is unavailable",
      );
    }
  }

  start(): boolean {
    this.assertNotDisposed();
    if (this.lifecycle === "running") return false;
    try {
      this.subscriptions.push(
        this.port.subscribe("generation_after_commands", (...args) =>
          this.handleGenerationAfterCommands(args),
        ),
      );
      this.subscriptions.push(
        this.port.subscribe("message_sent", () => this.handleCommittedUserMessage()),
      );
      for (const eventName of TAVERN_RECALL_INVALIDATION_EVENT_NAMES) {
        this.subscriptions.push(
          this.port.subscribe(eventName, () => {
            this.invalidate(eventName);
          }),
        );
      }
    } catch (error) {
      this.stopSubscriptions();
      throw new TavernRecallGenerationBarrierError(
        "SUBSCRIPTION_FAILED",
        error instanceof Error ? error.message : "Failed to subscribe Recall barrier events",
      );
    }
    this.lifecycle = "running";
    return true;
  }

  stop(reason = "recall_barrier_stopped"): boolean {
    this.assertNotDisposed();
    const wasRunning = this.lifecycle === "running";
    this.lifecycle = "stopped";
    this.invalidate(reason);
    this.stopSubscriptions();
    return wasRunning;
  }

  pagehide(): boolean {
    return this.stop("pagehide");
  }

  dispose(): boolean {
    if (this.lifecycle === "disposed") return false;
    if (this.lifecycle === "running") this.stop("recall_barrier_disposed");
    this.lifecycle = "disposed";
    this.waitingForUserMessage = null;
    this.removeInjection();
    this.stopSubscriptions();
    this.listeners.clear();
    return true;
  }

  subscribeReports(listener: TavernRecallBarrierReportListener): TavernEventSubscription {
    this.assertNotDisposed();
    this.listeners.add(listener);
    return { stop: () => this.listeners.delete(listener) };
  }

  getSnapshot(): TavernRecallGenerationBarrierSnapshot {
    return {
      barrier_version: TAVERN_RECALL_GENERATION_BARRIER_VERSION,
      lifecycle: this.lifecycle,
      latest_sequence: this.latestSequence,
      preparation_in_flight: this.preparation !== null,
      waiting_for_user_message: this.waitingForUserMessage !== null,
      injection_installed: this.installed !== null,
      last_report: this.lastReport,
    };
  }

  private async handleGenerationAfterCommands(args: readonly unknown[]): Promise<void> {
    if (this.lifecycle !== "running") return;
    if (isDryRun(args)) {
      this.publish({
        status: "SKIPPED_DRY_RUN",
        sequence: this.latestSequence,
      });
      return;
    }
    this.latestSequence += 1;
    const sequence = this.latestSequence;
    this.removeInjection();
    this.waitingForUserMessage = null;
    if (shouldWaitForCommittedUserMessage(args)) {
      this.waitingForUserMessage = { sequence };
      this.publish({ status: "DEFERRED_TO_MESSAGE_SENT", sequence });
      return;
    }
    await this.prepareWithinDeadline(sequence, "NO_NEW_USER_MESSAGE", "generation_after_commands");
  }

  private async handleCommittedUserMessage(): Promise<void> {
    if (this.lifecycle !== "running") return;
    const waiting = this.waitingForUserMessage;
    if (waiting === null) {
      this.invalidate("message_sent_without_deferred_generation");
      return;
    }
    this.waitingForUserMessage = null;
    await this.prepareWithinDeadline(waiting.sequence, "USER_MESSAGE_COMMITTED", "message_sent");
  }

  private async prepareWithinDeadline(
    sequence: number,
    trigger: TavernRecallBarrierTrigger,
    observerTrigger: "generation_after_commands" | "message_sent",
  ): Promise<void> {
    const startedAt = this.readNowMs();
    const work = this.prepareAndInstall(sequence, startedAt, trigger, observerTrigger);
    this.preparation = work;
    void work
      .finally(() => {
        if (this.preparation === work) this.preparation = null;
      })
      .catch(() => undefined);
    try {
      await this.awaitDeadline(work, sequence);
    } catch (error) {
      const descriptor = errorDescriptor(error);
      if (descriptor.error_code === "SUPERSEDED") return;
      this.publish({
        status: "DEGRADED_NO_INJECTION",
        sequence,
        trigger,
        reason:
          descriptor.error_code === "SEMANTIC_COVERAGE_NOT_READY" ||
          descriptor.error_code === "SEMANTIC_COVERAGE_MISSING"
            ? "NO_COMMITTED_COVERAGE"
            : descriptor.error_code === "SOURCE_CHANGED"
              ? "UNSAFE_SOURCE_CHANGE"
              : descriptor.error_code === "DEADLINE_EXCEEDED"
                ? "DEADLINE_EXCEEDED"
                : "RECALL_UNAVAILABLE",
        elapsed_ms: this.elapsedSince(startedAt),
        ...descriptor,
      });
    }
  }

  private async prepareAndInstall(
    sequence: number,
    startedAt: number,
    trigger: TavernRecallBarrierTrigger,
    observerTrigger: "generation_after_commands" | "message_sent",
  ): Promise<void> {
    const prepared = requireSemanticCoverage(
      await this.observer.prepareForMainGeneration(observerTrigger),
    );
    this.assertCurrent(sequence);
    const assembled = await this.recall.assemble({
      token_budget: this.config.token_budget,
      expected_semantic_coverage: prepared.extraction_audit,
      source_policy: "ALLOW_APPEND_ONLY_LIVE_TAIL",
      ...(this.config.principal_entity_id === undefined
        ? {}
        : { principal_entity_id: this.config.principal_entity_id }),
      ...(this.config.normalize_semantic_metadata === undefined
        ? {}
        : { normalize_semantic_metadata: this.config.normalize_semantic_metadata }),
    });
    this.assertCurrent(sequence);
    const rendered = renderTavernRecallPrompt(this.config.prompt_asset, assembled.bundle);
    const injectionDepth = recallInjectionDepthBeforeLatestAiWindow(
      this.port.readCurrentMessages({ include_swipes: false }),
      this.config.latest_ai_floor_count,
    );
    if (injectionDepth > MAX_INJECTION_DEPTH) {
      throw new TavernRecallGenerationBarrierError(
        "INVALID_CONFIG",
        "Current visible chat exceeds the supported Recall injection depth",
      );
    }
    const installInjection = this.port.installInjection;
    if (installInjection === undefined) {
      throw new TavernRecallGenerationBarrierError(
        "HOST_INJECTION_UNAVAILABLE",
        "Tavern Helper Prompt injection disappeared at runtime",
      );
    }
    const handle = installInjection({
      id: `narramem_recall_${sequence}`,
      position: "in_chat",
      depth: injectionDepth,
      role: "system",
      content: rendered.content,
      should_scan: false,
      once: true,
      prompt_asset_ref: rendered.prompt_asset_ref,
    });
    if (sequence !== this.latestSequence || this.lifecycle !== "running") {
      handle.remove();
      throw new TavernRecallGenerationBarrierError(
        "SUPERSEDED",
        "Recall injection was superseded before installation completed",
      );
    }
    this.installed = { rendered, handle };
    this.publish({
      status: "INJECTION_INSTALLED",
      sequence,
      trigger,
      extraction_audit: prepared.extraction_audit,
      memory_set_id: assembled.memory_set_id,
      source_checksum: assembled.source_checksum,
      source_alignment: assembled.source_alignment.mode,
      live_tail_message_count: assembled.source_alignment.live_tail_message_count,
      bundle_id: rendered.bundle_id,
      immediate_context_count: assembled.bundle.immediate_context.length,
      causal_antecedent_count: assembled.bundle.causal_antecedents.length,
      experience_echo_count: assembled.bundle.experience_echoes.length,
      active_thread_count: assembled.bundle.active_threads.length,
      matched_impact_count: assembled.bundle.matched_impacts.length,
      perspective_safe_entity_count: assembled.bundle.perspective_safe_entities?.length ?? 0,
      rejection_reason_counts: rejectionReasonCounts(assembled.trace),
      prompt_asset_ref: rendered.prompt_asset_ref,
      prompt_body_sha256: rendered.body_sha256,
      injection_depth: injectionDepth,
      elapsed_ms: this.elapsedSince(startedAt),
    });
  }

  private async awaitDeadline(work: Promise<void>, sequence: number): Promise<void> {
    let timer: unknown = null;
    const deadline = new Promise<never>((_resolve, reject) => {
      timer = this.runtime.set_timer(() => {
        if (sequence === this.latestSequence) {
          this.latestSequence += 1;
          this.removeInjection();
        }
        reject(
          new TavernRecallGenerationBarrierError(
            "DEADLINE_EXCEEDED",
            `Recall preparation exceeded ${this.config.max_prepare_ms ?? DEFAULT_MAX_PREPARE_MS} ms`,
          ),
        );
      }, this.config.max_prepare_ms ?? DEFAULT_MAX_PREPARE_MS);
    });
    try {
      await Promise.race([work, deadline]);
    } finally {
      if (timer !== null) this.runtime.clear_timer(timer);
    }
  }

  private elapsedSince(startedAt: number): number {
    return Math.max(0, this.readNowMs() - startedAt);
  }

  private readNowMs(): number {
    const value = this.runtime.now_ms();
    if (!Number.isFinite(value) || value < 0) {
      throw new TavernRecallGenerationBarrierError(
        "INVALID_RUNTIME",
        "Recall barrier runtime now_ms must return a finite non-negative number",
      );
    }
    return value;
  }

  private assertCurrent(sequence: number): void {
    if (sequence !== this.latestSequence || this.lifecycle !== "running") {
      throw new TavernRecallGenerationBarrierError(
        "SUPERSEDED",
        "Recall preparation was superseded by a source or lifecycle change",
      );
    }
  }

  private invalidate(reason: string): void {
    this.latestSequence += 1;
    this.waitingForUserMessage = null;
    const removed = this.removeInjection();
    this.publish({
      status: "INVALIDATED",
      sequence: this.latestSequence,
      reason,
      injection_removed: removed,
    });
  }

  private removeInjection(): boolean {
    const installed = this.installed;
    this.installed = null;
    if (installed === null) return false;
    installed.handle.remove();
    return true;
  }

  private publish(
    report: TavernRecallGenerationBarrierReport,
  ): TavernRecallGenerationBarrierReport {
    this.lastReport = report;
    for (const listener of [...this.listeners]) {
      try {
        listener(report);
      } catch {
        // Observational report listeners cannot break generation consistency.
      }
    }
    return report;
  }

  private stopSubscriptions(): void {
    while (this.subscriptions.length > 0) this.subscriptions.pop()?.stop();
  }

  private assertNotDisposed(): void {
    if (this.lifecycle === "disposed") {
      throw new TavernRecallGenerationBarrierError("DISPOSED", "Recall barrier is disposed");
    }
  }
}
