import type {
  ModularExtractionInput,
  ModularExtractionModuleId,
  ModularExtractionOutput,
} from "@narramem/core-domain";

import type { WireSchemaName } from "./wire-schema-catalog.js";
import { validateWireValue } from "./wire-schema-registry.js";

export interface ModularExtractionValidationIssue {
  readonly code: string;
  readonly path: string;
  readonly message: string;
}

export interface ModularExtractionValidationReport {
  readonly validator_version: "0.1.0";
  readonly accepted: boolean;
  readonly issues: readonly ModularExtractionValidationIssue[];
}

const INPUT_SCHEMAS: Readonly<Record<ModularExtractionModuleId, WireSchemaName>> = {
  M1: "modular_extraction_m1_input",
  M2: "modular_extraction_m2_input",
  M3: "modular_extraction_m3_input",
  M4: "modular_extraction_m4_input",
  M5: "modular_extraction_m5_input",
  M6: "modular_extraction_m6_input",
  M7: "modular_extraction_m7_input",
};

const OUTPUT_SCHEMAS: Readonly<Record<ModularExtractionModuleId, WireSchemaName>> = {
  M1: "modular_extraction_m1_output",
  M2: "modular_extraction_m2_output",
  M3: "modular_extraction_m3_output",
  M4: "modular_extraction_m4_output",
  M5: "modular_extraction_m5_output",
  M6: "modular_extraction_m6_output",
  M7: "modular_extraction_m7_output",
};

const RECORD_FIELDS: Readonly<Record<ModularExtractionModuleId, readonly string[]>> = {
  M1: ["entities"],
  M2: ["scenes", "episodes"],
  M3: ["events"],
  M4: ["state_transitions"],
  M5: ["epistemic_states"],
  M6: ["causal_links"],
  M7: [
    "prior_thread_dispositions",
    "prior_future_impact_dispositions",
    "threads",
    "future_impacts",
  ],
};

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

const issue = (code: string, path: string, message: string): ModularExtractionValidationIssue => ({
  code,
  path,
  message,
});

function wireIssues(
  schemaName: WireSchemaName,
  value: unknown,
): ModularExtractionValidationIssue[] {
  const report = validateWireValue(schemaName, value);
  return report.valid
    ? []
    : report.errors
        .slice(0, 24)
        .map((error) =>
          issue(
            "MODULAR_WIRE_INVALID",
            error.instancePath || "/",
            error.message ?? "Value does not match the module wire Schema",
          ),
        );
}

export function validateModularExtractionInput(
  value: unknown,
  moduleId: ModularExtractionModuleId,
): ModularExtractionValidationReport {
  const issues = wireIssues(INPUT_SCHEMAS[moduleId], value);
  return { validator_version: "0.1.0", accepted: issues.length === 0, issues };
}

function recordEvidenceIds(
  moduleId: ModularExtractionModuleId,
  field: string,
  record: unknown,
): string[] {
  if (!isObject(record)) return [];
  if (moduleId === "M2") {
    const values = field === "scenes" ? record.source_evidence_ids : record.evidence_ids;
    return Array.isArray(values)
      ? values.filter((item): item is string => typeof item === "string")
      : [];
  }
  if (moduleId === "M7") {
    return Array.isArray(record.evidence_ids)
      ? record.evidence_ids.filter((item): item is string => typeof item === "string")
      : [];
  }
  return Array.isArray(record.evidence_quotes)
    ? record.evidence_quotes.flatMap((quote) =>
        isObject(quote) && quote.support_role === "direct" && typeof quote.evidence_id === "string"
          ? [quote.evidence_id]
          : [],
      )
    : [];
}

export function validateModularExtractionOutput(
  value: unknown,
  input: ModularExtractionInput,
): ModularExtractionValidationReport {
  const issues = wireIssues(OUTPUT_SCHEMAS[input.module_id], value);
  if (issues.length > 0 || !isObject(value)) {
    return { validator_version: "0.1.0", accepted: false, issues };
  }
  if (value.module_id !== input.module_id) {
    issues.push(
      issue("MODULAR_MODULE_MISMATCH", "/module_id", "Output module_id differs from input"),
    );
  }
  if (value.source_revision_id !== input.source_revision_id) {
    issues.push(
      issue(
        "MODULAR_SOURCE_REVISION_MISMATCH",
        "/source_revision_id",
        "Output belongs to a different Source revision",
      ),
    );
  }

  const evidenceIds = input.current_evidence.map((evidence) => evidence.evidence_id);
  const evidenceSet = new Set<string>(evidenceIds);
  if (evidenceSet.size !== evidenceIds.length) {
    issues.push(
      issue(
        "MODULAR_INPUT_EVIDENCE_DUPLICATE",
        "/current_evidence",
        "Current module Evidence IDs must be unique",
      ),
    );
  }
  const records = RECORD_FIELDS[input.module_id].flatMap((field) => {
    const values = value[field];
    return Array.isArray(values) ? values.map((record, index) => ({ field, index, record })) : [];
  });
  const recordKeys = new Set<string>();
  for (const { field, index, record } of records) {
    const path = `/${field}/${index}`;
    if (!isObject(record) || typeof record.candidate_key !== "string") continue;
    if (recordKeys.has(record.candidate_key)) {
      issues.push(
        issue(
          "MODULAR_RECORD_KEY_DUPLICATE",
          `${path}/candidate_key`,
          "Candidate keys must be unique inside one module output",
        ),
      );
    }
    recordKeys.add(record.candidate_key);
    if (!recordEvidenceIds(input.module_id, field, record).some((id) => evidenceSet.has(id))) {
      issues.push(
        issue(
          "MODULAR_RECORD_CURRENT_EVIDENCE_MISSING",
          path,
          "Every module record requires direct support from current batch Evidence",
        ),
      );
    }
  }
  if (
    (records.length === 0 && value.result !== "no_new_facts") ||
    (records.length > 0 && value.result !== "complete")
  ) {
    issues.push(
      issue(
        "MODULAR_RESULT_RECORD_COUNT_MISMATCH",
        "/result",
        "result must be complete for non-empty records and no_new_facts for an empty module",
      ),
    );
  }

  const dispositions = Array.isArray(value.evidence_dispositions)
    ? value.evidence_dispositions
    : [];
  const dispositionIds = dispositions.flatMap((item) =>
    isObject(item) && typeof item.evidence_id === "string" ? [item.evidence_id] : [],
  );
  if (
    dispositionIds.length !== evidenceIds.length ||
    new Set(dispositionIds).size !== dispositionIds.length ||
    evidenceIds.some((id) => !dispositionIds.includes(id)) ||
    dispositionIds.some((id) => !evidenceSet.has(id))
  ) {
    issues.push(
      issue(
        "MODULAR_EVIDENCE_COVERAGE_INCOMPLETE",
        "/evidence_dispositions",
        "Every current Evidence ID must have exactly one disposition and no foreign ID is allowed",
      ),
    );
  }
  const dispositionRecordedKeys = new Set<string>();
  dispositions.forEach((item, index) => {
    if (!isObject(item) || !Array.isArray(item.record_keys)) return;
    const keys = item.record_keys.filter((key): key is string => typeof key === "string");
    if (item.disposition === "recorded") {
      if (keys.length === 0 || keys.some((key) => !recordKeys.has(key))) {
        issues.push(
          issue(
            "MODULAR_RECORDED_DISPOSITION_INVALID",
            `/evidence_dispositions/${index}/record_keys`,
            "A recorded disposition must reference one or more records in this module response",
          ),
        );
      }
      for (const key of keys) dispositionRecordedKeys.add(key);
    } else if (keys.length > 0) {
      issues.push(
        issue(
          "MODULAR_NON_RECORDED_KEYS_FORBIDDEN",
          `/evidence_dispositions/${index}/record_keys`,
          "Only recorded dispositions may contain record_keys",
        ),
      );
    }
  });
  for (const key of recordKeys) {
    if (!dispositionRecordedKeys.has(key)) {
      issues.push(
        issue(
          "MODULAR_RECORD_DISPOSITION_MISSING",
          "/evidence_dispositions",
          `Record ${key} is not claimed by any recorded Evidence disposition`,
        ),
      );
    }
  }
  return { validator_version: "0.1.0", accepted: issues.length === 0, issues };
}

export function asAcceptedModularExtractionOutput(
  value: unknown,
  input: ModularExtractionInput,
): ModularExtractionOutput {
  const report = validateModularExtractionOutput(value, input);
  if (!report.accepted) {
    throw new TypeError(report.issues.map((item) => `${item.code}@${item.path}`).join(", "));
  }
  return value as ModularExtractionOutput;
}
