import type { TavernJsonValue } from "./contracts.js";
import {
  readVerifiedTavernMemoryCheckpoint,
  TAVERN_MEMORY_CHECKPOINT_MANIFEST_KIND,
  type TavernMemoryCheckpointManifest,
  type TavernMemoryCheckpointStorePort,
} from "./memory-batch-finalizer.js";
import {
  TAVERN_MEMORY_MODULE_IDS,
  type TavernMemoryColdHead,
  type TavernMemoryCorePage,
  type TavernMemoryModuleId,
  type TavernMemoryModuleViewIndex,
  type TavernMemoryModuleViewItem,
  type TavernMemoryModuleViewPage,
} from "./memory-book-contracts.js";
import {
  alignTavernMemoryCheckpointSource,
  TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION,
} from "./memory-checkpoint-recall.js";
import { parseTavernRecallCorpus, type TavernRecallCorpus } from "./recall.js";
import { verifyTavernSourceSnapshot } from "./source-snapshot.js";
import type { TavernSourceSnapshot } from "./source-snapshot-contracts.js";
import { canonicalJson, checksumJson, sha256HexUtf8 } from "./worldbook-codec.js";

export const TAVERN_MEMORY_MUTATION_ROLLBACK_VERSION = "0.1.0" as const;

type CompletedBatch = TavernMemoryColdHead["source_index"]["completed_batches"][number];

interface RollbackTarget {
  readonly batch: CompletedBatch;
  readonly manifest: TavernMemoryCheckpointManifest;
  readonly corpus: TavernRecallCorpus;
}

export interface TavernMemoryMutationRollbackRequest {
  readonly book_store: TavernMemoryCheckpointStorePort;
  readonly current_source_snapshot: TavernSourceSnapshot;
  readonly new_source_revision_id: string;
  readonly valid_ai_count: number;
  readonly protected_ai_ordinals: readonly number[];
  readonly mutation_source_unit_id: string;
  readonly mutation_message_id: number;
  readonly mutation_ai_ordinal: number;
}

export interface TavernMemoryMutationRollbackPlan {
  readonly rollback_version: typeof TAVERN_MEMORY_MUTATION_ROLLBACK_VERSION;
  readonly from_checkpoint_id: string | null;
  readonly to_checkpoint_id: string | null;
  readonly committed_eligible_count_after: number;
  readonly hidden_through_message_id_after: number | null;
  readonly unhide_from_message_id: number | null;
}

export interface TavernMemoryMutationRollbackCommitRequest
  extends TavernMemoryMutationRollbackRequest {
  readonly plan: TavernMemoryMutationRollbackPlan;
  readonly unhidden_from_message_id: number | null;
  readonly operation_id: string;
  readonly committed_at: string;
}

export interface TavernMemoryMutationRollbackResult {
  readonly status: "ROLLED_BACK" | "ALREADY_ROLLED_BACK";
  readonly head: TavernMemoryColdHead;
  readonly plan: TavernMemoryMutationRollbackPlan;
}

async function readTarget(
  store: TavernMemoryCheckpointStorePort,
  batch: CompletedBatch,
): Promise<RollbackTarget> {
  const pageIds = batch.core_page_ids;
  if (pageIds === undefined || pageIds.length === 0) {
    throw new TypeError("Rollback target has no immutable checkpoint pages");
  }
  const records = (await Promise.all(pageIds.map((pageId) => store.readCorePage(pageId)))).flatMap(
    (page) => page.records,
  );
  const manifestRecord = records.find(
    (record) =>
      record.record_kind === TAVERN_MEMORY_CHECKPOINT_MANIFEST_KIND &&
      record.record_id === `checkpoint_manifest:${batch.checkpoint_id}`,
  );
  if (manifestRecord === undefined) throw new TypeError("Rollback checkpoint manifest is missing");
  const manifest = manifestRecord.payload as unknown as TavernMemoryCheckpointManifest;
  const body = records.filter((record) => record !== manifestRecord);
  if (
    manifest.checkpoint_id !== batch.checkpoint_id ||
    manifest.final_records_sha256 !== (await checksumJson(body)) ||
    canonicalJson(manifest.final_record_ids) !==
      canonicalJson(body.map((record) => record.record_id))
  ) {
    throw new TypeError("Rollback checkpoint pages failed manifest verification");
  }
  return { batch, manifest, corpus: parseTavernRecallCorpus(body) };
}

async function resolveTarget(
  request: TavernMemoryMutationRollbackRequest,
  head: TavernMemoryColdHead,
): Promise<RollbackTarget | null> {
  const eligible = head.source_index.completed_batches
    .filter(
      (batch) =>
        batch.last_ai_ordinal < request.mutation_ai_ordinal &&
        batch.recall_version === TAVERN_MEMORY_CHECKPOINT_RECALL_VERSION &&
        batch.core_page_ids !== undefined &&
        batch.core_page_ids.length > 0,
    )
    .sort((left, right) => right.last_ai_ordinal - left.last_ai_ordinal);
  const selected = eligible[0];
  if (selected === undefined) return null;
  const target = await readTarget(request.book_store, selected);
  await alignTavernMemoryCheckpointSource(
    target.manifest,
    request.current_source_snapshot,
    "ALLOW_APPEND_ONLY_LIVE_TAIL",
  );
  return target;
}

function assertRequest(request: TavernMemoryMutationRollbackRequest): void {
  if (
    request.new_source_revision_id.trim().length === 0 ||
    request.mutation_source_unit_id.trim().length === 0 ||
    !Number.isInteger(request.valid_ai_count) ||
    request.valid_ai_count < 0 ||
    !Number.isInteger(request.mutation_message_id) ||
    request.mutation_message_id < 0 ||
    !Number.isInteger(request.mutation_ai_ordinal) ||
    request.mutation_ai_ordinal < 1
  ) {
    throw new TypeError("Invalid mutation rollback request");
  }
}

export async function planTavernMemoryMutationRollback(
  request: TavernMemoryMutationRollbackRequest,
): Promise<TavernMemoryMutationRollbackPlan> {
  assertRequest(request);
  await verifyTavernSourceSnapshot(request.current_source_snapshot);
  const cold = await request.book_store.readColdHead();
  const head = cold.head;
  if (cold.status !== "READY" || head === null) throw new TypeError("Memory Book is unavailable");
  const target = await resolveTarget(request, head);
  const currentHidden = head.checkpoint_index.hidden_through_message_id;
  const targetHidden = target?.batch.hidden_through_message_id ?? null;
  const unhideCandidates = [
    ...(currentHidden !== null && request.mutation_message_id <= currentHidden
      ? [request.mutation_message_id]
      : []),
    ...(currentHidden !== null && (targetHidden === null || currentHidden > targetHidden)
      ? [(targetHidden ?? -1) + 1]
      : []),
  ];
  return {
    rollback_version: TAVERN_MEMORY_MUTATION_ROLLBACK_VERSION,
    from_checkpoint_id: head.checkpoint_index.checkpoint_id,
    to_checkpoint_id: target?.batch.checkpoint_id ?? null,
    committed_eligible_count_after: target?.batch.last_ai_ordinal ?? 0,
    hidden_through_message_id_after: targetHidden,
    unhide_from_message_id: unhideCandidates.length === 0 ? null : Math.min(...unhideCandidates),
  };
}

const asJson = (value: unknown): TavernJsonValue => value as TavernJsonValue;

function payloadBatchId(record: TavernMemoryCorePage["records"][number]): string | null {
  if (record.payload !== null && typeof record.payload === "object" && !Array.isArray(record.payload)) {
    const candidate = (record.payload as Readonly<Record<string, unknown>>).batch_id;
    if (typeof candidate === "string") return candidate;
  }
  return record.record_id.startsWith("memory_batch_input:")
    ? record.record_id.slice("memory_batch_input:".length)
    : null;
}

function newestFirst(left: TavernMemoryModuleViewItem, right: TavernMemoryModuleViewItem): number {
  return (
    right.sort_time.localeCompare(left.sort_time) ||
    right.record_revision - left.record_revision ||
    right.record_id.localeCompare(left.record_id)
  );
}

async function rebuildRetainedPages(
  request: TavernMemoryMutationRollbackCommitRequest,
  head: TavernMemoryColdHead,
  keptBatches: readonly CompletedBatch[],
): Promise<{
  readonly retained_core_page_ids: readonly string[];
  readonly module_views: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
  readonly module_view_pages: readonly TavernMemoryModuleViewPage[];
}> {
  const keptBatchIds = new Set(keptBatches.map((batch) => batch.batch_id));
  const checkpointPageIds = new Set(
    keptBatches.flatMap((batch) => batch.core_page_ids ?? []),
  );
  const corePages = await Promise.all(head.core_page_ids.map((pageId) => request.book_store.readCorePage(pageId)));
  const retainedCorePages = corePages.filter(
    (page) =>
      checkpointPageIds.has(page.page_id) ||
      page.records.some((record) => {
        const batchId = payloadBatchId(record);
        return batchId !== null && keptBatchIds.has(batchId);
      }),
  );
  const retainedCorePageIds = retainedCorePages.map((page) => page.page_id);
  const retainedCoreSet = new Set(retainedCorePageIds);
  const existingViews = await Promise.all(
    head.module_view_page_ids.map((pageId) => request.book_store.readModuleViewPage(pageId)),
  );
  const nextPages: TavernMemoryModuleViewPage[] = [];
  const indexes = {} as Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>;
  for (const moduleId of TAVERN_MEMORY_MODULE_IDS) {
    const deduplicated = new Map<string, TavernMemoryModuleViewItem>();
    for (const page of existingViews) {
      if (page.module_id !== moduleId) continue;
      for (const item of page.items) {
        if (!retainedCoreSet.has(item.core_page_id)) continue;
        const existing = deduplicated.get(item.record_id);
        if (existing === undefined || newestFirst(item, existing) < 0) {
          deduplicated.set(item.record_id, item);
        }
      }
    }
    const items = [...deduplicated.values()].sort(newestFirst);
    const chunks = Array.from({ length: Math.ceil(items.length / 24) }, (_unused, index) =>
      items.slice(index * 24, (index + 1) * 24),
    );
    const pageIds = await Promise.all(
      chunks.map(async (chunk, index) =>
        `rollback_view_${(
          await sha256HexUtf8(
            canonicalJson({
              operation_id: request.operation_id,
              mutation_source_unit_id: request.mutation_source_unit_id,
              to_checkpoint_id: request.plan.to_checkpoint_id,
              module_id: moduleId,
              index,
              records: chunk.map((item) => [item.record_id, item.record_revision]),
            }),
          )
        ).slice(0, 40)}`,
      ),
    );
    for (const [index, chunk] of chunks.entries()) {
      nextPages.push({
        page_id: pageIds[index] as string,
        module_id: moduleId,
        newer_page_id: null,
        older_page_id: pageIds[index + 1] ?? null,
        items: chunk,
      });
    }
    const newest = items[0];
    indexes[moduleId] = {
      module_id: moduleId,
      record_count: items.length,
      abnormal_count: items.filter((item) => item.status !== "ACTIVE").length,
      newest_cursor:
        newest === undefined
          ? null
          : {
              sort_time: newest.sort_time,
              record_revision: newest.record_revision,
              record_id: newest.record_id,
            },
      latest_page_id: pageIds[0] ?? null,
      oldest_page_id: pageIds.at(-1) ?? null,
      page_count: pageIds.length,
    };
  }
  return {
    retained_core_page_ids: retainedCorePageIds,
    module_views: indexes,
    module_view_pages: nextPages,
  };
}

export async function commitTavernMemoryMutationRollback(
  request: TavernMemoryMutationRollbackCommitRequest,
): Promise<TavernMemoryMutationRollbackResult> {
  assertRequest(request);
  if (
    request.operation_id.trim().length === 0 ||
    request.committed_at.trim().length === 0 ||
    request.unhidden_from_message_id !== request.plan.unhide_from_message_id
  ) {
    throw new TypeError("Mutation rollback host receipt or commit identity is invalid");
  }
  const expectedPlan = await planTavernMemoryMutationRollback(request);
  if (canonicalJson(expectedPlan) !== canonicalJson(request.plan)) {
    throw new TypeError("Mutation rollback plan changed before commit");
  }
  const cold = await request.book_store.readColdHead();
  const head = cold.head;
  if (cold.status !== "READY" || head === null) throw new TypeError("Memory Book is unavailable");
  if (
    head.source_index.mutation_from_source_unit_id === request.mutation_source_unit_id &&
    head.source_index.source_revision_id === request.new_source_revision_id &&
    head.checkpoint_index.checkpoint_id === request.plan.to_checkpoint_id
  ) {
    return { status: "ALREADY_ROLLED_BACK", head, plan: request.plan };
  }
  const targetBatch = head.source_index.completed_batches.find(
    (batch) => batch.checkpoint_id === request.plan.to_checkpoint_id,
  );
  const target =
    targetBatch === undefined ? null : await readTarget(request.book_store, targetBatch);
  const keptBatches = head.source_index.completed_batches.filter(
    (batch) => batch.last_ai_ordinal <= request.plan.committed_eligible_count_after,
  );
  const targetPages = target?.batch.core_page_ids ?? [];
  const activeState = target?.corpus.current_state_view ?? {};
  const epistemicState = {
    version: TAVERN_MEMORY_MUTATION_ROLLBACK_VERSION,
    states: target?.corpus.epistemic_states ?? [],
  };
  const threadImpact = {
    version: TAVERN_MEMORY_MUTATION_ROLLBACK_VERSION,
    threads: target?.corpus.narrative_threads ?? [],
    impacts: target?.corpus.future_impacts ?? [],
  };
  const retained = await rebuildRetainedPages(request, head, keptBatches);
  const committed = await request.book_store.commit({
    commit_id: `${request.operation_id}:mutation_rollback:${request.mutation_source_unit_id}`,
    expected_generation: head.generation,
    expected_generation_checksum: head.generation_checksum,
    committed_at: request.committed_at,
    source_index: {
      source_revision_id: request.new_source_revision_id,
      source_checksum: request.current_source_snapshot.checksum,
      valid_ai_count: request.valid_ai_count,
      committed_eligible_count: request.plan.committed_eligible_count_after,
      protected_ai_ordinals: request.protected_ai_ordinals,
      completed_batches: keptBatches,
      mutation_from_source_unit_id: request.mutation_source_unit_id,
    },
    work_state: null,
    checkpoint_index: {
      checkpoint_id: target?.batch.checkpoint_id ?? null,
      source_revision_id: target?.manifest.source_revision_id ?? null,
      covered_ai_ordinal: target?.batch.last_ai_ordinal ?? 0,
      recall_version: target?.batch.recall_version ?? null,
      hidden_through_message_id: request.plan.hidden_through_message_id_after,
      core_page_ids: targetPages,
    },
    active_state: asJson(activeState),
    epistemic_state: asJson(epistemicState),
    thread_impact: asJson(threadImpact),
    module_views: retained.module_views,
    audit_ring: [
      ...head.audit_ring,
      {
        at: request.committed_at,
        batch_id: null,
        module_id: null,
        event: "source_mutation_rollback",
        error_code: null,
      },
    ],
    retained_core_page_ids: retained.retained_core_page_ids,
    retained_module_view_page_ids: [],
    core_pages: [],
    module_view_pages: retained.module_view_pages,
  });
  const verifiedCold = await request.book_store.readColdHead();
  if (
    verifiedCold.status !== "READY" ||
    verifiedCold.head?.generation !== committed.generation ||
    verifiedCold.head.checkpoint_index.checkpoint_id !== request.plan.to_checkpoint_id
  ) {
    throw new TypeError("Mutation rollback failed cold verification");
  }
  if (request.plan.to_checkpoint_id !== null) {
    await readVerifiedTavernMemoryCheckpoint(request.book_store, request.plan.to_checkpoint_id);
  }
  return { status: "ROLLED_BACK", head: verifiedCold.head, plan: request.plan };
}
