const ARCHIVE_BOOK_PREFIX = "NarraMem__ARCHIVE__";
const SHA256_PATTERN = /^[0-9a-f]{64}$/u;
const ID_FIELDS = [
  "scene_id",
  "episode_id",
  "event_id",
  "entity_id",
  "identity_claim_id",
  "assessment_id",
  "assertion_id",
  "delta_id",
  "view_id",
  "epistemic_id",
  "proposition_id",
  "transfer_id",
  "causal_id",
  "thread_id",
  "impact_id",
  "interpretation_id",
  "cue_id",
] as const;

function toJsonValue(value: unknown): TavernJsonValue {
  canonicalJson(value);
  return value as TavernJsonValue;
}

function derivedRecordId(record: DerivedRecord): NarraMemId {
  const object = record as unknown as Readonly<Record<string, unknown>>;
  for (const field of ID_FIELDS) {
    const value = object[field];
    if (getNarraMemIdKind(value) !== undefined) return value as NarraMemId;
  }
  throw new TavernSemanticArchiveError("PROPOSAL_REJECTED", "Derived record has no typed ID");
}

export function incrementalCandidateKeyByRecordId(
  batch: NarrativeIncrementalExtractionCandidateBatch,
  context: NarrativeIncrementalCandidateCompilerContext,
  ports: CandidateCompilerPorts,
): ReadonlyMap<string, string> {
  const hygienic = applyCandidateHygiene(batch).batch;
  const result = new Map<string, string>();
  const add = (kind: NarraMemIdKind, stablePart: string, candidateKey: string): void => {
    const id = ports.allocate_id(
      kind,
      `${context.active_revision_id}:${context.compilation_key}:${stablePart}:${candidateKey}`,
    );
    result.set(id, candidateKey);
  };
  hygienic.entities.forEach((item) => {
    add("entity", "entity", item.candidate_key);
  });
  hygienic.scenes.forEach((item) => {
    add("scene", "scene", item.candidate_key);
  });
  hygienic.events.forEach((item) => {
    add("event", "event", item.candidate_key);
  });
  hygienic.state_transitions.forEach((item) => {
    add("state_delta", "state_delta", item.candidate_key);
    if (item.after_state.status === "known") {
      add("state_assertion", "state_assertion", item.candidate_key);
    }
  });
  hygienic.epistemic_states.forEach((item) => {
    add("proposition", "proposition", item.candidate_key);
    add("epistemic_state", "epistemic_state", item.candidate_key);
  });
  hygienic.causal_links.forEach((item) => {
    add("causal_link", "causal_link", item.candidate_key);
  });
  return result;
}

function coreWireDiagnosticCode(kind: string, keyword: string, path: string): string {
  const normalized = path
    .split("/")
    .filter((part) => part.length > 0)
    .join(".");
  return `CORE_WIRE.${kind}.${keyword}:${normalized.length === 0 ? "record" : normalized}`;
}

function semanticWireSchemaName(
  kind: NarraMemIdKind | undefined,
): Parameters<typeof validateWireValue>[0] | null {
  if (kind === "event") return "event_atom";
  if (
    kind === "entity" ||
    kind === "scene" ||
    kind === "episode" ||
    kind === "state_assertion" ||
    kind === "state_delta" ||
    kind === "proposition" ||
    kind === "epistemic_state" ||
    kind === "causal_link" ||
    kind === "current_state_view"
  ) {
    return kind;
  }
  return null;
}

function assertIncrementalCompiledRecords(
  records: readonly DerivedRecord[],
  candidateKeyByRecordId: ReadonlyMap<string, string>,
): void {
  for (const record of records) {
    const id = derivedRecordId(record);
    const kind = getNarraMemIdKind(id);
    const schemaName = semanticWireSchemaName(kind);
    if (schemaName === null) continue;
    const report = validateWireValue(schemaName, record);
    if (report.valid) continue;
    const candidateKeys = [
      ...(candidateKeyByRecordId.has(id) ? [candidateKeyByRecordId.get(id) as string] : []),
      ...record.derivation.dependency_refs.flatMap((dependencyId) => {
        const candidateKey = candidateKeyByRecordId.get(dependencyId);
        return candidateKey === undefined ? [] : [candidateKey];
      }),
    ];
    const errors = report.errors.slice(0, 12);
    throw new CandidateCompilationError(
      `Compiled ${kind ?? "unknown"} record failed its Core wire Schema`,
      [
        "INCREMENTAL_MERGE_RECORD_SCHEMA_INVALID",
        ...errors.map((error) =>
          coreWireDiagnosticCode(kind ?? "unknown", error.keyword, error.instancePath),
        ),
      ],
      {
        candidate_keys: [...new Set(candidateKeys)].sort(),
        diagnostic_paths: errors.map(
          (error) => `/compiled/${kind ?? "unknown"}${error.instancePath}`,
        ),
      },
    );
  }
}

function localizeIncrementalCompilationError(
  error: CandidateCompilationError,
  candidateKeyByRecordId: ReadonlyMap<string, string>,
): CandidateCompilationError {
  if (error.candidate_keys.length > 0) return error;
  const candidateKeys = error.record_ids.flatMap((recordId) => {
    const candidateKey = candidateKeyByRecordId.get(recordId);
    return candidateKey === undefined ? [] : [candidateKey];
  });
  if (candidateKeys.length === 0) return error;
  return new CandidateCompilationError(error.message, error.codes, {
    candidate_keys: [...new Set(candidateKeys)].sort(),
    diagnostic_paths: error.diagnostic_paths,
    record_ids: error.record_ids,
    dependency_record_ids: error.dependency_record_ids,
  });
}

const coreRecord = (
  recordId: string,
  recordKind: string,
  payload: unknown,
): TavernArchiveRecord => ({
  record_id: recordId,
  record_kind: recordKind,
  payload: toJsonValue(payload),
});

function assertWire(name: Parameters<typeof validateWireValue>[0], value: unknown): void {
  const report = validateWireValue(name, value);
  if (!report.valid) {
    throw new TavernSemanticArchiveError(
      "INVALID_INPUT",
      `${name} failed Core wire schema: ${report.errors[0]?.message ?? "unknown error"}`,
    );
  }
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object" && !Array.isArray(value);

function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return (
    Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
  );
}

function isStringArray(value: unknown): value is readonly string[] {
  return Array.isArray(value) && value.every((item) => typeof item === "string");
}

function isQuarantineFinding(value: unknown): boolean {
  if (
    !isObject(value) ||
    !hasExactKeys(value, [
      "code",
      "candidate_kind",
      "candidate_key",
      "root_candidate_keys",
      "evidence_ids",
      "message",
    ])
  ) {
    return false;
  }
  return (
    [
      "FLAT_DRAFT_STATE_UNKNOWN_BOTH_QUARANTINED",
      "FLAT_DRAFT_DEPENDENT_CANDIDATE_QUARANTINED",
      "FLAT_DRAFT_UNRESOLVED_REFERENCE_REMOVED",
      "FLAT_DRAFT_NONCONTIGUOUS_QUOTE_SPLIT",
    ].includes(value.code as string) &&
    ["entity", "event", "state", "epistemic", "causal", "unresolved_item"].includes(
      value.candidate_kind as string,
    ) &&
    typeof value.candidate_key === "string" &&
    value.candidate_key.length > 0 &&
    isStringArray(value.root_candidate_keys) &&
    isStringArray(value.evidence_ids) &&
    value.evidence_ids.every((item) => getNarraMemIdKind(item) === "evidence") &&
    typeof value.message === "string" &&
    value.message.length > 0
  );
}

function isCausalCompletenessFinding(value: unknown): boolean {
  if (
    !isObject(value) ||
    !hasExactKeys(value, [
      "code",
      "evidence_id",
      "cue",
      "start_code_point",
      "end_code_point",
      "message",
    ])
  ) {
    return false;
  }
  return (
    value.code === "EXPLICIT_CAUSAL_CUE_UNCOVERED" &&
    typeof value.evidence_id === "string" &&
    getNarraMemIdKind(value.evidence_id) === "evidence" &&
    typeof value.cue === "string" &&
    value.cue.length > 0 &&
    Number.isInteger(value.start_code_point) &&
    (value.start_code_point as number) >= 0 &&
    Number.isInteger(value.end_code_point) &&
    (value.end_code_point as number) > (value.start_code_point as number) &&
    typeof value.message === "string" &&
    value.message.length > 0
  );
}

function isExtractionQualityAudit(value: unknown): boolean {
  if (
    !isObject(value) ||
    !hasExactKeys(value, [
      "quality_audit_version",
      "source_response_sha256",
      "flat_draft_quarantine",
      "causal_completeness",
    ])
  ) {
    return false;
  }
  const quarantine = value.flat_draft_quarantine;
  const completeness = value.causal_completeness;
  const quarantineValid =
    quarantine === null ||
    (isObject(quarantine) &&
      hasExactKeys(quarantine, ["version", "findings"]) &&
      (quarantine.version === "0.1.0" || quarantine.version === "0.2.0") &&
      Array.isArray(quarantine.findings) &&
      quarantine.findings.every(isQuarantineFinding));
  return (
    value.quality_audit_version === "0.1.0" &&
    typeof value.source_response_sha256 === "string" &&
    SHA256_PATTERN.test(value.source_response_sha256) &&
    quarantineValid &&
    isObject(completeness) &&
    hasExactKeys(completeness, ["policy_version", "findings"]) &&
    completeness.policy_version === "0.1.0" &&
    Array.isArray(completeness.findings) &&
    completeness.findings.every(isCausalCompletenessFinding)
  );
}

export function readTavernSemanticManifestFromArchive(
  records: readonly TavernArchiveRecord[],
): TavernSemanticManifestPayload | null {
  const manifests = records.filter(
    (record) => record.record_id === TAVERN_SEMANTIC_MANIFEST_RECORD_ID,
  );
  if (manifests.length === 0) return null;
  if (manifests.length !== 1) {
    throw new TavernSemanticArchiveError(
      "INVALID_INPUT",
      "Active archive contains duplicate semantic manifests",
    );
  }
  const record = manifests[0];
  if (record?.record_kind !== TAVERN_SEMANTIC_MANIFEST_RECORD_KIND) return null;
  const value = record.payload;
  const expectedKeys = [
    "version",
    "task_fingerprint",
    "source_revision_id",
    "source_checksum",
    "model_input_sha256",
    "coverage_key_sha256",
    "candidate_batch_checksum",
    "changeset_id",
    "model_id",
    "model_identity_assurance",
    "prompt_contract_version",
    "prompt_body_sha256",
    "parameters_hash",
    "validator_version",
    "quality_audit",
  ];
  if (
    !isObject(value) ||
    Object.keys(value).length !== expectedKeys.length ||
    !expectedKeys.every((key) => Object.hasOwn(value, key)) ||
    value.version !== TAVERN_SEMANTIC_ARCHIVE_VERSION ||
    typeof value.task_fingerprint !== "string" ||
    !SHA256_PATTERN.test(value.task_fingerprint) ||
    typeof value.source_revision_id !== "string" ||
    getNarraMemIdKind(value.source_revision_id) !== "source_revision" ||
    typeof value.source_checksum !== "string" ||
    !SHA256_PATTERN.test(value.source_checksum) ||
    typeof value.model_input_sha256 !== "string" ||
    !SHA256_PATTERN.test(value.model_input_sha256) ||
    typeof value.coverage_key_sha256 !== "string" ||
    !SHA256_PATTERN.test(value.coverage_key_sha256) ||
    typeof value.candidate_batch_checksum !== "string" ||
    !SHA256_PATTERN.test(value.candidate_batch_checksum) ||
    typeof value.changeset_id !== "string" ||
    getNarraMemIdKind(value.changeset_id) !== "change_set" ||
    typeof value.model_id !== "string" ||
    value.model_id.length === 0 ||
    value.model_identity_assurance !== "requested_not_attested" ||
    typeof value.prompt_contract_version !== "string" ||
    value.prompt_contract_version.length === 0 ||
    !isHashDigest(value.prompt_body_sha256) ||
    !isHashDigest(value.parameters_hash) ||
    typeof value.validator_version !== "string" ||
    value.validator_version.length === 0 ||
    (value.quality_audit !== null && !isExtractionQualityAudit(value.quality_audit))
  ) {
    throw new TavernSemanticArchiveError("INVALID_INPUT", "Invalid active semantic manifest");
  }
  return value as unknown as TavernSemanticManifestPayload;
}

function causalContinuityBaselineFromArchive(
  records: readonly TavernArchiveRecord[],
  manifest: TavernSemanticManifestPayload | null,
  sourceSnapshot: TavernExtractionTask["source_snapshot"],
): TavernExtractionTask["causal_continuity_baseline"] {
  const carried = readTavernCarriedSemanticBaseFromArchive(records);
  if (carried === null) return null;
  if (
    manifest === null ||
    carried.memory_set_id !== sourceSnapshot.memory_set_id ||
    carried.source_checksum !== manifest.source_checksum ||
    carried.message_count >= sourceSnapshot.messages.length ||
    carried.source_revision >= sourceSnapshot.source_revision
  ) {
    throw new TavernSemanticArchiveError(
      "INVALID_INPUT",
      "Carried semantic base does not authenticate an older append-only extraction",
    );
  }
  let causalLinkCount = 0;
  for (const record of records) {
    if (record.record_kind !== "core_causal_link_v1") continue;
    assertWire("causal_link", record.payload);
    const link = record.payload as unknown as CausalLink;
    if (
      record.record_id !== link.causal_id ||
      link.derivation.input_revision_id !== manifest.source_revision_id
    ) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Carried CausalLink does not belong to the authenticated semantic base",
      );
    }
    causalLinkCount += 1;
  }
  return {
    source_revision_id: manifest.source_revision_id,
    source_checksum: manifest.source_checksum,
    causal_link_count: causalLinkCount,
  };
}

function lifecycleContinuityBaselineFromArchive(
  records: readonly TavernArchiveRecord[],
  manifest: TavernSemanticManifestPayload | null,
  causalBaseline: TavernExtractionTask["causal_continuity_baseline"],
  memorySetId: string,
  sourceSnapshot: TavernExtractionTask["source_snapshot"],
): TavernExtractionTask["lifecycle_continuity_baseline"] {
  if (causalBaseline === null || manifest === null) return null;
  const carried = readTavernCarriedSemanticBaseFromArchive(records);
  if (carried === null) return null;
  const previousSourceMaxOrdinal =
    carried.message_count === 0
      ? null
      : (sourceSnapshot.messages[carried.message_count - 1]?.message_id_at_capture ?? null);
  try {
    return deriveTavernNarrativeLifecycleContinuityBaseline(records, {
      memory_set_id: memorySetId,
      source_revision_id: manifest.source_revision_id as NarraMemId<"source_revision">,
      source_checksum: manifest.source_checksum,
      previous_source_max_ordinal: previousSourceMaxOrdinal,
    });
  } catch (error) {
    throw new TavernSemanticArchiveError(
      "INVALID_INPUT",
      error instanceof Error
        ? `Invalid lifecycle continuity baseline: ${error.message}`
        : "Invalid lifecycle continuity baseline",
    );
  }
}

function knownEntitiesFromArchive(
  records: readonly TavernArchiveRecord[],
): readonly ExtractionKnownEntity[] {
  const known: ExtractionKnownEntity[] = [];
  for (const record of records) {
    if (record.record_kind !== "core_entity_v1") continue;
    assertWire("entity", record.payload);
    const entity = record.payload as unknown as Entity;
    if (record.record_id !== entity.entity_id) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Archived Entity record ID does not match its payload",
      );
    }
    known.push({
      entity_id: entity.entity_id,
      entity_type: entity.entity_type,
      canonical_label: entity.canonical_label,
      aliases: entity.aliases.map((alias) => alias.label),
    });
  }
  return known.sort((left, right) => left.entity_id.localeCompare(right.entity_id));
}

async function rebaseKnownEntities(
  task: TavernExtractionTask,
  compiledAt: string,
): Promise<readonly Entity[]> {
  const expectedIds = new Set(
    task.core_source.model_input.known_entities.map((entity) => entity.entity_id),
  );
  const currentEvidenceIds = new Set(
    task.core_source.evidence_items.map((evidence) => evidence.evidence_id),
  );
  if (expectedIds.size !== task.known_entity_records.length) {
    throw new TavernSemanticArchiveError(
      "INVALID_INPUT",
      "Known Entity records do not match the extraction model input",
    );
  }
  const rebased: Entity[] = [];
  for (const record of task.known_entity_records) {
    if (
      record.record_kind !== "core_entity_v1" ||
      getNarraMemIdKind(record.record_id) !== "entity" ||
      !expectedIds.delete(record.record_id as NarraMemId<"entity">)
    ) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Known Entity record identity is missing or duplicated",
      );
    }
    assertWire("entity", record.payload);
    const entity = record.payload as unknown as Entity;
    const evidenceIds = new Set([
      ...entity.derivation.evidence_refs,
      ...entity.identity_evidence.map((span) => span.evidence_id),
      ...entity.aliases.flatMap((alias) => alias.evidence.map((span) => span.evidence_id)),
    ]);
    if (
      record.record_id !== entity.entity_id ||
      entity.memory_space_id !== task.core_source.memory_space.memory_space_id ||
      entity.branch_id !== task.core_source.memory_space.branch_id ||
      [...evidenceIds].some((evidenceId) => !currentEvidenceIds.has(evidenceId))
    ) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Known Entity cannot be rebased onto the current append-only Evidence set",
      );
    }
    const current: Entity = {
      ...entity,
      derivation: {
        derivation_id: await createDeterministicNarraMemId(
          "derivation",
          `tavern-known-entity-rebase:${task.core_source.source_revision.revision_id}:${entity.entity_id}`,
        ),
        input_revision_id: task.core_source.source_revision.revision_id,
        evidence_refs: [...entity.derivation.evidence_refs],
        dependency_refs: [],
        extractor: { kind: "rule" },
        validator_version: "tavern-known-entity-rebase@0.1.0",
        created_at: compiledAt,
      },
    };
    assertWire("entity", current);
    rebased.push(current);
  }
  if (expectedIds.size !== 0) {
    throw new TavernSemanticArchiveError(
      "INVALID_INPUT",
      "Extraction model input references an unavailable known Entity record",
    );
  }
  return rebased.sort((left, right) => left.entity_id.localeCompare(right.entity_id));
}

function valueGuidance(value: unknown): string {
  if (value === null) return "JSON null（仅在文本明确给出 null 语义时使用）";
  if (Array.isArray(value)) return "JSON array；保持既有数组元素语义";
  if (typeof value === "boolean") return "JSON boolean";
  if (typeof value === "number") return "JSON number";
  if (typeof value === "string") return "JSON string；沿用既有枚举或文本语义";
  return "JSON object；沿用既有字段语义";
}

function semanticVocabularyFromArchive(
  records: readonly TavernArchiveRecord[],
  requestedStateTerms: readonly ExtractionStateKeyTerm[],
  requestedClaimTerms: readonly ExtractionClaimPredicateTerm[],
): {
  readonly state_terms: readonly ExtractionStateKeyTerm[];
  readonly claim_terms: readonly ExtractionClaimPredicateTerm[];
} {
  const stateTerms = new Map(requestedStateTerms.map((term) => [term.state_key, term]));
  const claimTerms = new Map(requestedClaimTerms.map((term) => [term.predicate, term]));
  for (const record of records) {
    if (record.record_kind === "core_state_assertion_v1") {
      assertWire("state_assertion", record.payload);
      const assertion = record.payload as unknown as StateAssertion;
      const existing = stateTerms.get(assertion.state_key);
      if (existing === undefined) {
        stateTerms.set(assertion.state_key, {
          state_key: assertion.state_key,
          definition: "当前角色档案已存在的规范状态键；新观察语义等价时必须沿用。",
          subject_kinds: [assertion.subject.kind],
          value_guidance: valueGuidance(assertion.value),
        });
      } else if (!existing.subject_kinds.includes(assertion.subject.kind)) {
        stateTerms.set(assertion.state_key, {
          ...existing,
          subject_kinds: [...existing.subject_kinds, assertion.subject.kind].sort(),
        });
      }
    }
    if (record.record_kind === "core_proposition_v1") {
      assertWire("proposition", record.payload);
      const proposition = record.payload as unknown as Proposition;
      if (!claimTerms.has(proposition.claim.predicate)) {
        claimTerms.set(proposition.claim.predicate, {
          predicate: proposition.claim.predicate,
          definition: "当前角色档案已存在的规范命题谓词；新命题语义等价时必须沿用。",
          argument_guidance: "沿用既有命题的 argument 顺序与 kind；证据不足时写 unresolved item。",
        });
      }
    }
  }
  return {
    state_terms: [...stateTerms.values()].sort((left, right) =>
      left.state_key.localeCompare(right.state_key),
    ),
    claim_terms: [...claimTerms.values()].sort((left, right) =>
      left.predicate.localeCompare(right.predicate),
    ),
  };
}

export async function createTavernDeterministicCompilerPorts(
  batch:
    | ExtractionCandidateBatch
    | NarrativeExtractionCandidateBatch
    | NarrativeIncrementalExtractionCandidateBatch,
  context: CandidateCompilerContext,
  compiledAt: string,
): Promise<CandidateCompilerPorts> {
  const hygienic = applyCandidateHygiene(batch).batch;
  const allocations = new Map<string, NarraMemId>();
  const add = async (kind: NarraMemIdKind, stableKey: string): Promise<void> => {
    allocations.set(stableKey, await createDeterministicNarraMemId(kind, `compiler:${stableKey}`));
  };
  for (const candidate of hygienic.entities) {
    await add(
      "entity",
      `${context.active_revision_id}:${context.compilation_key}:entity:${candidate.candidate_key}`,
    );
    await add(
      "derivation",
      `${context.active_revision_id}:${context.compilation_key}:derivation:${candidate.candidate_key}`,
    );
  }
  for (const candidate of hygienic.scenes) {
    await add(
      "scene",
      `${context.active_revision_id}:${context.compilation_key}:scene:${candidate.candidate_key}`,
    );
    await add(
      "derivation",
      `${context.active_revision_id}:${context.compilation_key}:derivation:${candidate.candidate_key}`,
    );
  }
  for (const candidate of hygienic.events) {
    await add(
      "event",
      `${context.active_revision_id}:${context.compilation_key}:event:${candidate.candidate_key}`,
    );
    await add(
      "derivation",
      `${context.active_revision_id}:${context.compilation_key}:derivation:${candidate.candidate_key}`,
    );
  }
  if ("state_transitions" in hygienic) {
    for (const candidate of hygienic.state_transitions) {
      await add(
        "state_delta",
        `${context.active_revision_id}:${context.compilation_key}:state_delta:${candidate.candidate_key}`,
      );
      await add(
        "derivation",
        `${context.active_revision_id}:${context.compilation_key}:derivation:state_delta:${candidate.candidate_key}`,
      );
      if (candidate.after_state.status === "known") {
        await add(
          "state_assertion",
          `${context.active_revision_id}:${context.compilation_key}:state_assertion:${candidate.candidate_key}`,
        );
        await add(
          "derivation",
          `${context.active_revision_id}:${context.compilation_key}:derivation:state_assertion:${candidate.candidate_key}`,
        );
      }
    }
    for (const candidate of hygienic.epistemic_states) {
      await add(
        "proposition",
        `${context.active_revision_id}:${context.compilation_key}:proposition:${candidate.candidate_key}`,
      );
      await add(
        "derivation",
        `${context.active_revision_id}:${context.compilation_key}:derivation:proposition:${candidate.candidate_key}`,
      );
      await add(
        "epistemic_state",
        `${context.active_revision_id}:${context.compilation_key}:epistemic_state:${candidate.candidate_key}`,
      );
      await add(
        "derivation",
        `${context.active_revision_id}:${context.compilation_key}:derivation:epistemic_state:${candidate.candidate_key}`,
      );
    }
    for (const candidate of hygienic.causal_links) {
      await add(
        "causal_link",
        `${context.active_revision_id}:${context.compilation_key}:causal_link:${candidate.candidate_key}`,
      );
      await add(
        "derivation",
        `${context.active_revision_id}:${context.compilation_key}:derivation:causal_link:${candidate.candidate_key}`,
      );
    }
    if (hygienic.state_transitions.length > 0) {
      await add(
        "current_state_view",
        `${context.active_revision_id}:${context.compilation_key}:current_state_view`,
      );
      await add(
        "derivation",
        `${context.active_revision_id}:${context.compilation_key}:derivation:current_state_view`,
      );
    }
  }
  await add("change_set", `${context.active_revision_id}:${context.compilation_key}:change_set`);
  return {
    allocate_id: <Kind extends NarraMemIdKind>(kind: Kind, stableKey: string) => {
      const allocated = allocations.get(stableKey);
      if (allocated === undefined || getNarraMemIdKind(allocated) !== kind) {
        throw new TavernSemanticArchiveError(
          "PROPOSAL_REJECTED",
          `Compiler requested an unregistered ${kind} allocation`,
        );
      }
      return allocated as NarraMemId<Kind>;
    },
    hash_text: sha256DigestUtf8,
    now: () => compiledAt,
  };
}

const INCREMENTAL_SEMANTIC_RECORD_SCHEMAS = new Map<string, Parameters<typeof assertWire>[0]>([
  ["core_entity_v1", "entity"],
  ["core_scene_v1", "scene"],
  ["core_episode_v1", "episode"],
  ["core_event_v1", "event_atom"],
  ["core_state_assertion_v1", "state_assertion"],
  ["core_state_delta_v1", "state_delta"],
  ["core_proposition_v1", "proposition"],
  ["core_epistemic_state_v1", "epistemic_state"],
  ["core_causal_link_v1", "causal_link"],
  ["core_current_state_view_v1", "current_state_view"],
]);

function incrementalSemanticRecordsFromArchive(
  records: readonly TavernArchiveRecord[],
  sourceEntities: readonly Entity[],
): readonly NarrativeIncrementalSemanticRecord[] {
  const byId = new Map<string, NarrativeIncrementalSemanticRecord>();
  for (const record of records) {
    const schema = INCREMENTAL_SEMANTIC_RECORD_SCHEMAS.get(record.record_kind);
    if (schema === undefined) continue;
    assertWire(schema, record.payload);
    const semantic = record.payload as unknown as NarrativeIncrementalSemanticRecord;
    if (derivedRecordId(semantic) !== record.record_id || byId.has(record.record_id)) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        `Incremental semantic record ${record.record_id} is duplicated or misidentified`,
      );
    }
    byId.set(record.record_id, semantic);
  }
  for (const entity of sourceEntities) {
    assertWire("entity", entity);
    byId.set(entity.entity_id, entity);
  }
  return [...byId.values()].sort((left, right) =>
    derivedRecordId(left).localeCompare(derivedRecordId(right)),
  );
}

function boundedExistingSemanticContext(
  records: readonly NarrativeIncrementalSemanticRecord[],
  evidenceItems: TavernExtractionTask["core_source"]["evidence_items"],
  contextStartOrdinal: number,
  novelStartOrdinal: number,
): NarrativeIncrementalExtractionModelInput["existing_semantic_context"] {
  const evidenceOrder = new Map(
    evidenceItems.map((evidence) => [evidence.evidence_id, evidence.source_order.ordinal]),
  );
  const byId = new Map(records.map((record) => [derivedRecordId(record), record]));
  const selected = new Set<NarraMemId>();
  for (const record of records) {
    if (getNarraMemIdKind(derivedRecordId(record)) === "current_state_view") continue;
    if (
      record.derivation.evidence_refs.some((evidenceId) => {
        const ordinal = evidenceOrder.get(evidenceId);
        return (
          ordinal !== undefined && ordinal >= contextStartOrdinal && ordinal < novelStartOrdinal
        );
      })
    ) {
      selected.add(derivedRecordId(record));
    }
  }
  const currentStateView = records.find(
    (record): record is CurrentStateView =>
      getNarraMemIdKind(derivedRecordId(record)) === "current_state_view",
  );
  currentStateView?.assertion_refs.forEach((assertionId) => {
    selected.add(assertionId);
  });
  let changed = true;
  while (changed) {
    changed = false;
    for (const id of [...selected]) {
      const record = byId.get(id);
      if (record === undefined) continue;
      for (const dependencyId of record.derivation.dependency_refs) {
        const dependency = byId.get(dependencyId);
        if (
          dependency !== undefined &&
          getNarraMemIdKind(dependencyId) !== "entity" &&
          getNarraMemIdKind(dependencyId) !== "current_state_view" &&
          !selected.has(dependencyId)
        ) {
          selected.add(dependencyId);
          changed = true;
        }
      }
    }
  }
  const selectedRecords = records.filter((record) => selected.has(derivedRecordId(record)));
  const ofKind = <Kind extends ReturnType<typeof getNarraMemIdKind>>(kind: Kind) =>
    selectedRecords.filter((record) => getNarraMemIdKind(derivedRecordId(record)) === kind);
  return {
    scenes: ofKind(
      "scene",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["scenes"],
    episodes: ofKind(
      "episode",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["episodes"],
    events: ofKind(
      "event",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["events"],
    state_assertions: ofKind(
      "state_assertion",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["state_assertions"],
    state_deltas: ofKind(
      "state_delta",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["state_deltas"],
    propositions: ofKind(
      "proposition",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["propositions"],
    epistemic_states: ofKind(
      "epistemic_state",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["epistemic_states"],
    causal_links: ofKind(
      "causal_link",
    ) as NarrativeIncrementalExtractionModelInput["existing_semantic_context"]["causal_links"],
  };
}

export async function createTavernDeterministicMergePorts(request: {
  readonly source_revision_id: NarraMemId<"source_revision">;
  readonly stable_semantic_records: readonly NarrativeIncrementalSemanticRecord[];
  readonly merge_key: string;
  readonly compiled_at: string;
}): Promise<CandidateCompilerPorts> {
  const revisionId = request.source_revision_id;
  const mergeKey = request.merge_key;
  const compiledAt = request.compiled_at;
  const allocations = new Map<string, NarraMemId>();
  for (const record of request.stable_semantic_records) {
    const id = derivedRecordId(record);
    if (getNarraMemIdKind(id) === "current_state_view") continue;
    const key = `${revisionId}:${mergeKey}:rebase:${id}`;
    allocations.set(
      key,
      await createDeterministicNarraMemId("derivation", `incremental-merge:${key}`),
    );
  }
  const viewKey = `${revisionId}:${mergeKey}:current_state_view`;
  const viewDerivationKey = `${revisionId}:${mergeKey}:derivation:current_state_view`;
  allocations.set(
    viewKey,
    await createDeterministicNarraMemId("current_state_view", `incremental-merge:${viewKey}`),
  );
  allocations.set(
    viewDerivationKey,
    await createDeterministicNarraMemId("derivation", `incremental-merge:${viewDerivationKey}`),
  );
  return {
    allocate_id: <Kind extends NarraMemIdKind>(kind: Kind, stableKey: string) => {
      const allocated = allocations.get(stableKey);
      if (allocated === undefined || getNarraMemIdKind(allocated) !== kind) {
        throw new TavernSemanticArchiveError(
          "PROPOSAL_REJECTED",
          `Semantic merge requested an unregistered ${kind} allocation`,
        );
      }
      return allocated as NarraMemId<Kind>;
    },
    hash_text: sha256DigestUtf8,
    now: () => compiledAt,
  };
}

async function deterministicMergePorts(
  task: TavernIncrementalExtractionTask,
  mergeKey: string,
  compiledAt: string,
): Promise<CandidateCompilerPorts> {
  return createTavernDeterministicMergePorts({
    source_revision_id: task.base_task.core_source.source_revision.revision_id,
    stable_semantic_records: task.stable_semantic_records,
    merge_key: mergeKey,
    compiled_at: compiledAt,
  });
}

function priorLifecycleRecords(records: readonly TavernArchiveRecord[]): TavernArchiveRecord[] {
  const manifest = readTavernNarrativeLifecycleManifestFromArchive(records);
  if (manifest === null) return [];
  return records.filter(
    (record) =>
      record.record_kind === "core_narrative_thread_v1" ||
      record.record_kind === "core_future_impact_v1" ||
      (record.record_id === TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_ID &&
        record.record_kind === TAVERN_NARRATIVE_LIFECYCLE_MANIFEST_RECORD_KIND) ||
      (record.record_id === manifest.lifecycle_changeset_id &&
        record.record_kind === "core_authorized_changeset_v1"),
  );
}

export class TavernSemanticArchiveService {
  private readonly registry: TavernMemoryRegistry;

  constructor(
    private readonly port: TavernHostPort,
    private readonly segmentLimits: {
      readonly max_records_per_segment: number;
      readonly max_segment_utf8_bytes: number;
    },
  ) {
    this.registry = new TavernMemoryRegistry(port);
  }

  async prepareExtraction(request: TavernPrepareExtractionRequest): Promise<TavernExtractionTask> {
    const resolution = await this.registry.resolveCurrentMemorySet();
    if (resolution.status !== "EXACT" || resolution.selected === null) {
      throw new TavernSemanticArchiveError(
        "MEMORY_SET_NOT_EXACT",
        `Extraction requires EXACT Memory Set resolution, received ${resolution.status}`,
      );
    }
    const candidate = resolution.selected;
    const store = this.store(candidate);
    const control = await store.readControl();
    if (control.active_view === null) {
      throw new TavernSemanticArchiveError(
        "NO_ACTIVE_SOURCE",
        "Current chat must be persisted before extraction",
      );
    }
    const activeRecords = await store.readActiveSnapshot();
    const sourceSnapshot = await reconstructTavernSourceSnapshot(
      activeRecords,
      candidate.control.memory_set_id,
    );
    if (
      sourceSnapshot.source_revision !== control.active_view.source_revision ||
      sourceSnapshot.checksum !== control.active_view.source_checksum
    ) {
      throw new TavernSemanticArchiveError(
        "NO_ACTIVE_SOURCE",
        "Active source manifest does not match Control",
      );
    }
    const existingSemanticManifest = readTavernSemanticManifestFromArchive(activeRecords);
    const causalContinuityBaseline = causalContinuityBaselineFromArchive(
      activeRecords,
      existingSemanticManifest,
      sourceSnapshot,
    );
    const lifecycleContinuityBaseline = lifecycleContinuityBaselineFromArchive(
      activeRecords,
      existingSemanticManifest,
      causalContinuityBaseline,
      candidate.control.memory_set_id,
      sourceSnapshot,
    );
    const knownEntities = knownEntitiesFromArchive(activeRecords);
    const archivedKnownEntityRecords = activeRecords.filter(
      (record) => record.record_kind === "core_entity_v1",
    );
    const semanticVocabulary = semanticVocabularyFromArchive(
      activeRecords,
      request.state_key_vocabulary ?? [],
      request.claim_predicate_vocabulary ?? [],
    );
    let coreSource = await projectTavernCoreSource({
      snapshot: sourceSnapshot,
      known_entities: knownEntities,
      event_type_vocabulary: request.event_type_vocabulary,
      state_key_vocabulary: semanticVocabulary.state_terms,
      claim_predicate_vocabulary: semanticVocabulary.claim_terms,
      default_story_time: request.default_story_time,
      created_at: request.created_at,
    });
    const persistedRevisionRecord = activeRecords.find(
      (record) =>
        record.record_kind === "core_source_revision_v1" &&
        record.record_id === coreSource.source_revision.revision_id,
    );
    if (persistedRevisionRecord !== undefined) {
      assertWire("source_revision", persistedRevisionRecord.payload);
      const persistedRevision = persistedRevisionRecord.payload as unknown as SourceRevision;
      if (
        persistedRevision.snapshot_fingerprint.value !== sourceSnapshot.checksum ||
        persistedRevision.memory_space_id !== coreSource.memory_space.memory_space_id ||
        persistedRevision.branch_id !== coreSource.memory_space.branch_id
      ) {
        throw new TavernSemanticArchiveError(
          "INVALID_INPUT",
          "Archived SourceRevision does not match the current source projection",
        );
      }
      coreSource = await projectTavernCoreSource({
        snapshot: sourceSnapshot,
        known_entities: knownEntities,
        event_type_vocabulary: request.event_type_vocabulary,
        state_key_vocabulary: semanticVocabulary.state_terms,
        claim_predicate_vocabulary: semanticVocabulary.claim_terms,
        default_story_time: request.default_story_time,
        created_at: persistedRevision.created_at,
      });
    }
    const projectedEntityIds = new Set<string>(
      coreSource.source_entities.map((entity) => entity.entity_id),
    );
    const knownEntityRecords = [
      ...archivedKnownEntityRecords.filter((record) => !projectedEntityIds.has(record.record_id)),
      ...coreSource.source_entities.map((entity) =>
        coreRecord(entity.entity_id, "core_entity_v1", entity),
      ),
    ].sort((left, right) => left.record_id.localeCompare(right.record_id));
    assertWire("memory_space", coreSource.memory_space);
    assertWire("source_revision", coreSource.source_revision);
    for (const evidence of coreSource.evidence_items) assertWire("evidence_item", evidence);
    for (const entity of coreSource.source_entities) assertWire("entity", entity);
    assertWire("narrative_extraction_model_input", coreSource.model_input);
    const sourceProjection = await compileTavernCurrentArchive(sourceSnapshot);
    const modelInputSha256 = await checksumJson(coreSource.model_input);
    // Archive-derived entities and vocabulary are outputs of the last extraction.
    // Feeding them back into the next model input is useful when the source changes,
    // but they must not make an unchanged source look like a new extraction contract.
    // Explicit caller vocabulary remains part of the coverage key so an actual
    // configuration change still invalidates semantic coverage.
    const coverageKeySha256 = await checksumJson({
      ...coreSource.model_input,
      known_entities: [],
      state_key_vocabulary: request.state_key_vocabulary ?? [],
      claim_predicate_vocabulary: request.claim_predicate_vocabulary ?? [],
    });
    const taskFingerprint = await checksumJson({
      version: TAVERN_SEMANTIC_ARCHIVE_VERSION,
      control_checksum: control.checksum,
      active_view_id: control.active_view.view_id,
      source_checksum: sourceSnapshot.checksum,
      model_input: coreSource.model_input,
      causal_continuity_baseline: causalContinuityBaseline,
      lifecycle_continuity_baseline: lifecycleContinuityBaseline,
    });
    return {
      task_version: TAVERN_SEMANTIC_ARCHIVE_VERSION,
      task_fingerprint: taskFingerprint,
      resolution,
      candidate,
      control_checksum: control.checksum,
      active_view_id: control.active_view.view_id,
      source_snapshot: sourceSnapshot,
      source_records: sourceProjection.records,
      known_entity_records: knownEntityRecords,
      core_source: coreSource,
      model_input_sha256: modelInputSha256,
      coverage_key_sha256: coverageKeySha256,
      causal_continuity_baseline: causalContinuityBaseline,
      lifecycle_continuity_baseline: lifecycleContinuityBaseline,
      existing_semantic_manifest: existingSemanticManifest,
      ...(request.normalize_semantic_metadata === undefined
        ? {}
        : { normalize_semantic_metadata: request.normalize_semantic_metadata }),
    };
  }

  async prepareIncrementalExtraction(
    request: TavernPrepareIncrementalExtractionRequest,
  ): Promise<TavernIncrementalExtractionTask> {
    if (
      !Number.isInteger(request.chunk_message_limit) ||
      request.chunk_message_limit < 1 ||
      !Number.isInteger(request.context_message_limit) ||
      request.context_message_limit < 0
    ) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Incremental extraction requires positive chunk and non-negative context limits",
      );
    }
    const baseTask = await this.prepareExtraction(request);
    const store = this.store(baseTask.candidate);
    const activeRecords = await store.readActiveSnapshot();
    const activeRecordsChecksum = await checksumJson(activeRecords);
    const previousCursor = readTavernIncrementalSemanticCoverageFromArchive(activeRecords);
    if (previousCursor === null && baseTask.existing_semantic_manifest !== null) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "A pre-cursor semantic archive must be reset to Source before incremental extraction",
      );
    }
    if (previousCursor !== null) {
      const recovered = await recoverTavernIncrementalSemanticCoverage(
        previousCursor,
        baseTask.source_snapshot,
      );
      if (recovered.next_action === "RUN_LIFECYCLE") {
        throw new TavernSemanticArchiveError(
          "LIFECYCLE_PENDING",
          "The durable semantic chunk must finish lifecycle before another chunk starts",
        );
      }
      if (recovered.next_action === "RUN_REPAIR") {
        throw new TavernSemanticArchiveError(
          "REPAIR_PENDING",
          "The durable semantic chunk has quarantined records awaiting targeted repair",
        );
      }
      if (recovered.next_action === "CAUGHT_UP") {
        throw new TavernSemanticArchiveError(
          "NO_UNCOVERED_SOURCE",
          "Incremental semantic coverage already includes the current Source",
        );
      }
    }
    const snapshot = baseTask.source_snapshot;
    const coveredCount = previousCursor?.semantic_head.covered_message_count ?? 0;
    const startMessage = snapshot.messages[coveredCount];
    if (startMessage === undefined) {
      throw new TavernSemanticArchiveError(
        "NO_UNCOVERED_SOURCE",
        "Incremental semantic coverage already includes the current Source",
      );
    }
    const endIndex = Math.min(
      snapshot.messages.length - 1,
      coveredCount + request.chunk_message_limit - 1,
    );
    const initialEndOrdinal = snapshot.messages[endIndex]?.message_id_at_capture;
    if (initialEndOrdinal === undefined) {
      throw new TavernSemanticArchiveError("INVALID_INPUT", "Incremental chunk end disappeared");
    }
    const archivedKnownEntities = knownEntitiesFromArchive(activeRecords);
    const boundedCoreSource = await projectTavernCoreSource({
      snapshot,
      known_entities: archivedKnownEntities,
      event_type_vocabulary: baseTask.core_source.model_input.event_type_vocabulary,
      state_key_vocabulary: baseTask.core_source.model_input.state_key_vocabulary,
      claim_predicate_vocabulary: baseTask.core_source.model_input.claim_predicate_vocabulary,
      default_story_time: request.default_story_time,
      created_at: request.created_at,
      message_end_ordinal: initialEndOrdinal,
    });
    const modelEvidence = boundedCoreSource.model_input.evidence_items;
    const novelEvidenceThrough = (index: number) => {
      const endOrdinal = snapshot.messages[index]?.message_id_at_capture;
      if (endOrdinal === undefined) return [];
      return modelEvidence.filter(
        (evidence) =>
          evidence.source_order.ordinal >= startMessage.message_id_at_capture &&
          evidence.source_order.ordinal <= endOrdinal,
      );
    };
    const novelEvidence = novelEvidenceThrough(endIndex);
    if (novelEvidence.length === 0) {
      throw new TavernSemanticArchiveError(
        "NO_NARRATIVE_EVIDENCE",
        "The uncovered Source tail contains no model-visible narrative Evidence",
      );
    }
    const endMessage = snapshot.messages[endIndex];
    if (endMessage === undefined) {
      throw new TavernSemanticArchiveError("INVALID_INPUT", "Incremental chunk end disappeared");
    }
    const contextStartIndex = Math.max(0, coveredCount - request.context_message_limit);
    const contextStartOrdinal =
      snapshot.messages[contextStartIndex]?.message_id_at_capture ??
      startMessage.message_id_at_capture;
    const boundary = {
      covered_message_count: coveredCount,
      context_start_ordinal: contextStartOrdinal,
      novel_start_ordinal: startMessage.message_id_at_capture,
      novel_end_ordinal: endMessage.message_id_at_capture,
      chunk_sequence: (previousCursor?.semantic_head.chunk_sequence ?? 0) + 1,
    } as const;
    const contextEvidence = modelEvidence.filter(
      (evidence) =>
        evidence.source_order.ordinal >= contextStartOrdinal &&
        evidence.source_order.ordinal < startMessage.message_id_at_capture,
    );
    const stableSemanticRecords = incrementalSemanticRecordsFromArchive(
      activeRecords,
      boundedCoreSource.source_entities,
    );
    const modelInput: NarrativeIncrementalExtractionModelInput = {
      contract_version: "0.1.0",
      source_revision_id: baseTask.core_source.source_revision.revision_id,
      coverage_boundary: boundary,
      context_evidence: contextEvidence,
      novel_evidence: novelEvidence,
      known_entities: boundedCoreSource.model_input.known_entities,
      existing_semantic_context: boundedExistingSemanticContext(
        stableSemanticRecords,
        baseTask.core_source.evidence_items,
        contextStartOrdinal,
        startMessage.message_id_at_capture,
      ),
      event_type_vocabulary: baseTask.core_source.model_input.event_type_vocabulary,
      state_key_vocabulary: baseTask.core_source.model_input.state_key_vocabulary,
      claim_predicate_vocabulary: baseTask.core_source.model_input.claim_predicate_vocabulary,
      vocabulary_policy: "reuse_equivalent_else_propose",
      default_story_time: baseTask.core_source.model_input.default_story_time,
    };
    const inputReport = validateNarrativeIncrementalExtractionModelInput(modelInput);
    if (!inputReport.accepted) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        `Trusted incremental model input failed validation: ${inputReport.issues
          .map((issue) => issue.code)
          .join(",")}`,
      );
    }
    const modelInputSha256 = await checksumJson(modelInput);
    const coverageKeySha256 = await checksumJson({
      source_revision_id: modelInput.source_revision_id,
      coverage_boundary: boundary,
      context_evidence_ids: contextEvidence.map((evidence) => evidence.evidence_id),
      novel_evidence_ids: novelEvidence.map((evidence) => evidence.evidence_id),
      previous_semantic_corpus_sha256: previousCursor?.semantic_head.semantic_corpus_sha256 ?? null,
      event_type_vocabulary: request.event_type_vocabulary,
      state_key_vocabulary: request.state_key_vocabulary ?? [],
      claim_predicate_vocabulary: request.claim_predicate_vocabulary ?? [],
    });
    const taskFingerprint = await checksumJson({
      version: TAVERN_INCREMENTAL_SEMANTIC_ARCHIVE_VERSION,
      base_task_fingerprint: baseTask.task_fingerprint,
      active_records_checksum: activeRecordsChecksum,
      previous_cursor: previousCursor,
      model_input: modelInput,
    });
    return {
      task_version: TAVERN_INCREMENTAL_SEMANTIC_ARCHIVE_VERSION,
      task_fingerprint: taskFingerprint,
      base_task: baseTask,
      active_records: activeRecords,
      active_records_checksum: activeRecordsChecksum,
      previous_cursor: previousCursor,
      boundary,
      stable_semantic_records: stableSemanticRecords,
      model_input: modelInput,
      model_input_sha256: modelInputSha256,
      coverage_key_sha256: coverageKeySha256,
    };
  }

  async prepareIncrementalRepair(
    request: TavernPrepareIncrementalExtractionRequest,
    state: TavernIncrementalRepairState,
  ): Promise<TavernIncrementalExtractionTask> {
    const baseTask = await this.prepareExtraction(request);
    if (
      state.memory_set_id !== baseTask.candidate.control.memory_set_id ||
      state.source_revision_id !== baseTask.core_source.source_revision.revision_id ||
      state.source_checksum !== baseTask.source_snapshot.checksum ||
      state.model_input.source_revision_id !== baseTask.core_source.source_revision.revision_id
    ) {
      throw new TavernSemanticArchiveError(
        "STALE_TASK",
        "Pending targeted repair no longer matches the authoritative Source",
      );
    }
    const store = this.store(baseTask.candidate);
    const activeRecords = await store.readActiveSnapshot();
    const cursor = readTavernIncrementalSemanticCoverageFromArchive(activeRecords);
    if (
      cursor?.stage !== "partial_semantic_committed" ||
      cursor.semantic_head.chunk_sequence !== state.boundary.chunk_sequence ||
      cursor.semantic_head.novel_start_ordinal !== state.boundary.novel_start_ordinal ||
      cursor.semantic_head.novel_end_ordinal !== state.boundary.novel_end_ordinal
    ) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Pending targeted repair is not backed by a partial semantic coverage cursor",
      );
    }
    const inputReport = validateNarrativeIncrementalExtractionModelInput(state.model_input);
    if (!inputReport.accepted) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        `Persisted targeted repair input failed validation: ${inputReport.issues
          .map((item) => item.code)
          .join(",")}`,
      );
    }
    const stableSemanticRecords = incrementalSemanticRecordsFromArchive(
      activeRecords,
      baseTask.core_source.source_entities,
    );
    return {
      task_version: TAVERN_INCREMENTAL_SEMANTIC_ARCHIVE_VERSION,
      task_fingerprint: state.semantic_task_fingerprint,
      base_task: baseTask,
      active_records: activeRecords,
      active_records_checksum: await checksumJson(activeRecords),
      previous_cursor: cursor,
      boundary: state.boundary,
      stable_semantic_records: stableSemanticRecords,
      model_input: state.model_input,
      model_input_sha256: await checksumJson(state.model_input),
      coverage_key_sha256: await checksumJson({
        source_revision_id: state.source_revision_id,
        source_checksum: state.source_checksum,
        boundary: state.boundary,
        repair_store_version: state.schema_version,
      }),
    };
  }

  async commitCandidateBatch(
    request: TavernSemanticCommitRequest,
  ): Promise<TavernSemanticCommitResult> {
    if (request.task.task_version !== TAVERN_SEMANTIC_ARCHIVE_VERSION) {
      throw new TavernSemanticArchiveError("INVALID_INPUT", "Unsupported extraction task version");
    }
    const resolution = await this.registry.resolveCurrentMemorySet();
    if (
      resolution.status !== "EXACT" ||
      resolution.selected === null ||
      resolution.selected.control_book_name !== request.task.candidate.control_book_name
    ) {
      throw new TavernSemanticArchiveError(
        "STALE_TASK",
        "Memory Set identity changed after prepare",
      );
    }
    const store = this.store(resolution.selected);
    const control = await store.readControl();
    if (
      control.checksum !== request.task.control_checksum ||
      control.pending_transaction !== null ||
      control.active_view?.view_id !== request.task.active_view_id ||
      control.active_view.source_checksum !== request.task.source_snapshot.checksum
    ) {
      throw new TavernSemanticArchiveError(
        "STALE_TASK",
        "Control changed after extraction prepare",
      );
    }
    const knownEntityIds = request.task.core_source.model_input.known_entities.map(
      (entity) => entity.entity_id,
    );
    const context: CandidateCompilerContext = {
      memory_space_id: request.task.core_source.memory_space.memory_space_id,
      branch_id: request.task.core_source.memory_space.branch_id,
      compilation_key: request.compilation_key,
      active_revision_id: request.task.core_source.source_revision.revision_id,
      evidence_items: request.task.core_source.evidence_items,
      known_entity_ids: knownEntityIds,
      extractor: request.extractor,
    };
    const compilerPorts = await createTavernDeterministicCompilerPorts(
      request.candidate_batch,
      context,
      request.compiled_at,
    );
    const compiledProposal =
      request.candidate_batch.contract_version === "0.3.0"
        ? await compileNarrativeExtractionCandidateBatch(
            request.candidate_batch,
            context,
            compilerPorts,
          )
        : await compileExtractionCandidateBatch(request.candidate_batch, context, compilerPorts);
    const compiledDerived = compiledProposal.operations.flatMap((operation) =>
      operation.op === "add_derived" ? [operation.record] : [],
    );
    const continuityBaseline = request.task.causal_continuity_baseline;
    const compiledCausalLinkCount = compiledDerived.filter(
      (record) => getNarraMemIdKind(derivedRecordId(record)) === "causal_link",
    ).length;
    if (
      continuityBaseline !== null &&
      continuityBaseline.causal_link_count > 0 &&
      compiledCausalLinkCount === 0 &&
      (request.quality_audit?.causal_completeness.findings.length ?? 0) === 0
    ) {
      throw new CandidateCompilationError(
        `Append-only extraction silently dropped ${continuityBaseline.causal_link_count} authenticated CausalLink records`,
        ["CAUSAL_CONTINUITY_UNEXPLAINED"],
      );
    }
    const rebasedKnownEntities = await rebaseKnownEntities(request.task, request.compiled_at);
    const episodes = await projectTavernSceneEpisodes({
      source_revision_id: context.active_revision_id,
      derived_records: compiledDerived,
      created_at: request.compiled_at,
    });
    const proposal = {
      ...compiledProposal,
      producer: "hybrid" as const,
      operations: [
        ...rebasedKnownEntities.map((record) => ({ op: "add_derived" as const, record })),
        ...compiledProposal.operations,
        ...episodes.map((record) => ({ op: "add_derived" as const, record })),
      ],
    };
    const report = validateChangeSetProposal(proposal, {
      memory_space_id: context.memory_space_id,
      branch_id: context.branch_id,
      active_revision_id: context.active_revision_id,
      known_evidence_ids: context.evidence_items.map((evidence) => evidence.evidence_id),
      known_records: [],
    });
    if (!report.accepted) {
      throw new TavernSemanticArchiveError(
        "PROPOSAL_REJECTED",
        `Core Validator rejected proposal: ${report.issues.map((issue) => issue.code).join(",")}`,
      );
    }
    const acceptedReport = { ...report, accepted: true as const };
    const policyHash: HashDigest = createSha256Digest(
      await checksumJson({
        committer_version: "tavern-semantic-committer@0.1.0",
        producer: proposal.producer,
        allowed_operations: ["add_derived"],
        source_task_fingerprint: request.task.task_fingerprint,
      }),
    );
    const authorized: AuthorizedChangeSet = {
      stage: "authorized",
      changeset_id: proposal.changeset_id,
      memory_space_id: proposal.memory_space_id,
      branch_id: proposal.branch_id,
      based_on_revision_id: proposal.based_on_revision_id,
      producer: proposal.producer,
      operations: proposal.operations,
      validation_report: acceptedReport,
      authorization: {
        committer_version: "tavern-semantic-committer@0.1.0",
        policy_hash: policyHash,
        authorized_at: request.compiled_at,
      },
    };
    assertWire("authorized_change_set", authorized);
    const derived = proposal.operations.flatMap((operation) =>
      operation.op === "add_derived" ? [operation.record] : [],
    );
    if (derived.length !== proposal.operations.length) {
      throw new TavernSemanticArchiveError(
        "PROPOSAL_REJECTED",
        "Initial Tavern semantic commit only authorizes add_derived operations",
      );
    }
    const archiveRecords: TavernArchiveRecord[] = [
      ...request.task.source_records,
      coreRecord(
        request.task.core_source.memory_space.memory_space_id,
        "core_memory_space_v1",
        request.task.core_source.memory_space,
      ),
      coreRecord(
        request.task.core_source.source_revision.revision_id,
        "core_source_revision_v1",
        request.task.core_source.source_revision,
      ),
      ...request.task.core_source.evidence_items.map((evidence) =>
        coreRecord(evidence.evidence_id, "core_evidence_v1", evidence),
      ),
      ...derived.map((record) => {
        const recordId = derivedRecordId(record);
        return coreRecord(recordId, `core_${getNarraMemIdKind(recordId)}_v1`, record);
      }),
      coreRecord(proposal.changeset_id, "core_authorized_changeset_v1", authorized),
      ...(request.task.lifecycle_continuity_baseline === null
        ? []
        : [
            coreRecord(
              TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_ID,
              TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_KIND,
              request.task.lifecycle_continuity_baseline,
            ),
          ]),
      coreRecord(TAVERN_SEMANTIC_MANIFEST_RECORD_ID, TAVERN_SEMANTIC_MANIFEST_RECORD_KIND, {
        version: TAVERN_SEMANTIC_ARCHIVE_VERSION,
        task_fingerprint: request.task.task_fingerprint,
        source_revision_id: request.task.core_source.source_revision.revision_id,
        source_checksum: request.task.source_snapshot.checksum,
        model_input_sha256: request.task.model_input_sha256,
        coverage_key_sha256: request.task.coverage_key_sha256,
        candidate_batch_checksum: await checksumJson(request.candidate_batch),
        changeset_id: proposal.changeset_id,
        model_id: request.extractor.model_id,
        model_identity_assurance: request.extractor.model_identity_assurance,
        prompt_contract_version: request.extractor.prompt_contract_version,
        prompt_body_sha256: request.extractor.prompt_body_sha256,
        parameters_hash: request.extractor.parameters_hash,
        validator_version: report.validator_version,
        quality_audit: request.quality_audit ?? null,
      }),
    ];
    const committed = await store.commitFullSnapshot({
      transaction_id: request.transaction_id,
      writer_id: request.writer_id,
      build_id: request.build_id,
      view_id: request.view_id,
      source_revision: request.task.source_snapshot.source_revision,
      source_checksum: request.task.source_snapshot.checksum,
      expected_commit_sequence: control.commit_sequence,
      expected_view_id: control.active_view.view_id,
      records: archiveRecords,
      after_durable_phase: async (phase) => {
        if (phase === "pending_recorded" || phase === "pointer_committed") {
          const stability = await reconcileTavernSourceSnapshot(this.port, {
            memory_set_id: request.task.source_snapshot.memory_set_id,
            previous_snapshot: request.task.source_snapshot,
            observed_hints: [],
            ...(request.task.normalize_semantic_metadata === undefined
              ? {}
              : { normalize_semantic_metadata: request.task.normalize_semantic_metadata }),
          });
          if (stability.status !== "UNCHANGED") {
            throw new TavernSemanticArchiveError(
              "SOURCE_CHANGED_DURING_COMMIT",
              `Current chat changed during semantic ${phase}`,
            );
          }
        }
        await request.after_durable_phase?.(phase);
      },
    });
    return {
      control: committed.control,
      proposal,
      validation_report: acceptedReport,
      authorized_changeset: authorized,
      derived_record_count: derived.length,
      archive_record_count: archiveRecords.length,
    };
  }

  async commitIncrementalCandidateBatch(
    request: TavernIncrementalSemanticCommitRequest,
  ): Promise<TavernIncrementalSemanticCommitResult> {
    if (request.task.task_version !== TAVERN_INCREMENTAL_SEMANTIC_ARCHIVE_VERSION) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Unsupported incremental extraction task version",
      );
    }
    const baseTask = request.task.base_task;
    const resolution = await this.registry.resolveCurrentMemorySet();
    if (
      resolution.status !== "EXACT" ||
      resolution.selected === null ||
      resolution.selected.control_book_name !== baseTask.candidate.control_book_name
    ) {
      throw new TavernSemanticArchiveError(
        "STALE_TASK",
        "Memory Set identity changed after incremental prepare",
      );
    }
    const store = this.store(resolution.selected);
    const control = await store.readControl();
    if (
      control.checksum !== baseTask.control_checksum ||
      control.pending_transaction !== null ||
      control.active_view?.view_id !== baseTask.active_view_id ||
      control.active_view.source_checksum !== baseTask.source_snapshot.checksum
    ) {
      throw new TavernSemanticArchiveError(
        "STALE_TASK",
        "Control changed after incremental extraction prepare",
      );
    }
    const activeRecords = await store.readActiveSnapshot();
    if ((await checksumJson(activeRecords)) !== request.task.active_records_checksum) {
      throw new TavernSemanticArchiveError(
        "STALE_TASK",
        "Active archive changed after incremental extraction prepare",
      );
    }
    const context: NarrativeIncrementalCandidateCompilerContext = {
      memory_space_id: baseTask.core_source.memory_space.memory_space_id,
      branch_id: baseTask.core_source.memory_space.branch_id,
      compilation_key: request.compilation_key,
      active_revision_id: baseTask.core_source.source_revision.revision_id,
      evidence_items: baseTask.core_source.evidence_items,
      known_entity_ids: request.task.model_input.known_entities.map((entity) => entity.entity_id),
      extractor: request.extractor,
      novel_evidence_ids: request.task.model_input.novel_evidence.map(
        (evidence) => evidence.evidence_id,
      ),
      existing_semantic_context: request.task.model_input.existing_semantic_context,
    };
    const compilerPorts = await createTavernDeterministicCompilerPorts(
      request.candidate_batch,
      context,
      request.compiled_at,
    );
    const compiledChunk = await compileNarrativeIncrementalExtractionCandidateBatch(
      request.candidate_batch,
      context,
      compilerPorts,
    );
    const compiledDerived = compiledChunk.operations.flatMap((operation) =>
      operation.op === "add_derived" ? [operation.record] : [],
    );
    const candidateKeyByRecordId = incrementalCandidateKeyByRecordId(
      request.candidate_batch,
      context,
      compilerPorts,
    );
    assertIncrementalCompiledRecords(compiledDerived, candidateKeyByRecordId);
    const episodes = await projectTavernSceneEpisodes({
      source_revision_id: context.active_revision_id,
      derived_records: compiledDerived,
      created_at: request.compiled_at,
    });
    assertIncrementalCompiledRecords(episodes, candidateKeyByRecordId);
    const chunkProposal = {
      ...compiledChunk,
      operations: [
        ...compiledChunk.operations,
        ...episodes.map((record) => ({ op: "add_derived" as const, record })),
      ],
    };
    const checkpoint = [...baseTask.core_source.evidence_items]
      .filter(
        (evidence) => evidence.source_order.ordinal <= request.task.boundary.novel_end_ordinal,
      )
      .sort(
        (left, right) =>
          left.source_order.ordinal - right.source_order.ordinal ||
          left.source_order.component - right.source_order.component,
      )
      .at(-1)?.source_order;
    if (checkpoint === undefined) {
      throw new TavernSemanticArchiveError(
        "INVALID_INPUT",
        "Incremental semantic checkpoint has no authoritative Evidence",
      );
    }
    const mergeKey = `${request.compilation_key}:chunk:${request.task.boundary.chunk_sequence}`;
    const mergePorts = await deterministicMergePorts(request.task, mergeKey, request.compiled_at);
    let merged: Awaited<ReturnType<typeof mergeNarrativeIncrementalSemanticCorpus>>;
    try {
      merged = await mergeNarrativeIncrementalSemanticCorpus(
        {
          memory_space_id: context.memory_space_id,
          branch_id: context.branch_id,
          source_revision_id: context.active_revision_id,
          checkpoint,
          replace_from_ordinal: request.task.boundary.novel_start_ordinal,
          stable_records: request.task.stable_semantic_records,
          chunk_proposal: chunkProposal,
          current_evidence_items: baseTask.core_source.evidence_items,
          merge_key: mergeKey,
        },
        mergePorts,
      );
    } catch (error) {
      if (error instanceof CandidateCompilationError) {
        throw localizeIncrementalCompilationError(error, candidateKeyByRecordId);
      }
      throw error;
    }
    const proposal = {
      ...compiledChunk,
      producer: "hybrid" as const,
      operations: merged.records.map((record) => ({ op: "add_derived" as const, record })),
    };
    const report = validateChangeSetProposal(proposal, {
      memory_space_id: context.memory_space_id,
      branch_id: context.branch_id,
      active_revision_id: context.active_revision_id,
      known_evidence_ids: context.evidence_items.map((evidence) => evidence.evidence_id),
      known_records: [],
    });
    if (!report.accepted) {
      throw new TavernSemanticArchiveError(
        "PROPOSAL_REJECTED",
        `Core Validator rejected incremental proposal: ${report.issues
          .map((issue) => `${issue.code}:${issue.record_ref ?? "unknown"}`)
          .join(
            ",",
          )}; StateView support=${merged.current_state_view.derivation.evidence_refs.length}/${merged.current_state_view.derivation.dependency_refs.length}`,
      );
    }
    const acceptedReport = { ...report, accepted: true as const };
    const policyHash = createSha256Digest(
      await checksumJson({
        committer_version: "tavern-incremental-semantic-committer@0.1.0",
        merge_version: merged.merge_version,
        allowed_operations: ["add_derived"],
        source_task_fingerprint: request.task.task_fingerprint,
      }),
    );
    const authorized: AuthorizedChangeSet = {
      stage: "authorized",
      changeset_id: proposal.changeset_id,
      memory_space_id: proposal.memory_space_id,
      branch_id: proposal.branch_id,
      based_on_revision_id: proposal.based_on_revision_id,
      producer: proposal.producer,
      operations: proposal.operations,
      validation_report: acceptedReport,
      authorization: {
        committer_version: "tavern-incremental-semantic-committer@0.1.0",
        policy_hash: policyHash,
        authorized_at: request.compiled_at,
      },
    };
    assertWire("authorized_change_set", authorized);
    const coverageProvenance = {
      ...request.extractor,
      validator_version: report.validator_version,
    };
    const repairCursor =
      request.task.previous_cursor?.stage === "partial_semantic_committed" &&
      request.task.previous_cursor.semantic_head.chunk_sequence ===
        request.task.boundary.chunk_sequence
        ? request.task.previous_cursor
        : null;
    const coverage =
      repairCursor === null
        ? await createTavernSemanticCoverageCommit({
            source_snapshot: baseTask.source_snapshot,
            source_revision_id: context.active_revision_id,
            boundary: request.task.boundary,
            previous_cursor: request.task.previous_cursor,
            semantic_corpus_sha256: merged.semantic_corpus_hash.value,
            semantic_changeset_id: proposal.changeset_id,
            provenance: coverageProvenance,
            completion: request.completion ?? "complete",
          })
        : {
            ...repairCursor,
            stage:
              request.completion === "partial_repair_pending"
                ? ("partial_semantic_committed" as const)
                : ("semantic_committed" as const),
            semantic_head: {
              ...repairCursor.semantic_head,
              semantic_corpus_sha256: merged.semantic_corpus_hash.value,
              semantic_changeset_id: proposal.changeset_id,
              provenance: coverageProvenance,
            },
          };
    const semanticManifest: TavernSemanticManifestPayload = {
      version: TAVERN_SEMANTIC_ARCHIVE_VERSION,
      task_fingerprint: request.task.task_fingerprint,
      source_revision_id: context.active_revision_id,
      source_checksum: baseTask.source_snapshot.checksum,
      model_input_sha256: request.task.model_input_sha256,
      coverage_key_sha256: request.task.coverage_key_sha256,
      candidate_batch_checksum: await checksumJson(request.candidate_batch),
      changeset_id: proposal.changeset_id,
      model_id: request.extractor.model_id,
      model_identity_assurance: request.extractor.model_identity_assurance,
      prompt_contract_version: request.extractor.prompt_contract_version,
      prompt_body_sha256: request.extractor.prompt_body_sha256,
      parameters_hash: request.extractor.parameters_hash,
      validator_version: report.validator_version,
      quality_audit: request.quality_audit ?? null,
    };
    const previousSafeCount =
      request.task.previous_cursor?.consumer_safe_head?.covered_message_count;
    const previousSafeOrdinal =
      previousSafeCount === undefined
        ? null
        : (baseTask.source_snapshot.messages[previousSafeCount - 1]?.message_id_at_capture ?? null);
    const incrementalLifecycleBaseline =
      previousSafeCount === undefined ||
      request.task.previous_cursor?.semantic_head.source_checksum !==
        baseTask.source_snapshot.checksum
        ? null
        : deriveTavernNarrativeLifecycleContinuityBaseline(activeRecords, {
            memory_set_id: baseTask.source_snapshot.memory_set_id,
            source_revision_id: context.active_revision_id,
            source_checksum: baseTask.source_snapshot.checksum,
            previous_source_max_ordinal: previousSafeOrdinal,
          });
    const lifecycleBaseline =
      baseTask.lifecycle_continuity_baseline ?? incrementalLifecycleBaseline;
    const archiveRecords: TavernArchiveRecord[] = [
      ...baseTask.source_records,
      coreRecord(
        baseTask.core_source.memory_space.memory_space_id,
        "core_memory_space_v1",
        baseTask.core_source.memory_space,
      ),
      coreRecord(
        baseTask.core_source.source_revision.revision_id,
        "core_source_revision_v1",
        baseTask.core_source.source_revision,
      ),
      ...baseTask.core_source.evidence_items.map((evidence) =>
        coreRecord(evidence.evidence_id, "core_evidence_v1", evidence),
      ),
      ...merged.records.map((record) => {
        const recordId = derivedRecordId(record);
        return coreRecord(recordId, `core_${getNarraMemIdKind(recordId)}_v1`, record);
      }),
      coreRecord(proposal.changeset_id, "core_authorized_changeset_v1", authorized),
      ...priorLifecycleRecords(activeRecords),
      ...(lifecycleBaseline === null
        ? []
        : [
            coreRecord(
              TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_ID,
              TAVERN_NARRATIVE_LIFECYCLE_CONTINUITY_BASELINE_RECORD_KIND,
              lifecycleBaseline,
            ),
          ]),
      coreRecord(
        TAVERN_SEMANTIC_MANIFEST_RECORD_ID,
        TAVERN_SEMANTIC_MANIFEST_RECORD_KIND,
        semanticManifest,
      ),
      createTavernIncrementalSemanticCoverageArchiveRecord(coverage),
    ];
    const committed = await store.commitFullSnapshot({
      transaction_id: request.transaction_id,
      writer_id: request.writer_id,
      build_id: request.build_id,
      view_id: request.view_id,
      source_revision: baseTask.source_snapshot.source_revision,
      source_checksum: baseTask.source_snapshot.checksum,
      expected_commit_sequence: control.commit_sequence,
      expected_view_id: control.active_view.view_id,
      records: archiveRecords,
      after_durable_phase: async (phase) => {
        if (phase === "pending_recorded" || phase === "pointer_committed") {
          const stability = await reconcileTavernSourceSnapshot(this.port, {
            memory_set_id: baseTask.source_snapshot.memory_set_id,
            previous_snapshot: baseTask.source_snapshot,
            observed_hints: [],
            ...(baseTask.normalize_semantic_metadata === undefined
              ? {}
              : { normalize_semantic_metadata: baseTask.normalize_semantic_metadata }),
          });
          if (stability.status !== "UNCHANGED") {
            throw new TavernSemanticArchiveError(
              "SOURCE_CHANGED_DURING_COMMIT",
              `Current chat changed during incremental semantic ${phase}`,
            );
          }
        }
        await request.after_durable_phase?.(phase);
      },
    });
    return {
      control: committed.control,
      proposal,
      validation_report: acceptedReport,
      authorized_changeset: authorized,
      derived_record_count: merged.records.length,
      archive_record_count: archiveRecords.length,
      coverage,
      removed_semantic_record_ids: merged.removed_record_ids,
    };
  }

  private store(candidate: TavernExtractionTask["candidate"]): TavernWorldbookSnapshotStore {
    const memorySetId = candidate.control.memory_set_id;
    return new TavernWorldbookSnapshotStore(this.port, {
      memory_set_id: memorySetId,
      control_book_name: candidate.control_book_name,
      segment_book_prefix: `${ARCHIVE_BOOK_PREFIX}${memorySetId}__`,
      initial_identity_anchor: candidate.control.identity_anchor,
      max_records_per_segment: this.segmentLimits.max_records_per_segment,
      max_segment_utf8_bytes: this.segmentLimits.max_segment_utf8_bytes,
    });
  }
}
