import type { TavernJsonValue } from "./contracts.js";

export const TAVERN_MEMORY_BOOK_VERSION = "0.1.0" as const;
export const TAVERN_MEMORY_BOOK_ENTRY_FORMAT = "narramem.tavern-memory-book-entry" as const;
export const TAVERN_MEMORY_REGISTRY_VERSION = "0.1.0" as const;
export const TAVERN_MEMORY_REGISTRY_FORMAT = "narramem.tavern-memory-registry" as const;
export const TAVERN_MEMORY_REGISTRY_BOOK_NAME = "NarraMem__REGISTRY__v2" as const;

export const TAVERN_MEMORY_MODULE_IDS = ["M1", "M2", "M3", "M4", "M5", "M6", "M7"] as const;
export type TavernMemoryModuleId = (typeof TAVERN_MEMORY_MODULE_IDS)[number];

export type TavernMemoryModuleStatus =
  | "PENDING"
  | "RUNNING"
  | "COMMITTED"
  | "NEEDS_USER"
  | "INTERRUPTED"
  | "INVALIDATED";

export interface TavernMemoryModuleWorkState {
  readonly module_id: TavernMemoryModuleId;
  readonly status: TavernMemoryModuleStatus;
  readonly module_revision: number;
  readonly accepted_record_ids: readonly string[];
  readonly pending_target_ids: readonly string[];
  /** Latest immutable candidate partition used to resume this module without a model call. */
  readonly partition_page_id: string | null;
  /** Latest immutable content-free Provider/validation provenance page. */
  readonly last_attempt_page_id: string | null;
  readonly base_calls: number;
  readonly transport_retry_calls: number;
  readonly continuation_calls: number;
  readonly targeted_repair_calls: number;
  readonly manual_repair_calls: number;
  readonly last_error_code: string | null;
}

export interface TavernMemoryBatchWorkState {
  readonly batch_id: string;
  readonly source_revision_id: string;
  readonly first_ai_ordinal: number;
  readonly last_ai_ordinal: number;
  readonly source_unit_ids: readonly string[];
  readonly status:
    | "READY"
    | "MODULE_RUNNING"
    | "NEEDS_USER"
    | "FINALIZING"
    | "CHECKPOINT_VERIFIED"
    | "RECALL_READY"
    | "VISIBILITY_APPLIED"
    | "COMPLETE"
    | "INVALIDATED";
  readonly modules: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleWorkState>>;
  /** Content-free local failure marker. FINALIZING remains retryable and the old checkpoint stays active. */
  readonly finalization_error_code?: string | null;
  readonly finalization_error_target_ids?: readonly string[];
}

export interface TavernMemorySourceIndex {
  readonly source_revision_id: string;
  readonly source_checksum: string;
  readonly valid_ai_count: number;
  readonly committed_eligible_count: number;
  readonly protected_ai_ordinals: readonly number[];
  readonly completed_batches: readonly {
    readonly batch_id: string;
    readonly first_ai_ordinal: number;
    readonly last_ai_ordinal: number;
    readonly checkpoint_id: string;
    /** Present for v2 checkpoints; legacy imports without it cannot be a rollback target. */
    readonly source_revision_id?: string;
    readonly core_page_ids?: readonly string[];
    readonly recall_version?: string | null;
    readonly hidden_through_message_id?: number | null;
  }[];
  readonly mutation_from_source_unit_id: string | null;
}

export interface TavernMemoryCheckpointIndex {
  readonly checkpoint_id: string | null;
  readonly source_revision_id: string | null;
  readonly covered_ai_ordinal: number;
  readonly recall_version: string | null;
  readonly hidden_through_message_id: number | null;
  readonly core_page_ids: readonly string[];
}

export interface TavernMemoryViewCursor {
  readonly sort_time: string;
  readonly record_revision: number;
  readonly record_id: string;
}

export interface TavernMemoryModuleViewItem {
  readonly record_id: string;
  readonly record_revision: number;
  readonly sort_time: string;
  readonly title: string;
  readonly summary: string;
  readonly status: "ACTIVE" | "SUPERSEDED" | "USER_DISPUTED" | "DEPENDENCY_STALE";
  readonly source_floor_start: number | null;
  readonly source_floor_end: number | null;
  readonly core_page_id: string;
}

export interface TavernMemoryModuleViewIndex {
  readonly module_id: TavernMemoryModuleId;
  readonly record_count: number;
  readonly abnormal_count: number;
  readonly newest_cursor: TavernMemoryViewCursor | null;
  readonly latest_page_id: string | null;
  readonly oldest_page_id: string | null;
  readonly page_count: number;
}

export interface TavernMemoryModuleViewPage {
  readonly page_id: string;
  readonly module_id: TavernMemoryModuleId;
  /** Reserved for legacy imports; v2 immutable pages keep this null. */
  readonly newer_page_id: string | null;
  /** Append-only link from the new page to the previously latest page. */
  readonly older_page_id: string | null;
  /** Newest first with a deterministic cursor; the UI never persists offset positions. */
  readonly items: readonly TavernMemoryModuleViewItem[];
}

export interface TavernMemoryAuditItem {
  readonly at: string;
  readonly batch_id: string | null;
  readonly module_id: TavernMemoryModuleId | null;
  readonly event: string;
  readonly error_code: string | null;
}

export interface TavernMemoryColdHead {
  readonly memory_set_id: string;
  /** True only for a verified compaction/root generation that does not require older heads. */
  readonly chain_root: boolean;
  readonly commit_id: string;
  readonly commit_payload_checksum: string;
  readonly generation: number;
  readonly generation_checksum: string;
  readonly previous_generation_checksum: string | null;
  readonly committed_at: string;
  readonly source_index: TavernMemorySourceIndex;
  readonly work_state: TavernMemoryBatchWorkState | null;
  readonly checkpoint_index: TavernMemoryCheckpointIndex;
  readonly active_state: TavernJsonValue;
  readonly epistemic_state: TavernJsonValue;
  readonly thread_impact: TavernJsonValue;
  readonly module_views: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
  readonly audit_ring: readonly TavernMemoryAuditItem[];
  readonly core_page_ids: readonly string[];
  readonly module_view_page_ids: readonly string[];
  readonly core_page_refs: readonly TavernMemoryPageRef[];
  readonly module_view_page_refs: readonly TavernMemoryPageRef[];
}

export interface TavernMemoryCorePage {
  readonly page_id: string;
  readonly records: readonly {
    readonly record_id: string;
    readonly record_kind: string;
    readonly payload: TavernJsonValue;
  }[];
}

export interface TavernMemoryPageRef {
  readonly page_id: string;
  readonly payload_checksum: string;
  readonly created_generation: number;
}

export interface TavernMemoryBookCommitRequest {
  /** Stable idempotency key for this exact logical commit. */
  readonly commit_id: string;
  readonly expected_generation: number;
  readonly expected_generation_checksum: string | null;
  readonly committed_at: string;
  readonly source_index: TavernMemorySourceIndex;
  readonly work_state: TavernMemoryBatchWorkState | null;
  readonly checkpoint_index: TavernMemoryCheckpointIndex;
  readonly active_state: TavernJsonValue;
  readonly epistemic_state: TavernJsonValue;
  readonly thread_impact: TavernJsonValue;
  readonly module_views: Readonly<Record<TavernMemoryModuleId, TavernMemoryModuleViewIndex>>;
  readonly audit_ring: readonly TavernMemoryAuditItem[];
  /** Existing immutable pages that remain reachable from the new head. */
  readonly retained_core_page_ids: readonly string[];
  readonly retained_module_view_page_ids: readonly string[];
  /** Only newly created immutable pages; existing pages must be retained by id instead of rewritten. */
  readonly core_pages: readonly TavernMemoryCorePage[];
  readonly module_view_pages: readonly TavernMemoryModuleViewPage[];
}

export interface TavernMemoryBookCompactionRequest {
  /** Stable idempotency key; retry the same operation id after an interrupted host save. */
  readonly operation_id: string;
  readonly expected_generation: number;
  readonly expected_generation_checksum: string;
  readonly compacted_at: string;
}

export interface TavernMemoryBookCompactionResult {
  readonly head: TavernMemoryColdHead;
  readonly entries_before: number;
  readonly entries_after: number;
  readonly removed_entries: number;
}

export interface TavernMemoryBookOptions {
  readonly memory_set_id: string;
  readonly book_name: string;
  readonly max_cold_head_utf8_bytes: number;
  readonly max_core_page_utf8_bytes: number;
  readonly max_audit_items: number;
}

export interface TavernMemoryBookReadResult {
  readonly status: "EMPTY" | "READY";
  readonly head: TavernMemoryColdHead | null;
  readonly rejected_generations: readonly number[];
}

export interface TavernMemoryRegistryRecord {
  readonly status: "ACTIVE" | "DELETE_PENDING";
  readonly host_user_id: string;
  readonly chat_id: string;
  readonly character_or_group_id: string;
  readonly memory_set_id: string;
  readonly memory_book_name: string;
  readonly chat_anchor_hash: string;
}

export interface TavernMemoryRegistrySnapshot {
  readonly generation: number;
  readonly mutation_id: string | null;
  readonly previous_generation_checksum: string | null;
  readonly records: readonly TavernMemoryRegistryRecord[];
  readonly checksum: string;
}

export interface TavernMemoryRegistryWriteRequest {
  readonly mutation_id: string;
  readonly expected_generation: number;
  readonly expected_checksum: string | null;
  readonly records: readonly TavernMemoryRegistryRecord[];
}

export class TavernMemoryBookError extends Error {
  constructor(
    readonly code:
      | "INVALID_INPUT"
      | "BOOK_NOT_FOUND"
      | "BOOK_CORRUPT"
      | "STALE_GENERATION"
      | "WRITE_CONFLICT"
      | "VERIFY_FAILED"
      | "HEAD_TOO_LARGE"
      | "PAGE_TOO_LARGE"
      | "REGISTRY_COLLISION"
      | "DELETE_FAILED",
    message: string,
  ) {
    super(message);
    this.name = "TavernMemoryBookError";
  }
}
