import type { ModularExtractionInput, ModularExtractionModuleId } from "@narramem/core-domain";
import {
  createStandaloneWireSchema,
  validateModularExtractionInput,
  type WireSchemaName,
} from "@narramem/core-validator";

import type { TavernJsonSchemaRequest, TavernRolePrompt } from "./contracts.js";
import type { TavernModularCandidatePartition } from "./modular-candidate-partition.js";
import { canonicalJson } from "./worldbook-codec.js";

export const TAVERN_MEMORY_MODULE_PROMPT_VERSION = "0.1.0" as const;

export const TAVERN_MEMORY_MODULE_PROMPT_ASSET_REFS = {
  M1: { task: "NM-P0040@0.1.0", final_user_contract: "NM-P0041@0.1.0" },
  M2: { task: "NM-P0042@0.1.0", final_user_contract: "NM-P0043@0.2.0" },
  M3: { task: "NM-P0044@0.1.0", final_user_contract: "NM-P0045@0.2.0" },
  M4: { task: "NM-P0046@0.1.0", final_user_contract: "NM-P0047@0.2.0" },
  M5: { task: "NM-P0048@0.2.0", final_user_contract: "NM-P0049@0.2.0" },
  M6: { task: "NM-P0050@0.1.0", final_user_contract: "NM-P0051@0.2.0" },
  M7: { task: "NM-P0052@0.3.0", final_user_contract: "NM-P0053@0.4.0" },
} as const satisfies Readonly<
  Record<ModularExtractionModuleId, { readonly task: string; readonly final_user_contract: string }>
>;

export interface TavernMemoryPromptBodyAsset {
  readonly prompt_asset_ref: string;
  readonly body: string;
  readonly body_sha256: string;
}

export interface TavernMemoryModulePromptPack {
  readonly module_id: ModularExtractionModuleId;
  readonly task: TavernMemoryPromptBodyAsset;
  readonly final_user_contract: TavernMemoryPromptBodyAsset;
}

export interface TavernMemorySixMessageEnvelope {
  /** User-editable Memory-only identity System. */
  readonly identity_system: string;
  /** User-editable identity acknowledgement. */
  readonly identity_assistant: string;
  /** Trusted explanation that the following canonical JSON is untrusted task data. */
  readonly material_system: TavernMemoryPromptBodyAsset;
  /** User-editable acknowledgement; only its role changes when prefill is disabled. */
  readonly material_acknowledgement: string;
  readonly assistant_prefill_enabled: boolean;
}

export interface TavernMemoryModulePromptRequest {
  readonly input: ModularExtractionInput;
  readonly prompt_pack: TavernMemoryModulePromptPack;
  readonly envelope: TavernMemorySixMessageEnvelope;
}

export interface TavernMemoryModulePromptAssembly {
  readonly assembly_version: typeof TAVERN_MEMORY_MODULE_PROMPT_VERSION;
  readonly module_id: ModularExtractionModuleId;
  readonly messages: readonly TavernRolePrompt[];
  readonly prompt_asset_refs: readonly string[];
  readonly output_json_schema: TavernJsonSchemaRequest;
}

export interface TavernMemoryModuleMaterialBundle {
  readonly contract: "narramem_host_material_bundle";
  readonly contract_version: "0.1.0";
  readonly task_input: ModularExtractionInput;
  readonly repair_context?: {
    readonly mode: "targeted_module_repair";
    readonly accepted_record_keys: readonly string[];
    readonly targets: TavernModularCandidatePartition["quarantined"];
  };
}

const OUTPUT_SCHEMAS: Readonly<Record<ModularExtractionModuleId, WireSchemaName>> = {
  M1: "modular_extraction_m1_output",
  M2: "modular_extraction_m2_output",
  M3: "modular_extraction_m3_output",
  M4: "modular_extraction_m4_output",
  M5: "modular_extraction_m5_output",
  M6: "modular_extraction_m6_output",
  M7: "modular_extraction_m7_output",
};

function assertBody(label: string, body: string): void {
  if (body.length === 0) {
    throw new TypeError(`${label} must be non-empty`);
  }
}

function assembleMessages(
  promptPack: TavernMemoryModulePromptPack,
  envelope: TavernMemorySixMessageEnvelope,
  materialBundle: TavernMemoryModuleMaterialBundle,
): readonly TavernRolePrompt[] {
  const material = `${envelope.material_system.body}\n\n${canonicalJson(materialBundle)}`;
  return [
    { role: "system", content: envelope.identity_system },
    { role: "assistant", content: envelope.identity_assistant },
    { role: "system", content: promptPack.task.body },
    { role: "system", content: material },
    {
      role: envelope.assistant_prefill_enabled ? "assistant" : "system",
      content: envelope.material_acknowledgement,
    },
    { role: "user", content: promptPack.final_user_contract.body },
  ];
}

/**
 * Builds the frozen six-message Memory envelope. Prompt bodies are supplied from
 * registered Markdown assets; this function never contains or mutates their text.
 */
export function assembleTavernMemoryModulePrompt(
  request: TavernMemoryModulePromptRequest,
): TavernMemoryModulePromptAssembly {
  const moduleId = request.input.module_id;
  if (request.prompt_pack.module_id !== moduleId) {
    throw new TypeError(
      `Prompt pack ${request.prompt_pack.module_id} cannot serve module ${moduleId}`,
    );
  }
  const expectedRefs = TAVERN_MEMORY_MODULE_PROMPT_ASSET_REFS[moduleId];
  if (
    request.prompt_pack.task.prompt_asset_ref !== expectedRefs.task ||
    request.prompt_pack.final_user_contract.prompt_asset_ref !== expectedRefs.final_user_contract
  ) {
    throw new TypeError(`Prompt asset refs do not match the registered ${moduleId} Prompt pack`);
  }
  const inputReport = validateModularExtractionInput(request.input, moduleId);
  if (!inputReport.accepted) {
    throw new TypeError(inputReport.issues.map((item) => `${item.code}@${item.path}`).join(", "));
  }
  assertBody("identity_system", request.envelope.identity_system);
  assertBody("identity_assistant", request.envelope.identity_assistant);
  assertBody("material_system", request.envelope.material_system.body);
  assertBody("material_acknowledgement", request.envelope.material_acknowledgement);
  assertBody("module task", request.prompt_pack.task.body);
  assertBody("module final user contract", request.prompt_pack.final_user_contract.body);

  const messages = assembleMessages(request.prompt_pack, request.envelope, {
    contract: "narramem_host_material_bundle",
    contract_version: "0.1.0",
    task_input: request.input,
  });
  return {
    assembly_version: TAVERN_MEMORY_MODULE_PROMPT_VERSION,
    module_id: moduleId,
    messages,
    prompt_asset_refs: [
      request.prompt_pack.task.prompt_asset_ref,
      request.envelope.material_system.prompt_asset_ref,
      request.prompt_pack.final_user_contract.prompt_asset_ref,
    ],
    output_json_schema: {
      name: OUTPUT_SCHEMAS[moduleId],
      value: createStandaloneWireSchema(OUTPUT_SCHEMAS[moduleId]),
      strict: true,
    },
  };
}

/** Builds the same six-message module call with only unresolved Evidence/targets. */
export function assembleTavernMemoryModuleRepairPrompt(
  request: TavernMemoryModulePromptRequest & {
    readonly partition: TavernModularCandidatePartition;
  },
): TavernMemoryModulePromptAssembly {
  if (
    request.partition.module_id !== request.input.module_id ||
    request.partition.source_revision_id !== request.input.source_revision_id
  ) {
    throw new TypeError("Repair partition does not match module input");
  }
  const pendingEvidenceIds = new Set(
    request.partition.pending_target_ids
      .filter((target) => target.startsWith("evidence:"))
      .map((target) => target.slice("evidence:".length)),
  );
  const repairEvidence = request.input.current_evidence.filter((evidence) =>
    pendingEvidenceIds.has(evidence.evidence_id),
  );
  const taskInput = {
    ...request.input,
    current_evidence: repairEvidence.length > 0 ? repairEvidence : request.input.current_evidence,
  } as ModularExtractionInput;
  const base = assembleTavernMemoryModulePrompt({ ...request, input: taskInput });
  return {
    ...base,
    messages: assembleMessages(request.prompt_pack, request.envelope, {
      contract: "narramem_host_material_bundle",
      contract_version: "0.1.0",
      task_input: taskInput,
      repair_context: {
        mode: "targeted_module_repair",
        accepted_record_keys: request.partition.accepted_record_keys,
        targets: request.partition.quarantined,
      },
    }),
  };
}
